def _f4lps_extract_wf_text_directive(text):
    """Retourne (texte_normal, wf_text, position) depuis [WF:73] ou <waterfall:73>.

    position = 'before' si la directive est au début du message, sinon 'after'.
    Cela permet par exemple :
      [WF:CQ CQ]
      CQ CQ CQ DE F4LPS K
    ou en fin de QSO :
      TNX QSO...
      [WF:73]
      73 DE F4LPS
    """
    try:
        t = str(text or '')
        pat = r'(?:\[\s*WF\s*[:=]\s*([^\]\r\n]{1,24})\s*\]|<\s*waterfall\s*[:=]\s*([^>\r\n]{1,24})\s*>)'
        m = re.search(pat, t, flags=re.IGNORECASE)
        if not m:
            return t, '', 'before'
        wf = (m.group(1) or m.group(2) or '').strip().upper()
        before = t[:m.start()].strip()
        after = t[m.end():].strip()
        # Si l'utilisateur place la directive après du texte utile, on dessine à la fin.
        pos = 'after' if len(before) > 5 else 'before'
        t2 = (before + ('\n' if before and after else '') + after).strip()
        return t2, wf, pos
    except Exception:
        return str(text or ''), '', 'before'


def _f4lps_make_wf_preview_text(text):
    """Prévisualisation locale du texte waterfall — police 7x11 style DM780.

    Affiche le dessin tel qu'il apparaîtra dans le waterfall.
    Un mot par ligne si le texte contient des espaces (ex: CQ CQ).
    """
    try:
        txt = ''.join(ch for ch in str(text or '').upper() if ch in _F4LPS_WF_FONT)[:12]
        if not txt:
            txt = '73'

        CHAR_H = 7
        # Largeur variable : le Q utilise 6 colonnes pour une vraie queue.
        GAP_X  = 1

        # Même logique que la fonction audio : CQ CQ empilé verticalement
        raw_words = txt.split()
        if txt.strip() == 'CQ CQ':
            words = ['CQ', 'CQ']
        else:
            long_words = [w for w in raw_words if len(w) >= 2]
            if len(long_words) >= 2:
                words = long_words
            else:
                words = [''.join(raw_words)]

        lines_out = []
        for word in words:
            rows_out = ['' for _ in range(CHAR_H)]
            for ch in word:
                glyph = _F4LPS_WF_FONT.get(ch, _F4LPS_WF_FONT.get(' '))
                gw = max((len(r) for r in glyph), default=5)
                for y in range(CHAR_H):
                    row_str = glyph[y] if y < len(glyph) else '0' * gw
                    for x in range(gw):
                        bit = row_str[x] if x < len(row_str) else '0'
                        rows_out[y] += '█' if bit == '1' else ' '
                    rows_out[y] += ' ' * GAP_X
            lines_out.append(rows_out)

        all_rows = []
        for i, rows in enumerate(lines_out):
            all_rows.extend(rows)
            if i < len(lines_out) - 1:
                all_rows.append('')

        maxlen = max((len(r) for r in all_rows), default=0)
        border = '┌' + '─' * maxlen + '┐'
        bottom = '└' + '─' * maxlen + '┘'
        body   = ['│' + r.ljust(maxlen) + '│' for r in all_rows]
        return '\n'.join([border] + body + [bottom])
    except Exception:
        return str(text or '')

def _f4lps_make_waterfall_text_audio(text, sample_rate=48000, center_hz=1500.0, amplitude=0.25):
    """Texte waterfall V3 — lettres DEBOUT et lisibles.

    Géométrie correcte du waterfall :
      - axe X = fréquence  -> colonnes des lettres (gauche vers droite)
      - axe Y = temps      -> lignes des lettres (haut vers bas)

    Comme le waterfall ajoute les nouvelles lignes en haut, on émet les lignes
    du bitmap du bas vers le haut. À la fin du dessin, la lettre apparaît donc
    dans le sens normal, et non couchée/miroir.
    """
    try:
        sr = int(sample_rate or 48000)
        center = float(center_hz or 1500.0)
        raw = re.sub(r'\s+', ' ', str(text or '').upper().strip())
        if not raw:
            return np.zeros(0, dtype=np.float32)

        clean = ''.join(ch for ch in raw if ch in _F4LPS_WF_FONT or ch.isspace()).strip()
        if not clean:
            return np.zeros(0, dtype=np.float32)

        # C et Q spécialement redessinés pour être lisibles sur un waterfall.
        fine_override = {
            # V4 : police 5x7 plus compacte et plus nette dans une bande étroite.
            # C très ouvert à droite, Q avec une queue courte qui ne touche pas le C.
            'C': [
                '01110',
                '10001',
                '10000',
                '10000',
                '10000',
                '10001',
                '01110',
            ],
            'Q': [
                '01110',
                '10001',
                '10001',
                '10001',
                '10101',
                '10010',
                '01101',
            ],
        }

        CHAR_H = 7
        CHAR_GAP = 5       # V6 : davantage d'air entre lettres, évite l'effet collé
        WORD_GAP = 7       # V6 : espace mot plus franc
        COL_HZ = 15.0      # V6 : colonnes plus rapprochées en fréquence; CQ reste étroit malgré l'espace accru
        ROW_DUR = 0.260    # V7 : tons plus longs = raies spectrales plus étroites, moins de bavure horizontale
        ROW_PAUSE = 0.022  # V7 : petite coupure entre lignes, lisible sans grossir le dessin

        def glyph_for(ch):
            return fine_override.get(ch, _F4LPS_WF_FONT.get(ch, _F4LPS_WF_FONT[' ']))

        # Construction d'une seule matrice de texte, comme une vraie police bitmap.
        rows = ['' for _ in range(CHAR_H)]
        chars = list(clean)
        for i, ch in enumerate(chars):
            if ch == ' ':
                for y in range(CHAR_H):
                    rows[y] += '0' * WORD_GAP
                continue
            glyph = glyph_for(ch)
            gw = max(len(r) for r in glyph)
            for y in range(CHAR_H):
                gr = glyph[y] if y < len(glyph) else ''
                rows[y] += gr.ljust(gw, '0')
                # espace entre caractères, sauf avant espace explicite
                if i < len(chars)-1 and chars[i+1] != ' ':
                    rows[y] += '0' * CHAR_GAP

        width = max((len(r) for r in rows), default=0)
        if width <= 0:
            return np.zeros(0, dtype=np.float32)
        rows = [r.ljust(width, '0') for r in rows]

        # Centrer tout le mot autour de center_hz.
        total_span = (width - 1) * COL_HZ
        f_left = center - total_span / 2.0

        n_row = max(512, int(sr * ROW_DUR))
        n_pause = max(0, int(sr * ROW_PAUSE))
        t = np.arange(n_row, dtype=np.float64) / float(sr)

        # V8 : enveloppe anti-bavure, géométrie inchangée.
        # Taper plus court + durée de ligne plus longue : le trait reste blanc au centre
        # mais les commutations ne créent plus de grandes ailes horizontales en fréquence.
        edge = max(16, int(n_row * 0.12))
        env = np.ones(n_row, dtype=np.float64)
        ramp = np.sin(np.linspace(0.0, math.pi/2.0, edge))**2
        env[:edge] = ramp
        env[-edge:] = ramp[::-1]

        # Même puissance PAR TON pour CQ, 73 et tout autre texte.
        # L'ancienne normalisation /sqrt(active) rendait les lettres riches en pixels
        # moins blanches. Ici chaque trait garde la même amplitude spectrale.
        PER_TONE_GAIN = 0.060

        chunks = []
        phase = {}

        # IMPORTANT : le nouveau waterfall apparaît en haut et descend ensuite.
        # Pour obtenir la première ligne du caractère EN HAUT à la fin, on transmet
        # donc la dernière ligne du bitmap en premier.
        for y in range(CHAR_H - 1, -1, -1):
            seg = np.zeros(n_row, dtype=np.float64)
            active = 0
            for x in range(width):
                if rows[y][x] != '1':
                    continue
                f = f_left + x * COL_HZ
                if not (80.0 <= f <= 3000.0):
                    continue
                key = round(float(f), 3)
                ph = phase.get(key, 0.0)
                seg += np.sin(2.0 * math.pi * float(f) * t + ph)
                phase[key] = math.fmod(
                    ph + 2.0 * math.pi * float(f) * n_row / float(sr),
                    2.0 * math.pi
                )
                active += 1
            if active:
                seg = seg * PER_TONE_GAIN * env
                # Sécurité anti-clipping : limitation douce uniquement sur les crêtes multiton.
                seg = np.tanh(seg / 0.48) * 0.48
            chunks.append(seg.astype(np.float32))
            if n_pause:
                chunks.append(np.zeros(n_pause, dtype=np.float32))

        if not chunks:
            return np.zeros(0, dtype=np.float32)

        audio = np.concatenate(chunks).astype(np.float32)
        pad = np.zeros(int(sr * 0.20), dtype=np.float32)
        audio = np.concatenate([pad, audio, pad])
        # V8 : PAS de renormalisation globale selon le mot — niveau WF renforcé.
        # C'est indispensable pour que CQ et 73 aient exactement la même blancheur par trait.
        # La sécurité de crête est déjà assurée ligne par ligne ci-dessus.
        return np.clip(audio, -0.48, 0.48).astype(np.float32)

    except Exception as e:
        try:
            print(f"[WF] erreur: {e}")
        except Exception:
            pass
        return np.zeros(0, dtype=np.float32)

