def _f4lps_forward_wheel_to_scroll(widget, event):
    """Redirige la molette vers le QScrollArea parent au lieu de modifier un réglage."""
    try:
        p = widget.parent()
        while p is not None:
            if isinstance(p, QScrollArea):
                bar = p.verticalScrollBar()
                delta = event.angleDelta().y() if hasattr(event, 'angleDelta') else 0
                bar.setValue(bar.value() - delta)
                event.accept()
                return
            p = p.parent()
    except Exception:
        pass
    try:
        event.ignore()
    except Exception:
        pass

class F4LPSNoWheelSlider(QSlider):
    """Slider : molette = scroll fenêtre, clic/glisser = réglage."""
    def wheelEvent(self, event):
        _f4lps_forward_wheel_to_scroll(self, event)

class F4LPSNoWheelComboBox(QComboBox):
    """Combo : empêche la molette de changer carte son / port / choix."""
    def wheelEvent(self, event):
        _f4lps_forward_wheel_to_scroll(self, event)

class F4LPSNoWheelSpinBox(QSpinBox):
    """SpinBox : empêche la molette de changer les valeurs en scrollant."""
    def wheelEvent(self, event):
        _f4lps_forward_wheel_to_scroll(self, event)

class F4LPSNoWheelDoubleSpinBox(QDoubleSpinBox):
    """DoubleSpinBox : empêche la molette de changer les valeurs en scrollant."""
    def wheelEvent(self, event):
        _f4lps_forward_wheel_to_scroll(self, event)

def _f4lps_patch_no_wheel_recursive(root):
    """Bloque la molette sur tous les réglages enfants.

    Utile pour le panneau Radio CAT intégré : les QComboBox d'origine
    (port COM, baudrate, protocole, CI-V, OmniRig...) ne doivent jamais
    changer quand on fait simplement défiler la fenêtre Réglages.
    """
    try:
        classes = (QComboBox, QSpinBox, QDoubleSpinBox, QSlider)
        for w in root.findChildren(classes):
            try:
                w.setFocusPolicy(Qt.StrongFocus)
                w.wheelEvent = (lambda ev, _w=w: _f4lps_forward_wheel_to_scroll(_w, ev))
            except Exception:
                pass
    except Exception:
        pass


