# Table inverse — printables prioritaires sur les codes ctrl ambigus
_vc_priority = list(range(32, 127)) + [ord('\n'), ord('\r'), ord('\t')] + list(range(0, 32))
VARICODE_INV = {}
for _vc_i in _vc_priority:
    _vc_ch = chr(_vc_i)
    if _vc_ch in VARICODE:
        _vc_code = VARICODE[_vc_ch]
        if _vc_code not in VARICODE_INV:
            VARICODE_INV[_vc_code] = _vc_ch



# ============================================================================
# RSID TEXTE F4LPS — identification automatique du mode
# ============================================================================

# V1.6.134 F4LPS — Table de libellés acceptés côté RX.
# Attention : ceci ne remplace pas encore le décodage Reed-Solomon audio complet.
# Cette table sert à afficher proprement les RSID texte explicites et prépare
# le futur décodeur universel sans créer de faux RSID lors des changements de fréquence.
_F4LPS_RSID_TEXT_MODES = {
    'BPSK31','BPSK63','BPSK125','BPSK250','BPSK500',
    'QPSK31','QPSK63','QPSK125','QPSK250','QPSK500',
    'RTTY','MFSK16','MFSK32','MFSK64','DOMINOEX 4','DOMINOEX 5','DOMINOEX 8','DOMINOEX 11','DOMINOEX 16','DOMINOEX 22',
    'OLIVIA 4/125','OLIVIA 4/250','OLIVIA 8/250','OLIVIA 8/500','OLIVIA 16/500','OLIVIA 32/1000',
    'CONTESTIA 4/125','CONTESTIA 8/250','CONTESTIA 8/500','THOR4','THOR8','THOR11','THOR16','THROB1','THROB2','THROB4','MT63','HELL'
}

def _f4lps_rsid_label(mode_name):
    m = str(mode_name or '').upper().replace('_', ' ').replace('-', ' ')
    m = re.sub(r'\s+', ' ', m).strip()
    if 'OLIVIA' in m:
        mm = re.search(r'(\d+)\s*/\s*(\d+)', m)
        return f"OLIVIA {mm.group(1)}/{mm.group(2)}" if mm else m
    if 'DOMINO' in m:
        mm = re.search(r'(\d+)', m)
        return f"DOMINOEX {mm.group(1)}" if mm else 'DOMINOEX'
    if 'BPSK' in m or 'QPSK' in m:
        return m.replace(' ', '')
    return m

def _f4lps_rsid_to_mode(label, family=''):
    s = str(label or '').upper().replace('-', ' ')
    s = re.sub(r'\s+', ' ', s).strip()
    if 'OLIVIA' in s:
        mm = re.search(r'(\d+)\s*/\s*(\d+)', s)
        return f"OLIVIA {mm.group(1)}/{mm.group(2)}" if mm else None
    if 'DOMINO' in s or s.startswith('DM'):
        mm = re.search(r'(\d+)', s)
        return f"DominoEX {mm.group(1)}" if mm else None
    for p in ('BPSK','QPSK'):
        mm = re.search(p + r'\s*(31|63|125|250|500)', s)
        if mm:
            return f"{p}{mm.group(1)}"
    if s.startswith('RTTY'):
        return 'RTTY'
    mm = re.search(r'MFSK\s*(\d+)', s)
    if mm:
        return f"MFSK{mm.group(1)}"
    mm = re.search(r'THOR\s*(\d+)', s)
    if mm:
        return f"THOR{mm.group(1)}"
    mm = re.search(r'THROB\s*(\d+)', s)
    if mm:
        return f"THROB{mm.group(1)}"
    if 'HELL' in s:
        return 'HELL'
    if s.startswith('MT63'):
        return 'MT63'
    if s.startswith('CONTESTIA'):
        return s
    return None

def _f4lps_extract_rsid(text):
    """Retourne (label, texte_sans_rsid). Accepte [RSID:...], RSID:..., RSID ..."""
    t = str(text or '')
    pats = [
        r'\[\s*RSID\s*\]\s*([^\r\n]+)',
        r'\[\s*RSID\s*[:=]\s*([^\]\r\n]+)\s*\]',
        r'\bRSID\s*[:=]\s*([^\r\n]+)',
        r'\bRSID\s+(OLIVIA\s+\d+\s*/\s*\d+|DOMINOEX\s+\d+|DOMINO\s*\d+|DM\s*\d+|[BQ]PSK\s*(?:31|63|125|250|500)|RTTY(?:\s*45|\s*50|\s*75)?|MFSK\s*\d+|CONTESTIA\s+\d+\s*/\s*\d+|THOR\s*\d+|MT63(?:\s*\d+)?|HELL(?:SCHREIBER)?|THROB\s*\d+)',
    ]
    for pat in pats:
        m = re.search(pat, t, flags=re.IGNORECASE)
        if m:
            label = m.group(1).strip()
            t2 = (t[:m.start()] + t[m.end():]).lstrip(' \t\r\n:-')
            return label, t2
    return None, t

# ============================================================================
# DECODEUR PSK V3 — Acquisition max-energie + Gardner TED
# Ref: G3PLX PSK31 spec, fldigi architecture
# Convention G3PLX: bit 0 = inversion de phase (~pi), bit 1 = stable (~0)
# ============================================================================
class PSKDecoder:
    """Decodeur BPSK31/QPSK31/BPSK63/QPSK63/BPSK125/QPSK125."""

    _ACQ_SYMBOLS = 8

    def __init__(self, sample_rate=48000, mode="BPSK31"):
        self.sample_rate = sample_rate
        self.center_freq = 1500.0
        self._sos        = None
        self._dx_mode    = False
        self._filt_delay = 0
        self._filt_zi_i  = None
        self._filt_zi_q  = None
        self.set_mode(mode)

    def set_dx_mode(self, enabled=True):
        """Mode DX / signaux faibles : plus patient au verrouillage et filtre moins serré."""
        self._dx_mode = bool(enabled)
        try:
            self._build_filter()
        except Exception:
            pass

    def force_fast_acquire(self, seconds=3.5):
        """V1.6.138 : acquisition rapide juste après RSID / changement de mode.

        Le burst RSID est placé avant le texte PSK. Si on attend trop de blocs
        stables après le changement de mode, le début du message est perdu et
        l'utilisateur a l'impression que le RX tarde à démarrer. Ce flag ne
        change pas la décision Varicode ; il réduit seulement l'attente avant
        acquisition pendant quelques secondes.
        """
        try:
            self._fast_acq_until = time.time() + float(seconds)
            self._lock_count = 0
            self._weak_count = 0
            self._rx_locked = False
            self._acquired = False
            self._acq_i = []
            self._acq_q = []
            self._last_phase = None
            self._bit_buf = []
            self._bad_chars = 0
            self._good_chars = 0
        except Exception:
            pass

    def _fast_acquire_active(self):
        try:
            return time.time() < float(getattr(self, '_fast_acq_until', 0.0) or 0.0)
        except Exception:
            return False

    def set_mode(self, mode_name):
        self.mode_name = mode_name
        params = PSK_MODES.get(mode_name, PSK_MODES["BPSK31"])
        self.baud_rate = params["baud"]
        self.psk_type  = params["type"]
        self.sps       = self.sample_rate / self.baud_rate
        self.sps_int   = max(1, int(round(self.sps)))
        self._build_filter()
        self._reset()

    def set_tx_active(self, active=True):
        self._tx_active = bool(active)
        try:
            if not self._tx_active:
                self._tx_buf[:] = 0
                self._tx_pos = 0
        except Exception:
            pass
        self.update()

    def push_tx_audio(self, samples):
        """Affiche immédiatement le vrai signal TX dans le waterfall local.
        Version corrigée F4LPS : on ne dessine plus une fausse trame et on
        n'attend plus 8192 échantillons avant de voir quelque chose. Chaque
        chunk TX est transformé en FFT courte, puis injecté directement comme
        une ligne waterfall, exactement comme le RX.
        """
        try:
            arr = np.asarray(samples, dtype=np.float32).flatten()
            if arr.size < 16:
                return
            self._init_buf()
            # FFT courte pour affichage immédiat + zéro-padding pour une ligne nette.
            fft_size = int(getattr(self, '_tx_fft_size', 4096) or 4096)
            fft_size = max(1024, min(8192, fft_size))
            if arr.size >= fft_size:
                buf = arr[-fft_size:].astype(np.float32, copy=False)
            else:
                buf = np.zeros(fft_size, dtype=np.float32)
                buf[-arr.size:] = arr
            win = buf * np.hanning(fft_size).astype(np.float32)
            spec = np.abs(np.fft.rfft(win))
            mdb = (20.0 * np.log10(np.maximum(spec, 1e-10))).astype(np.float32)
            # Spectre réel 0..5000 Hz, comme le RX/PSK/Olivia.
            sr = float(getattr(self, "_tx_sample_rate", getattr(self, "sample_rate", 48000.0)) or 48000.0)
            bin_5k = int(5000.0 / (sr / 2.0) * len(mdb)) + 2
            mdb = mdb[:min(bin_5k, len(mdb))]
            # Injection directe : le waterfall défile pendant le TX même si le RX est arrêté.
            self._push_line(mdb, sr)
            self._latest_mag = mdb
            self._latest_sr = sr
            self._has_new_data = False
            self.update()
        except Exception as e:
            try:
                print(f"⚠️ TX waterfall ignoré: {e}")
            except Exception:
                pass

    def set_center_freq(self, hz):
        hz = float(hz)
        moved = abs(hz - getattr(self, 'center_freq', hz))
        self.center_freq = hz
        self._ol_freq = 2.0 * math.pi * self.center_freq / self.sample_rate

        # V1.6.146 : lorsqu'on clique sur une nouvelle cascade déjà en émission,
        # il faut remettre le mélangeur/Costas à zéro, mais NE PAS repartir comme
        # au tout premier lancement. L'ancien _reset() effaçait aussi le bruit de
        # fond et laissait l'acquisition normale attendre une grande partie du QSO.
        if moved >= 25.0 and hasattr(self, '_sos') and self._sos is not None:
            old_noise = float(getattr(self, '_noise_floor', 1e-9) or 1e-9)
            self._reset()

            # Conserver une estimation réaliste du bruit au lieu d'apprendre la
            # porteuse reçue comme si elle était elle-même le bruit de fond.
            self._noise_floor = max(1e-12, old_noise)

            # Ouvrir immédiatement le squelch et utiliser seulement 4 symboles
            # pour l'acquisition pendant les premières secondes après le clic.
            self.force_fast_acquire(7.0)

            # Marqueur permettant de reconnaître le tout premier bloc après QSY.
            self._retune_pending = True

    def _build_filter(self):
        """
        Filtre passe-bas SOS (Second-Order Sections) numeriquement stable.
        Ord3, fc = 1.0*baud — bon compromis attenuation / delai de groupe.
        sosfilt_zi est utilise pour le filtrage stateful chunk-par-chunk.
        """
        from scipy.signal import butter, sosfilt_zi
        # V1.5.1 DM780 DSP : filtre de canal nettement plus serré.
        # BPSK31 utile ≈ 31 Hz, on garde une marge pour les transitions varicode
        # et le QSB, mais on évite d'envoyer tout le bruit au Costas.
        # V1.6.115 DX : filtre un peu moins serré en signaux faibles pour éviter de déformer les phases.
        # V1.6.149 : en mode DX, 1.55*baud laissait entrer trop de bruit autour
        # des signaux moyens. 1.35 conserve les transitions PSK tout en améliorant
        # nettement le rapport signal/bruit au Costas.
        fc_mult = 1.35 if bool(getattr(self, '_dx_mode', False)) else 1.25
        fc = min(fc_mult * self.baud_rate / (0.5 * self.sample_rate), 0.49)
        self._sos = butter(5, fc, btype='low', output='sos')
        zi = sosfilt_zi(self._sos)
        self._filt_zi_i = zi.copy()
        self._filt_zi_q = zi.copy()

        # Ancienne version : scipy.signal.group_delay() sur ce filtre très étroit
        # provoquait parfois le warning "denominator is extremely small" à 0 Hz.
        # Ce n'était pas une panne, mais ça inquiétait au lancement.
        # On utilise donc une compensation sûre et bornée basée sur la vitesse PSK.
        self._filt_delay = int(max(8, min(self.sps_int * 2, self.sample_rate * 0.05)))

    def _reset(self):
        self._ol_phase   = 0.0
        self._ol_freq    = 2.0 * math.pi * self.center_freq / self.sample_rate
        self._agc        = 1e-3
        self._last_phase = None
        self._energy     = 0.0
        self._snr        = 0.0
        self._bit_buf    = []
        self._bad_chars  = 0
        self._good_chars = 0
        # Squelch / anti-bruit : évite les faux caractères lorsque seuls
        # le souffle et les parasites arrivent dans le filtre PSK.
        self._noise_floor = 1e-9
        self._signal_db   = 0.0
        self._lock_count  = 0
        self._weak_count  = 0
        self._dx_hold_count = 0
        self._rx_locked   = False
        self._mu         = 0.0
        self._acquired   = False
        self._acq_i      = []
        self._acq_q      = []
        self._ted_gain   = 0.0025  # V1.6.69: TED plus doux, évite Z -> ( dans les indicatifs
        self._prev_iv    = 0.0
        self._prev_qv    = 0.0
        # Costas loop
        self._costas_freq  = 0.0
        self._costas_phase = 0.0
        # V1.5 : boucle plus lente/filtrée comme DM780 : moins de faux verrouillage
        # sur le bruit, mais garde l'AFC sur une raie PSK réelle.
        self._costas_alpha = 0.0028 if self.baud_rate <= 31.25 else 0.0045
        self._costas_beta  = self._costas_alpha * self._costas_alpha * 0.18
        if hasattr(self, '_sos') and self._sos is not None:
            self._build_filter()

    def _downmix_filter(self, samples):
        """Downmix IQ + filtre passe-bas SOS stateful."""
        from scipy.signal import sosfilt
        n = len(samples)
        idx = np.arange(n, dtype=np.float64)
        ph  = self._ol_phase + self._ol_freq * idx
        i_raw =  samples * np.cos(ph)
        q_raw = -samples * np.sin(ph)
        self._ol_phase = math.fmod(
            self._ol_phase + self._ol_freq * n, 2.0 * math.pi)
        i_f, self._filt_zi_i = sosfilt(self._sos, i_raw, zi=self._filt_zi_i)
        q_f, self._filt_zi_q = sosfilt(self._sos, q_raw, zi=self._filt_zi_q)
        return i_f, q_f

    def _costas_rotate(self, i_f, q_f):
        """
        Costas loop second-order vectorisee — corrige la derive de frequence.
        Traitee par blocs de 64 samples pour allier vitesse et precision.
        """
        n   = len(i_f)
        ph  = self._costas_phase
        frq = self._costas_freq
        alpha = self._costas_alpha
        beta  = self._costas_beta
        max_frq = 2.0 * math.pi * 45.0 / self.sample_rate

        i_out = np.empty(n, dtype=np.float64)
        q_out = np.empty(n, dtype=np.float64)

        BLOCK = 64
        k = 0
        while k < n:
            end = min(k + BLOCK, n)
            blk = end - k
            idx = np.arange(blk, dtype=np.float64)
            phases = ph + frq * idx
            c = np.cos(phases)
            s = np.sin(phases)
            ii =  i_f[k:end] * c + q_f[k:end] * s
            qq = -i_f[k:end] * s + q_f[k:end] * c
            i_out[k:end] = ii
            q_out[k:end] = qq

            if self.psk_type == 'BPSK':
                err_arr = qq * np.sign(ii + 1e-12)
            else:
                err_arr = qq * np.sign(ii + 1e-12) - ii * np.sign(qq + 1e-12)

            # Erreur normalisée par la puissance pour éviter que le bruit fort
            # ou une surcharge audio fasse partir la boucle Costas.
            pwr = float(np.mean(ii*ii + qq*qq)) + 1e-12
            err_mean = float(np.mean(err_arr)) / math.sqrt(pwr)
            err_mean = max(-1.0, min(1.0, err_mean))
            frq += beta * err_mean
            frq = max(-max_frq, min(max_frq, frq))
            ph += frq * blk + alpha * err_mean
            ph = math.fmod(ph, 2.0 * math.pi)
            k = end

        self._costas_phase = ph
        self._costas_freq  = frq
        return i_out, q_out

    def _check_phase_polarity(self, i_f, q_f):
        """
        Resolution de l'ambiguite de phase 180 degres BPSK.
        Le preambule PSK31 = suite de bit-1 (phases stables, dphi ~ 0).
        Si verrouille en opposition, les dphi seront tous ~ pi.
        On detecte ce cas et on pivote la boucle de pi.
        """
        n = len(i_f)
        positions = list(range(int(self._mu), n, self.sps_int))
        if len(positions) < 4:
            return
        phases = [math.atan2(float(q_f[p]), float(i_f[p]))
                  for p in positions if p < n]
        if len(phases) < 4:
            return
        near_zero = sum(1 for i in range(1, len(phases))
                        if abs((phases[i] - phases[i-1] + math.pi) % (2*math.pi) - math.pi) < math.pi * 0.5)
        near_pi = len(phases) - 1 - near_zero
        if near_pi > near_zero:
            # Boucle en opposition -> pivoter de pi
            self._costas_phase = math.fmod(
                self._costas_phase + math.pi, 2.0 * math.pi)
            self._last_phase = None
            self._bit_buf    = []

    def _quick_decode_score(self, i_f, q_f, mu_try):
        """Score de verrouillage Varicode pour choisir le vrai point symbole.
        L'ancien choix "max énergie" peut tomber entre deux symboles : on voit alors
        exactement le comportement de la capture, quelques lettres mais beaucoup de
        caractères faux. Ici on essaie les phases symbole et on garde celle qui donne
        le plus de Varicode imprimable, comme une acquisition DM780/fldigi simplifiée.
        """
        n = len(i_f)
        pos = float(mu_try)
        last_phase = None
        bits = []
        good = bad = 0
        chars = []
        max_chars = 48
        while pos + 1 < n and (good + bad) < max_chars:
            i0 = int(pos)
            frac = pos - i0
            iv = float(i_f[i0] + frac * (i_f[i0 + 1] - i_f[i0]))
            qv = float(q_f[i0] + frac * (q_f[i0 + 1] - q_f[i0]))
            ph = math.atan2(qv, iv)
            if last_phase is not None:
                dphi = (ph - last_phase + math.pi) % (2.0 * math.pi) - math.pi
                bit = '0' if abs(dphi) > math.pi * 0.65 else '1'  # V1.6.69: seuil BPSK plus tolérant
                bits.append(bit)
                bstr = ''.join(bits)
                while '00' in bstr:
                    sep = bstr.index('00')
                    code = bstr[:sep]
                    bstr = bstr[sep+2:]
                    if code:
                        ch = VARICODE_INV.get(code)
                        if ch and ch in PSK_PRINTABLE and ch not in ('\r','\n','\t'):
                            good += 1
                            chars.append(ch)
                        else:
                            bad += 1
                bits = list(bstr[-80:])
            last_phase = ph
            pos += self.sps
        # V1.6.143 : PAS de bonus CQ/DE/RST.
        # Avant, l'acquisition favorisait CQ/DE/73/599 : le RX accrochait bien
        # sur un appel CQ, mais pouvait choisir une mauvaise phase quand on prenait
        # un QSO en cours au milieu d'une phrase normale. On juge uniquement la
        # cohérence Varicode imprimable.
        printable_ratio = good / max(1, good + bad)
        return good * 5 - bad * 8 + int(printable_ratio * 14)

    def _acquire(self):
        """Acquisition symbole robuste V1.6 : énergie + score Varicode.
        La version précédente choisissait seulement le point de symbole par énergie.
        Sur PSK31 réel avec fading, plusieurs points ont la même énergie et un mauvais
        mu donne du texte presque lisible mais faux. On filtre/Costas, puis on teste
        plusieurs mu et on choisit celui qui produit les meilleurs Varicodes.
        """
        i_f = np.concatenate(self._acq_i)
        q_f = np.concatenate(self._acq_q)
        delay = getattr(self, '_filt_delay', 0)
        if delay > 0 and delay < len(i_f) // 2:
            i_f = i_f[delay:]
            q_f = q_f[delay:]
        n = len(i_f)
        if n < self.sps_int * 4:
            self._mu = 0.0
            self._acquired = True
            return i_f, q_f

        # Costas provisoire pour que le score Varicode voie les vraies inversions.
        saved_phase = self._costas_phase
        saved_freq = self._costas_freq
        ii, qq = self._costas_rotate(i_f, q_f)
        self._costas_phase = saved_phase
        self._costas_freq = saved_freq

        best_mu = 0
        best_score = -10**9
        step = max(1, self.sps_int // 32)  # assez fin sans coûter trop cher
        search = range(0, self.sps_int, step)
        # On ignore le début du filtre pour le scoring.
        for mu_try in search:
            score = self._quick_decode_score(ii, qq, mu_try + self.sps_int)
            if score > best_score:
                best_score = score
                best_mu = mu_try

        # V1.6.138 : en acquisition rapide, le buffer est volontairement court.
        # Si le score Varicode n'a pas encore assez de caractères pour être fiable,
        # on prend le maximum d'énergie symbole comme point de départ, plus rapide
        # et souvent meilleur au tout début d'une réponse OM.
        try:
            if best_score <= 2:
                # V1.6.145 : au tout début il n'y a souvent pas assez de Varicode
                # complet pour choisir la phase. Le maximum d'énergie est alors
                # plus fiable et évite de rester bloqué plusieurs dizaines de secondes.
                search2 = range(0, self.sps_int, max(1, self.sps_int // 32))
                best_e = -1.0
                best_e_mu = best_mu
                for mu_try in search2:
                    idxs = np.arange(int(mu_try), len(ii), self.sps_int, dtype=np.int64)
                    if idxs.size >= 2:
                        e = float(np.mean(ii[idxs] * ii[idxs] + qq[idxs] * qq[idxs]))
                        if e > best_e:
                            best_e = e
                            best_e_mu = mu_try
                best_mu = best_e_mu
        except Exception:
            pass

        self._mu = float(best_mu)
        self._acquired = True
        self._last_phase = None
        self._bit_buf = []
        self._bad_chars = 0
        self._good_chars = 0
        return i_f, q_f

    def _update_squelch(self, en_chunk):
        """Squelch progressif : bloque le souffle, mais laisse passer les PSK faibles.

        La V1.2 apprenait le bruit de fond trop vite : dès qu'un vrai signal arrivait,
        il était intégré au bruit, donc le rapport signal/bruit retombait et le RX
        restait fermé. Ici le bruit ne monte que très lentement, et il descend vite.
        """
        en = max(float(en_chunk), 1e-12)

        # Initialisation douce. Après un clic sur une cascade déjà active,
        # conserver le bruit précédent : sinon la porteuse PSK devient le nouveau
        # bruit de référence et le squelch peut rester fermé longtemps.
        retune_pending = bool(getattr(self, '_retune_pending', False))
        if self._noise_floor <= 1.1e-9 and not retune_pending:
            self._noise_floor = max(1e-12, en * 0.35)
        if retune_pending:
            self._retune_pending = False

        # Le bruit de fond peut descendre vite quand le canal devient plus propre.
        if en < self._noise_floor:
            self._noise_floor = 0.70 * self._noise_floor + 0.30 * en
        # Il ne monte que très lentement, sinon un vrai signal devient lui-même le bruit.
        elif not self._rx_locked:
            self._noise_floor = 0.995 * self._noise_floor + 0.005 * min(en, self._noise_floor * 1.8)
        elif en < self._noise_floor * 1.5:
            self._noise_floor = 0.998 * self._noise_floor + 0.002 * en

        nf = max(self._noise_floor, 1e-12)
        self._signal_db = 10.0 * math.log10(en / nf)

        dx = bool(getattr(self, '_dx_mode', False))
        fast = bool(self._fast_acquire_active())
        # V1.6.138 : pendant quelques secondes après RSID/changement de mode,
        # le RX doit accrocher vite. On ne modifie pas le Varicode, seulement
        # les délais de verrouillage/squelch.
        # V1.6.149 : seuil DX un peu plus sélectif. L'ancien 1.7 dB ouvrait
        # facilement sur du bruit moyen et donnait du charabia.
        min_lock_db = 1.2 if fast else (2.2 if dx else PSK_MIN_LOCK_DB)
        # Une fois verrouillé, rester très tolérant au QSB pour éviter les coupures.
        keep_lock_db = 0.10 if fast else (0.05 if dx else PSK_KEEP_LOCK_DB)
        # Maintien beaucoup plus long sur les creux courts des signaux moyens.
        unlock_chunks = 110 if fast else (150 if dx else max(PSK_UNLOCK_CHUNKS, 90))
        # Deux blocs suffisent en DX : démarrage plus rapide sans ouvrir sur un seul pic.
        required_chunks = 1 if fast else (2 if dx else PSK_REQUIRED_LOCK_CHUNKS)
        lock_db = keep_lock_db if self._rx_locked else min_lock_db
        if self._signal_db >= lock_db:
            self._lock_count += 1
            self._weak_count = 0
        else:
            self._weak_count += 1
            self._lock_count = max(0, self._lock_count - 1)

        if not self._rx_locked and self._lock_count >= required_chunks:
            self._rx_locked = True
        if self._rx_locked and self._weak_count >= unlock_chunks:
            self._rx_locked = False
            self._acquired = False
            self._acq_i = []
            self._acq_q = []
            self._last_phase = None
            self._bit_buf = []
            self._bad_chars = 0
            self._good_chars = 0

        return self._rx_locked

    def _decode_samples(self, i_f, q_f):
        # Costas loop en temps réel sur chaque chunk
        i_f, q_f = self._costas_rotate(i_f, q_f)

        n = len(i_f)
        decoded = []
        pos = self._mu

        while pos + 1 < n:
            i0 = int(pos)
            if i0 + 1 >= n:
                break
            frac = pos - i0
            iv = i_f[i0] + frac * (i_f[i0 + 1] - i_f[i0])
            qv = q_f[i0] + frac * (q_f[i0 + 1] - q_f[i0])

            mag = math.sqrt(iv * iv + qv * qv) + 1e-12
            # AGC à constante de temps rapide
            self._agc = 0.995 * self._agc + 0.005 * mag
            agc = max(self._agc, 1e-6)
            iv_n = iv / agc
            qv_n = qv / agc

            # SNR estimé
            self._snr = 0.98 * self._snr + 0.02 * max(
                0.0, 10.0 * math.log10(mag / agc + 1e-10) + 30.0)

            # Énergie locale sur ce chunk (mise à jour au fil des symboles)
            self._energy = 0.99 * self._energy + 0.01 * (iv * iv + qv * qv)

            # Gardner TED — synchronisation symbole
            corr = 0.0
            half_pos = pos - self.sps * 0.5
            if half_pos >= 0:
                h0 = int(half_pos)
                if h0 + 1 < n:
                    hf = half_pos - h0
                    ih = (i_f[h0] + hf*(i_f[h0+1]-i_f[h0])) / agc
                    qh = (q_f[h0] + hf*(q_f[h0+1]-q_f[h0])) / agc
                    ted_err = ((iv_n - self._prev_iv)*ih +
                               (qv_n - self._prev_qv)*qh)
                    lim  = self.sps * 0.018
                    # TED limité : l'ancien réglage corrigeait trop et faisait
                    # glisser l'horloge symbole sur le bruit.
                    corr = max(-lim, min(lim, self._ted_gain * ted_err))
            self._prev_iv = iv_n
            self._prev_qv = qv_n

            # Décision de bit — pas de garde sur _energy (Costas loop
            # s'occupe du verrouillage, pas besoin d'attendre l'énergie)
            sym_phase = math.atan2(qv_n, iv_n)

            if self._last_phase is None:
                # Premier symbole valide — initialiser sans produire de bit
                self._last_phase = sym_phase
                pos += self.sps + corr
                continue

            dphi = sym_phase - self._last_phase
            self._last_phase = sym_phase
            # Normaliser dans [-π, π]
            dphi = (dphi + math.pi) % (2.0 * math.pi) - math.pi

            if self.psk_type == 'BPSK':
                # Convention G3PLX: inversion de phase (~π) = bit 0, stable (~0) = bit 1
                bit = 0 if abs(dphi) > math.pi * 0.65 else 1  # V1.6.69: seuil BPSK plus tolérant
                self._bit_buf.append(str(bit))
            else:
                # QPSK différentiel — 2 bits par symbole
                q_sym = int(round(dphi / (math.pi / 2.0))) % 4
                self._bit_buf.append(str(q_sym & 1))
                self._bit_buf.append(str((q_sym >> 1) & 1))

            # Décodage Varicode : séparateur = "00"
            bits_str = ''.join(self._bit_buf)
            while '00' in bits_str:
                sep      = bits_str.index('00')
                code     = bits_str[:sep]
                bits_str = bits_str[sep + 2:]
                if code:
                    ch = VARICODE_INV.get(code)
                    if ch and ch in PSK_PRINTABLE:
                        self._good_chars += 1
                        # V1.6.143 : les erreurs anciennes ne doivent pas rester
                        # éternellement et provoquer une réacquisition en plein QSO.
                        if self._bad_chars > 0:
                            self._bad_chars = max(0, self._bad_chars - 1)
                        decoded.append(ch)
                    else:
                        self._bad_chars += 1
                        # Trop de varicodes impossibles = perte de verrouillage,
                        # on réacquiert au lieu d'imprimer du charabia.
                        _inner_limit = 18 if self._good_chars <= 2 else 55
                        if self._bad_chars > _inner_limit and self._bad_chars > max(6, self._good_chars * 5):
                            self._acquired = False
                            self._last_phase = None
                            self._bit_buf = []
                            self._bad_chars = 0
                            self._good_chars = 0
                            break
            self._bit_buf = list(bits_str)
            # Éviter accumulation de bits orphelins
            if len(self._bit_buf) > 150:
                self._bit_buf = self._bit_buf[-60:]

            pos += self.sps + corr

        # IMPORTANT : conserver la position du prochain symbole par rapport
        # au début du PROCHAIN chunk. L'ancienne version faisait fmod(pos, sps),
        # ce qui cassait la synchro symbole chunk après chunk (décodage faux).
        self._mu = pos - n
        # Si le prochain symbole tombe juste avant le début du prochain chunk,
        # on le reporte au symbole suivant au lieu de repartir à zéro : c'était
        # une grosse source de désynchronisation.
        while self._mu < 0:
            self._mu += self.sps
        while self._mu >= self.sps:
            self._mu -= self.sps
        return ''.join(decoded)

    def process_audio(self, samples):
        samples = np.asarray(samples, dtype=np.float64)
        if len(samples) == 0:
            return ('', self._snr)

        i_f, q_f = self._downmix_filter(samples)
        en_chunk = float(np.mean(i_f ** 2 + q_f ** 2))

        # Squelch numérique : si le signal centré PSK n'est pas assez fort
        # par rapport au bruit mesuré, on coupe le décodage et on vide les bits.
        if not self._update_squelch(en_chunk):
            self._snr = 0.95 * self._snr + 0.05 * max(0.0, self._signal_db)
            self._last_phase = None
            self._bit_buf = []
            return ('', self._snr)

        prev_energy = self._energy
        self._energy = 0.90 * self._energy + 0.10 * en_chunk

        # Réacquisition automatique si signal revient après silence ou perte lock.
        if (self._acquired and
                (prev_energy < max(self._noise_floor * 1.05, 1e-9)) and
                self._energy > max(self._noise_floor * (6.0 if bool(getattr(self, '_dx_mode', False)) else 5.0), 1e-8)):
            # V1.6.149 : ne réacquérir que sur un vrai nouveau départ après silence.
            # L'ancien seuil 2.6x se déclenchait pendant le QSB des signaux moyens.
            self._acquired  = False
            self._acq_i     = []
            self._acq_q     = []
            self._last_phase = None
            self._bit_buf   = []

        delay = getattr(self, '_filt_delay', 0)
        if not self._acquired:
            self._acq_i.append(i_f)
            self._acq_q.append(q_f)
            # Limiter le buffer d'acquisition pour éviter de traîner du bruit ancien.
            if len(self._acq_i) > 12:
                self._acq_i = self._acq_i[-12:]
                self._acq_q = self._acq_q[-12:]
            total = sum(len(b) for b in self._acq_i)
            fast = bool(self._fast_acquire_active())
            # V1.6.149 : 10 symboles en DX retardaient trop le début des réponses.
            # Six symboles donnent assez de matière au score sans perdre plusieurs mots.
            need_symbols = 4 if fast else (5 if bool(getattr(self, '_dx_mode', False)) else 6)
            if total >= self.sps_int * need_symbols + delay:
                ia, qa = self._acquire()
                return (self._decode_samples(ia, qa), self._snr)
            return ('', self._snr)

        text = self._decode_samples(i_f, q_f)
        # S'il y a beaucoup plus d'erreurs Varicode que de bons caractères,
        # on supprime la sortie et on force une nouvelle acquisition.
        # V1.6.145 : une mauvaise phase choisie au début ne doit plus rester
        # bloquée jusqu'à 100 erreurs. Si aucun caractère fiable n'arrive, on
        # relance rapidement l'acquisition ; avec du texte déjà correct on reste
        # plus patient pour ne pas couper sur un QSB.
        _reacq_bad_limit = 18 if self._good_chars <= 2 else 55
        if self._bad_chars > _reacq_bad_limit and self._bad_chars > max(6, self._good_chars * 5):
            self._acquired = False
            self._last_phase = None
            self._bit_buf = []
            self._bad_chars = 0
            self._good_chars = 0
            return ('', self._snr)
        return (text, self._snr)

# ============================================================================
# ENCODEUR PSK
# ============================================================================
class PSKEncoder:
    """Encodeur BPSK/QPSK.

    V8.3.12 F4LPS — TX PSK phase continue.
    IMPORTANT : la porteuse RF/audio ne doit JAMAIS redemarrer a t=0 a chaque
    symbole. Seule la phase de DONNEE est modifiee entre deux symboles.
    L'ancienne implementation recreait sin(2*pi*f*t + phase) avec t repartant
    de zero pour chaque symbole : a une frequence audio non multiple du baud,
    cela ajoutait une rotation parasite a chaque symbole et rendait le signal
    indecodable par un modem externe.
    """

    def __init__(self, sample_rate=48000, mode="BPSK31", center_freq=1500.0):
        self.sample_rate = int(sample_rate)
        self.center_freq = float(center_freq)
        self._amplitude  = 0.35
        self.set_mode(mode)

    def set_mode(self, mode_name):
        self.mode_name  = mode_name
        p = PSK_MODES.get(mode_name, PSK_MODES["BPSK31"])
        self.baud_rate  = float(p["baud"])
        self.psk_type   = p["type"]
        self.symbol_len = max(8, int(round(self.sample_rate / self.baud_rate)))
        self._make_envelope()

    def set_center_freq(self, hz):
        self.center_freq = float(hz)

    def _make_envelope(self):
        # Rampe uniquement autour d'une VRAIE transition de phase.
        # 20 % du symbole max, borne a 8 ms pour rester propre a 31/63/125 baud.
        n = self.symbol_len
        ramp = min(max(4, int(self.sample_rate * 0.006)), max(4, n // 5))
        self._ramp_len = int(ramp)
        if ramp > 1:
            x = np.arange(ramp, dtype=np.float64) / float(ramp - 1)
            self._fade_in = (0.5 - 0.5*np.cos(np.pi*x)).astype(np.float64)
            self._fade_out = self._fade_in[::-1].copy()
        else:
            self._fade_in = np.ones(1, dtype=np.float64)
            self._fade_out = np.ones(1, dtype=np.float64)

    def _text_to_bits(self, text):
        bits = []
        for ch in str(text or '').upper():
            code = VARICODE.get(ch, VARICODE[' '])
            bits.extend(code)
            bits.extend(('0', '0'))
        return bits

    def _render_bpsk_bits(self, bits, start_phase=0.0, fade_start=True, fade_end=True):
        """Rend une suite BPSK avec porteuse ABSOLUMENT continue.

        G3PLX : bit 0 = inversion 180 degres ; bit 1 = phase stable.
        La transition est placee a la frontiere du symbole et adoucie par une
        extinction/remontee tres courte uniquement lorsqu'il y a inversion.
        """
        bits = [str(b) for b in bits]
        if not bits:
            return np.zeros(0, dtype=np.float32)

        n = self.symbol_len
        total = len(bits) * n
        out = np.empty(total, dtype=np.float64)
        data_phase = float(start_phase)
        carrier_w = 2.0 * math.pi * float(self.center_freq) / float(self.sample_rate)
        ramp = min(self._ramp_len, n // 3)

        # Une inversion correspondant au bit courant a lieu a son DEBUT.
        transitions = [b == '0' for b in bits]

        for i, bit in enumerate(bits):
            if bit == '0':
                data_phase += math.pi

            i0 = i * n
            idx = np.arange(i0, i0 + n, dtype=np.float64)  # temps GLOBAL
            seg = np.sin(carrier_w * idx + data_phase)

            env = np.ones(n, dtype=np.float64)
            if ramp > 1:
                # Si phase modifiee au debut de ce symbole, remontee depuis 0.
                if transitions[i] or (i == 0 and fade_start):
                    env[:ramp] *= self._fade_in[:ramp]
                # Si le symbole suivant inverse la phase, descendre a 0 avant
                # la frontiere afin que le retournement de signe soit propre.
                if i + 1 < len(bits) and transitions[i + 1]:
                    env[-ramp:] *= self._fade_out[-ramp:]
                elif i == len(bits) - 1 and fade_end:
                    env[-ramp:] *= self._fade_out[-ramp:]

            out[i0:i0+n] = seg * env

        return (out * float(self._amplitude)).astype(np.float32)

    def encode_text(self, text):
        # Préambule : phase stable puis idle PSK (zeros = inversions), ensuite
        # Varicode, puis idle final. Une seule generation continue garantit que
        # la phase porteuse reste correcte quelle que soit la frequence audio.
        payload = self._text_to_bits(text)

        if self.psk_type == 'BPSK':
            bits = ['1'] * 16 + ['0'] * 32 + payload + ['0'] * 24
            audio = self._render_bpsk_bits(bits, start_phase=0.0,
                                           fade_start=True, fade_end=True)
            silence = np.zeros(self.symbol_len * 4, dtype=np.float32)
            return np.concatenate((audio, silence))

        # QPSK historique : on conserve le mapping existant, mais avec une
        # porteuse continue. (Le BPSK est le chemin de reference valide ici.)
        bits = payload
        dibits = []
        for i in range(0, len(bits), 2):
            b0 = int(bits[i])
            b1 = int(bits[i+1]) if i+1 < len(bits) else 0
            dibits.append((b0 + 2*b1) * (math.pi/2.0))
        if not dibits:
            return np.zeros(0, dtype=np.float32)
        n = self.symbol_len
        total = len(dibits) * n
        out = np.empty(total, dtype=np.float64)
        carrier_w = 2.0 * math.pi * float(self.center_freq) / float(self.sample_rate)
        data_phase = 0.0
        ramp = min(self._ramp_len, n // 3)
        for i, delta in enumerate(dibits):
            data_phase += delta
            i0 = i*n
            idx = np.arange(i0, i0+n, dtype=np.float64)
            seg = np.sin(carrier_w*idx + data_phase)
            env = np.ones(n, dtype=np.float64)
            if ramp > 1:
                if abs(delta) > 1e-12 or i == 0:
                    env[:ramp] *= self._fade_in[:ramp]
                if i+1 < len(dibits) and abs(dibits[i+1]) > 1e-12:
                    env[-ramp:] *= self._fade_out[-ramp:]
                elif i == len(dibits)-1:
                    env[-ramp:] *= self._fade_out[-ramp:]
            out[i0:i0+n] = seg*env
        silence = np.zeros(self.symbol_len*4, dtype=np.float32)
        return np.concatenate(((out*float(self._amplitude)).astype(np.float32), silence))

    def encode_char(self, char):
        # Utilise exactement le meme moteur phase-continue que encode_text.
        code = VARICODE.get(str(char or ' ').upper()[:1], VARICODE[' '])
        bits = list(code) + ['0', '0']
        if self.psk_type == 'BPSK':
            return self._render_bpsk_bits(bits, start_phase=0.0,
                                          fade_start=True, fade_end=True)
        return self.encode_text(str(char or ' ')[:1])


# ============================================================================
# DÉCODEUR PSK CONTINU EXPÉRIMENTAL
# ============================================================================
class ContinuousPSKDecoder(PSKDecoder):
    """Acquisition courte puis suivi Costas/Gardner permanent."""

    def _reset(self):
        super()._reset()
        self._cont_i = []
        self._cont_q = []
        self._cont_started = False

    def _continuous_choose_phase(self, i_f, q_f):
        try:
            saved_phase = self._costas_phase
            saved_freq = self._costas_freq
            ii, qq = self._costas_rotate(i_f, q_f)
            self._costas_phase = saved_phase
            self._costas_freq = saved_freq

            best_mu = 0.0
            best_score = -10**9
            step = max(1, self.sps_int // 24)
            for mu_try in range(0, self.sps_int, step):
                score = self._quick_decode_score(ii, qq, mu_try)
                if score > best_score:
                    best_score = score
                    best_mu = float(mu_try)
            return best_mu, int(best_score)
        except Exception:
            return 0.0, -999

    def process_audio(self, samples):
        samples = np.asarray(samples, dtype=np.float64)
        if len(samples) == 0:
            return ('', self._snr)

        i_f, q_f = self._downmix_filter(samples)
        en_chunk = float(np.mean(i_f ** 2 + q_f ** 2))

        if not self._update_squelch(en_chunk):
            self._snr = 0.95 * self._snr + 0.05 * max(0.0, self._signal_db)
            self._last_phase = None
            self._bit_buf = []
            self._cont_i = []
            self._cont_q = []
            self._cont_started = False
            return ('', self._snr)

        if not self._cont_started:
            self._cont_i.append(i_f)
            self._cont_q.append(q_f)
            if len(self._cont_i) > 10:
                self._cont_i = self._cont_i[-10:]
                self._cont_q = self._cont_q[-10:]

            total = sum(len(x) for x in self._cont_i)

            # V2.1.8 — reprise RX rapide après TX.
            # L'ancien moteur attendait systématiquement environ 280 ms, puis
            # cherchait la phase sur dix symboles. Si le correspondant répondait
            # immédiatement, le début de sa préambule pouvait déjà être perdu.
            # Pendant la fenêtre force_fast_acquire(), cinq symboles et environ
            # 120 ms suffisent. En fonctionnement normal on conserve l'analyse
            # plus prudente de 280 ms.
            if self._fast_acquire_active():
                need = max(self.sps_int * 5, int(self.sample_rate * 0.12))
            else:
                need = max(self.sps_int * 10, int(self.sample_rate * 0.28))
            if total < need:
                return ('', self._snr)

            ia = np.concatenate(self._cont_i)
            qa = np.concatenate(self._cont_q)
            self._mu, score = self._continuous_choose_phase(ia, qa)
            self._acquisition_score = score
            self._cont_started = True
            self._acquired = True
            self._last_phase = None
            self._bit_buf = []
            self._bad_chars = 0
            self._good_chars = 0
            self._cont_i = []
            self._cont_q = []
            return (self._decode_samples(ia, qa), self._snr)

        txt = self._decode_samples(i_f, q_f)

        bad_limit = 12 if self._good_chars == 0 else 35
        if self._bad_chars > bad_limit and self._bad_chars > max(6, self._good_chars * 5):
            self._cont_started = False
            self._acquired = False
            self._last_phase = None
            self._bit_buf = []
            self._bad_chars = 0
            self._good_chars = 0
            self._cont_i = []
            self._cont_q = []
            return ('', self._snr)

        return (txt, self._snr)

