_DOMINO_ENC = {}
_DOMINO_DEC = {}
for _i, _t in enumerate(_DOMINO_PRIMARY_TRIPLES):
    _seq = tuple(int(x) for x in _t if int(x) != 0)
    if _seq:
        _DOMINO_ENC[chr(_i)] = _seq
        _DOMINO_DEC[_seq] = chr(_i)
# V0.12 F4LPS — L'ESPACE.
# Le triplet de l'index 32 est (0, 0, 0) : le filtre « x != 0 » ci-dessus le
# reduisait donc a une sequence VIDE, et l'espace se retrouvait sans code.
# Or en DominoEX l'espace est le nibble 0, et c'est le caractere le plus
# frequent d'un QSO : environ un sur cinq. A l'emission il etait purement
# saute ; a la reception, un nibble 0 recu ne correspondait a rien et decalait
# l'assemblage des caracteres, ce qui transformait la suite en charabia.
_DOMINO_ENC[' '] = (0,)
_DOMINO_DEC[(0,)] = ' '
# fallback CR/LF/texte radio
_DOMINO_ENC.setdefault('\n', _DOMINO_ENC.get('\r', (2,13)))
_DOMINO_DEC.setdefault(_DOMINO_ENC.get(' ', ()), ' ')

def _domino_varidec(seq):
    return _DOMINO_DEC.get(tuple(seq), '')

def _domino_varienc(ch):
    if not ch:
        return ()
    # DominoEX primaire privilégie ASCII exact; garde minuscules/majuscules.
    return _DOMINO_ENC.get(ch, _DOMINO_ENC.get(ch.upper(), _DOMINO_ENC.get(' ', ())))

