DOMINOEX_MODES = {
    "DominoEX 4":  {"tones": 18, "baud": 3.906,  "spacing": 7.812,  "base_freq": 1500, "bandwidth": 173.0},
    "DominoEX 8":  {"tones": 18, "baud": 7.8125, "spacing": 15.625, "base_freq": 1500, "bandwidth": 346.0},
    "DominoEX 11": {"tones": 18, "baud": 10.766, "spacing": 15.625, "base_freq": 1500, "bandwidth": 262.0},
    "DominoEX 16": {"tones": 18, "baud": 15.625, "spacing": 20.0,   "base_freq": 1500, "bandwidth": 355.0},
    "DominoEX 22": {"tones": 18, "baud": 21.533, "spacing": 29.1,   "base_freq": 1500, "bandwidth": 524.0},
}

class DominoEXDecoder:
    """Décodeur DominoEX basé sur MFSK différentiel.
    Algorithme : détection FFT des tonalités, décodage différentiel,
    assemblage des caractères par paires de symboles.
    """
    def __init__(self, sample_rate=48000, mode="DominoEX 8"):
        self.sample_rate = sample_rate
        self.center_freq = 1500.0
        self.set_mode(mode)
        self._symbol_buf = []
        self._nibble_buf = []
        self._last_symbol = None
        self._sync_counter = 0
        self._mag_out = np.zeros(512)
        self._last_best_energy = 0.0
        self._last_snr_db = 0.0
        self._rx_locked_phase = None
        self._char_nibbles = []


    def set_mode(self, mode):
        p = DOMINOEX_MODES.get(mode, DOMINOEX_MODES["DominoEX 8"])
        self.baud       = p["baud"]
        self.spacing    = p["spacing"]
        self.n_tones    = p["tones"]
        self.base_freq  = p["base_freq"]
        self.samples_per_symbol = int(self.sample_rate / self.baud)
        self._fft_size  = max(512, 2 ** math.ceil(math.log2(self.samples_per_symbol)))
        self._buf       = np.zeros(self._fft_size * 2, dtype=np.float32)
        self._buf_pos   = 0
        self._last_symbol = None
        self._nibble_buf = []
        self._symbol_buf = []
        self._char_nibbles = []
        self._rx_locked_phase = None

    def set_center_freq(self, hz):
        """Centre RX réel du signal DominoEX.
        Avant, le décodeur cherchait toujours les 18 tons autour de 1500 Hz,
        même quand le curseur était à 600, 1000 ou 2500 Hz. Résultat : il
        décodait le bruit et imprimait du charabia.
        """
        try:
            hz = float(hz)
        except Exception:
            return
        hz = max(20.0, min(3000.0, hz))
        if abs(hz - getattr(self, 'center_freq', hz)) > max(2.0, self.spacing * 0.35):
            self._last_symbol = None
            self._nibble_buf = []
            self._symbol_buf = []
            self._char_nibbles = []
        self.center_freq = hz

    def _tone_freqs(self):
        # Banque principale : 18 tons centrés autour du curseur RX.
        mid = (self.n_tones - 1) / 2.0
        return [self.center_freq + (i - mid) * self.spacing for i in range(self.n_tones)]

    def _tone_banks(self):
        """Banque de tons DominoEX centrée sur le curseur.
        On évite maintenant de changer entre plusieurs banques à chaque symbole :
        cela cassait l'IFK+ différentiel. Auto Center place le curseur au centre,
        puis le décodeur garde cette même échelle stable.
        """
        mid = (self.n_tones - 1) / 2.0
        c = float(self.center_freq)
        sp = float(self.spacing)
        return [[c + (i - mid) * sp for i in range(self.n_tones)]]

    def push_samples(self, samples):
        """Pousse des échantillons audio, retourne (texte_décodé, magnitude_FFT)."""
        decoded = []
        arr = np.asarray(samples, dtype=np.float32)

        # Remplir le buffer
        n = min(len(arr), len(self._buf) - self._buf_pos)
        self._buf[self._buf_pos:self._buf_pos + n] = arr[:n]
        self._buf_pos += n

        sps = self.samples_per_symbol

        while self._buf_pos >= sps:
            block = self._buf[:sps]
            # FFT
            fft_size = max(1024, sps)
            fft_size = 2 ** math.ceil(math.log2(fft_size))
            windowed = block * np.hanning(sps)
            padded   = np.zeros(fft_size)
            padded[:sps] = windowed
            spectrum = np.abs(np.fft.rfft(padded))

            # Magnitude pour affichage waterfall — ÉCHELLE RÉELLE Hz.
            # IMPORTANT : l'ancienne version envoyait seulement les 512 premiers bins
            # et le widget waterfall les interprétait comme 0..5000 Hz.
            # En DominoEX4, avec FFT 16384, 512 bins ne couvrent qu'environ 1500 Hz :
            # les repères 1000/1500/2000 étaient donc faux et les signaux paraissaient
            # à la mauvaise largeur. On envoie maintenant le spectre réel 0..5000 Hz
            # en dB, comme le waterfall PSK. Le widget recadre ensuite proprement 0..3000 Hz.
            hz_per_bin = float(self.sample_rate) / float(fft_size)
            bin_5k = int(min(len(spectrum), max(16, math.ceil(5000.0 / max(hz_per_bin, 1e-9)) + 1)))
            spec_5k = spectrum[:bin_5k].astype(np.float32)
            self._mag_out = (20.0 * np.log10(np.maximum(spec_5k, 1e-10))).astype(np.float32)

            # Détecter la tonalité dominante.
            # FIX RX : on ne suppose plus que le curseur est forcément le centre exact.
            freqs = np.fft.rfftfreq(fft_size, 1.0 / self.sample_rate)
            best_pack = None
            for tone_freqs in self._tone_banks():
                energies = []
                for tf in tone_freqs:
                    idx = int(np.argmin(np.abs(freqs - tf)))
                    # Fenêtre étroite mais pas trop : DominoEX4 a des tons proches.
                    w = 2
                    lo = max(0, idx - w); hi = min(len(spectrum), idx + w + 1)
                    energies.append(float(np.sum(spectrum[lo:hi])))
                best_t = int(np.argmax(energies))
                sorted_e = sorted(energies)
                best_e = float(sorted_e[-1]) if sorted_e else 0.0
                second = float(sorted_e[-2]) if len(sorted_e) >= 2 else 1e-12
                median = float(np.median(energies)) if energies else 1e-12
                # Score = énergie du ton dominant + contraste avec le fond de la banque.
                snr_tone = 10.0 * math.log10((best_e + 1e-12) / (max(second, median) + 1e-12))
                score = snr_tone + 0.15 * 10.0 * math.log10((best_e + 1e-12) / (median + 1e-12))
                pack = (score, snr_tone, best_t, best_e, energies)
                if best_pack is None or pack[0] > best_pack[0]:
                    best_pack = pack

            _score, snr_tone, best_tone, best_energy, energies = best_pack
            self._last_best_energy = float(best_energy)
            self._last_snr_db = float(snr_tone)

            # Ne plus remettre la synchro à zéro à chaque symbole faible : ça empêchait
            # complètement le décodage sur QSB/faible signal. On saute seulement ce symbole.
            if snr_tone < 0.25:
                self._buf[:self._buf_pos - sps] = self._buf[sps:self._buf_pos]
                self._buf_pos -= sps
                continue

            # Décodage IFK+ DominoEX réel.
            # fldigi : c = round(curr - prev) - 2 ; si négatif +18.
            # Le résultat est un nibble varicode. Un nibble <8 démarre un
            # caractère, les nibbles >=8 continuent le caractère.
            if self._last_symbol is None:
                self._last_symbol = best_tone
                self._buf[:self._buf_pos - sps] = self._buf[sps:self._buf_pos]
                self._buf_pos -= sps
                continue

            raw_forward = (best_tone - self._last_symbol)
            nibble = int(round(raw_forward)) - 2
            while nibble < 0:
                nibble += self.n_tones
            nibble %= self.n_tones

            if nibble > 15:
                # Valeur hors alphabet nibble : symbole probablement faux/QRM.
                self._last_symbol = best_tone
                self._buf[:self._buf_pos - sps] = self._buf[sps:self._buf_pos]
                self._buf_pos -= sps
                continue

            self._last_symbol = best_tone

            # Synchronisation caractère native DominoEX : initial < 8, suite >= 8.
            if nibble < 8:
                if self._char_nibbles:
                    ch = _domino_varidec(self._char_nibbles)
                    if ch and (ch.isprintable() or ch in '\r\n'):
                        decoded.append(ch)
                self._char_nibbles = [nibble]
            else:
                if self._char_nibbles and len(self._char_nibbles) < 3:
                    self._char_nibbles.append(nibble)
                elif len(self._char_nibbles) >= 3:
                    self._char_nibbles = []

            # Décaler le buffer
            self._buf[:self._buf_pos - sps] = self._buf[sps:self._buf_pos]
            self._buf_pos -= sps

        return ''.join(decoded), self._mag_out.copy()

    def get_mag(self):
        return self._mag_out.copy()


