# ENCODEUR DOMINOEX
# ============================================================================

class DominoEXEncoder:
    """Encodeur DominoEX : texte → échantillons audio MFSK."""
    def __init__(self, sample_rate=48000, mode="DominoEX 8", center_freq=1500.0):
        self.sample_rate  = sample_rate
        self.center_freq  = center_freq
        self.set_mode(mode)
        self._phase = 0.0

    def set_mode(self, mode):
        p = DOMINOEX_MODES.get(mode, DOMINOEX_MODES["DominoEX 8"])
        self.baud    = p["baud"]
        self.spacing = p["spacing"]
        self.n_tones = p["tones"]
        self.samples_per_symbol = int(self.sample_rate / self.baud)

    def _tone_freq(self, tone_idx):
        # V0.12 F4LPS — ALIGNEMENT DE LA GRILLE.
        # L'encodeur utilisait n_tones // 2 = 9, le decodeur (n_tones - 1)/2 =
        # 8,5 : un DEMI espacement d'ecart, soit 7,81 Hz en DominoEX 8. Chaque
        # ton emis tombait donc exactement a mi-chemin entre deux tons de la
        # grille de reception — le pire cas possible, la decision basculant au
        # hasard entre les deux voisins. D'ou le charabia en boucle locale.
        # C'est le decodeur qui a raison : sa convention centre les 18 tons SUR
        # le curseur RX (milieu de bande = center_freq), alors que celle de
        # l'encodeur decalait toute la bande d'un demi-pas vers le bas.
        mid = (self.n_tones - 1) / 2.0
        return self.center_freq + (tone_idx - mid) * self.spacing

    def _text_to_symbols(self, text):
        # Encodeur DominoEX primaire réel : varicode nibble puis IFK+.
        # Le symbole TX = symbole précédent + nibble + 2 (mod 18).
        symbols = []
        prev = 0
        for c in text:
            for nib in _domino_varienc(c):
                tone = (prev + int(nib) + 2) % self.n_tones
                symbols.append(tone)
                prev = tone
        return symbols

    def encode_text(self, text, amplitude=0.8):
        """Encode du texte en échantillons audio float32.

        IMPORTANT : ancienne version = enveloppe raised-cosine sur CHAQUE symbole.
        En DominoEX 4/8 cela coupe presque le son entre les symboles et donne un TX
        par intermittence. Ici le niveau reste continu, avec seulement un petit
        fondu au début et à la fin du message.
        """
        symbols = self._text_to_symbols(text)
        if not symbols:
            return np.zeros(0, dtype=np.float32)

        sps = int(self.samples_per_symbol)
        all_samples = []

        def make_tone(freq):
            t = np.arange(sps, dtype=np.float32) / float(self.sample_rate)
            chunk = amplitude * np.sin((2.0 * np.pi * freq * t) + self._phase)
            self._phase = (self._phase + 2.0 * np.pi * freq * sps / float(self.sample_rate)) % (2.0 * np.pi)
            return chunk.astype(np.float32, copy=False)

        # Préambule IFK+ : 8 vrais symboles DominoEX (espaces) pour ouvrir AGC/synchro.
        pre_prev = 0
        pre = []
        for _ in range(8):
            for nib in _domino_varienc(' '):
                pre_prev = (pre_prev + int(nib) + 2) % self.n_tones
                pre.append(pre_prev)
        for sym in pre:
            all_samples.append(make_tone(self._tone_freq(sym)))

        # Données continues : changement de tonalité sans couper le niveau audio
        for sym in symbols:
            all_samples.append(make_tone(self._tone_freq(sym)))

        out = np.concatenate(all_samples).astype(np.float32, copy=False)

        # Petit fondu global pour éviter le clac début/fin, sans rendre le signal intermittent
        ramp = min(int(0.006 * self.sample_rate), max(8, len(out)//20))
        if ramp > 1 and len(out) > ramp * 2:
            env = np.ones(len(out), dtype=np.float32)
            env[:ramp] = np.linspace(0.0, 1.0, ramp, dtype=np.float32)
            env[-ramp:] = np.linspace(1.0, 0.0, ramp, dtype=np.float32)
            out *= env
        return out


