# ============================================================================
# TABLES RTTY (portées depuis RTTY_TERMINAL_V1_1_2)
# ============================================================================
BAUDOT = [
    ('\x00','\x00'), ('E','3'),    ('\n','\n'),  ('A','-'),
    (' ',' '),       ('S',"'"),   ('I','8'),     ('U','7'),
    ('\r','\r'),     ('D','\x05'),('R','4'),     ('J','\x07'),
    ('N',','),       ('F','!'),   ('C',':'),     ('K','('),
    ('T','5'),       ('Z','"'),   ('L',')'),     ('W','2'),
    ('H','#'),       ('Y','6'),   ('P','0'),     ('Q','1'),
    ('O','9'),       ('B','?'),   ('G','&'),     ('\x1F','\x1F'),
    ('M','.'),       ('X','/'),   ('V',';'),     ('\x1E','\x1E'),
]
LTRS_SHIFT = 31; FIGS_SHIFT = 27
BAUDOT_LTRS = {ch:i for i,(ch,_) in enumerate(BAUDOT) if ch and ch>=' '}
BAUDOT_FIGS = {ch:i for i,(_,ch) in enumerate(BAUDOT) if ch and ch>=' '}

class RTTYDecoder:
    """Décodeur RTTY FSK Baudot ITA2 + AMTOR/SITOR Mode B."""

    def __init__(self, sample_rate=48000, baud=45, shift=170):
        self.sample_rate = sample_rate
        self.center_freq = 1500.0
        self.baud_rate   = BAUD_RATES.get(baud, 45.45)
        self.shift_hz    = float(shift)
        self.symbol_len  = int(sample_rate / self.baud_rate)
        self._update_freqs()
        self._mode   = 'LTRS'
        self._bits   = []
        self._snr    = 0.0

    def _update_freqs(self):
        self.mark_freq  = self.center_freq + self.shift_hz/2
        self.space_freq = self.center_freq - self.shift_hz/2

    def set_center_freq(self, hz):
        self.center_freq = float(hz); self._update_freqs()

    def set_shift(self, shift_hz):
        self.shift_hz = float(shift_hz); self._update_freqs()

    def set_baud(self, baud):
        self.baud_rate  = BAUD_RATES.get(baud, 45.45)
        self.symbol_len = int(self.sample_rate / self.baud_rate)

    def _goertzel_v(self, chunk, freq):
        N = len(chunk)
        if N == 0: return 0.0
        omega = 2*np.pi*freq/self.sample_rate
        t = np.arange(N, dtype=np.float64)
        real = float(np.sum(chunk * np.cos(omega*t)))
        imag = float(np.sum(chunk * np.sin(omega*t)))
        return real*real + imag*imag

    def process_audio(self, samples):
        samples = np.asarray(samples, dtype=np.float64).flatten()
        decoded = []
        step    = self.symbol_len

        # Accumuler les samples entre les appels
        if not hasattr(self, '_sample_buf'):
            self._sample_buf = np.zeros(0, dtype=np.float64)
        self._sample_buf = np.concatenate([self._sample_buf, samples])

        # Traiter par symboles entiers
        while len(self._sample_buf) >= step:
            chunk = self._sample_buf[:step]
            self._sample_buf = self._sample_buf[step:]

            mark_e = self._goertzel_v(chunk, self.mark_freq)
            spc_e  = self._goertzel_v(chunk, self.space_freq)
            bit    = 1 if mark_e > spc_e else 0

            total  = mark_e + spc_e + 1e-12
            snr_v  = 10*math.log10(max(mark_e,spc_e)/(total/2+1e-12)+1e-6)
            self._snr = 0.9*self._snr + 0.1*max(0, snr_v)

            self._bits.append(bit)

            # Chercher trame : START(0) + 5 bits + STOP(1) + STOP_HALF
            # Le stop dure 1.5 symboles → on consomme 8 bits (stop arrondi à 2)
            while len(self._bits) >= 8:
                if self._bits[0] != 0:
                    # Pas un start bit — glisser d'un bit
                    self._bits.pop(0)
                    continue
                bits5 = self._bits[1:6]
                stop  = self._bits[6]
                if stop != 1:
                    # Stop invalide — glisser
                    self._bits.pop(0)
                    continue
                code = sum(b << i for i, b in enumerate(bits5))
                # Consommer 7 bits + ignorer le demi-stop (bit 7)
                self._bits = self._bits[7:]
                ch = self._decode(code)
                if ch:
                    decoded.append(ch)

        # Limiter la taille du buffer de bits
        if len(self._bits) > 100:
            self._bits = self._bits[-50:]

        return (''.join(decoded), self._snr)

    def _decode(self, code):
        if code < 0 or code >= len(BAUDOT): return ''
        ltrs_ch, figs_ch = BAUDOT[code]
        if code == LTRS_SHIFT: self._mode='LTRS'; return ''
        if code == FIGS_SHIFT: self._mode='FIGS'; return ''
        ch = ltrs_ch if self._mode=='LTRS' else figs_ch
        return ch if ch and ord(ch)>=32 else ''

    def reset(self):
        self._mode='LTRS'; self._bits=[]; self._snr=0.0


# ============================================================================
# ENCODEUR RTTY
# ============================================================================

class RTTYEncoder:
    """Encodeur RTTY FSK Baudot."""

    def __init__(self, sample_rate=48000, baud=45, shift=170, center_freq=1500.0):
        self.sample_rate = int(sample_rate)
        self.center_freq = float(center_freq)
        self._amplitude  = 0.7
        self.baud_rate   = BAUD_RATES.get(baud, 45.45)
        self.shift_hz    = float(shift)
        self.symbol_len  = int(sample_rate / self.baud_rate)
        self._make_syms()

    def set_center_freq(self, hz):
        self.center_freq = float(hz); self._make_syms()

    def set_shift(self, shift_hz):
        self.shift_hz = float(shift_hz); self._make_syms()

    def set_baud(self, baud):
        self.baud_rate  = BAUD_RATES.get(baud, 45.45)
        self.symbol_len = int(self.sample_rate / self.baud_rate)
        self._make_syms()

    def _make_syms(self):
        n    = self.symbol_len
        t    = np.arange(n, dtype=np.float64) / self.sample_rate
        ramp = min(int(self.sample_rate*0.005), n//8)
        env  = np.ones(n, dtype=np.float32)
        if ramp > 0:
            fade = (0.5*(1-np.cos(np.pi*np.arange(ramp)/ramp))).astype(np.float32)
            env[:ramp]=fade; env[-ramp:]=fade[::-1]
        mf = self.center_freq + self.shift_hz/2
        sf = self.center_freq - self.shift_hz/2
        self._mark_sym  = (self._amplitude*np.sin(2*np.pi*mf*t)*env).astype(np.float32)
        self._space_sym = (self._amplitude*np.sin(2*np.pi*sf*t)*env).astype(np.float32)

    def _add_char(self, code, frames):
        n = self.symbol_len
        frames.append(self._space_sym)          # start (SPACE)
        for i in range(5):
            frames.append(self._mark_sym if (code>>i)&1 else self._space_sym)
        frames.append(self._mark_sym)           # stop MARK
        frames.append(self._mark_sym[:n//2])    # stop 1.5

    def encode_text(self, text):
        frames = []; in_figs = False
        n_pre  = max(1, int(self.sample_rate*0.2/self.symbol_len))
        for _ in range(n_pre): frames.append(self._mark_sym)  # préambule MARK
        self._add_char(LTRS_SHIFT, frames); in_figs=False

        for ch in text.upper():
            if ch in BAUDOT_LTRS:
                if in_figs: self._add_char(LTRS_SHIFT,frames); in_figs=False
                self._add_char(BAUDOT_LTRS[ch], frames)
            elif ch in BAUDOT_FIGS:
                if not in_figs: self._add_char(FIGS_SHIFT,frames); in_figs=True
                self._add_char(BAUDOT_FIGS[ch], frames)

        self._add_char(LTRS_SHIFT, frames)
        for _ in range(n_pre): frames.append(self._mark_sym)

        return np.concatenate(frames) if frames else np.zeros(0,dtype=np.float32)


