# ============================================================================
# MULTIDIGI V0.1 F4LPS — ADAPTATEURS DE MODEM (interface commune)
# ============================================================================
# Chaque famille de mode (PSK / OLIVIA / DOMINOEX / RTTY) a été développée
# séparément avec sa propre interface décodeur/encodeur. Plutôt que de
# réécrire ces décodeurs (risqué — Olivia notamment est complexe), on les
# enveloppe derrière une interface COMMUNE, unique point que le reste du
# programme (thread audio RX, thread TX, waterfall) a besoin de connaître :
#
#   process_audio(samples)      -> (texte_decode: str, snr_db: float)
#   set_center_freq(hz)
#   set_mode(nom_du_mode)
#   reset()
#   set_dx_mode(actif)          (no-op si non applicable au mode)
#   set_tx_active(actif)        (no-op si non applicable au mode)
#   push_tx_audio(samples)      (no-op si non applicable au mode)
#
# PSKDecoder/ContinuousPSKDecoder respectent DÉJÀ cette interface (RIEN n'a
# changé pour PSK — c'est le mode de référence). Olivia/DominoEX/RTTY sont
# enveloppés ci-dessous.
# ============================================================================

class _OliviaModemAdapter:
    """Adapte OliviaDecoder (process_audio -> 3-tuple) à l'interface commune."""
    def __init__(self, sample_rate=48000, mode="OLIVIA 8/250"):
        self._d = OliviaDecoder(sample_rate, mode)

    def process_audio(self, samples):
        text, snr, _extra = self._d.process_audio(samples)
        return text, snr

    def set_center_freq(self, hz):
        try:
            self._d.set_center_freq(float(hz))
        except Exception:
            pass

    def set_mode(self, mode_name):
        try:
            self._d.set_mode(mode_name)
        except Exception:
            pass

    def reset(self):
        try:
            self._d.reset()
        except Exception:
            pass

    def set_dx_mode(self, enabled=True):
        pass  # pas de mode DX spécifique côté Olivia

    def set_auto_center(self, enabled):
        """MULTIDIGI V0.1 F4LPS : active/désactive le centrage fin automatique
        interne d'Olivia (existant dans le décodeur mais jamais branché
        auparavant -- rien nulle part ne mettait ce drapeau à True)."""
        try:
            self._d.auto_center_enabled = bool(enabled)
        except Exception:
            pass

    def set_tx_active(self, active=True):
        pass  # Olivia ne fait rien de particulier pendant le TX local

    def push_tx_audio(self, samples):
        pass

    def __getattr__(self, name):
        return getattr(self._d, name)


class _DominoEXModemAdapter:
    """Adapte DominoEXDecoder (push_samples au lieu de process_audio,
    pas de notion de SNR exposée) à l'interface commune."""
    def __init__(self, sample_rate=48000, mode="DominoEX 8"):
        self._d = DominoEXDecoder(sample_rate, mode)

    def process_audio(self, samples):
        text, _mag = self._d.push_samples(samples)
        # V0.1 : DominoEXDecoder ne calcule pas de SNR dédié pour l'instant.
        # 0.0 est affiché tel quel — pas une valeur inventée, juste "non
        # disponible" pour ce mode en attendant un futur ajout côté décodeur.
        return text, 0.0

    def set_center_freq(self, hz):
        try:
            self._d.set_center_freq(float(hz))
        except Exception:
            pass

    def set_mode(self, mode_name):
        try:
            self._d.set_mode(mode_name)
        except Exception:
            pass

    def reset(self):
        pass  # DominoEXDecoder n'expose pas de reset() dédié pour l'instant

    def set_dx_mode(self, enabled=True):
        pass

    def set_tx_active(self, active=True):
        pass

    def push_tx_audio(self, samples):
        pass

    def __getattr__(self, name):
        return getattr(self._d, name)


# Table de correspondance nom de mode RTTY -> (bauds, décalage Hz). Valeurs
# standard amateur (identiques à fldigi/MultiPsk pour ces libellés).
_RTTY_MODE_PARAMS = {
    "RTTY 45":  (45.45, 170.0),
    "RTTY 50":  (50.0,  170.0),
    "RTTY 75":  (75.0,  170.0),
    "RTTY 100": (100.0, 170.0),
}
RTTY_MODE_NAMES = list(_RTTY_MODE_PARAMS.keys())


class _RTTYModemAdapter:
    """Adapte RTTYDecoder (set_baud/set_shift séparés, pas de set_mode
    unique) à l'interface commune."""
    def __init__(self, sample_rate=48000, mode="RTTY 45"):
        baud, shift = _RTTY_MODE_PARAMS.get(mode, (45.45, 170.0))
        self._d = RTTYDecoder(sample_rate, baud=baud, shift=shift)

    def process_audio(self, samples):
        return self._d.process_audio(samples)

    def set_center_freq(self, hz):
        try:
            self._d.set_center_freq(float(hz))
        except Exception:
            pass

    def set_mode(self, mode_name):
        baud, shift = _RTTY_MODE_PARAMS.get(mode_name, (45.45, 170.0))
        try:
            self._d.set_baud(baud)
            self._d.set_shift(shift)
        except Exception:
            pass

    def reset(self):
        try:
            self._d.reset()
        except Exception:
            pass

    def set_dx_mode(self, enabled=True):
        pass

    def set_tx_active(self, active=True):
        pass

    def push_tx_audio(self, samples):
        pass

    def __getattr__(self, name):
        return getattr(self._d, name)


class _DominoEXEncoderAdapter:
    """DominoEXEncoder n'a pas de set_center_freq() (juste un attribut
    center_freq direct) -- c'est CE bug précis qui faisait planter le TX
    (AttributeError). Corrigé ici."""
    def __init__(self, sample_rate=48000, mode="DominoEX 8", center_freq=1500.0):
        self._e = DominoEXEncoder(sample_rate, mode, center_freq)

    def set_mode(self, mode_name):
        try:
            self._e.set_mode(mode_name)
        except Exception:
            pass

    def set_center_freq(self, hz):
        self._e.center_freq = float(hz)

    def encode_text(self, text):
        return self._e.encode_text(text)

    def __getattr__(self, name):
        # V0.1 F4LPS : délégation automatique -- tout attribut non défini ici
        # (baud_rate, mode_name, center_freq... utilisés par l'affichage
        # "Vérif TX" et les diagnostics) est lu directement sur l'objet réel
        # au lieu de silencieusement renvoyer une valeur par défaut (0, '?').
        return getattr(self._e, name)


class _RTTYEncoderAdapter:
    """RTTYEncoder attend baud/shift au constructeur plutôt qu'un nom de
    mode ; cet adaptateur garde la même interface encode_text/set_mode que
    les autres encodeurs."""
    def __init__(self, sample_rate=48000, mode="RTTY 45", center_freq=1500.0):
        baud, shift = _RTTY_MODE_PARAMS.get(mode, (45.45, 170.0))
        self._e = RTTYEncoder(sample_rate, baud=baud, shift=shift, center_freq=center_freq)

    def set_mode(self, mode_name):
        baud, shift = _RTTY_MODE_PARAMS.get(mode_name, (45.45, 170.0))
        try:
            self._e.set_baud(baud)
            self._e.set_shift(shift)
        except Exception:
            pass

    def set_center_freq(self, hz):
        try:
            self._e.set_center_freq(float(hz))
        except Exception:
            pass

    def encode_text(self, text):
        return self._e.encode_text(text)

    def __getattr__(self, name):
        return getattr(self._e, name)


