class FeldHellEncoder:
    """Texte -> audio Feld Hell (OOK d'une porteuse).

    Interface alignee sur les autres encodeurs de MultiDigi : set_mode,
    set_center_freq, encode_text, sample_rate, _amplitude. La premiere version
    n'avait aucune de ces methodes — elle ne servait qu'a mes tests — et
    faisait planter le programme au choix de la famille HELL.

    Chaque caractere est peint comme une matrice de 7 lignes sur 7 colonnes
    (glyphe 5 colonnes + 2 de separation), emise colonne par colonne.
    """
    def __init__(self, sample_rate=44100, mode="FELD HELL", center=1500.0):
        self.sample_rate = float(sample_rate)
        self._amplitude = 0.5
        self.center = float(center)
        self.set_mode(mode)

    def set_mode(self, mode):
        p = HELL_MODES.get(mode, HELL_MODES["FELD HELL"])
        self.mode = mode
        self.prate = float(p["pixel_rate"])
        self.rows = int(p["rows"])
        self.spp = self.sample_rate / self.prate

    def set_center_freq(self, hz):
        self.center = float(hz)

    def text_to_bitmap(self, texte):
        """Convertit du texte en matrice (7, n). Inconnu -> espace."""
        vide = HELL_FONT_5x7[' ']
        cols = []
        for ch in str(texte or '').upper():
            g = HELL_FONT_5x7.get(ch, vide)
            for x in range(5):
                cols.append([int(g[y][x]) for y in range(7)])
            cols.append([0] * 7)      # 2 colonnes de separation
            cols.append([0] * 7)
        if not cols:
            return np.zeros((7, 0), dtype=np.uint8)
        return np.array(cols, dtype=np.uint8).T

    def encode_text(self, texte):
        return self.encode_bitmap(self.text_to_bitmap(texte))

    def encode_bitmap(self, bm):
        """bm : tableau (rows, ncols) de 0/1, emis colonne par colonne."""
        bm = np.asarray(bm)
        if bm.size == 0:
            return np.zeros(0, dtype=np.float32)
        # V0.10b F4LPS : le Feld Hell emet une colonne DE BAS EN HAUT. Sans ce
        # retournement, notre emission serait lue tete en bas par les autres
        # stations. Le defaut etait invisible en boucle locale (encodeur et
        # decodeur partageaient la meme erreur) ; il n'est apparu qu'en
        # corrigeant la reception sur un signal reel.
        seq = bm[::-1, :].T.reshape(-1)
        n = int(round(len(seq) * self.spp))
        t = np.arange(n) / self.sample_rate
        porteuse = np.sin(2 * np.pi * self.center * t)
        idx = np.clip((np.arange(n) / self.spp).astype(int), 0, len(seq) - 1)
        env = seq[idx].astype(np.float64)
        # Fronts adoucis : un OOK a flancs raides occuperait toute la bande.
        k = max(3, int(self.spp * 0.35)) | 1
        env = np.convolve(env, np.hanning(k) / np.hanning(k).sum(), mode='same')
        return (porteuse * env * float(self._amplitude)).astype(np.float32)


class FeldHellDecoder:
    """Audio -> colonnes de 7 niveaux de gris. Pas de texte : Hell est une image."""
    INTERNAL_SR = 8000.0

    def __init__(self, sample_rate=44100, mode="FELD HELL"):
        self.sample_rate = float(sample_rate)
        self.set_mode(mode)

    def set_mode(self, mode):
        p = HELL_MODES.get(mode, HELL_MODES["FELD HELL"])
        self.mode = mode
        self.prate = float(p["pixel_rate"]); self.rows = int(p["rows"])
        self.bw = float(p["bandwidth"])
        self._center = 1500.0
        self.reset()

    def reset(self):
        self._buf = np.zeros(0, dtype=np.float64)
        self._phase = 0.0
        self._pxpos = 0.0
        self._col = []
        self._agc = 1e-6
        self._rs_prev = np.zeros(0); self._rs_pos = 0.0
        self._rs_b = None; self._rs_zi = None

    def set_center_freq(self, hz):
        self._center = float(hz)

    def _to_8k(self, x):
        if int(self.sample_rate) == int(self.INTERNAL_SR):
            return np.asarray(x, dtype=np.float64)
        if self._rs_b is None:
            # V0.8c F4LPS : ce fichier importe scipy sous les alias
            # _sp_firwin / _sp_lfilter. Les noms nus firwin/lfilter, herites
            # de mon module de test, n'existent pas ici : le decodeur Hell
            # levait « name 'firwin' is not defined » a chaque bloc audio.
            self._rs_b = _sp_firwin(63, 3500.0 / (self.sample_rate / 2.0))
            self._rs_zi = np.zeros(62)
        y, self._rs_zi = _sp_lfilter(self._rs_b, [1.0], np.asarray(x, dtype=np.float64), zi=self._rs_zi)
        buf = np.concatenate([self._rs_prev, y])
        ratio = self.sample_rate / self.INTERNAL_SR
        pos = self._rs_pos; avail = len(buf) - 1 - pos
        if avail < 0:
            self._rs_prev = buf; return np.zeros(0)
        n = int(np.floor(avail / ratio)) + 1
        idx = pos + np.arange(n) * ratio
        i0 = idx.astype(np.int64); fr = idx - i0
        out = buf[i0] * (1 - fr) + buf[i0 + 1] * fr
        npos = pos + n * ratio; keep = min(int(np.floor(npos)), len(buf))
        self._rs_prev = buf[keep:]; self._rs_pos = npos - keep
        return out

    def process_audio(self, chunk):
        """Retourne une liste de colonnes, chacune un vecteur de `rows` valeurs 0..1."""
        x = self._to_8k(np.asarray(chunk, dtype=np.float64).flatten())
        if len(x) == 0:
            return []
        # melange complexe vers la bande de base, puis detection d'enveloppe
        n = len(x)
        t = (self._phase + np.arange(n)) / self.INTERNAL_SR
        self._phase += n
        bb = x * np.exp(-2j * np.pi * self._center * t)
        b = _sp_firwin(63, min(0.95, (self.bw * 0.6) / (self.INTERNAL_SR / 2.0)))
        bb = np.convolve(bb, b, mode='same')
        env = np.abs(bb)
        self._buf = np.concatenate([self._buf, env])
        spp = self.INTERNAL_SR / self.prate
        cols = []
        # Position fractionnaire conservee : a 122,5 px/s et 8 kHz, spp vaut
        # 65,306 echantillons. Tronquer a 65 fait deriver d'un pixel toutes
        # les 218 colonnes, ce qui suffit a rendre l'image illisible.
        while len(self._buf) >= spp + 2:
            self._pxpos = getattr(self, '_pxpos', 0.0)
            k = int(round(self._pxpos + spp)) - int(round(self._pxpos))
            k = max(1, k)
            px = float(np.mean(self._buf[:k]))
            self._buf = self._buf[k:]
            self._pxpos = (self._pxpos + spp) - k
            self._agc = max(self._agc * 0.999, px, 1e-6)
            self._col.append(min(1.0, px / self._agc))
            if len(self._col) >= self.rows:
                cols.append(np.array(self._col[:self.rows]))
                self._col = self._col[self.rows:]
        return cols


class _HellModemAdapter:
    """Expose le decodeur Hell avec la meme interface que les autres familles.

    process_audio() doit rendre (texte, snr) : c'est ce que PSKAudioThread
    depaquette. V0.14 F4LPS : cet adaptateur renvoyait trois valeurs, ce qui
    levait une ValueError a chaque bloc (sans consequence visible ici puisque
    Hell n'affiche pas de texte, mais le bug etait le meme que pour le CW). Hell
    ne produit pas de texte : on renvoie une chaine vide et on empile les
    colonnes dans une file que la fenetre d'affichage vient consommer. Le
    pipeline existant n'a ainsi pas besoin d'etre modifie.
    """
    def __init__(self, sample_rate, mode="FELD HELL"):
        self._d = FeldHellDecoder(sample_rate, mode)
        self.columns = []
        self._snr = 0.0

    def process_audio(self, chunk):
        try:
            cols = self._d.process_audio(chunk)
        except Exception as e:
            print(f"HELL: {e}")
            return ('', self._snr)
        if cols:
            self.columns.extend(cols)
            if len(self.columns) > 4000:
                self.columns = self.columns[-4000:]
        return ('', self._snr)

    def take_columns(self):
        c = self.columns
        self.columns = []
        return c

    def __getattr__(self, name):
        return getattr(self._d, name)


# ============================================================================
# V0.9 F4LPS — DÉCODEUR CW (extrait de CW Terminal V1.8 V3 DSP)
# ============================================================================
# Décodeur repris TEL QUEL depuis CW Terminal : CWPostProcessor,
# V124AGCDecoder et sa surcouche V3ProNoiseGateDecoder (anti-bruit, anti faux
# E/T/I). Aucune ligne de la chaîne DSP n'a été modifiée — c'est exactement le
# code qui tourne déjà chez F4LPS.
#
# NON REPRIS volontairement : synthèse vocale, automate de contexte QSO,
# affichage VFO, OmniRig/CAT, scan de bande, et les quatre autres décodeurs
# du banc d'essai (OZ1JHM, template matching, Goertzel, CWGet). Un seul
# décodeur, le plus abouti.
#
# IMPORTS : le décodeur appelle butter/lfilter/hilbert par leur nom NU, alors
# que MULTIDIGI importe scipy sous les alias _sp_firwin/_sp_lfilter. hilbert
# n'est même importé nulle part ailleurs dans ce fichier. Sans l'import ci-
# dessous, le décodeur lèverait « name 'hilbert' is not defined » à chaque
# bloc audio — exactement la panne rencontrée sur Feld Hell en V0.8.
# ============================================================================
try:
    from scipy.signal import butter, lfilter, hilbert, sosfilt, sosfilt_zi
except Exception:
    butter = lfilter = hilbert = sosfilt = sosfilt_zi = None

class CWPostProcessor:
    """Post-traitement linguistique pour CW - Correction agressive V1.55"""
    
    # Substitutions agressives fréquentes en CW bruité
    CHAR_SUBSTITUTIONS = {
        # Chiffres ↔ Lettres (confusions CW classiques)
        'O': '0', '0': 'O',
        'I': '1', '1': 'I',
        'S': '5', '5': 'S',
        'Z': '2', '2': 'Z',
        'B': '8', '8': 'B',
        'G': '6', '6': 'G',
        'T': '7', '7': 'T',
        'A': '4', '4': 'A',
        'E': '3', '3': 'E',
        # Confusions lettres ↔ lettres fréquentes en CW bruité
        'Q': 'O', 'U': 'V', 'V': 'U',
        'N': 'M', 'D': 'B', 'K': 'R',
        'F': 'L', 'X': 'H', 'W': 'M',
    }
    
    # Mots qui PRECEDENT systématiquement un indicatif en CW
    CALLSIGN_PRECURSORS = {
        'DE', 'QRZ', 'QSL', 'PSE', 'BK',
        # Contexte contest
        'CQ', 'NR', 'TNX', 'TU', 'UR', 'RST',
        'ES', 'AGN', 'SRI', 'GL', 'GD', 'HW',
        # Après un RST ou numéro
        '599', '5NN', '559', '579', '339',
    }

    def __init__(self, q_codes, cw_abbrev, country_prefixes):
        self.q_codes = q_codes
        self.cw_abbrev = cw_abbrev
        self.country_prefixes = country_prefixes
        self.max_distance = 1  # était 2 — POUR→PWR, WTH→21H évités
        self._prev_word = ''
        self._expect_callsign = False
        # V1.55 : buffer pour fusion de fragments d'indicatif
        self._callsign_fragment = ''   # ex: "SP7U" en attente de "ZX"
        self._fragment_count = 0       # nb de mots depuis le fragment
        
    def fix_qcode(self, word):
        """Corrige un Q-code avec distance ≤ 2"""
        word_upper = word.upper()
        
        # Déjà correct ?
        if word_upper in self.q_codes:
            return word_upper, True
        
        # Commence par Q + 2-3 lettres ?
        if not (word_upper.startswith('Q') and 3 <= len(word_upper) <= 4):
            return word, False
        
        # Cherche le Q-code le plus proche
        best_match = None
        best_distance = self.max_distance + 1
        
        for qcode in self.q_codes:
            dist = levenshtein_distance(word_upper, qcode)
            if dist < best_distance:
                best_distance = dist
                best_match = qcode
        
        if best_distance <= self.max_distance:
            return best_match, True
        
        return word, False
    
    def fix_abbreviation(self, word):
        """Corrige une abréviation CW avec distance ≤ 1.
        Ne corrige QUE les mots courts (≤ 5 chars) pour éviter
        POUR→PWR, SPECIAL→?, PRESENTATION→? etc.
        """
        word_upper = word.upper()

        # Déjà correct ?
        if word_upper in self.cw_abbrev:
            return word_upper, True

        # Ne pas tenter la correction sur les mots longs (langue naturelle)
        if len(word_upper) > 5:
            return word, False

        # Cherche l'abréviation la plus proche (distance ≤ 1 seulement)
        best_match = None
        best_distance = self.max_distance + 1

        for abbrev in self.cw_abbrev:
            # Ne comparer qu'avec des abréviations de longueur similaire (±1)
            if abs(len(word_upper) - len(abbrev)) > 1:
                continue
            dist = levenshtein_distance(word_upper, abbrev)
            if dist < best_distance:
                best_distance = dist
                best_match = abbrev

        if best_distance <= self.max_distance:
            return best_match, True

        return word, False
    
    # Mots CW/contest qui ressemblent à des indicatifs mais n'en sont pas
    _NOT_CALLSIGN = {
        '5NN','5NN?','599','559','579','529','339','449','479','589',
        '5NE','5NB','5NC','5ND','5NF','5NG','5NH','5NI','5NJ','5NK',
        '73','88','33','55','44','99','5BD',
        'TU','TNX','TNKS','TKS','QTH','QRZ','QSL','QSB','QRM','QRN',
        'QRP','QRO','QSY','QRT','QRX','CQ','DE','ES','UR','UP','DWN',
        'PSE','PLZ','NR','NRS','AGN','HW','BK','SK','KN','AR','AS',
        'CUL','CUU','GUD','GD','GL','GM','GE','GA','GN','GB',
    }

    def is_callsign_pattern(self, word):
        """Vérifie si le mot ressemble à un indicatif, y compris formats spéciaux type DM50GFS."""
        import re
        w = word.upper().strip()

        if not w or w in self._NOT_CALLSIGN:
            return False
        # RST contest : chiffre + 2 mêmes lettres (5NN, 5TT, 9AA...)
        if len(w) == 3 and w[0].isdigit() and w[1].isalpha() and w[1] == w[2]:
            return False
        if len(w) == 3 and w[0].isdigit() and w[1].isalpha() and w[2].isdigit():
            return False

        # Indicatif standard : prefixe (1-3) + 1 ou 2 chiffres + suffixe (1-6)
        pattern = r'^(?P<prefix>[A-Z]{1,3})(?P<num>\d{1,2})(?P<suffix>[A-Z0-9]{1,6})(/[A-Z0-9]{1,4})?$'
        m = re.match(pattern, w)
        if not m:
            return False

        prefix = m.group('prefix')
        suffix = m.group('suffix')
        if len(suffix) < 1:
            return False

        for plen in [3, 2, 1]:
            candidate = prefix[:plen]
            if candidate in self.country_prefixes:
                return True
        return False

    def is_callsign_prefix(self, word):
        """Détecte un fragment d'indicatif encore incomplet."""
        import re
        word_upper = word.upper().strip()
        # préfixe 1-3 lettres + 1 ou 2 chiffres + suffixe encore très court (1 caractère)
        m = re.match(r'^(?P<prefix>[A-Z]{1,3})(?P<num>\d{1,2})(?P<suffix>[A-Z0-9]{1})$', word_upper)
        if not m:
            return False
        prefix = m.group('prefix')
        for plen in [3, 2, 1]:
            if prefix[:plen] in self.country_prefixes:
                return True
        return False

    def fix_callsign(self, word):
        """Corrige un indicatif avec substitutions agressives, y compris formats spéciaux à 2 chiffres."""
        word_upper = word.upper().strip()

        if self.is_callsign_pattern(word_upper):
            return word_upper, True

        variants = self._generate_variants(word_upper, max_subs=2 if len(word_upper) >= 6 else 1)
        for variant in variants:
            if self.is_callsign_pattern(variant):
                return variant, True

        return word, False

    def _generate_variants(self, word, max_subs=2):
        """Génère des variantes avec substitutions de caractères."""
        if max_subs == 0:
            return [word]

        variants = set([word])

        for i, char in enumerate(word):
            if char in self.CHAR_SUBSTITUTIONS:
                replacement = self.CHAR_SUBSTITUTIONS[char]
                new_word = word[:i] + replacement + word[i+1:]
                variants.add(new_word)

                if max_subs > 1:
                    sub_variants = self._generate_variants(new_word, max_subs - 1)
                    variants.update(sub_variants)

        return list(variants)

    def process_word(self, word):
        """
        Traite un mot avec contexte CW — V1.5b : fusion fragments + détection CQ répété.
        Si un mot court (2-4 chars) apparaît 3× de suite → probablement CQ CQ CQ.
        """
        import re
        if not word or len(word) < 2:
            self._prev_word = word
            self._callsign_fragment = ''
            return word, 'normal'

        word_upper = word.upper()

        # V1.5 : détection CQ répété améliorée
        # Variantes directes connues de CQ (confusions CW typiques)
        CQ_VARIANTS = {
            'CQ','GQ','CO','KQ','CR','TQ','LQ','CK','CP','DQ','CG',
            'OQ','AQ','EQ','QQ','CN','CF','CV','CB','CI','CX','CY','CJ',
        }
        NOT_CQ = {'DE','TU','AR','SK','BK','OK','ES','KN','QSL','QSO',
                  'PSE','TNX','TKS','NR','OM','YL','FB','HI','GL'}

        def _looks_like_cq(w):
            """Mot de 2 chars proche de CQ morphologiquement."""
            if w in CQ_VARIANTS: return True
            if len(w) == 2:
                # Distance Levenshtein ≤ 1 avec CQ
                if w[1] in 'QROKG' and w[0] in 'CGKDT': return True
                if w[0] == 'C' and w[1] not in 'AEIOU': return True
            return False

        if not hasattr(self, '_cq_buf'): self._cq_buf = []
        if not hasattr(self, '_repeat_buf'): self._repeat_buf = []

        if len(word_upper) <= 4 and word_upper.isalpha() and word_upper not in NOT_CQ:
            self._cq_buf.append(word_upper)
            if len(self._cq_buf) > 5: self._cq_buf.pop(0)
            self._repeat_buf.append(word_upper)
            if len(self._repeat_buf) > 4: self._repeat_buf.pop(0)

            # Cas 1 : 3 mots identiques courts → CQ CQ CQ
            if (len(self._repeat_buf) >= 3 and
                    len(set(self._repeat_buf[-3:])) == 1):
                self._repeat_buf.clear(); self._cq_buf.clear()
                self._expect_callsign = False
                self._prev_word = 'CQ'
                return 'CQ', 'qcode'

            # Cas 2 : 2+ mots similaires à CQ parmi les 3 derniers
            last3 = self._cq_buf[-3:]
            cq_like = sum(1 for w in last3 if _looks_like_cq(w))
            if len(last3) >= 2 and cq_like >= 2:
                self._cq_buf.clear(); self._repeat_buf.clear()
                self._expect_callsign = False
                self._prev_word = 'CQ'
                return 'CQ', 'qcode'

            # Cas 3 : mot actuel = variante directe de CQ
            if word_upper in CQ_VARIANTS and word_upper != 'CQ':
                # Confirme seulement si contexte cohérent (précédé d'un CQ-like)
                prev_cq = any(_looks_like_cq(w) for w in self._cq_buf[:-1])
                if prev_cq:
                    self._expect_callsign = False
                    self._prev_word = 'CQ'
                    return 'CQ', 'qcode'
        else:
            self._repeat_buf.clear()
            if word_upper in NOT_CQ:
                self._cq_buf.clear()

        # V1.55 : tentative de fusion avec fragment en attente
        if self._callsign_fragment and self._fragment_count <= 1:
            merged = self._callsign_fragment + word_upper
            corrected_m, is_cs_m = self.fix_callsign(merged)
            if is_cs_m:
                # Fusion réussie ! On retourne l'indicatif complet
                self._callsign_fragment = ''
                self._fragment_count = 0
                self._prev_word = corrected_m
                return corrected_m, 'callsign'
            # Fusion échouée — invalide le fragment
            self._callsign_fragment = ''
            self._fragment_count = 0
        elif self._callsign_fragment:
            self._callsign_fragment = ''
            self._fragment_count = 0
        else:
            self._fragment_count = max(0, self._fragment_count - 1)

        # 1. Q-code ?
        corrected, is_qcode = self.fix_qcode(word)
        if is_qcode:
            if corrected == 'CQ':
                self._expect_callsign = False
            else:
                self._expect_callsign = (corrected in self.CALLSIGN_PRECURSORS)
            self._prev_word = corrected
            return corrected, 'qcode'

        # 2. Abréviation ? (DE, TU, BK...)
        corrected, is_abbrev = self.fix_abbreviation(word)
        if is_abbrev:
            if corrected == 'CQ':
                self._expect_callsign = False
                self._cq_count = getattr(self, '_cq_count', 0) + 1
            else:
                self._expect_callsign = (corrected in self.CALLSIGN_PRECURSORS)
                self._cq_count = 0
            self._prev_word = corrected
            return corrected, 'abbrev'

        # 3. Indicatif attendu apres DE/CQ/QRZ -> on force
        if self._expect_callsign:
            self._expect_callsign = False
            corrected, is_cs = self.fix_callsign(word)
            if is_cs:
                self._prev_word = corrected
                # V1.55 : si suffixe court → mettre en attente de fusion
                if self.is_callsign_prefix(corrected):
                    self._callsign_fragment = corrected
                    self._fragment_count = 1
                return corrected, 'callsign'
            if re.match(r'^[A-Z0-9]{3,10}$', word_upper):
                self._prev_word = word_upper
                return word_upper, 'callsign'

        # 4. Indicatif standard ?
        corrected, is_callsign = self.fix_callsign(word)
        if is_callsign:
            self._prev_word = corrected
            # V1.55 : indicatif avec suffixe trop court → stocker pour fusion
            if self.is_callsign_prefix(corrected):
                self._callsign_fragment = corrected
                self._fragment_count = 1
            return corrected, 'callsign'

        # 5. Mot précédent = indicatif → répétition probable
        if self._prev_word and self.is_callsign_pattern(self._prev_word):
            corrected, is_cs = self.fix_callsign(word)
            if is_cs:
                self._prev_word = corrected
                return corrected, 'callsign'

        # V1.55 : le mot courant seul ne ressemble pas à un indicatif
        # mais si prev_word était un fragment, tenter fusion avec substitutions
        if self._prev_word and self.is_callsign_prefix(self._prev_word):
            if re.match(r'^[A-Z0-9]{1,4}$', word_upper) and len(word_upper) <= 4:
                merged = self._prev_word + word_upper
                corrected_m, is_cs_m = self.fix_callsign(merged)
                if is_cs_m:
                    self._prev_word = corrected_m
                    return corrected_m, 'callsign'

        self._prev_word = word_upper
        return word, 'normal'

# ============================================================================
# CW DECODER V12.4 - AGC + GOERTZEL
# ============================================================================



