    def __init__(self, sample_rate=48000):
        self.sample_rate = sample_rate
        
        # Post-processor CW (Correction Q-codes, abréviations, indicatifs)
        self.postprocessor = CWPostProcessor(
            self.Q_CODES, 
            self.CW_ABBREVIATIONS, 
            self.COUNTRY_PREFIXES
        )
        self.enable_postprocess = False  # BRUT par défaut  # Activé par défaut
        self.current_word_buffer = ""  # Buffer pour le mot en cours
        
        # État FSM
        self.state = self.STATE_IDLE
        self.tone_start_time = 0
        self.space_start_time = 0
        # V0.24 F4LPS : file des SILENCES, pour en deduire les seuils
        # d'espacement par mesure plutot que par calcul (voir _calibrate_spaces).
        self.space_durations = deque(maxlen=60)
        self._char_space_thr = 0.0
        self._word_space_thr = 0.0
        self.last_char_time = 0  # NOUVEAU - pour timeout
        
        # Buffer morse
        self.current_morse = ""
        self.decoded_text = ""
        
        # Timeout pour forcer fin de mot — 500ms à 28 WPM (7 dits = ~300ms)
        self.word_timeout = 0.8  # 800ms — identique v135
        
        # Tracking FFT
        self.base_pitch = 640
        self.detected_pitch = self.base_pitch
        self.pitch_offset = 0
        self.pitch_locked = False
        self.last_fft_scan = 0
        self.fft_scan_interval = 0.2
        # Mode pitch
        self.auto_pitch = True          # suivi automatique FFT
        self.user_pitch_lock = False    # verrouillage manuel utilisateur
        # AUTO mode: 'strongest' (pile-up), 'base' (guide avec la ligne rouge), 'selected' (clic sur signal)
        self.auto_mode = 'strongest'
        self.preferred_pitch = None  # Hz (mode 'selected')
        self.follow_strongest = True   # compat (dérivé de auto_mode)
        self.manual_pitch = self.base_pitch

        # AFC: au premier lock FFT, base_pitch = detected_pitch
        self.auto_center_enabled = True
        self.auto_center_done = False

        
        # Stabilisation autopitch : vote sur les derniers pics avant de bouger
        self.peak_history = deque(maxlen=5)      # historique des 5 derniers pics détectés
        self._stable_candidate = None             # candidat en cours de validation
        self._stable_candidate_count = 0          # combien de fois ce candidat a été vu
        self._ema_pitch = 0.0                     # lissage EMA du pitch détecté
        self._STABLE_VOTES_REQUIRED = 3           # doit apparaître 3x d'affilée pour accepter
        self._MIN_MOVE_HZ = 20                    # déplacement minimum pour bouger (Hz)
        self._MAX_JUMP_HZ = 200                   # saut max acceptable en un scan (Hz)
        self._TRACK_DEADBAND_HZ = 18              # zone morte: ne pas suivre les micro-dérives
        self._TRACK_MAX_STEP_HZ = 6               # pas max par scan pour éviter la dérive lente
        self._tracking_lost_count = 0             # perte de tracking prolongée
        self._tracking_last_good_t = 0.0          # dernier instant avec pic crédible
        self._pitch_candidate = None              # candidat de déplacement en validation
        self._pitch_candidate_since = 0.0

        # Buffer d'accumulation pour la FFT autopitch
        # chunk_size=512 est trop petit (résolution 93Hz/bin à 48kHz)
        # On accumule jusqu'à 8192 samples → résolution ~6Hz/bin à 48kHz
        self._fft_accum = np.zeros(8192, dtype=np.float32)
