                      f"{getattr(d,'_n81_word_threshold',0.0):.2f} "
                      f"N82raw={getattr(d,'_n82_last_raw_word','')} "
                      f"N82fin={getattr(d,'_n82_last_final_word','')} "
                      f"N82corr={getattr(d,'_n82_last_correction','NONE')} "
                      f"N82ok={getattr(d,'_n82_corrected_words',0)} "
                      f"N82plain={getattr(d,'_n82_raw_words',0)} "
                      f"N83gap={getattr(d,'_next_last_gap','-')} "
                      f"N83src={getattr(d,'_n83_gap_source','?')} "
