    # ------------------------------------------------------------------
    # V64 — probe ordre/polarité LLR. Diagnostic seulement.
    # ------------------------------------------------------------------
    @staticmethod
    def _v64_apply_llr_mapping(llr, mapping_name):
        a = np.asarray(llr, dtype=np.float32).flatten()
        if a.size != 174:
            return a.copy()

        trip = a.reshape(58,3)
        name = str(mapping_name or "NORMAL").upper()
        sign = False

        if name.endswith("_SIGN"):
            sign = True
            name = name[:-5]

        if name == "NORMAL":
            out = a.copy()
        elif name == "SIGN_INV":
            out = -a.copy()
            sign = False
        elif name == "TRIPLET_210":
            out = trip[:, [2,1,0]].reshape(-1).copy()
        elif name == "TRIPLET_021":
            out = trip[:, [0,2,1]].reshape(-1).copy()
        elif name == "TRIPLET_102":
            out = trip[:, [1,0,2]].reshape(-1).copy()
        elif name == "TRIPLET_120":
            out = trip[:, [1,2,0]].reshape(-1).copy()
        elif name == "TRIPLET_201":
            out = trip[:, [2,0,1]].reshape(-1).copy()
        elif name == "REVERSE174":
            out = a[::-1].copy()
        else:
            out = a.copy()

        if sign:
            out = -out

        return out

    def _v65_log_probe_row(self, row):
        """Ecriture robuste : aucune exception de probe ne reste invisible."""
        try:
            cols = [
                "V65",
                str(row.get("local","")),
                f'{float(row.get("epoch",0.0)):.6f}',
                f'{float(row.get("center",0.0)):.3f}',
                f'{float(row.get("start",0))/12000.0:.6f}',
                str(row.get("frontend","")),
                str(row.get("pass_name","")),
                str(row.get("mapping","")),
                str(int(row.get("checks",87))),
                "YES" if bool(row.get("ok",False)) else "NO",
                "OK" if bool(row.get("crc",False)) else "NO",
                str(row.get("raw12","")).replace('"',"'").replace("\\n"," "),
                str(int(row.get("hard_errors",-1))),
                str(int(row.get("iterations",0))),
                str(row.get("note","")),
                str(row.get("error","")).replace('"',"'").replace("\\n"," "),
            ]
            with open(self._v65_llr_probe_path, "a", encoding="utf-8") as fp:
                # Quote text-bearing fields safely enough for Excel/CSV.
                fp.write(
                    ",".join(
                        f'"{v}"' if ("," in v or '"' in v or " " in v) else v
                        for v in cols
                    ) + "\\n"
                )
        except Exception as exc:
            try:
                print("⚠️ V65 log row:", type(exc).__name__, exc)
            except Exception:
                pass

    def _v65_decoded87_from_cw(self, c, cw):
        """Reproduit exactement la fin de bpdecode174_87 pour le diagnostic.

        IMPORTANT : le codeword LDPC n'est pas systématique dans son ordre
        interne. Il faut COLORDER avant de prendre les 87 derniers bits.
        """
        try:
            arr = np.asarray(cw, dtype=np.int8).flatten()
            if arr.size != 174:
                return None
            order = np.asarray(c._JS8_COLORDER, dtype=np.int32)
            if order.size != 174:
                return None
            reordered = arr[order]
            return reordered[87:174].astype(np.int8)
        except Exception:
            return None

    def _v65_probe_llr_order(self, c, powers, frontend, center_hz,
                             start, snapshot_epoch, preferred_pass=None):
        """V65 : teste les passes REELLES + ordre/polarité des 174 LLR.

        Le point clé par rapport à V64 :
          - on ne teste plus seulement AMP/LOG bruts ;
          - on recrée A1/L2/A3/A4, LOG x3.25..4.00 et L-W4..12 ;
          - CHAQUE pass est soumis aux mappings historiques ;
          - raw12 diagnostique reconstruit avec COLORDER correct ;
          - tout échec Python est écrit dans le CSV.

        La validation reste stricte : seul LDPC convergé + CRC OK peut être
        renvoyé comme vrai décodage.
        """
        epoch = (
            float(snapshot_epoch)
            if snapshot_epoch is not None else time.time()
        )
        local = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(epoch))

        try:
            soft = c._make_softbits174(powers)
            if soft is None:
                self._v65_log_probe_row({
                    "local":local, "epoch":epoch, "center":center_hz,
                    "start":start, "frontend":frontend, "pass_name":"INIT",
                    "mapping":"NONE", "checks":87, "note":"SOFT_NONE"
                })
                return None

            a0, l0, _hard = soft
            a0 = np.asarray(a0, dtype=np.float32).flatten()
            l0 = np.asarray(l0, dtype=np.float32).flatten()

            if a0.size != 174 or l0.size != 174:
                raise ValueError(
                    f"LLR size AMP={a0.size} LOG={l0.size}, attendu 174"
                )

            # Reproduit la famille de passes de _v20_ldpc4.
            pass_bank = []

            pass_bank.append(("A1", a0.copy()))
            pass_bank.append(("L2", l0.copy()))

            q = a0.copy()
            q[:24] = 0.0
            pass_bank.append(("A3_ERASE0_23", q))

            q = a0.copy()
            q[24:48] = 0.0
            pass_bank.append(("A4_ERASE24_47", q))

            log_unit = l0 / 2.83
            for scale in (3.25, 3.50, 3.75, 4.00):
                pass_bank.append((
                    f"L-S{scale:.2f}",
                    (log_unit * float(scale)).astype(np.float32)
                ))

            weak_order = np.argsort(np.abs(l0))
            for nweak in (4, 6, 8, 10, 12):
                q = l0.copy()
                q[weak_order[:nweak]] = 0.0
                pass_bank.append((f"L-W{nweak}", q))

            # V66 LITE : ne teste plus les 13 passes à chaque fois.
            # On garde uniquement la passe qui a déjà donné le meilleur L,
            # plus au maximum deux voisines pertinentes.
            _pref = str(preferred_pass or "").upper()
            if _pref:
                wanted = set()
                if _pref.startswith("L-S"):
                    wanted.add(_pref)
                    try:
                        _sc = float(_pref.split("S",1)[1])
                        for _d in (-0.25, 0.25):
                            wanted.add(f"L-S{_sc+_d:.2f}".upper())
                    except Exception:
                        pass
                elif _pref.startswith("A4"):
                    wanted.update(("A4_ERASE24_47","A1","L2"))
                elif _pref.startswith("A3"):
                    wanted.update(("A3_ERASE0_23","A1","L2"))
                elif _pref.startswith("L-W"):
                    wanted.update((_pref,"L2","A1"))
                elif _pref.startswith("L2"):
                    wanted.update(("L2","A1","L-S3.50"))
                else:
                    wanted.update(("A1","L2"))

                _filtered = [
                    (n,q) for (n,q) in pass_bank
                    if str(n).upper() in wanted
                ]
                if _filtered:
                    pass_bank = _filtered[:3]

            # V66 : mappings les plus plausibles en priorité.
            mappings = (
                "NORMAL",
                "TRIPLET_210",
                "TRIPLET_021",
                "TRIPLET_102",
                "TRIPLET_120",
                "TRIPLET_201",
                "SIGN_INV",
                "REVERSE174",
            )

            best = None
            best_rank = None

            for pass_name, base_llr in pass_bank:
                for mapping in mappings:
                    try:
                        llr = self._v64_apply_llr_mapping(
                            base_llr, mapping
                        )

                        ok,d87,cw,he,it,nc = c._bpdecode174_87(
                            llr, max_iterations=45
                        )
                        nc = int(nc)
                        he = int(he)
                        it = int(it)
                        crc = False
                        raw12 = ""

                        # Vrai chemin : CRC seulement si convergence LDPC.
                        if ok and nc == 0:
                            try:
                                crc = bool(c._check_crc12_js8(d87)[0])
                            except Exception:
                                crc = False

                        # Forensic raw12 : pour comparer à la vieille version
                        # qui "écrivait des messages". Jamais publié dans RX.
                        if nc <= 8:
                            dprobe = None
                            if (
                                ok
                                and np.asarray(d87).size == 87
                            ):
                                dprobe = np.asarray(
                                    d87, dtype=np.int8
                                )
                            else:
                                dprobe = self._v65_decoded87_from_cw(
                                    c, cw
                                )

                            if dprobe is not None:
                                try:
                                    raw12,_i3 = c._extract_js8_message(
                                        dprobe
                                    )
                                except Exception:
                                    raw12 = ""

                        self._v65_log_probe_row({
                            "local":local,
                            "epoch":epoch,
                            "center":center_hz,
                            "start":start,
                            "frontend":frontend,
                            "pass_name":pass_name,
                            "mapping":mapping,
                            "checks":nc,
                            "ok":ok,
                            "crc":crc,
                            "raw12":raw12,
                            "hard_errors":he,
                            "iterations":it,
                            "note":(
                                "CRC_VALID"
                                if crc else (
                                    "RAW12_FORENSIC"
                                    if raw12 else "TEST"
                                )
                            ),
                            "error":"",
                        })

                        rank = (
                            0 if crc else 1,
                            nc,
                            he if he >= 0 else 999,
                        )
                        if best_rank is None or rank < best_rank:
                            best_rank = rank
                            best = {
                                "crc":bool(crc),
                                "checks":nc,
                                "pass_name":pass_name,
                                "mapping":mapping,
                                "d87":d87,
                                "cw":cw,
                                "llr":llr,
                                "raw12":raw12,
                                "hard_errors":he,
                                "iterations":it,
                            }

                        if crc:
                            return best

                    except Exception as exc:
                        self._v65_log_probe_row({
                            "local":local,
                            "epoch":epoch,
                            "center":center_hz,
                            "start":start,
                            "frontend":frontend,
                            "pass_name":pass_name,
                            "mapping":mapping,
                            "checks":87,
                            "ok":False,
                            "crc":False,
                            "raw12":"",
                            "hard_errors":-1,
                            "iterations":0,
                            "note":"EXCEPTION",
                            "error":f"{type(exc).__name__}: {exc}",
                        })

            return best

        except Exception as exc:
            self._v65_log_probe_row({
                "local":local,
                "epoch":epoch,
                "center":center_hz,
                "start":start,
                "frontend":frontend,
                "pass_name":"FATAL",
                "mapping":"NONE",
                "checks":87,
                "ok":False,
                "crc":False,
                "raw12":"",
                "hard_errors":-1,
                "iterations":0,
                "note":"FATAL_EXCEPTION",
                "error":f"{type(exc).__name__}: {exc}",
            })
            return None


    # ------------------------------------------------------------------
    # V63 — ancien frontal Hann, utilisé uniquement pour comparaison A/B/C.
    # ------------------------------------------------------------------
    def _v63_hann_powers(self, c, cycle, start, center_hz):
        try:
            ns = int(c.symbol_samples_12k)
            need = int(start) + 79 * ns
            if int(start) < 0 or need > len(cycle):
                return None

            f0 = float(center_hz) - 3.5 * float(c.tone_spacing)
            window = np.hanning(ns).astype(np.float64)
            n = np.arange(ns, dtype=np.float64)
            osc = [
                np.exp(
                    -2j*np.pi*(f0 + k*float(c.tone_spacing))*n/12000.0
                )
                for k in range(8)
            ]

            powers = np.zeros((79,8), dtype=np.float32)
            for sym in range(79):
                a = int(start) + sym*ns
                seg = np.asarray(cycle[a:a+ns], dtype=np.float64)
                if seg.size != ns:
                    return None
                seg = (seg - np.mean(seg)) * window

                for k in range(8):
                    z = np.dot(seg, osc[k])
                    powers[sym,k] = float(
                        (z.real*z.real + z.imag*z.imag) / (ns*ns)
                    )

            return powers

        except Exception:
            return None

    def _v63_log_compare(self, snapshot_epoch, center_hz, start, chain,
                         nsync, blocks, checks, pname, crc):
        try:
            epoch = (
                float(snapshot_epoch)
                if snapshot_epoch is not None
                else time.time()
            )
            local = time.strftime(
                "%Y-%m-%d %H:%M:%S",
                time.localtime(epoch)
            )
            with open(
                self._v63_compare_log_path, "a", encoding="utf-8"
            ) as fp:
                fp.write(
                    f'V63,{local},{epoch:.6f},JS8 40,'
                    f'{float(center_hz):.3f},{float(start)/12000.0:.6f},'
                    f'{chain},{int(nsync)},"{tuple(blocks)}",'
                    f'{int(checks)},{pname},{"OK" if crc else "NO"}\n'
                )
        except Exception:
            pass

    # ------------------------------------------------------------------
    # V62 — frontal complexe JS8 40 à 240 Hz.
    # ------------------------------------------------------------------
    def _v62_complex_baseband(self, cycle, center_hz):
        """Convertit le cycle réel 12 kHz en bande de base complexe 240 Hz.

        Architecture volontairement proche du frontal JS8Call Mode C :
          - recentrage complexe sur le centre des 8 tons ;
          - filtrage anti-repliement ;
          - sous-échantillonnage 12000 -> 240 Hz (facteur 50) ;
          - conservation de la phase sur toute la trame.

        Le centre des 8 tons est utilisé ici plutôt que tone-0. Après mélange,
        les tons JS8 40 sont à -70,-50,-30,-10,+10,+30,+50,+70 Hz.
        """
        try:
            x = np.asarray(cycle, dtype=np.float64).reshape(-1)
            if x.size < 600:
                return None

            fs = 12000.0
            fs2 = 240.0
            n = np.arange(x.size, dtype=np.float64)

            # Mélange continu : aucune remise à zéro de phase entre symboles.
            mixed = x.astype(np.complex128) * np.exp(
                -2j * np.pi * float(center_hz) * n / fs
            )

            if SCIPY_AVAILABLE:
                # resample_poly filtre avant décimation et aligne le premier
                # échantillon de sortie sur le premier échantillon d'entrée.
                bb = scipy.signal.resample_poly(
                    mixed,
                    up=1,
                    down=50,
                    window=("kaiser", 8.0),
                    padtype="constant"
                )
            else:
                # Repli FFT si scipy n'est pas disponible. Ce chemin reste
                # complexe et bande-limitant, mais scipy est fortement préféré.
                nout = max(1, int(round(x.size / 50.0)))
                X = np.fft.fft(mixed)
                Xs = np.fft.fftshift(X)
                keep = min(nout, Xs.size)
                mid = Xs.size // 2
                lo = mid - keep // 2
                hi = lo + keep
                Y = np.zeros(nout, dtype=np.complex128)
                chunk = Xs[lo:hi]
                if chunk.size == nout:
                    Y[:] = np.fft.ifftshift(chunk)
                else:
                    Y[:chunk.size] = np.fft.ifftshift(chunk)
                bb = np.fft.ifft(Y)

            return np.asarray(bb, dtype=np.complex64)

        except Exception:
            return None

    def _v62_powers_from_baseband(self, bb, start_12k, df_hz):
        """Construit powers[79,8] depuis la bande de base complexe 240 Hz.

        Chaque symbole JS8 40 = 12 échantillons à 240 Hz.
        Le décalage fin de fréquence est appliqué comme une rotation de phase
        continue, exactement avant la FFT symbole dans l'esprit de js8dec().
        """
        try:
            if bb is None:
                return None

            fs2 = 240.0
            ns2 = 12
            start2 = int(round(float(start_12k) / 50.0))
            need = start2 + 79 * ns2

            if start2 < 0 or need > len(bb):
                return None

            # Correction fréquence continue.
            idx = np.arange(len(bb), dtype=np.float64)
            corrected = np.asarray(bb, dtype=np.complex128) * np.exp(
                -2j * np.pi * float(df_hz) * idx / fs2
            )

            # Tons relatifs au centre du groupe 8-FSK.
            tone_hz = -70.0 + 20.0 * np.arange(8, dtype=np.float64)
            m = np.arange(ns2, dtype=np.float64)
            osc = np.exp(
                -2j * np.pi * tone_hz[:, None] * m[None, :] / fs2
            )

            powers = np.zeros((79, 8), dtype=np.float32)

            for sym in range(79):
                a = start2 + sym * ns2
                seg = corrected[a:a+ns2]
                if seg.size != ns2:
                    return None

                # 8 corrélateurs cohérents sur exactement un symbole.
                z = osc @ seg
                powers[sym, :] = (
                    (z.real*z.real + z.imag*z.imag) / float(ns2*ns2)
                ).astype(np.float32)

            return powers

        except Exception:
            return None

    # ------------------------------------------------------------------
    def _resolve_cycle(self, x12, snapshot_epoch, frame_samples):
        """Facture la logique de calage (UTC ou repli elargi) hors de
        decode_cycle, pour pouvoir la reutiliser depuis le multi-passes
        avec soustraction. Retourne (cycle, nominal_start, cycle_offset,
        used_utc_alignment) ou cycle_offset est la position de cycle[0]
        dans x12 (buffer complet), necessaire pour soustraire au bon
        endroit lors du multi-passes."""
        c = self.core
        margin_samples = int(round(2.0 * 12000.0))
        used_utc_alignment = False
        cycle = None
        nominal_start = None
        cycle_offset = 0

        if snapshot_epoch is not None and snapshot_epoch > 0:
            frame_s = float(c.frame_s)
            slot_end_epoch = math.floor(float(snapshot_epoch) / frame_s) * frame_s
            slot_start_epoch = slot_end_epoch - frame_s
            lag_s = float(snapshot_epoch) - slot_start_epoch
            samples_from_end = int(round(lag_s * 12000.0))
            slot_start_idx = len(x12) - samples_from_end

            lo = slot_start_idx - margin_samples
            hi = slot_start_idx + frame_samples + margin_samples
            if lo >= 0 and hi <= len(x12):
                cycle = x12[lo:hi]
                nominal_start = margin_samples
                cycle_offset = lo
                used_utc_alignment = True

        if not used_utc_alignment:
            cycle_n = int(round(c.frame_s * 12000.0))
            if len(x12) >= cycle_n:
                cycle = x12[-cycle_n:]
                cycle_offset = len(x12) - cycle_n
            else:
                cycle = x12
                cycle_offset = 0
            nominal_start = int(round(c.start_delay_s * 12000.0))

        return cycle, nominal_start, cycle_offset, used_utc_alignment


    def _v94_classify_raw_costas(self, x, raw_rows, c, snapshot_epoch=None):
        """V94 diagnostic-only RAW -> submode classifier.

        This is deliberately independent of V91. It starts from strong RAW
        Costas maxima, which are known to be produced in live reception.

        For each strong RAW seed (>=5/7), the same absolute seed time/frequency
        is tested as NORMAL / FAST / TURBO / SLOW. For each submode we test
        the seed as Costas block 0, 1 or 2, plus a tiny timing/frequency grid.

        Operational RX remains JS8 NORMAL. No candidate is displayed unless
        the normal decoder later passes its mandatory CRC.
        """
        try:
            if not raw_rows:
                return

            sr = 12000.0
            xx = np.asarray(x, dtype=np.float64).flatten()
            modes = (
                ("NORMAL", 1920, 6.25),
                ("FAST",   1200, 10.0),
                ("TURBO",   600, 20.0),
                ("SLOW",   3840, 3.125),
            )

            # Costas sequence currently used by the active JS8 decoder.
            try:
                pats = tuple(tuple(int(v) for v in p) for p in c._costas)
                if len(pats) != 3:
                    raise ValueError
            except Exception:
                pats = ((4,2,5,6,1,3,0),) * 3

            # Strong RAW seeds only, then deduplicate same event.
            seeds = []
            for q in raw_rows:
                try:
                    h = int(q.get("hits", 0))
                    if h < 5:
                        continue
                    bs = int(q.get("block_start", -1))
                    fc = float(q.get("center", 0.0))
                    bi = int(q.get("block", -1))
                    if bs < 0 or not (0 <= bi <= 2):
                        continue
                    seeds.append((h, bs, fc, bi))
                except Exception:
                    continue

            seeds.sort(key=lambda z: -z[0])
            chosen = []
            for z in seeds:
                if any(
                    abs(z[1] - y[1]) <= int(0.10 * sr)
                    and abs(z[2] - y[2]) <= 12.0
                    for y in chosen
                ):
                    continue
                chosen.append(z)
                if len(chosen) >= 10:
                    break

            if not chosen:
                return

            if not hasattr(self, "_v94_seen"):
                self._v94_seen = set()

            # Tiny local grid: enough to absorb the RAW 12.5 ms timing grid
            # and the 10 Hz first-pass frequency grid without burdening RX.
            dt_grid = (-300, 0, 300)   # samples = -25, 0, +25 ms
            df_grid = (-4.0, 0.0, 4.0)

            def score_frame(nsps, spacing, fst, center):
                """Score only the 21 Costas symbols, not all 79 DATA symbols."""
                if fst < 0 or fst + 79 * nsps > len(xx):
                    return None

                n = np.arange(nsps, dtype=np.float64)
                win = np.hanning(nsps)
                total = 0
                blocks = []

                for bidx, base_sym in enumerate((0, 36, 72)):
                    bh = 0
                    pat = pats[bidx]
                    for j in range(7):
                        a = int(fst + (base_sym + j) * nsps)
                        seg = xx[a:a+nsps]
                        if seg.size != nsps:
                            return None
                        seg = (seg - np.mean(seg)) * win

                        # Eight matched tone bins around MultiDigi center_hz.
                        vals = np.empty(8, dtype=np.float64)
                        for tone in range(8):
                            f = float(center) + (tone - 3.5) * float(spacing)
                            ph = -2.0j * np.pi * f * n / sr
                            z = np.dot(seg, np.exp(ph))
                            vals[tone] = z.real*z.real + z.imag*z.imag

                        if int(np.argmax(vals)) == int(pat[j]):
                            bh += 1

                    blocks.append(bh)
                    total += bh

                return int(total), tuple(int(v) for v in blocks)

            folder = os.path.dirname(os.path.abspath(__file__))
            path = os.path.join(folder, "JS8_NORMAL_V94_RAW_SUBMODE_CLASSIFIER.csv")
            newfile = not os.path.exists(path)

            rows_out = []

            for raw_hits, block_start, raw_center, raw_block in chosen:
                event_key = (
                    int(round(float(snapshot_epoch or 0.0))),
                    int(round(block_start / 150.0)),
                    int(round(raw_center * 2.0)),
                )
                if event_key in self._v94_seen:
                    continue

                best_mode = {}
                for mode, nsps, spacing in modes:
                    best = None

                    # We do NOT trust the NORMAL raw block index for another
                    # submode. Test the same seed instant as B0, B1 and B2.
                    for assumed_block in (0, 1, 2):
                        nominal_fst = int(
                            block_start - assumed_block * 36 * nsps
                        )

                        for dts in dt_grid:
                            fst = nominal_fst + int(dts)
                            for df in df_grid:
                                fc = float(raw_center + df)
                                sc = score_frame(nsps, spacing, fst, fc)
                                if sc is None:
                                    continue
                                total, blocks = sc
                                rank = (
                                    total,
                                    min(blocks),
                                    max(blocks),
                                    -abs(dts),
                                    -abs(df),
                                )
                                if best is None or rank > best[0]:
                                    best = (
                                        rank, total, blocks, assumed_block,
                                        dts, df, fst, fc
                                    )

                    best_mode[mode] = best

                valid = [
                    (v[1], min(v[2]), m, v)
                    for m, v in best_mode.items() if v is not None
                ]
                if not valid:
                    continue
                valid.sort(reverse=True)
                probable = valid[0][2]
                margin = (
                    valid[0][0] - valid[1][0]
                    if len(valid) > 1 else valid[0][0]
                )

                # V95 — trace EXACTE d'un candidat clairement NORMAL.
                # On ne change pas le décodage : diagnostic seulement.
                if probable == "NORMAL":
                    _vn = best_mode.get("NORMAL")
                    if (
                        _vn is not None
                        and int(raw_hits) >= 6
                        and int(_vn[1]) >= 8
                        and int(margin) >= 2
                    ):
                        try:
                            _fst95 = int(_vn[6])
                            _fc95 = float(_vn[7])
                            _f095 = _fc95 - 3.5 * 6.25

                            if not hasattr(self, "_v95_seen"):
                                self._v95_seen = set()
                            _k95 = (
                                int(round(float(snapshot_epoch or 0.0))),
                                int(round(_fst95 / 150.0)),
                                int(round(_fc95 * 2.0)),
                            )

                            if _k95 not in self._v95_seen:
                                _arr95 = {
                                    "version": np.asarray(["V95_CONFIDENT_NORMAL_TRACE"]),
                                    "cycle_float32": np.asarray(xx, dtype=np.float32),
                                    "snapshot_epoch": np.asarray([float(snapshot_epoch or 0.0)]),
                                    "raw_hits": np.asarray([int(raw_hits)]),
                                    "raw_block": np.asarray([int(raw_block)]),
                                    "raw_center_hz": np.asarray([float(raw_center)]),
                                    "frame_start_samples": np.asarray([_fst95]),
                                    "tested_center_hz": np.asarray([_fc95]),
                                    "classifier_costas_total": np.asarray([int(_vn[1])]),
                                    "classifier_blocks": np.asarray(_vn[2], dtype=np.int16),
                                    "winner_margin": np.asarray([int(margin)]),
                                }
                                _summ95 = []

                                _p_leg = c._symbol_tone_powers(xx, _fst95, _f095)
                                try:
                                    _p_d60 = c._v88_normal_downsampled_powers(
                                        xx, _fst95, _f095
                                    )
                                except Exception:
                                    _p_d60 = None

                                for _front, _pp in (
                                    ("LEGACY", _p_leg),
                                    ("DOWN60", _p_d60),
                                ):
                                    if _pp is None:
                                        continue
                                    _pp = np.asarray(_pp, dtype=np.float32)
                                    _low = _front.lower()
                                    _arr95[f"powers_{_low}_float32"] = _pp

                                    # Costas recalculé sur les mêmes 79x8
                                    # qui entrent ensuite dans DATA/LDPC.
                                    _rb = []
                                    for _bi, _base in enumerate((0, 36, 72)):
                                        _hh = 0
                                        for _j in range(7):
                                            if int(np.argmax(_pp[_base + _j])) == int(pats[_bi][_j]):
                                                _hh += 1
                                        _rb.append(_hh)
                                    _rc = int(sum(_rb))

                                    try:
                                        _soft = c._make_softbits174(_pp)
                                        if _soft is not None:
                                            _la, _ll, _hard = _soft
                                            _arr95[f"llr_amp_{_low}_float32"] = np.asarray(_la, dtype=np.float32)
                                            _arr95[f"llr_log_{_low}_float32"] = np.asarray(_ll, dtype=np.float32)
                                            _arr95[f"hard_{_low}"] = np.asarray(_hard)
                                    except Exception as _se:
                                        print("⚠️ V95 softbits", _front, repr(_se))

                                    _checks, _pass, _crc, _d87, _txt = self._v20_ldpc4(c, _pp)
                                    if _d87 is not None:
                                        _arr95[f"d87_{_low}"] = np.asarray(_d87)

                                    # Qualité DATA : rapport énergie gagnant / 2e ton.
                                    _dp = np.asarray(
                                        _pp[list(c.DATA_POSITIONS), :],
                                        dtype=np.float64
                                    )
                                    _so = np.sort(_dp, axis=1)
                                    _rat = _so[:, -1] / (_so[:, -2] + 1e-30)
                                    _arr95[f"data_ratio_{_low}_float32"] = np.asarray(_rat, dtype=np.float32)

                                    _summ95.append(
                                        (_front, _rc, tuple(_rb), int(_checks),
                                         str(_pass), bool(_crc), str(_txt or ""),
                                         float(np.median(_rat)))
                                    )

                                if _summ95:
                                    _folder95 = os.path.dirname(os.path.abspath(__file__))
                                    _stamp95 = time.strftime("%Y%m%d_%H%M%S", time.localtime())
                                    _base95 = (
                                        f"V95_CONFIDENT_NORMAL_{_stamp95}"
                                        f"_F{_fc95:.1f}_RAW{int(raw_hits)}"
                                        f"_S{int(_vn[1])}_M{int(margin)}"
                                    )
                                    _npz95 = os.path.join(_folder95, _base95 + ".npz")
                                    np.savez_compressed(_npz95, **_arr95)

                                    _csv95 = os.path.join(
                                        _folder95,
                                        "JS8_NORMAL_V95_CONFIDENT_NORMAL_TRACE.csv"
                                    )
                                    _new95 = not os.path.exists(_csv95)
                                    with open(_csv95, "a", encoding="utf-8", newline="") as _fh95:
                                        _w95 = csv.writer(_fh95, delimiter=";")
                                        if _new95:
                                            _w95.writerow([
                                                "epoch","raw_hits","raw_center_hz",
                                                "frame_start","tested_center_hz",
                                                "class_costas","class_b0","class_b1","class_b2",
                                                "winner_margin","frontend","recalc_costas",
                                                "recalc_b0","recalc_b1","recalc_b2",
                                                "ldpc_checks","ldpc_pass","crc_ok","text",
                                                "data_ratio_median","npz_file"
                                            ])
                                        for _r95 in _summ95:
                                            _w95.writerow([
                                                f"{float(snapshot_epoch or 0.0):.6f}",
                                                int(raw_hits), f"{float(raw_center):.6f}",
                                                _fst95, f"{_fc95:.6f}",
                                                int(_vn[1]), int(_vn[2][0]), int(_vn[2][1]), int(_vn[2][2]),
                                                int(margin), _r95[0], _r95[1],
                                                _r95[2][0], _r95[2][1], _r95[2][2],
                                                _r95[3], _r95[4], int(_r95[5]), _r95[6],
                                                f"{_r95[7]:.6f}", os.path.basename(_npz95)
                                            ])

                                    print(
                                        f"🧬 V95 NORMAL CERTAIN F={_fc95:.1f} "
                                        f"RAW={raw_hits}/7 CLASS={_vn[1]}/21{_vn[2]} "
                                        f"marge={margin} | "
                                        + " | ".join(
                                            f"{r[0]} Costas={r[1]}/21{r[2]} "
                                            f"L={r[3]} {r[4]} CRC={'OK' if r[5] else 'NO'}"
                                            for r in _summ95
                                        )
                                    )
                                    print("💾 V95 :", os.path.basename(_npz95))
                                    self._v95_seen.add(_k95)

                        except Exception as _e95:
                            print("❌ V95 confident NORMAL trace :", repr(_e95))

                display = []
                for mode, _, _ in modes:
                    v = best_mode.get(mode)
                    if v is None:
                        display.append(f"{mode}=NA")
                    else:
                        display.append(
                            f"{mode}={v[1]}/21{v[2]}"
                        )

                print(
                    f"🧭 V94 RAW SUBMODE raw={raw_hits}/7 "
                    f"F={raw_center:.1f}Hz B{raw_block} | "
                    + " | ".join(display)
                    + f" | probable={probable} Δ={margin}"
                )

                for mode, _, _ in modes:
                    v = best_mode.get(mode)
                    if v is None:
                        continue
                    rows_out.append([
                        f"{float(snapshot_epoch or 0.0):.6f}",
                        raw_hits, raw_block, block_start,
                        f"{raw_center:.6f}",
                        mode, v[1], v[2][0], v[2][1], v[2][2],
                        v[3], v[4],
                        f"{float(v[5]):.3f}",
                        v[6], f"{float(v[7]):.6f}",
                        probable, margin,
                    ])

                self._v94_seen.add(event_key)

            if rows_out:
                with open(path, "a", encoding="utf-8", newline="") as fh:
                    w = csv.writer(fh, delimiter=";")
                    if newfile:
                        w.writerow([
                            "epoch","raw_hits","raw_block","raw_block_start",
                            "raw_center_hz","tested_mode","costas_total",
                            "block0","block1","block2","assumed_seed_block",
                            "dt_samples","df_hz","frame_start","tested_center_hz",
                            "probable_mode","winner_margin"
                        ])
                    w.writerows(rows_out)

        except Exception as e:
            print("❌ V94 RAW submode classifier error :", repr(e))


    def _v30_write_raw_costas(self, raw_rows, snapshot_epoch=None):
        """Journalise les meilleurs scores Costas BRUTS avant filtrage.

        raw_rows: liste de dicts block/hits/frame_start/block_start/center.
        On garde les 30 meilleurs par cycle pour ne pas saturer le disque.
        """
        try:
            if not raw_rows:
                return

            now = time.time()
            if now - float(self._v30_raw_last) < 0.8:
                return

            rows = sorted(
                raw_rows,
                key=lambda q: (
                    -int(q.get("hits", 0)),
                    int(q.get("block", 0)),
                    float(q.get("center", 0.0)),
                )
            )[:30]

            fields = [
                "version","local_time","epoch","variant",
                "rank","block","hits7","center_hz",
                "frame_start_s","block_start_s",
                "full_band","note"
            ]

            with open(self._v30_raw_log_path, "a", newline="", encoding="utf-8") as fp:
                w = csv.DictWriter(fp, fieldnames=fields)
                for rank, q in enumerate(rows, 1):
                    w.writerow({
                        "version": "V71",
                        "local_time": time.strftime(
                            "%Y-%m-%d %H:%M:%S", time.localtime(now)
                        ),
                        "epoch": (
                            snapshot_epoch
                            if snapshot_epoch is not None else now
                        ),
                        "variant": str(getattr(self.core, "variant", "JS8")),
                        "rank": int(rank),
                        "block": int(q.get("block", -1)) + 1,
                        "hits7": int(q.get("hits", 0)),
                        "center_hz": round(float(q.get("center", 0.0)), 3),
                        "frame_start_s": round(
                            float(q.get("frame_start", 0)) / 12000.0, 4
                        ),
                        "block_start_s": round(
                            float(q.get("block_start", 0)) / 12000.0, 4
                        ),
                        "full_band": True,
                        "note": str(q.get("note", "")),
                    })

            self._v30_raw_last = now
        except Exception:
            pass

    def _v32_write_costas_correlations(self, seeds, weak_by_block,
                                         snapshot_epoch=None):
        """Pour chaque seed 5/7 ou 6/7+, trouve la meilleure correspondance
        dans chacun des deux autres blocs, SANS appliquer les tolérances.

        On journalise dt/df exacts pour voir si les vraies correspondances
        sont systématiquement décalées.
        """
        try:
            if not seeds:
                return

            now = time.time()
            if now - float(self._v32_corr_last) < 0.8:
                return

            fields = [
                "version","local_time","epoch","variant",
                "seed_block","seed_hits","seed_center_hz","seed_frame_start_s",
                "other_block","best_hits","best_center_hz","best_frame_start_s",
                "dt_ms","df_hz","within_v31_time","within_v31_freq",
                "within_both","note"
            ]

            rows = []
            time_tol_ms = 240.0
            freq_tol_hz = 22.0

            for seed in seeds[:40]:
                sb = int(seed["block"])
                sh = int(seed["hits"])
                sf = float(seed["center"])
                ss = int(seed["frame_start"])

                for ob in range(3):
                    if ob == sb:
                        continue

                    best = None
                    for conf in weak_by_block[ob]:
                        ch = int(conf["hits"])
                        cf = float(conf["center"])
                        cs = int(conf["frame_start"])

                        dt_ms = (ss - cs) / 12000.0 * 1000.0
                        df_hz = sf - cf

                        # Pour le diagnostic on privilégie d'abord le score,
                        # puis la proximité temporelle, puis fréquentielle.
                        rank = (
                            -ch,
                            abs(dt_ms),
                            abs(df_hz),
                        )
                        if best is None or rank < best["rank"]:
                            best = {
                                "rank": rank,
                                "hits": ch,
                                "center": cf,
                                "frame_start": cs,
                                "dt_ms": dt_ms,
                                "df_hz": df_hz,
                            }

                    if best is None:
                        rows.append({
                            "version":"V32",
                            "local_time":time.strftime(
                                "%Y-%m-%d %H:%M:%S", time.localtime(now)
                            ),
                            "epoch":snapshot_epoch if snapshot_epoch is not None else now,
                            "variant":str(getattr(self.core, "variant", "JS8")),
                            "seed_block":sb+1,
                            "seed_hits":sh,
                            "seed_center_hz":round(sf,3),
                            "seed_frame_start_s":round(ss/12000.0,4),
                            "other_block":ob+1,
                            "best_hits":0,
                            "best_center_hz":"",
                            "best_frame_start_s":"",
                            "dt_ms":"",
                            "df_hz":"",
                            "within_v31_time":False,
                            "within_v31_freq":False,
                            "within_both":False,
                            "note":"no_match",
                        })
                        continue

                    wt = abs(best["dt_ms"]) <= time_tol_ms
                    wf = abs(best["df_hz"]) <= freq_tol_hz

                    rows.append({
                        "version":"V32",
                        "local_time":time.strftime(
                            "%Y-%m-%d %H:%M:%S", time.localtime(now)
                        ),
                        "epoch":snapshot_epoch if snapshot_epoch is not None else now,
                        "variant":str(getattr(self.core, "variant", "JS8")),
                        "seed_block":sb+1,
                        "seed_hits":sh,
                        "seed_center_hz":round(sf,3),
                        "seed_frame_start_s":round(ss/12000.0,4),
                        "other_block":ob+1,
                        "best_hits":int(best["hits"]),
                        "best_center_hz":round(float(best["center"]),3),
                        "best_frame_start_s":round(
                            float(best["frame_start"])/12000.0,4
                        ),
                        "dt_ms":round(float(best["dt_ms"]),2),
                        "df_hz":round(float(best["df_hz"]),2),
                        "within_v31_time":bool(wt),
                        "within_v31_freq":bool(wf),
                        "within_both":bool(wt and wf),
                        "note":"best_other_block",
                    })

            with open(self._v32_corr_log_path, "a", newline="", encoding="utf-8") as fp:
                w = csv.DictWriter(fp, fieldnames=fields)
                w.writerows(rows)

            self._v32_corr_last = now
        except Exception:
            pass

    def _v33_write_freq_first(self, seeds, weak_by_block,
                                  snapshot_epoch=None):
        """Diagnostic V33 : fréquence d'abord.

        Pour chaque seed >=5/7 et chaque autre bloc :
          - freq_best : minimum |df|, puis minimum |dt|, puis meilleur hit
          - score_best: meilleur hit, puis minimum |df|, puis minimum |dt|

        Aucun seuil de validation n'est appliqué ici : c'est du diagnostic pur.
        """
        try:
            if not seeds:
                return

            now = time.time()
            if now - float(self._v33_freq_last) < 0.8:
                return

            fields = [
                "version","local_time","epoch","variant",
                "seed_block","seed_hits","seed_center_hz","seed_frame_start_s",
                "other_block",
                "freq_best_hits","freq_best_center_hz","freq_best_frame_start_s",
                "freq_best_df_hz","freq_best_dt_ms",
                "score_best_hits","score_best_center_hz","score_best_frame_start_s",
                "score_best_df_hz","score_best_dt_ms",
                "same_freq_5hz","same_freq_10hz","same_freq_20hz",
                "note"
            ]

            rows = []

            for seed in seeds[:50]:
                sb = int(seed["block"])
                sh = int(seed["hits"])
                sf = float(seed["center"])
                ss = int(seed["frame_start"])

                for ob in range(3):
                    if ob == sb:
                        continue

                    cands = list(weak_by_block[ob])
                    if not cands:
                        rows.append({
                            "version":"V33",
                            "local_time":time.strftime(
                                "%Y-%m-%d %H:%M:%S", time.localtime(now)
                            ),
                            "epoch":snapshot_epoch if snapshot_epoch is not None else now,
                            "variant":str(getattr(self.core, "variant", "JS8")),
                            "seed_block":sb+1,
                            "seed_hits":sh,
                            "seed_center_hz":round(sf,3),
                            "seed_frame_start_s":round(ss/12000.0,4),
                            "other_block":ob+1,
                            "freq_best_hits":0,
                            "freq_best_center_hz":"",
                            "freq_best_frame_start_s":"",
                            "freq_best_df_hz":"",
                            "freq_best_dt_ms":"",
                            "score_best_hits":0,
                            "score_best_center_hz":"",
                            "score_best_frame_start_s":"",
                            "score_best_df_hz":"",
                            "score_best_dt_ms":"",
                            "same_freq_5hz":False,
                            "same_freq_10hz":False,
                            "same_freq_20hz":False,
                            "note":"no_other_block_candidates",
                        })
                        continue

                    def metrics(conf):
                        cf = float(conf["center"])
                        cs = int(conf["frame_start"])
                        ch = int(conf["hits"])
                        df = sf - cf
                        dt_ms = (ss - cs) / 12000.0 * 1000.0
                        return ch, cf, cs, df, dt_ms

                    # A) fréquence la plus proche d'abord
                    freq_best = min(
                        cands,
                        key=lambda conf: (
                            abs(sf - float(conf["center"])),
                            abs((ss - int(conf["frame_start"])) / 12000.0 * 1000.0),
                            -int(conf["hits"]),
                        )
                    )

                    # B) meilleur score Costas d'abord
                    score_best = min(
                        cands,
                        key=lambda conf: (
                            -int(conf["hits"]),
                            abs(sf - float(conf["center"])),
                            abs((ss - int(conf["frame_start"])) / 12000.0 * 1000.0),
                        )
                    )

                    f_h, f_c, f_s, f_df, f_dt = metrics(freq_best)
                    s_h, s_c, s_s, s_df, s_dt = metrics(score_best)

                    rows.append({
                        "version":"V33",
                        "local_time":time.strftime(
                            "%Y-%m-%d %H:%M:%S", time.localtime(now)
                        ),
                        "epoch":snapshot_epoch if snapshot_epoch is not None else now,
                        "variant":str(getattr(self.core, "variant", "JS8")),
                        "seed_block":sb+1,
                        "seed_hits":sh,
                        "seed_center_hz":round(sf,3),
                        "seed_frame_start_s":round(ss/12000.0,4),
                        "other_block":ob+1,

                        "freq_best_hits":f_h,
                        "freq_best_center_hz":round(f_c,3),
                        "freq_best_frame_start_s":round(f_s/12000.0,4),
                        "freq_best_df_hz":round(f_df,2),
                        "freq_best_dt_ms":round(f_dt,2),

                        "score_best_hits":s_h,
                        "score_best_center_hz":round(s_c,3),
                        "score_best_frame_start_s":round(s_s/12000.0,4),
                        "score_best_df_hz":round(s_df,2),
                        "score_best_dt_ms":round(s_dt,2),

                        "same_freq_5hz":abs(f_df) <= 5.0,
                        "same_freq_10hz":abs(f_df) <= 10.0,
                        "same_freq_20hz":abs(f_df) <= 20.0,
                        "note":"freq_first_vs_score_first",
                    })

            with open(self._v33_freq_log_path, "a", newline="", encoding="utf-8") as fp:
                w = csv.DictWriter(fp, fieldnames=fields)
                w.writerows(rows)

            self._v33_freq_last = now
        except Exception:
            pass

