    def _send_hrd(self):
        try:
            ip = self.hrd_ip.text().strip()
            port = int(self.hrd_port_edit.text().strip())
            try:
                self._logbook_settings['hrd_ip'] = ip
                self._logbook_settings['hrd_port'] = str(port)
                if self._parent is not None:
                    self._parent._logbook_settings = dict(self._logbook_settings)
                    self._parent._save_settings()
            except Exception:
                pass
            call = self.h_call.text().strip().upper()
            rst_s = self.h_rst_s.text().strip(); rst_r = self.h_rst_r.text().strip()
            name = self.h_name.text().strip()
            freq = self.h_freq.text().strip(); mode = self.h_mode.text().strip().upper()
            band = self.h_band.text().strip(); mycall = self.h_mycall.text().strip().upper()
            now = datetime.utcnow()
            date_adif = now.strftime("%Y%m%d"); time_adif = now.strftime("%H%M")
            try: freq_adif = f"{float(freq):.6f}"
            except: freq_adif = freq
            def af(t, v): v = str(v); return f"<{t}:{len(v)}>{v}"
            adif = (af("CALL",call)+af("QSO_DATE",date_adif)+af("TIME_ON",time_adif)
                    +af("TIME_OFF",now.strftime("%H%M"))+af("FREQ",freq_adif)
                    +af("BAND",band)+af("MODE",mode)+af("RST_SENT",rst_s)
                    +af("RST_RCVD",rst_r)+af("NAME",name)
                    +af("STATION_CALLSIGN",mycall)
                    +af("COMMENT","Via MultiDigi by F4LPS")+"<EOR>")
            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            sock.settimeout(2); sock.sendto(adif.encode('utf-8'), (ip, port)); sock.close()
            self.hrd_status.setText(f"✅ Envoyé → {ip}:{port}  {call}")
            self.hrd_status.setStyleSheet("color:#00ff88; font-size:9pt;")
        except Exception as e:
            self.hrd_status.setText(f"❌ {e}")
            self.hrd_status.setStyleSheet("color:#ff4444; font-size:9pt;")

