    def _send_n1mm(self):
        try:
            ip = self.n1mm_ip.text().strip(); port = int(self.n1mm_port.text().strip())
            call = self.n1_call.text().strip().upper()
            rsts = self.n1_rsts.text().strip(); rstr = self.n1_rstr.text().strip()
            freq = self.n1_freq.text().strip(); mode = self.n1_mode.text().strip().upper()
            mycall = self.n1_mycall.text().strip().upper()
            now = datetime.utcnow()
            try: freq_khz = int(float(freq) * 1000)
            except: freq_khz = 0
            xml = (f'<contactinfo>'
                   f'<contestname>PSK QSO</contestname>'
                   f'<mycall>{mycall}</mycall><operator>{mycall}</operator>'
                   f'<call>{call}</call>'
                   f'<band>{self._freq_to_band(freq_khz*1000)}</band>'
                   f'<mode>{mode}</mode>'
                   f'<rxfreq>{freq_khz}</rxfreq><txfreq>{freq_khz}</txfreq>'
                   f'<snt>{rsts}</snt><rcv>{rstr}</rcv>'
                   f'<timestamp>{now.strftime("%Y-%m-%d %H%M%S")}</timestamp>'
                   f'<IsRunQSO>0</IsRunQSO></contactinfo>')
            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            sock.settimeout(2); sock.sendto(xml.encode('utf-8'), (ip, port)); sock.close()
            self.n1mm_status.setText(f"✅ Envoyé → {ip}:{port}  {call}")
            self.n1mm_status.setStyleSheet("color:#00ff88; font-size:9pt;")
        except Exception as e:
            self.n1mm_status.setText(f"❌ {e}")
            self.n1mm_status.setStyleSheet("color:#ff4444; font-size:9pt;")

