    def _send_adif_udp(self, ip, port, call, freq, band, mode, mycall, rst_s, rst_r, status_label):
        now = datetime.utcnow()
        date_adif = now.strftime("%Y%m%d"); time_adif = now.strftime("%H%M")
        try: freq_adif = f"{float(freq):.6f}"
        except: freq_adif = freq
        def af(t, v): v = str(v); return f"<{t}:{len(v)}>{v}"
        adif = (af("CALL",call)+af("QSO_DATE",date_adif)+af("TIME_ON",time_adif)
                +af("TIME_OFF",now.strftime("%H%M"))+af("FREQ",freq_adif)
                +af("BAND",band)+af("MODE",mode)+af("RST_SENT",rst_s)
                +af("RST_RCVD",rst_r)+af("STATION_CALLSIGN",mycall)
                +af("COMMENT","Via MultiDigi by F4LPS")+"<EOR>")
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.settimeout(2); sock.sendto(adif.encode('utf-8'), (ip, port)); sock.close()
        status_label.setText(f"✅ Envoyé → {ip}:{port}  {call}")
        status_label.setStyleSheet("color:#00ff88; font-size:9pt;")

    def _send_dxlog(self):
        try:
            self._send_adif_udp(self.dxlog_ip.text().strip(), int(self.dxlog_port.text().strip()),
                self.dx_call.text().strip().upper(), self.dx_freq.text().strip(),
                self._freq_to_band(int(float(self.dx_freq.text() or 0)*1e6)),
                self.dx_mode.text().strip().upper(), self.dx_mycall.text().strip().upper(),
                self.dx_rsts.text().strip(), self.dx_rstr.text().strip(), self.dxlog_status)
        except Exception as e:
            self.dxlog_status.setText(f"❌ {e}"); self.dxlog_status.setStyleSheet("color:#ff4444; font-size:9pt;")

