    def _send_wavelog(self):
        pass
        try:
            import requests as _req
        except ImportError:
            self.wl_status.setText("❌ Module 'requests' manquant — pip install requests")
            self.wl_status.setStyleSheet("color:#ff4444; font-size:9pt;"); return
        try:
            url    = self.wl_url.text().strip()
            apikey = self.wl_apikey.text().strip()
            call   = self.wl_call.text().strip().upper()
            rst_s  = self.wl_rst_s.text().strip()
            rst_r  = self.wl_rst_r.text().strip()
            freq   = self.wl_freq.text().strip()
            band   = self.wl_band.text().strip()
            mode   = self.wl_mode.text().strip().upper()
            mycall = self.wl_mycall.text().strip().upper()
            name   = self.wl_name.text().strip()
            date_s = self.wl_date.text().strip()   # YYYY-MM-DD
            time_s = self.wl_time.text().strip()   # HH:MM
            if not apikey or not call:
                self.wl_status.setText("❌ Clé API et indicatif requis")
                self.wl_status.setStyleSheet("color:#ff4444; font-size:9pt;"); return
            # WaveLog attend format ADIF dans le champ 'adif'
            def af(tag, val):
                v = str(val); return f"<{tag}:{len(v)}>{v}"
            date_adif = date_s.replace("-", "")
            time_adif = time_s.replace(":", "")
            try:
                freq_mhz = f"{float(freq)*1000:.0f}"  # MHz → kHz pour WaveLog
            except Exception:
                freq_mhz = freq
            adif = (af("CALL", call) + af("QSO_DATE", date_adif) + af("TIME_ON", time_adif) + af("TIME_OFF", now.strftime("%H%M"))
                    + af("BAND", band) + af("MODE", mode) + af("FREQ", freq)
                    + af("RST_SENT", rst_s) + af("RST_RCVD", rst_r)
                    + af("NAME", name) + af("STATION_CALLSIGN", mycall)
                    + af("COMMENT", "Via MultiDigi by F4LPS") + "<EOR>")
            payload = {"key": apikey, "adif": adif}
            resp = _req.post(url, json=payload, timeout=8)
            if resp.status_code in (200, 201):
                self.wl_status.setText(f"✅ QSO envoyé vers WaveLog — {call}  {band}  {mode}")
                self.wl_status.setStyleSheet("color:#00ff88; font-size:9pt;")
                print(f"[LOG WaveLog] POST → {url} | {resp.status_code} | {resp.text[:80]}")
            else:
                self.wl_status.setText(f"⚠️ HTTP {resp.status_code} — {resp.text[:60]}")
                self.wl_status.setStyleSheet("color:#ffaa00; font-size:9pt;")
        except Exception as e:
            self.wl_status.setText(f"❌ Erreur : {e}")
            self.wl_status.setStyleSheet("color:#ff4444; font-size:9pt;")

