    def _build_qrz_tab(self):
        w = QWidget()
        lay = QVBoxLayout(w)
        lay.setSpacing(8)
        info = QLabel(
            "QRZ Logbook API : envoi direct via HTTP POST avec la clé d'accès API du logbook.\n"
            "La clé API se récupère dans les réglages du logbook QRZ.com."
        )
        info.setWordWrap(True)
        info.setStyleSheet("color:#8888aa; font-size: 9pt; padding: 4px;")
        lay.addWidget(info)
        cfg_grp = QGroupBox("Configuration QRZ.com")
        c_lay = QGridLayout(cfg_grp)
        self.q_api = QLineEdit(str(self._logbook_settings.get('qrz_api_key',''))); self.q_api.setPlaceholderText("Access Key QRZ Logbook")
        self.q_mycall = QLineEdit(str(self._logbook_settings.get('qrz_mycall', self.my_call)))
        c_lay.addWidget(QLabel("API Key :"), 0, 0); c_lay.addWidget(self.q_api, 0, 1)
        c_lay.addWidget(QLabel("Mon indicatif :"), 1, 0); c_lay.addWidget(self.q_mycall, 1, 1)

        # Recherche internationale des informations OM via HamQTH.
        # HamDB/Callook ne couvrent pas correctement les indicatifs français ;
        # HamQTH nécessite un compte gratuit et fournit généralement le prénom/QTH/locator.
        self.hamqth_user = QLineEdit(str(self._logbook_settings.get('hamqth_user','')))
        self.hamqth_user.setPlaceholderText("Identifiant HamQTH")
        self.hamqth_password = QLineEdit(str(self._logbook_settings.get('hamqth_password','')))
        self.hamqth_password.setPlaceholderText("Mot de passe HamQTH")
        self.hamqth_password.setEchoMode(QLineEdit.Password)
        c_lay.addWidget(QLabel("HamQTH utilisateur :"), 2, 0); c_lay.addWidget(self.hamqth_user, 2, 1)
        c_lay.addWidget(QLabel("HamQTH mot de passe :"), 3, 0); c_lay.addWidget(self.hamqth_password, 3, 1)

        self.qrz_xml_user = QLineEdit(str(self._logbook_settings.get('qrz_xml_user','')))
        self.qrz_xml_user.setPlaceholderText("Identifiant QRZ.com")
        self.qrz_xml_password = QLineEdit(str(self._logbook_settings.get('qrz_xml_password') or self._logbook_settings.get('qrz_xml_pass','')))
        self.qrz_xml_password.setPlaceholderText("Mot de passe QRZ.com")
        self.qrz_xml_password.setEchoMode(QLineEdit.Password)
        c_lay.addWidget(QLabel("QRZ XML utilisateur :"), 4, 0); c_lay.addWidget(self.qrz_xml_user, 4, 1)
        c_lay.addWidget(QLabel("QRZ XML mot de passe :"), 5, 0); c_lay.addWidget(self.qrz_xml_password, 5, 1)

        hamqth_note = QLabel("Recherche prénom : QRZ XML officiel en priorité, puis HamQTH et les bases publiques. Un abonnement QRZ Logbook Data peut être nécessaire pour obtenir tous les champs.")
        hamqth_note.setWordWrap(True)
        hamqth_note.setStyleSheet("color:#d6a84b;font-size:9pt;")
        c_lay.addWidget(hamqth_note, 6, 0, 1, 2)

        self.callbook_validate_btn = QPushButton("✅ Valider et tester QRZ")
        self.callbook_validate_btn.setToolTip("Enregistre les identifiants puis teste la connexion QRZ XML.")
        self.callbook_validate_btn.setStyleSheet(
            "QPushButton{background:#103b20;color:#7dff9c;border:1px solid #2f9a55;"
            "border-radius:4px;padding:5px 12px;font-weight:bold;}"
            "QPushButton:hover{background:#17552d;}"
        )
        c_lay.addWidget(self.callbook_validate_btn, 7, 0, 1, 2)

        def _save_hamqth_lookup_credentials():
            try:
                self._logbook_settings['hamqth_user'] = self.hamqth_user.text().strip()
                self._logbook_settings['hamqth_password'] = self.hamqth_password.text()
                self._logbook_settings['qrz_xml_user'] = self.qrz_xml_user.text().strip()
                qrz_pwd = self.qrz_xml_password.text()
                # Deux parties historiques du programme utilisaient deux noms différents.
                # On garde désormais les deux clés synchronisées pour que le terminal
                # et le Grid Tracker lisent exactement les mêmes identifiants.
                self._logbook_settings['qrz_xml_password'] = qrz_pwd
                self._logbook_settings['qrz_xml_pass'] = qrz_pwd
                if self._parent is not None:
                    self._parent._logbook_settings = dict(self._logbook_settings)
                    self._parent._dx_lookup_cache = {}
                    self._parent._dx_lookup_last_requested = ''
                    self._parent._save_settings()
                    self._parent._set_status("✅ Identifiants Callbook enregistrés")
            except Exception as e:
                print("HamQTH sauvegarde ignorée:", e)
        self.hamqth_user.editingFinished.connect(_save_hamqth_lookup_credentials)
        self.hamqth_password.editingFinished.connect(_save_hamqth_lookup_credentials)
        self.qrz_xml_user.editingFinished.connect(_save_hamqth_lookup_credentials)
        self.qrz_xml_password.editingFinished.connect(_save_hamqth_lookup_credentials)

        def _validate_and_test_qrz():
            _save_hamqth_lookup_credentials()
            user = self.qrz_xml_user.text().strip()
            password = self.qrz_xml_password.text()
            if not user or not password:
                QMessageBox.warning(self, "QRZ XML", "Renseignez l'identifiant et le mot de passe QRZ XML.")
                return
            self.callbook_validate_btn.setEnabled(False)
            self.callbook_validate_btn.setText("⏳ Test QRZ en cours…")

            # Le résultat du thread est récupéré par un QTimer créé dans le thread Qt.
            # L'ancienne version appelait QTimer.singleShot depuis le thread réseau :
            # ce thread n'avait pas de boucle d'événements Qt et le bouton restait bloqué.
            result_box = {'done': False, 'ok': False, 'msg': ''}

            def worker():
                ok = False
                msg = ''
                try:
                    import xml.etree.ElementTree as ET
                    url = ('https://xmldata.qrz.com/xml/current/?username=' + urllib.parse.quote(user, safe='') +
                           '&password=' + urllib.parse.quote(password, safe='') +
                           '&agent=MultiDigi-3.1.5')
                    req = urllib.request.Request(url, headers={'User-Agent':'MultiDigi/3.1.5'})
                    with urllib.request.urlopen(req, timeout=12) as r:
                        raw = r.read(262144)
                    root = ET.fromstring(raw)

                    # QRZ renvoie un espace de noms XML par défaut. Les recherches
                    # './/Session/Key' ne trouvent alors rien même si la connexion
                    # est acceptée. Lecture volontairement indépendante du namespace.
                    def _qrz_local_text(node, wanted):
                        wanted = str(wanted).lower()
                        for elem in node.iter():
                            tag = str(getattr(elem, 'tag', '')).split('}')[-1].lower()
                            if tag == wanted and elem.text:
                                return elem.text.strip()
                        return ''

                    key = _qrz_local_text(root, 'Key')
                    err = _qrz_local_text(root, 'Error') or _qrz_local_text(root, 'Message')
                    if key:
                        ok = True
                        msg = 'Connexion QRZ XML acceptée.'
                    else:
                        msg = err or 'Connexion refusée ou accès XML non inclus dans le compte.'
                except Exception as exc:
                    msg = str(exc) or exc.__class__.__name__
                result_box['ok'] = bool(ok)
                result_box['msg'] = msg
                result_box['done'] = True

            test_thread = threading.Thread(target=worker, daemon=True, name='QRZXMLTest')
            test_thread.start()

            poll_timer = QTimer(self)
            poll_timer.setInterval(100)
            elapsed = {'ms': 0}

            def finish_test():
                poll_timer.stop()
                poll_timer.deleteLater()
                self.callbook_validate_btn.setEnabled(True)
                self.callbook_validate_btn.setText("✅ Valider et tester QRZ")
                ok = bool(result_box.get('ok'))
                msg = str(result_box.get('msg') or 'Aucune réponse de QRZ XML.')
                if ok:
                    QMessageBox.information(self, "QRZ XML", msg)
                    if self._parent is not None:
                        self._parent._set_status("✅ QRZ XML : connexion acceptée")
                        try:
                            self._parent._force_dx_callsign_lookup()
                        except Exception:
                            pass
                else:
                    QMessageBox.warning(self, "QRZ XML", "Échec du test :\n" + msg)
                    if self._parent is not None:
                        self._parent._set_status("❌ QRZ XML : " + msg[:180])

            def poll_result():
                elapsed['ms'] += poll_timer.interval()
                if result_box.get('done'):
                    finish_test()
                elif elapsed['ms'] >= 20000:
                    result_box['ok'] = False
                    result_box['msg'] = 'Délai dépassé : QRZ XML ne répond pas après 20 secondes.'
                    result_box['done'] = True
                    finish_test()

            poll_timer.timeout.connect(poll_result)
            poll_timer.start()

        self.callbook_validate_btn.clicked.connect(_validate_and_test_qrz)

        lay.addWidget(cfg_grp)
        fields_grp = QGroupBox("Données QSO")
        f_lay = QGridLayout(fields_grp)

        def add_field(row, label, widget):
            lbl = QLabel(label)
            lbl.setAlignment(Qt.AlignRight | Qt.AlignVCenter)
            f_lay.addWidget(lbl, row, 0)
            f_lay.addWidget(widget, row, 1)

        self.q_call  = QLineEdit(self.call);      self.q_call.setMinimumWidth(120)
        self.q_rst_s = QLineEdit(self.rst_sent);  self.q_rst_s.setMaximumWidth(60)
        self.q_rst_r = QLineEdit(self.rst_rcvd);  self.q_rst_r.setMaximumWidth(60)
        self.q_name  = QLineEdit(self.name);      self.q_name.setMinimumWidth(100)
        self.q_freq  = QLineEdit(self.freq_mhz);  self.q_freq.setMaximumWidth(100)
        self.q_band  = QLineEdit(self.band);      self.q_band.setMaximumWidth(60)
        self.q_mode  = QLineEdit(self.mode);      self.q_mode.setMaximumWidth(60)
        self.q_date  = QLineEdit(self.utc_now.strftime("%Y%m%d")); self.q_date.setMaximumWidth(100)
        self.q_time  = QLineEdit(self.utc_now.strftime("%H%M"));   self.q_time.setMaximumWidth(60)
        add_field(0, "Indicatif :",  self.q_call)
        add_field(1, "RST envoyé :", self.q_rst_s)
        add_field(2, "RST reçu :",   self.q_rst_r)
        add_field(3, "Prénom :",     self.q_name)
        add_field(4, "Fréquence MHz :", self.q_freq)
        add_field(5, "Bande :",      self.q_band)
        add_field(6, "Mode :",       self.q_mode)
        add_field(7, "Date UTC :",   self.q_date)
        add_field(8, "Heure UTC :",  self.q_time)
        lay.addWidget(fields_grp)
        self.q_status = QLabel("")
        self.q_status.setStyleSheet("color:#00ff88; font-size:9pt;")
        lay.addWidget(self.q_status)
        send_btn = QPushButton("📡  Envoyer QSO vers QRZ.com")
        send_btn.setStyleSheet("background:#001a33; color:#44aaff; border:1px solid #003366; font-size: 10pt;")
        send_btn.clicked.connect(self._send_qrz)
        lay.addWidget(send_btn)
        lay.addStretch()
        return w

    def _send_qrz(self):
        try:
            key    = self.q_api.text().strip()
            mycall = self.q_mycall.text().strip().upper()
            call   = self.q_call.text().strip().upper()
            rst_s  = self.q_rst_s.text().strip()
            rst_r  = self.q_rst_r.text().strip()
            band   = self.q_band.text().strip()
            mode   = self.q_mode.text().strip().upper()
            date_s = self.q_date.text().strip()
            time_s = self.q_time.text().strip()
            freq_s = self.q_freq.text().strip()
            name_s = self.q_name.text().strip()
            if not key or not call or not mycall:
                self.q_status.setText("❌ API Key QRZ, mon indicatif et indicatif DX requis")
                self.q_status.setStyleSheet("color:#ff4444; font-size:9pt;")
                return
            adif = self._make_qrz_adif_record(call, date_s, time_s, band, mode, mycall, rst_s, rst_r, freq_s, name_s)
            reply = self._api_post("https://logbook.qrz.com/api", {"KEY": key, "ACTION": "INSERT", "ADIF": adif, "OPTION": "REPLACE"}, user_agent="PSKTerminal/1.1 F4LPS")
            reply_up = str(reply or '').upper()
            if "RESULT=OK" in reply_up or "RESULT=REPLACE" in reply_up:
                self.q_status.setText(f"✅ QRZ.com log direct OK — {call}")
                self.q_status.setStyleSheet("color:#00ff88; font-size:9pt;")
                try:
                    self._logbook_settings['qrz_api_key'] = key
                    self._logbook_settings['qrz_mycall'] = mycall
                    self._logbook_settings['logsel_qrz'] = bool(getattr(self, 'logsel_qrz', None) and self.logsel_qrz.isChecked())
                    self._logbook_settings['logsel_hrd'] = bool(getattr(self, 'logsel_hrd', None) and self.logsel_hrd.isChecked())
                    if self._parent is not None:
                        self._parent._logbook_settings = dict(self._logbook_settings)
                        self._parent._save_settings()
                except Exception:
                    pass
            else:
                self.q_status.setText("⚠️ QRZ.com refusé : " + str(reply)[:180])
                self.q_status.setStyleSheet("color:#ffaa44; font-size:9pt;")
            print("[LOG QRZ]", reply[:400])
        except Exception as e:
            self.q_status.setText(f"❌ Erreur QRZ : {e}")
            self.q_status.setStyleSheet("color:#ff4444; font-size:9pt;")

    def _build_lotw_tab(self):
        w = QWidget()
        lay = QVBoxLayout(w)
        lay.setSpacing(8)
        info = QLabel("LoTW : envoi via TQSL en ligne de commande. La documentation ARRL recommande TrustedQSL/TQSL pour automatiser l'upload.")
        info.setWordWrap(True)
        info.setStyleSheet("color:#88aacc; font-size:9pt; padding:4px;")
        lay.addWidget(info)
        cfg = QGroupBox("Configuration TQSL / LoTW")
        cg = QGridLayout(cfg)
        self.lotw_tqsl = QLineEdit("tqsl")
        self.lotw_station = QLineEdit()
        self.lotw_station.setPlaceholderText("Nom de Station Location TQSL")
        self.lotw_pass = QLineEdit(); self.lotw_pass.setEchoMode(QLineEdit.Password)
        self.lotw_pass.setPlaceholderText("Mot de passe certificat (si besoin)")
        cg.addWidget(QLabel("Chemin TQSL :"), 0, 0); cg.addWidget(self.lotw_tqsl, 0, 1)
        cg.addWidget(QLabel("Station Location :"), 1, 0); cg.addWidget(self.lotw_station, 1, 1)
        cg.addWidget(QLabel("Mot de passe certificat :"), 2, 0); cg.addWidget(self.lotw_pass, 2, 1)
        lay.addWidget(cfg)
        grp = QGroupBox("Données QSO")
        g = QGridLayout(grp)
        self.l_call   = QLineEdit(self.call)
        self.l_rst_s  = QLineEdit(self.rst_sent);  self.l_rst_s.setMaximumWidth(60)
        self.l_rst_r  = QLineEdit(self.rst_rcvd);  self.l_rst_r.setMaximumWidth(60)
        self.l_freq   = QLineEdit(self.freq_mhz);  self.l_freq.setMaximumWidth(100)
        self.l_band   = QLineEdit(self.band);      self.l_band.setMaximumWidth(60)
        self.l_mode   = QLineEdit(self.mode);      self.l_mode.setMaximumWidth(60)
        self.l_mycall = QLineEdit(self.my_call)
        self.l_date   = QLineEdit(self.utc_now.strftime("%Y%m%d")); self.l_date.setMaximumWidth(100)
        self.l_time   = QLineEdit(self.utc_now.strftime("%H%M"));   self.l_time.setMaximumWidth(60)
        fields = [("Indicatif DX :", self.l_call), ("RST envoyé :", self.l_rst_s), ("RST reçu :", self.l_rst_r),
                  ("Fréquence MHz :", self.l_freq), ("Bande :", self.l_band), ("Mode :", self.l_mode),
                  ("Mon indicatif :", self.l_mycall), ("Date UTC :", self.l_date), ("Heure UTC :", self.l_time)]
        for r,(lab,wid) in enumerate(fields):
            l = QLabel(lab); l.setAlignment(Qt.AlignRight | Qt.AlignVCenter)
            g.addWidget(l, r, 0); g.addWidget(wid, r, 1)
        lay.addWidget(grp)
        self.lotw_status = QLabel("")
        self.lotw_status.setStyleSheet("color:#00ff88; font-size:9pt;")
        lay.addWidget(self.lotw_status)
        btn = QPushButton("🛰️  Envoyer QSO vers LoTW via TQSL")
        btn.setStyleSheet("background:#1a1a33; color:#88ccff; border:1px solid #335577; font-size:10pt;")
        btn.clicked.connect(self._send_lotw)
        lay.addWidget(btn)
        lay.addStretch()
        return w

    def _send_lotw(self):
        pass
        try:
            tqsl_path = self.lotw_tqsl.text().strip() or "tqsl"
            station   = self.lotw_station.text().strip()
            password  = self.lotw_pass.text().strip()
            call      = self.l_call.text().strip().upper()
            rst_s     = self.l_rst_s.text().strip()
            rst_r     = self.l_rst_r.text().strip()
            freq_s    = self.l_freq.text().strip()
            band      = self.l_band.text().strip()
            mode      = self.l_mode.text().strip().upper()
            mycall    = self.l_mycall.text().strip().upper()
            date_s    = self.l_date.text().strip()
            time_s    = self.l_time.text().strip()
            exe = shutil.which(tqsl_path) if os.path.basename(tqsl_path) == tqsl_path else tqsl_path
            if not exe or (os.path.basename(tqsl_path) != tqsl_path and not os.path.exists(exe)):
                self.lotw_status.setText("❌ TQSL introuvable. Indiquez le chemin complet vers tqsl.exe")
                self.lotw_status.setStyleSheet("color:#ff4444; font-size:9pt;")
                return
            if not station:
                self.lotw_status.setText("❌ Station Location TQSL requise")
                self.lotw_status.setStyleSheet("color:#ff4444; font-size:9pt;")
                return
            adif = self._make_adif_record(call, date_s, time_s, band, mode, mycall, rst_s, rst_r, freq_s)
            with tempfile.NamedTemporaryFile("w", suffix=".adi", delete=False, encoding="utf-8") as tf:
                tf.write(adif)
                temp_adi = tf.name
            cmd = [exe, "-d", "-u", "-x", "-l", station]
            if password:
                cmd += ["-p", password]
            cmd.append(temp_adi)
            proc = subprocess.run(cmd, capture_output=True, text=True)
            output = (proc.stdout or "") + "\n" + (proc.stderr or "")
            if proc.returncode == 0:
                self.lotw_status.setText(f"✅ Envoi LoTW lancé via TQSL pour {call}")
                self.lotw_status.setStyleSheet("color:#00ff88; font-size:9pt;")
            else:
                self.lotw_status.setText("⚠️ TQSL a renvoyé une erreur — voir console")
                self.lotw_status.setStyleSheet("color:#ffaa44; font-size:9pt;")
            print("[LOG LoTW CMD]", " ".join(cmd))
            print("[LOG LoTW OUT]", output[:1200])
        except Exception as e:
            self.lotw_status.setText(f"❌ Erreur LoTW : {e}")
            self.lotw_status.setStyleSheet("color:#ff4444; font-size:9pt;")

    def _build_adif_tab(self):
        w = QWidget(); lay = QVBoxLayout(w); lay.setSpacing(8)
        grp = QGroupBox("Export ADIF local")
        g = QGridLayout(grp)
        def lbl(t): l=QLabel(t); l.setAlignment(Qt.AlignRight|Qt.AlignVCenter); return l
        self.a_call  = QLineEdit(self.call)
        self.a_rst_s = QLineEdit(self.rst_sent); self.a_rst_s.setMaximumWidth(60)
        self.a_rst_r = QLineEdit(self.rst_rcvd); self.a_rst_r.setMaximumWidth(60)
        self.a_freq  = QLineEdit(self.freq_mhz); self.a_freq.setMaximumWidth(100)
        self.a_mode  = QLineEdit(self.mode);     self.a_mode.setMaximumWidth(60)
        self.a_band  = QLineEdit(self.band);     self.a_band.setMaximumWidth(60)
        self.a_mycall= QLineEdit(self.my_call)
        self.a_date  = QLineEdit(self.utc_now.strftime("%Y%m%d")); self.a_date.setMaximumWidth(100)
        self.a_time  = QLineEdit(self.utc_now.strftime("%H%M"));   self.a_time.setMaximumWidth(60)
        for row,(l,f) in enumerate([
            ("Indicatif :",self.a_call),("RST ↑ :",self.a_rst_s),("RST ↓ :",self.a_rst_r),
            ("Fréq MHz :",self.a_freq),("Mode :",self.a_mode),("Bande :",self.a_band),
            ("Mon ind. :",self.a_mycall),("Date YYYYMMDD :",self.a_date),("Heure HHMM :",self.a_time),
        ]):
            g.addWidget(lbl(l), row, 0); g.addWidget(f, row, 1)
        lay.addWidget(grp)
        self.adif_status = QLabel(""); self.adif_status.setStyleSheet("color:#00ff88; font-size:9pt;"); lay.addWidget(self.adif_status)
        row_btns = QHBoxLayout()
        btn_save = QPushButton("💾  Enregistrer ADIF…")
        btn_save.setStyleSheet("background:#002233; color:#44ccff; border:1px solid #004466;")
        btn_save.clicked.connect(self._save_adif)
        btn_append = QPushButton("➕  Ajouter à un ADIF existant…")
        btn_append.setStyleSheet("background:#002200; color:#88ff66; border:1px solid #004400;")
        btn_append.clicked.connect(self._append_adif)
        row_btns.addWidget(btn_save); row_btns.addWidget(btn_append)
        lay.addLayout(row_btns); lay.addStretch(); return w

    def _build_adif_str(self):
        def af(t, v): v=str(v) if v else ""; return f"<{t}:{len(v)}>{v}" if v else ""
        now = datetime.utcnow()
        return (af("CALL",self.a_call.text().strip().upper())
                +af("QSO_DATE",self.a_date.text().strip())
                +af("TIME_ON",self.a_time.text().strip())
                +af("TIME_OFF",now.strftime("%H%M"))
                +af("FREQ",self.a_freq.text().strip())
                +af("BAND",self.a_band.text().strip())
                +af("MODE",self.a_mode.text().strip().upper())
                +af("RST_SENT",self.a_rst_s.text().strip())
                +af("RST_RCVD",self.a_rst_r.text().strip())
                +af("STATION_CALLSIGN",self.a_mycall.text().strip().upper())
                +af("COMMENT","Via MultiDigi by F4LPS")+"<EOR>\n")

    def _save_adif(self):
        call = self.a_call.text().strip().upper()
        path, _ = QFileDialog.getSaveFileName(self, "Enregistrer ADIF",
            f"QSO_{call}_{self.a_date.text().strip()}.adi", "ADIF (*.adi *.adif)")
        if not path:
            return
        try:
            with open(path, 'w', encoding='utf-8') as f:
                f.write(f"MultiDigi V1.1 F4LPS\n<ADIF_VER:5>3.1.4 <EOH>\n")
                f.write(self._build_adif_str())
            self.adif_status.setText(f"✅ Enregistré : {path}")
            self.adif_status.setStyleSheet("color:#00ff88; font-size:9pt;")
        except Exception as e:
            self.adif_status.setText(f"❌ {e}"); self.adif_status.setStyleSheet("color:#ff4444; font-size:9pt;")

    def _append_adif(self):
        path, _ = QFileDialog.getOpenFileName(self, "Sélectionner ADIF existant",
            "", "ADIF (*.adi *.adif)")
        if not path:
            return
        try:
            with open(path, 'a', encoding='utf-8') as f:
                f.write(self._build_adif_str())
            self.adif_status.setText(f"✅ Ajouté à : {path}")
            self.adif_status.setStyleSheet("color:#00ff88; font-size:9pt;")
        except Exception as e:
            self.adif_status.setText(f"❌ {e}"); self.adif_status.setStyleSheet("color:#ff4444; font-size:9pt;")


