# ============================================================================
# THREAD POLLING FRÉQUENCE — non bloquant pour le thread Qt
# ============================================================================
class _FreqPollThread(QThread):
    """
    Lit la fréquence radio en arrière-plan.
    Le thread Qt n'est jamais bloqué par le timeout série.
    """
    freq_ready = pyqtSignal(int)   # fréquence en Hz

    def __init__(self, radio_controller, interval_ms=3000, single_shot=False):
        super().__init__()
        self._rc          = radio_controller
        self._interval_ms = interval_ms
        self._single_shot = single_shot
        self._running     = True

    def stop(self):
        self._running = False

    def run(self):
        while self._running:
            if self._rc.connected:
                try:
                    freq = self._rc.get_frequency()
                    if freq and freq > 0:
                        self.freq_ready.emit(int(freq))
                except Exception:
                    pass
            if self._single_shot or self._interval_ms <= 0:
                break
            # Attendre par tranches de 200ms pour pouvoir s'arrêter proprement
            waited = 0
            while self._running and waited < self._interval_ms:
                self.msleep(200)
                waited += 200


class RadioController:
    def __init__(self):
        self.connection_type=None; self.serial_port=None
        self.protocol='icom'; self.civ_address=0x94
        self._lock=threading.Lock()
        self.omnirig=None; self.rig=None

    @property
    def connected(self): return self.connection_type is not None

    def connect_serial(self, port, baudrate=19200, protocol='icom', civ_address=0x94, cw_port_name=None):
        if not SERIAL_AVAILABLE: return False,"pyserial non disponible"
        try:
            if self.serial_port and self.serial_port.is_open: self.serial_port.close()
            self.serial_port=serial.Serial(port=port,baudrate=baudrate,
                bytesize=8,parity='N',stopbits=1,timeout=1,write_timeout=1)
            # V8.4.2 F4LPS : de nombreux adaptateurs USB-CI-V/CAT (et ports
            # série virtuels type Eltima) exigent DTR/RTS actifs pour
            # alimenter le circuit ou établir la liaison — sans ça, le port
            # Windows s'ouvre normalement (donc "connecté") mais la radio ne
            # répond jamais aux requêtes, y compris la lecture de fréquence.
            try:
                self.serial_port.dtr = True
                self.serial_port.rts = True
            except Exception:
                pass
            self.connection_type='serial'; self.protocol=protocol; self.civ_address=civ_address
            # V8.4.3 F4LPS : sur certains ports virtuels (Eltima...), le pont
            # met un instant à s'établir juste après l'ouverture — un premier
            # échange immédiat peut partir dans le vide. On laisse le temps
            # de s'installer avant le premier essai, puis plusieurs essais
            # espacés. Si ça échoue quand même, on rapporte les octets bruts
            # reçus (le cas échéant) pour diagnostiquer précisément la cause.
            time.sleep(0.3)
            freq = 0
            last_raw = b''
            last_io_error = None
            for _ in range(4):
                try:
                    if protocol == 'icom':
                        freq, last_raw = self._icom_get_freq_debug()
                        last_io_error = self.last_io_error
                    else:
                        freq = self._yaesu_get_freq()
                        last_raw = b''
                except Exception as e:
                    freq = 0
                    last_io_error = str(e)
                if freq:
                    break
                time.sleep(0.3)
            if freq:
                return True, f"Connecté {port} {baudrate}bd — {freq/1e6:.4f} MHz"
            if last_io_error:
                return True, (f"Connecté {port} {baudrate}bd — ⚠️ erreur d'E/S sur le port : {last_io_error}")
            if last_raw:
                hexdump = last_raw.hex(' ')
                return True, (f"Connecté {port} {baudrate}bd — ⚠️ réponse reçue mais illisible : {hexdump}")
            return True, (f"Connecté {port} {baudrate}bd — ⚠️ aucun octet reçu de la radio "
                           f"(vérifie baudrate/adresse CI-V/protocole et que le câble CAT est bien relié)")
        except Exception as e: return False,str(e)

    def connect_omnirig(self, rig_number=1):
        try:
            if not OMNIRIG_AVAILABLE:
                return False, "OmniRig non disponible — installez OmniRig v2"
            self.omnirig = win32com.client.Dispatch("OmniRig.OmniRigX")
            self.rig = self.omnirig.Rig1 if rig_number == 1 else self.omnirig.Rig2
            if self.rig.Status == 0:
                return False, "Radio non configurée dans OmniRig"
            self.connection_type = 'omnirig'
            self.omnirig_rig_number = rig_number
            return True, f"OmniRig Rig{rig_number} connecté ({self.rig.StatusStr})"
        except Exception as e:
            return False, f"Erreur OmniRig : {e}"

    def get_frequency(self):
        if not self.connected: return 0
        try:
            if self.connection_type == 'omnirig' and self.rig:
                return int(self.rig.Freq or 0)
            if self.connection_type == 'hrd':
                client = getattr(self, '_hrd_client', None)
                hz = client.get_frequency_hz() if client else None
                return int(hz) if hz else 0
            if self.connection_type == 'flrig':
                freq = self._flrig_call('rig.get_vfoA', 'main.get_frequency')
                return int(float(freq)) if freq is not None else 0
            if self.protocol=='icom': return self._icom_get_freq()
            else: return self._yaesu_get_freq()
        except: return 0

    def set_frequency(self, freq_hz):
        if not self.connected: return False
        try:
            if self.connection_type == 'omnirig' and self.rig:
                self.rig.Freq = int(freq_hz); return True
            if self.connection_type == 'hrd':
                c = getattr(self,'_hrd_client',None)
                return bool(c.set_frequency_hz(int(freq_hz))) if c else False
            if self.connection_type == 'flrig':
                self._flrig_call('main.set_frequency','rig.set_vfoA',args=(float(freq_hz),))
                return True
            if self.protocol=='icom':
                self._icom_set_freq(int(freq_hz))
            else:
                self._yaesu_set_freq(int(freq_hz))
            return True
        except: return False

    def ptt_on(self):
        if not self.connected: return
        try:
            if self.connection_type == 'omnirig' and self.rig:
                self.rig.Tx = 1; return
            if self.connection_type == 'hrd':
                c = getattr(self,'_hrd_client',None)
                if c: c.ptt_on(); return
            if self.connection_type == 'flrig':
                self._flrig_call('rig.set_ptt','main.set_ptt',args=(1,)); return
            if self.protocol=='icom':
                self.serial_port.write(bytes([0xFE,0xFE,self.civ_address,0xE0,0x1C,0x00,0x01,0xFD]))
            else:
                # V8.4.1 F4LPS : PTT Yaesu (protocole CAT 5 octets) manquait —
                # la fréquence se lisait mais l'émission ne partait jamais
                # en connexion série directe (hors OmniRig/HRD/FLRig).
                self._yaesu_ptt_on()
        except: pass

    def ptt_off(self):
        if not self.connected: return
        try:
            if self.connection_type == 'omnirig' and self.rig:
                self.rig.Tx = 0; return
            if self.connection_type == 'hrd':
                c = getattr(self,'_hrd_client',None)
                if c: c.ptt_off(); return
            if self.connection_type == 'flrig':
                self._flrig_call('rig.set_ptt','main.set_ptt',args=(0,)); return
            if self.protocol=='icom':
                self.serial_port.write(bytes([0xFE,0xFE,self.civ_address,0xE0,0x1C,0x00,0x00,0xFD]))
            else:
                self._yaesu_ptt_off()
        except: pass

    def set_mode_usb(self):
        """Passe la radio en USB via la connexion CAT active."""
        if not self.connected:
            return False
        try:
            if self.connection_type == 'omnirig' and self.rig:
                # OmniRig RigParamX : PM_SSB_U = 0x02000000.
                self.rig.Mode = 0x02000000
                return True
            if self.connection_type == 'hrd':
                c = getattr(self, '_hrd_client', None)
                if c:
                    c.send_simple_command('set mode USB')
                    return True
            if self.connection_type == 'flrig':
                self._flrig_call('rig.set_mode', args=('USB',))
                return True
            if self.protocol == 'icom':
                # CI-V 06 01 = USB.
                self.serial_port.write(bytes([
                    0xFE, 0xFE, self.civ_address, 0xE0,
                    0x06, 0x01, 0xFD
                ]))
                return True
        except Exception:
            pass
        return False

    def set_mode_cw(self):
        """Passe la radio en CW via la connexion CAT active."""
        if not self.connected:
            return False
        try:
            if self.connection_type == 'omnirig' and self.rig:
                # OmniRig RigParamX : PM_CW_U = 0x00800000.
                self.rig.Mode = 0x00800000
                return True
            if self.connection_type == 'hrd':
                c = getattr(self, '_hrd_client', None)
                if c:
                    c.send_simple_command('set mode CW')
                    return True
            if self.connection_type == 'flrig':
                self._flrig_call('rig.set_mode', args=('CW',))
                return True
            if self.protocol == 'icom':
                # CI-V 06 03 = CW.
                self.serial_port.write(bytes([
                    0xFE, 0xFE, self.civ_address, 0xE0,
                    0x06, 0x03, 0xFD
                ]))
                return True
        except Exception:
            pass
        return False

    def disconnect(self):
        if self.connection_type == 'omnirig':
            self.omnirig=None; self.rig=None
        try: self._hrd_client=None
        except: pass
        try: self._flrig_proxy=None
        except: pass
        if self.serial_port:
            try:
                if self.serial_port.is_open: self.serial_port.close()
            except: pass
        self.connection_type=None

        self.connection_type=None

    def _icom_set_freq(self, freq_hz):
        freq_str=f"{int(freq_hz):010d}"
        bcd=[]
        for i in range(4,-1,-1):
            pos=i*2; bcd.append((int(freq_str[pos])<<4)|int(freq_str[pos+1]))
        cmd=bytes([0xFE,0xFE,self.civ_address,0xE0,0x05])+bytes(bcd)+bytes([0xFD])
        self.serial_port.write(cmd); time.sleep(0.05); self.serial_port.read(10)

    def _icom_get_freq(self):
        freq, _raw = self._icom_get_freq_debug()
        return freq

    def _icom_get_freq_debug(self):
        """V8.4.3 F4LPS : identique à _icom_get_freq mais renvoie aussi les
        octets bruts reçus, pour diagnostiquer un port qui répond avec
        n'importe quoi (adresse CI-V erronée, écho seul, bruit...) plutôt
        que de rien recevoir du tout.
        V8.4.4 F4LPS : write()/read() pouvaient lever une exception (port
        virtuel qui refuse l'écriture, erreur d'accès...) — avant, cette
        exception remontait à l'appelant et écrasait silencieusement le
        diagnostic, affichant à tort "aucun octet reçu" au lieu de la vraie
        erreur d'E/S. On capture maintenant l'erreur et on la renvoie sous
        forme de texte via self.last_io_error pour l'afficher à l'utilisateur."""
        self.last_io_error = None
        with self._lock:
            cmd=bytes([0xFE,0xFE,self.civ_address,0xE0,0x03,0xFD])
            try:
                self.serial_port.reset_input_buffer()
            except Exception:
                pass
            try:
                self.serial_port.write(cmd)
                time.sleep(0.35)
                resp=self.serial_port.read(64)
            except Exception as e:
                self.last_io_error = str(e)
                return 0, b''
        for i in range(len(resp)-10):
            if resp[i]==0xFE and resp[i+1]==0xFE and resp[i+2]==0xE0 and resp[i+4]==0x03:
                bcd=resp[i+5:i+10]
                freq_str="".join(f"{(b>>4)&0xF}{b&0xF}" for b in reversed(bcd))
                try:
                    f=int(freq_str)
                    return (f, resp) if 0<f<1000000000 else (0, resp)
                except: pass
        return 0, resp

    def _yaesu_get_freq(self):
        self.serial_port.write(bytes([0,0,0,0,3])); time.sleep(0.2)
        resp=self.serial_port.read(5)
        if len(resp)<5: return 0
        freq=0
        for b in resp[:4]: freq=freq*100+(b>>4)*10+(b&0xF)
        return freq*10

    def _yaesu_set_freq(self, freq_hz):
        """CAT Yaesu 5 octets (FT-847/857/897/100...) : commande 0x01,
        fréquence en BCD sur 4 octets, pas de 10 Hz."""
        val = int(round(freq_hz / 10.0))
        s = f"{val:08d}"
        bcd = bytes((int(s[i]) << 4) | int(s[i+1]) for i in range(0, 8, 2))
        self.serial_port.write(bcd + bytes([0x01]))

    def _yaesu_ptt_on(self):
        """CAT Yaesu 5 octets : commande 0x0F, P1=0x00 -> TX ON."""
        self.serial_port.write(bytes([0x00, 0, 0, 0, 0x0F]))

    def _yaesu_ptt_off(self):
        """CAT Yaesu 5 octets : commande 0x0F, P1=0x80 -> TX OFF (RX)."""
        self.serial_port.write(bytes([0x80, 0, 0, 0, 0x0F]))



# ── HRD IP Server + FLRig pour Radio CAT PSK ────────────────────────────────
class _HRDRigControlClient:
    MAGIC1 = 0x1234ABCD
    MAGIC2 = 0xABCD1234

    def __init__(self, host='127.0.0.1', port=7809):
        self.host = host
        self.port = int(port)
        self._buttons_cache = None
        self._tx_button_name = None

    def _recv_exact(self, sock, size):
        data = bytearray()
        while len(data) < size:
            chunk = sock.recv(size - len(data))
            if not chunk:
                break
            data.extend(chunk)
        return bytes(data)

    def _send(self, cmd):
        s = None
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.settimeout(2.0)
            s.connect((self.host, self.port))
            payload = (cmd + '\x00').encode('utf-16-le')
            size = 16 + len(payload)
            msg = struct.pack('<IIIi', size, self.MAGIC1, self.MAGIC2, 0) + payload
            s.sendall(msg)
            header = self._recv_exact(s, 16)
            if len(header) < 16:
                return None
            total_size, magic1, magic2, _ = struct.unpack('<IIIi', header)
            if magic1 != self.MAGIC1 or magic2 != self.MAGIC2 or total_size < 16:
                return None
            body = self._recv_exact(s, total_size - 16) if total_size > 16 else b''
            return body.decode('utf-16-le', errors='ignore').rstrip('\x00').strip()
        except Exception as e:
            print(f'❌ HRD CAT: {e}')
            return None
        finally:
            try:
                if s: s.close()
            except Exception:
                pass

    def send_simple_command(self, cmd):
        resp = self._send(cmd)
        if resp is None:
            return False
        low = str(resp).strip().lower()
        return not (low.startswith('error') or low.startswith('exception'))

    def get_frequency_hz(self):
        resp = self._send('get frequency')
        if not resp:
            return None
        try:
            hz = float(resp)
            return int(hz if hz > 1000 else hz * 1e6)
        except Exception:
            m = re.search(r'(\d{5,})', str(resp))
            return int(m.group(1)) if m else None

    def set_frequency_hz(self, freq_hz):
        return self.send_simple_command(f'set frequency-hz {int(freq_hz)}')

    def get_buttons(self):
        if self._buttons_cache is None:
            resp = self._send('get buttons') or ''
            self._buttons_cache = [b.strip() for b in resp.split(',') if b.strip()]
        return list(self._buttons_cache)

    def _find_ptt_button(self):
        if self._tx_button_name:
            return self._tx_button_name
        for name in self.get_buttons():
            low = name.lower()
            if low in ('tx', 'ptt', 'mox', 'transmit') or 'tx' in low or 'ptt' in low:
                self._tx_button_name = name
                return name
        return None

    def set_button(self, name, checked=True):
        return self.send_simple_command(f'set button-select {name} {"1" if checked else "0"}')

    def ptt_on(self):
        btn = self._find_ptt_button()
        return self.set_button(btn, True) if btn else False

    def ptt_off(self):
        btn = self._find_ptt_button()
        return self.set_button(btn, False) if btn else False


def _rc_connect_hrd(self, host='127.0.0.1', port=7809):
    try:
        client = _HRDRigControlClient(host, int(port))
        freq = client.get_frequency_hz()
        if freq is None:
            return False, f'HRD IP Server non accessible sur {host}:{int(port)}'
        self.disconnect()
        self._hrd_client = client
        self.connection_type = 'hrd'
        return True, f'HRD connecté ({host}:{int(port)}) — {int(freq)/1e6:.4f} MHz'
    except Exception as e:
        return False, f'Erreur HRD: {e}'


def _rc_connect_flrig(self, host='127.0.0.1', port=12345):
    try:
        proxy = _xmlrpc_client.ServerProxy(f'http://{host}:{int(port)}/RPC2', allow_none=True)
        ok = False
        for call in (lambda: proxy.main.get_version(), lambda: proxy.rig.get_vfoA(), lambda: proxy.rig.get_vfo()):
            try:
                call(); ok = True; break
            except Exception:
                pass
        if not ok:
            return False, f'FLRig inaccessible sur {host}:{int(port)}'
        self.disconnect()
        self._flrig_proxy = proxy
        self.connection_type = 'flrig'
        return True, f'FLRig connecté ({host}:{int(port)})'
    except Exception as e:
        return False, f'Erreur FLRig: {e}'


def _rc_flrig_call(self, *method_names, args=()):
    proxy = getattr(self, '_flrig_proxy', None)
    if proxy is None:
        raise RuntimeError('FLRig non connecté')
    last = None
    for name in method_names:
        try:
            obj = proxy
            for part in name.split('.'):
                obj = getattr(obj, part)
            return obj(*args)
        except Exception as e:
            last = e
    raise last or RuntimeError('Aucune méthode FLRig valide')

RadioController.connect_hrd = _rc_connect_hrd
RadioController.connect_flrig = _rc_connect_flrig
RadioController._flrig_call = _rc_flrig_call


