# FENÊTRE ÉDITION MACROS (V1.6.53)
# ============================================================================
class MacrosWindow(QDialog):
    def __init__(self, parent):
        super().__init__(parent, Qt.Window)
        self.main=parent; self.setWindowTitle("🖊  Macros rapides + libres — MultiDigi")
        self.setMinimumSize(800,580); self.resize(900,640)
        self.setStyleSheet("QDialog{background:#0d000d;color:#ddaacc;}QTextEdit,QLineEdit{background:#08000f;color:#ffaacc;font-family:'Courier New';font-size:9pt;border:1px solid #440044;padding:3px;}QPushButton{border-radius:3px;padding:3px 12px;}QLabel{color:#ccaabb;font-size:8pt;}QGroupBox{border:1px solid #440044;border-radius:4px;margin-top:8px;color:#cc88aa;}QGroupBox::title{subcontrol-origin:margin;left:8px;padding:0 4px;}")
        self._build_ui()
        self._t=QTimer(self); self._t.timeout.connect(self._refresh); self._t.start(2000)
    def _build_ui(self):
        root=QVBoxLayout(self); root.setContentsMargins(10,8,10,8); root.setSpacing(6)
        hdr=QHBoxLayout()
        hdr.addWidget(QLabel("<b style='color:#ff88cc;font-size:11pt;'>🖊  Macros rapides éditables</b>"))
        hdr.addStretch()
        self._call_badge=QLabel("CALL : —")
        self._call_badge.setStyleSheet("color:#00ffcc;font-family:'Courier New';font-size:10pt;font-weight:bold;background:#001a10;border:1px solid #006644;padding:2px 10px;border-radius:10px;")
        hdr.addWidget(self._call_badge)
        btn_save=QPushButton("💾 Sauvegarder"); btn_save.setStyleSheet("background:#150010;color:#ff44aa;border:1px solid #4a004a;")
        btn_save.clicked.connect(self.main._save_settings); hdr.addWidget(btn_save)
        root.addLayout(hdr)
        sep=QFrame(); sep.setFrameShape(QFrame.HLine); sep.setStyleSheet("background:#330033;max-height:1px;"); root.addWidget(sep)
        grp=QGroupBox("Macros — nom du bouton rapide + texte éditables")
        g=QGridLayout(grp); g.setSpacing(4); g.setContentsMargins(8,14,8,6); g.setColumnStretch(2,1)
        self._macro_edits=[]
        self._macro_name_edits=[]
        names=getattr(self.main,'_macro_names',[f"F{i+1}" for i in range(len(getattr(self.main, '_macros', [])))])
        for i in range(len(getattr(self.main, '_macros', []))):
            lbl=QLabel(f"<b>F{i+1}</b>")
            lbl.setFixedWidth(36)
            name_ed=QLineEdit(names[i] if i<len(names) else f"F{i+1}")
            name_ed.setFixedWidth(135)
            name_ed.setToolTip("Nom affiché sur le bouton macro rapide")
            ed=QTextEdit(); ed.setPlainText(self.main._macros[i] if i<len(self.main._macros) else ""); ed.setFixedHeight(42)
            def _set_macro_text(idx, widget):
                try:
                    self.main._macros[idx]=widget.toPlainText()
                except Exception:
                    pass
            def _set_macro_name(idx, widget):
                try:
                    while len(self.main._macro_names) <= idx:
                        self.main._macro_names.append(f"F{len(self.main._macro_names)+1}")
                    self.main._macro_names[idx]=widget.text().strip() or f"F{idx+1}"
                    if hasattr(self.main, '_refresh_macro_bar_labels'):
                        self.main._refresh_macro_bar_labels()
                except Exception:
                    pass
            ed.textChanged.connect(lambda idx=i,e=ed: _set_macro_text(idx,e))
            name_ed.textChanged.connect(lambda txt,idx=i,e=name_ed: _set_macro_name(idx,e))
            g.addWidget(lbl,i,0); g.addWidget(name_ed,i,1); g.addWidget(ed,i,2)
            self._macro_name_edits.append(name_ed)
            self._macro_edits.append(ed)
        self.main._macro_edits=self._macro_edits
        self.main._macro_name_edits=self._macro_name_edits
        root.addWidget(grp)
        pg=QGroupBox("👁  Aperçu"); pgl=QVBoxLayout(pg); pgl.setContentsMargins(8,12,8,6)
        self._prev=QTextEdit(); self._prev.setReadOnly(True); self._prev.setMaximumHeight(70)
        self._prev.setStyleSheet("QTextEdit{background:#020008;color:#00ffcc;font-family:'Courier New';font-size:9pt;border:1px solid #220044;}")
        pgl.addWidget(self._prev); root.addWidget(pg)
        ref=QLabel("<i><b>Variables :</b> {MYCALL} {DXCALL} {CALL} {FIRSTNAME} {DXNAME} {RST_TX} {RST_RX} {RST} {NAME} {QTH} {LOCATOR} {POWER} {ANTENNA} {RIG} {LICENCE} {QSL} {INFO} {PROGRAM} {FREQ} {BAND} {MODE} {DATE} {TIME} {UTC} &nbsp;&nbsp; <b>Balises :</b> &lt;stop&gt; &lt;add-log&gt;</i>")
        ref.setWordWrap(True); ref.setStyleSheet("color:#554455;font-size:7pt;"); root.addWidget(ref)
    def _show_preview(self, idx):
        raw=self.main._macros[idx] if idx<len(self.main._macros) else ""
        t,dl,st=self.main._process_macro_tags(self.main._expand_macro(raw))
        self._prev.setPlainText(t+("\n✅ log auto" if dl else "")+("\n⏹ stop TX" if st else ""))
    def _refresh(self):
        try:
            self._call_badge.setText(f"CALL : {getattr(self.main,'_last_dxcall','') or '—'}")
            fam = getattr(self.main, '_family', 'PSK')
            self.setWindowTitle(f"🖊  Macros {fam} — MultiDigi")
        except: pass
    def closeEvent(self,e): e.ignore(); self.hide()
    def keyPressEvent(self,event):
        fkeys=[Qt.Key_F1,Qt.Key_F2,Qt.Key_F3,Qt.Key_F4,Qt.Key_F5,Qt.Key_F6,Qt.Key_F7,Qt.Key_F8,Qt.Key_F9,Qt.Key_F10]
        k=event.key()
        if k in fkeys:
            idx=fkeys.index(k)
            if event.modifiers()&Qt.ShiftModifier: self.main._send_macro(idx)
            else: self.main._copy_macro_to_tx(idx)
        else: super().keyPressEvent(event)

