class RadioCatWindow(QDialog):
    """Fenêtre dédiée RADIO CAT — CI-V, HRD, FLRig, OmniRig."""
    def __init__(self, parent):
        super().__init__(parent, Qt.Window)
        self.main = parent
        self.setWindowTitle("🎛️  RADIO CAT — MultiDigi")
        self.setMinimumSize(540, 580)
        self.resize(600, 640)
        self.setStyleSheet(parent.styleSheet())
        self._build_ui()
        self._t = QTimer(self)
        self._t.timeout.connect(self._refresh)
        self._t.start(2000)

    def _grp(self, title):
        g = QGroupBox(title)
        g.setStyleSheet(
            "QGroupBox{border:1px solid #003366;border-radius:4px;margin-top:8px;"
            "color:#00aaff;font-weight:bold;font-size:9pt;}"
            "QGroupBox::title{subcontrol-origin:margin;left:8px;padding:0 4px;}"
        )
        return g

    def _lbl(self, t):
        l = QLabel(t)
        l.setStyleSheet("color:#5588aa;font-size:8pt;")
        l.setAlignment(Qt.AlignRight | Qt.AlignVCenter)
        return l

    def _ed(self, val=""):
        e = QLineEdit(val)
        e.setStyleSheet(
            "background:#050f1a;color:#88ccff;border:1px solid #003366;"
            "padding:3px 5px;font-family:'Courier New';"
        )
        return e

