            ("🔴 PTT ON",    lambda: m.radio_ctrl.ptt_on(),         f"background:#2a0000;color:#ff4444;font-weight:bold;border:1px solid #880000;padding:5px 10px;border-radius:3px;"),
            ("⬛ PTT OFF",   lambda: m.radio_ctrl.ptt_off(),        f"background:#111;color:#aaaaaa;{_ss}"),
