        self.tx_freq_spin.setSuffix(" Hz")
        self.tx_freq_spin.setSingleStep(10)
        self.tx_freq_spin.setToolTip("Fréquence audio d'émission dans le waterfall. Exemple : 1500 Hz en USB.")
        try:
            self.tx_freq_spin.valueChanged.connect(lambda *_: self._save_settings())
        except Exception:
            pass
        tx_row.addWidget(self.tx_freq_spin)
        self.tx_link_rx_cb = QCheckBox("TX = RX")
        self.tx_link_rx_cb.setChecked(True)
        self.tx_link_rx_cb.setToolTip("Si coché, le TX suit automatiquement RX Center / clic waterfall.")
        self.tx_link_rx_cb.toggled.connect(self._on_tx_link_toggled)
