    def _toggle_js8_auto_detect(self, enabled):
        try:
            decoder = getattr(self, "decoder_obj", None)
            if decoder is not None and hasattr(decoder, "set_auto_detect"):
                decoder.set_auto_detect(bool(enabled))
            at = getattr(self, "audio_thread", None)
            if at is not None:
                d2 = getattr(at, "decoder", None)
                if d2 is not None and hasattr(d2, "set_auto_detect"):
                    d2.set_auto_detect(bool(enabled))
            self._set_status(
                "📡 Auto-détection JS8 0-3000 Hz : "
                + ("ON" if enabled else "OFF")
            )
        except Exception:
            pass

    def _update_js8_ruler_from_decoder(self):
        """Recale la règle temps JS8 sur la vraie synchro Costas reçue."""
        try:
            if getattr(self, "_family", "") != "JS8":
                return

            decoder = None

            # Depending on current MultiDigi plumbing, decoder can sit in
            # audio_thread.decoder or directly on the main window.
            at = getattr(self, "audio_thread", None)
            if at is not None:
                decoder = getattr(at, "decoder", None)
                if decoder is None:
                    decoder = getattr(at, "modem_decoder", None)

            if decoder is None:
                decoder = getattr(self, "decoder", None)

            if decoder is None or not hasattr(decoder, "get_diagnostics"):
                return

            d = decoder.get_diagnostics() or {}

            # V8.3.37 : diagnostic JS8 réel visible dans l'interface.
            try:
                state = str(d.get("state", "ATTENTE JS8") or "ATTENTE JS8")
                sync_score = float(d.get("sync", 0.0) or 0.0)
                acq_best = float(d.get("acq_best_score", 0.0) or 0.0)
                acq_freq = float(d.get("acq_best_freq", 0.0) or 0.0)
                llr_count = int(d.get("llr_count", 0) or 0)
                ldpc_status = str(d.get("ldpc_status", "—") or "—")
                crc_ok = bool(d.get("crc_ok", False))
                txt = str(d.get("js8_text", "") or "")
                attempts = int(d.get("ldpc_attempts", 0) or 0)
                ok_count = int(d.get("ldpc_ok_count", 0) or 0)
                crc_fails = int(d.get("crc_fail_count", 0) or 0)
                post_frames = int(d.get("postsync_frames", 0) or 0)
                post_best = int(d.get("postsync_best_checks", 87) or 87)
                pol_n = int(d.get("postsync_normal_checks", 87) or 87)
                pol_i = int(d.get("postsync_invert_checks", 87) or 87)
                pol_pref = str(
                    d.get("postsync_preferred_polarity", "NORMAL")
                    or "NORMAL"
                )
                scale_best = float(
                    d.get("postsync_scale_best", 1.0) or 1.0
                )
                scale_checks = int(
                    d.get("postsync_scale_checks", 87) or 87
                )
                cmp_n = int(
                    d.get("cmp_normal_checks", 87) or 87
                )
                cmp_201 = int(
                    d.get("cmp_201sign_checks", 87) or 87
                )
                cmp_win = str(
                    d.get("cmp_winner", "—") or "—"
                )
                llr_min = float(d.get("llr_min_abs", 0.0) or 0.0)
                llr_p10 = float(d.get("llr_p10_abs", 0.0) or 0.0)
                weak_syms = str(d.get("llr_weak_symbols", "—") or "—")
                smart_n = int(d.get("smart_erase_best_n", 0) or 0)
                smart_checks = int(
                    d.get("smart_erase_best_checks", 87) or 87
                )
                smart_table = str(
                    d.get("smart_erase_table", "—") or "—"
                )

                if hasattr(self, "js8_decode_status"):
                    crc_txt = "OK" if crc_ok else "—"
                    llr_mean = float(d.get("llr_abs_mean", 0.0) or 0.0)
                    llr_pos = int(d.get("llr_pos", 0) or 0)
                    llr_neg = int(d.get("llr_neg", 0) or 0)
                    best_map = str(
                        d.get("llr_best_mapping", "—") or "—"
                    )
                    best_checks = int(
                        d.get("llr_best_checks", 87) or 87
                    )
                    cache_map = str(
                        d.get("mapping_cache", "—") or "—"
                    )
                    cache_valid = bool(
                        d.get("mapping_cache_valid", False)
                    )

                    _mem_suffix = ""
                    if bool(d.get("frame_just_ended", False)):
                        _mem_suffix = (
                            f" | MEM={float(d.get('last_good_sync_freq',0.0)):.0f}Hz"
                        )
                    # TEST PIPELINE JS8 — AFFICHAGE EXCLUSIF.
                    # On remplace temporairement toute la longue ligne MONO
                    # pour garantir la visibilité du scanner pleine bande.
                    try:
                        # IMPORTANT : l'audio brut est envoyé à
                        # self.audio_thread.decoder.process_audio(samples).
                        # C'est CETTE instance qui possède le vrai _band_buffer.
                        _live_decoder = getattr(
                            getattr(self, "audio_thread", None),
                            "decoder",
                            None,
                        )
                        if _live_decoder is None:
                            raise RuntimeError("audio_thread.decoder absent")
                        _mst = _live_decoder.get_band_status()
                        _due = ",".join(
                            str(v).replace("JS8 ", "")
                            for v in (_mst.get("hb_due", ()) or ())
                        ) or "-"
                        _err = str(_mst.get("hb_exception", "") or "")
                        _calls = int(
                            getattr(
                                getattr(self, "audio_thread", None),
                                "_live_process_calls",
                                0,
                            )
                        )
                        _bank_key = (
                            int(_mst.get("hb_done",0)),
                            tuple(
                                (
                                    round(float(q.get("freq_hz",0.0)), 1),
                                    str(q.get("variant","")),
                                    round(float(q.get("costas",0.0)), 2),
                                )
                                for q in (_mst.get("costas_grid", []) or [])
                            )
                        )
                        if getattr(self, "_js8_last_bank_print", None) != _bank_key:
                            self._js8_last_bank_print = _bank_key
                            print(
                                "JS8 COSTAS ACQ V71 | "
                                + (", ".join(
                                    f"{str(q.get('variant','')).replace('JS8 ','')}:"
                                    f"G{float(q.get('energy_gate_hz',0.0)):.1f}->"
                                    f"CEN{float(q.get('center_hz',q.get('freq_hz',0.0))):.1f}/"
                                    f"d{float(q.get('gate_delta_hz',0.0)):+.1f}/"
                                    f"C{float(q.get('costas',0.0)):.2f}"
                                    for q in (_mst.get("costas_grid", []) or [])
                                ) or "VIDE")
                            )
                        _scan_ms = float(
                            _mst.get("last_scan_ms", 0.0) or 0.0
                        )
                        _grid = list(_mst.get("costas_grid", []) or [])
                        # Candidats issus DIRECTEMENT de la grille Costas.
                        # Aucun barycentre spectral n'intervient ici.
                        _short = {
                            "JS8 NORMAL": "N",
                            "JS8 FAST": "F",
                            "JS8 SLOW": "S",
                            "JS8 40": "T",
                        }
                        _grid_txt = " ; ".join(
                            (
                                f"{_short.get(str(q.get('variant','')),'?')} "
                                f"G={float(q.get('energy_gate_hz',0.0)):.0f}→"
                                f"CEN={float(q.get('center_hz',q.get('freq_hz',0.0))):.0f} "
                                f"d={float(q.get('gate_delta_hz',0.0)):+.0f} "
                                f"C={float(q.get('costas',0.0)):.2f} "
                                f"S={int(q.get('nsync',0))}/21 "
                                f"{('D'+str(int(q.get('v34_seed_hits',0)))+'+'+str(int(q.get('v31_confirm_hits',0)))+' ') if q.get('v34_direct_confirm',False) else ''}"
                                f"{('C5+'+str(int(q.get('v31_confirm_hits',0)))+' ') if q.get('v31_confirmed_5of7',False) else ''}"
                                f"{('FS'+str(int(q.get('v29_single_hits',0)))+' ') if q.get('v29_fallback_single',False) else ''}"
                                f"CB={int(q.get('v22_n_blocks',0))} "
                                f"PH={int(q.get('v22_pair_hits',0))} "
                                f"TH={int(q.get('v22_third_hits',0))} "
                                f"L={int(q.get('checks',87))} "
                                f"{'R* ' if q.get('v26_recovery_improved',False) else ('R ' if q.get('v26_recovery_used',False) else '')}"
                                f"P={q.get('ldpc_pass','—')} "
                                f"df={float(q.get('refine_df_hz',0.0)):+.0f} "
                                f"dt={int(q.get('refine_dt_ms',0)):+d}ms "
                                f"CRC={q.get('crc','—')}"
                            )
                            for q in _grid[:12]
                        )
                        if not _grid_txt:
                            _gates = list(_mst.get("signal_bank", []) or [])
                            _grid_txt = "GATES=" + (
                                ",".join(
                                    f"{float(g.get('freq_hz',0.0)):.0f}"
                                    for g in _gates[:12]
                                ) or "—"
                            )
                        msg = (
                            f"JS8 COSTAS PAIR V22 | "
                            f"C={_calls} A={_mst.get('hb_audio',0)} "
                            f"S={_mst.get('hb_schedule',0)} "
                            f"W={_mst.get('hb_worker',0)} "
                            f"D={_mst.get('hb_done',0)} "
                            f"T={_scan_ms:.0f}ms | "
                            f"GRID={_grid_txt} | "
                            f"ERR={_err[:70] if _err else '-'}"
                        )
                    except Exception as _e:
                        msg = (
                            "JS8 LIVE PIPELINE | "
                            f"STATUS ERROR={type(_e).__name__}: {str(_e)[:120]}"
                        )
                    self.js8_decode_status.setText(msg)
                    if crc_ok and txt:
                        self.js8_decode_status.setStyleSheet(
                            "background:#06200d;color:#66ff99;border:1px solid #33aa66;"
                            "border-radius:3px;padding:3px 8px;font-family:'Courier New';"
                            "font-size:8pt;font-weight:bold;"
                        )
                    elif bool(d.get("time_locked", False)):
                        self.js8_decode_status.setStyleSheet(
                            "background:#201a05;color:#ffdd66;border:1px solid #8a7020;"
                            "border-radius:3px;padding:3px 8px;font-family:'Courier New';"
                            "font-size:8pt;font-weight:bold;"
                        )
                    else:
                        self.js8_decode_status.setStyleSheet(
                            "background:#071018;color:#aaccff;border:1px solid #26445a;"
                            "border-radius:3px;padding:3px 8px;font-family:'Courier New';"
                            "font-size:8pt;font-weight:bold;"
                        )

                # Réutilise aussi le panneau Diagnostic RX existant.
                if hasattr(self, "diag_state"):
                    self.diag_state.setText(state)
                    self.diag_costas.setText(f"{sync_score:.2f}")
                    self.diag_timing.setText(
                        "SYNC" if bool(d.get("time_locked", False)) else "—"
                    )
                    self.diag_dcd.setText(
                        "ON" if bool(d.get("time_locked", False)) else "OFF"
                    )
                    self.diag_snr.setText(
                        f"{float(d.get('snr', -99.0) or -99.0):.1f} dB"
                    )
                    self.diag_varicode.setText(
                        f"LDPC {ok_count}/{attempts}" if attempts else "LDPC —"
                    )
                    self.diag_chars.setText(
                        f"{int(d.get('js8_text_count', 0) or 0)} / {crc_fails}"
                    )
            except Exception:
                pass

            try:
                auto_f = float(d.get("auto_detect_freq", 0.0) or 0.0)
                confirmed = bool(d.get("auto_detect_confirmed", False))
                confirm_score = float(
                    d.get("auto_detect_confirm_score", 0.0) or 0.0
                )
                manual_override = bool(d.get("manual_override", False))
                if (
                    not manual_override
                    and confirmed
                    and auto_f > 80.0
                    and confirm_score >= 1.35
                ):
                    if hasattr(self, "waterfall"):
                        self.waterfall.set_center_freq(auto_f)
                    try:
                        self._rx_center_hz = float(auto_f)
                    except Exception:
                        pass
            except Exception:
                pass

            if not bool(d.get("time_locked", False)):
                return

            epoch = float(d.get("frame_start_epoch", 0.0) or 0.0)
            if epoch <= 0:
                return

            serial = int(d.get("frame_serial", 0) or 0)
            last_serial = int(getattr(self, "_js8_last_ruler_serial", -1))

            # Re-lock only when a newly decoded/synchronized frame arrives.
            if serial == last_serial:
                return

            self._js8_last_ruler_serial = serial
            self.js8_time_ruler.sync_to_received_frame(
                epoch,
                quality=float(d.get("sync", 0.0) or 0.0),
                dt=float(d.get("dt", 0.0) or 0.0),
                freq=float(d.get("center", 0.0) or 0.0),
            )

        except Exception:
            pass

    def _qsy_js8(self, freq_hz):
        """QSY JS8 : USB puis fréquence."""
        try:
            rc = getattr(self, "radio_ctrl", None)
            if rc is not None and bool(getattr(rc, "connected", False)):
                try:
                    rc.set_mode_usb()
                except Exception:
                    pass
                QTimer.singleShot(80, lambda f=int(freq_hz): self._qsy(f))
            else:
                self._qsy(int(freq_hz))
        except Exception:
            self._qsy(int(freq_hz))

    def _update_freq_buttons(self, base_mode):
        """Met à jour les boutons de fréquences PSK ou JS8."""
        while self._freq_grid.count():
            item = self._freq_grid.takeAt(0)
            if item.widget():
                item.widget().deleteLater()

        is_js8 = str(base_mode or "").upper() == "JS8"

        if is_js8:
            freqs = list(JS8_FREQUENCIES)
            cols = 6
            if hasattr(self, "freq_grp"):
                self.freq_grp.setTitle(
                    "📻 FRÉQUENCES JS8 — Clic = USB + QSY radio"
                )
        else:
            key = base_mode if base_mode in PSK_FREQUENCIES else "BPSK31"
            freqs = PSK_FREQUENCIES.get(key, [])
            cols = 6
            if hasattr(self, "freq_grp"):
                self.freq_grp.setTitle(
                    "📻 FRÉQUENCES PSK — Clic = QSY radio + marqueur"
                )

        for i, (freq_hz, band, label) in enumerate(freqs):
            bg, fg = BAND_COLORS.get(band, ("#1a0015", "#ff44aa"))
            btn = QPushButton(label)
            btn.setMinimumHeight(48)
            btn.setMinimumWidth(85)
            btn.setToolTip(
                f"{freq_hz/1e6:.4f} MHz — {band}"
                + (" — fréquence JS8Call" if is_js8 else "")
            )
            btn.setStyleSheet(
                f"QPushButton{{background:{bg};color:{fg};font-weight:bold;"
                f"font-size:8pt;border:1px solid {fg};border-radius:4px;}}"
                f"QPushButton:hover{{background:{fg};color:#000;}}"
            )
            if is_js8:
                btn.clicked.connect(
                    lambda checked, f=freq_hz: self._qsy_js8(f)
                )
            else:
                btn.clicked.connect(
                    lambda checked, f=freq_hz: self._qsy(f)
                )
            self._freq_grid.addWidget(btn, i // cols, i % cols)


