    def _update_rx_center_display(self, hz=None):
        try:
            if hz is None:
                hz = float(self.center_freq_spin.value()) if hasattr(self, 'center_freq_spin') else float(getattr(self.waterfall, 'center_freq', 1500.0))
            if hasattr(self, 'rx_center_lbl'):
                self.rx_center_lbl.setText(f"RX Center : {float(hz):.0f} Hz")
        except Exception:
            pass

    def _nudge_center_hz(self, delta_hz):
        """Déplace RX Center de ±1 Hz, sans lancer l'AutoCenter."""
        try:
            cur = float(self.center_freq_spin.value())
            new_hz = max(float(self.center_freq_spin.minimum()), min(float(self.center_freq_spin.maximum()), cur + float(delta_hz)))
            try:
                if hasattr(self, 'btn_autopitch') and self.btn_autopitch.isChecked():
                    self.btn_autopitch.setChecked(False)
                    self._autopitch_enabled = False
            except Exception:
                pass
            self.center_freq_spin.blockSignals(True)
            self.center_freq_spin.setValue(new_hz)
            self.center_freq_spin.blockSignals(False)
            self._on_center_freq_changed(new_hz)
            self._update_rx_center_display(new_hz)
            self._set_status(f"RX Center ajusté : {new_hz:.0f} Hz")
        except Exception as e:
            try: print(f"⚠️ Ajust RX Center ±1 Hz ignoré: {e}")
            except Exception: pass

    def _open_macros_window(self):
        if not hasattr(self, '_macros_win') or self._macros_win is None:
            self._macros_win = MacrosWindow(self)
        self._macros_win.show(); self._macros_win.raise_(); self._macros_win.activateWindow()

    def eventFilter(self, obj, event):
        from PyQt5.QtCore import QEvent

        # Double-clic dans le texte RX : prendre uniquement le mot sous la souris
        # et le mettre dans CALL actif, sans la sélection QTextEdit qui attrapait
        # parfois plusieurs mots.
        try:
            if hasattr(self, 'rx_text') and obj is self.rx_text.viewport() and event.type() == QEvent.MouseButtonDblClick:
                # V2.1.6 : priorité aux lignes RSID. Le curseur ne se déplace
                # jamais tout seul ; seul ce double-clic volontaire applique f=...Hz.
                try:
                    line_cursor = self.rx_text.cursorForPosition(event.pos())
                    line_cursor.select(QTextCursor.LineUnderCursor)
                    line_text = str(line_cursor.selectedText() or '')
                    m_rsid = re.search(r'RSID:.*?f\s*=\s*([0-9]+(?:[.,][0-9]+)?)\s*Hz',
                                       line_text, flags=re.IGNORECASE)
                    if m_rsid:
                        hz = float(m_rsid.group(1).replace(',', '.'))
                        self._on_wf_click(hz)
                        self._set_status(
                            f'✓ RX Center déplacé volontairement sur le RSID : {hz:.0f} Hz'
                        )
                        return True
                except Exception:
                    pass

                # V1.6.106 : double-clic = un seul mot, jamais une phrase complète.
                # Si c'est un indicatif, il devient CALL actif. Sinon le mot est simplement copié.
                if self._rx_use_call_from_mouse(event.pos(), copy_clipboard=True):
                    return True
                word = self._rx_word_under_pos(event.pos())
                if word:
                    try:
                        if self._rx_is_name_candidate(word):
                            self._rx_set_dx_name_from_word(word)
                            QApplication.clipboard().setText(word)
                            return True
                        QApplication.clipboard().setText(word)
                        self._set_status(f"📋 Mot RX copié : {word}")
                    except Exception:
                        pass
                    return True
        except Exception:
            pass

        if event.type() == QEvent.Enter:
            idx = obj.property("macro_idx")
            if idx is not None:
                raw = self._macros[idx] if idx < len(self._macros) else ""
                if raw:
                    exp = self._expand_macro(raw)
                    text, do_log, stop = self._process_macro_tags(exp)
                    tip = text[:500] + ("..." if len(text)>500 else "")
                    tags = []
                    if do_log: tags.append("<add-log> ✅ log auto")
                    if stop:   tags.append("<stop> ⏹ arrêt TX")
                    if tags:   tip += "\n\n" + "\n".join(tags)
                    tip += "\n\nClic gauche : copier dans TX\nClic droit  : éditer"
                    obj.setToolTip(tip)
        return super().eventFilter(obj, event)

    def _refresh_macro_bar_labels(self):
        try:
            names = getattr(self, '_macro_names', [])
            for i, btn in enumerate(getattr(self, '_macro_bar_btns', [])):
                name = names[i] if i < len(names) and names[i] else f"F{i+1}"
                btn.setText(f"▶ {name}")
        except Exception:
            pass

    def _edit_macro_dialog(self, idx):
        names = getattr(self,'_macro_names',[f"F{i+1}" for i in range(len(getattr(self, '_macros', [])))])
        name  = names[idx] if idx<len(names) else f"F{idx+1}"
        raw   = self._macros[idx] if idx<len(self._macros) else ""
        dlg = QDialog(self); dlg.setWindowTitle(f"Éditer macro F{idx+1}"); dlg.setMinimumWidth(700)
        dlg.setStyleSheet("QDialog{background:#0d000d;color:#ddaacc;}QTextEdit,QLineEdit{background:#08000f;color:#ffaacc;font-family:'Courier New';font-size:10pt;border:1px solid #440044;padding:4px;}QLabel{color:#aa7799;}QPushButton{border-radius:3px;padding:4px 14px;}")
        lay = QVBoxLayout(dlg); lay.setSpacing(8)
        lay.addWidget(QLabel(f"<b style='color:#ff88cc;font-size:10pt;'>Macro F{idx+1}</b><br><span style='color:#664455;font-size:8pt;'>Modifie le titre du bouton rapide et le texte envoyé.<br>Variables : {{DXCALL}} {{CALL}} {{MYCALL}} {{FIRSTNAME}} {{RST}} {{NAME}} {{QTH}} {{LOCATOR}} {{POWER}} {{ANTENNA}} {{RIG}} {{LICENCE}} {{QSL}} {{INFO}} {{PROGRAM}} {{MODE}} {{BAND}} {{DATE}} {{TIME}} {{UTC}}<br>Balises : &lt;stop&gt; arrête TX · &lt;add-log&gt; logue le QSO</span>"))
        lay.addWidget(QLabel("Titre du bouton rapide :"))
        name_ed = QLineEdit(name); lay.addWidget(name_ed)
        lay.addWidget(QLabel("Texte de la macro :"))
        ed = QTextEdit(); ed.setPlainText(raw); ed.setMinimumHeight(150); lay.addWidget(ed)
        lay.addWidget(QLabel("<span style='color:#664455;'>Aperçu :</span>"))
        prev = QTextEdit(); prev.setReadOnly(True); prev.setMaximumHeight(110)
        prev.setStyleSheet("QTextEdit{background:#020008;color:#00ffcc;font-family:'Courier New';font-size:9pt;border:1px solid #220044;}")
        lay.addWidget(prev)
        def upd():
            t,dl,st = self._process_macro_tags(self._expand_macro(ed.toPlainText()))
            prev.setPlainText(t + ("\n\n✅ log auto" if dl else "") + ("\n⏹ stop TX" if st else ""))
        ed.textChanged.connect(upd); upd()
        row=QHBoxLayout(); row.addStretch()
        bok=QPushButton("✅ Valider"); bok.setStyleSheet("background:#002200;color:#44ff44;border:1px solid #008800;")
        bnk=QPushButton("Annuler"); bnk.setStyleSheet("background:#150010;color:#ff4488;border:1px solid #440022;")
        row.addWidget(bok); row.addWidget(bnk); lay.addLayout(row)
        def save():
            while len(self._macro_names) <= idx:
                self._macro_names.append(f"F{len(self._macro_names)+1}")
            self._macro_names[idx]=name_ed.text().strip() or f"F{idx+1}"
            self._macros[idx]=ed.toPlainText()
            if hasattr(self,'_macros_win') and self._macros_win:
                try: self._macros_win._macro_edits[idx].setPlainText(ed.toPlainText())
                except Exception: pass
                try: self._macros_win._macro_name_edits[idx].setText(self._macro_names[idx])
                except Exception: pass
            self._refresh_macro_bar_labels()
            try: self._save_settings()
            except Exception: pass
            dlg.accept()
        bok.clicked.connect(save); bnk.clicked.connect(dlg.reject); dlg.exec_()

