    # ── Vérification de mise à jour (GitHub Releases) ──────────────────────────

    def _check_for_updates(self, manual=False):
        """V8.4 F4LPS : lance la vérification en tâche de fond. manual=True
        (bouton cliqué) affiche aussi le résultat s'il n'y a rien de neuf ou
        en cas d'échec réseau ; manual=False (démarrage) reste silencieux
        sauf s'il y a vraiment une mise à jour disponible."""
        if getattr(self, '_update_check_thread', None) is not None and self._update_check_thread.isRunning():
            return
        self._update_check_manual = bool(manual)
        if manual and hasattr(self, 'update_status_label'):
            self.update_status_label.setText(f"Version actuelle : {PROGRAM_VERSION_TAG} — vérification...")
        self._update_check_thread = UpdateCheckThread()
        self._update_check_thread.update_available.connect(self._on_update_available)
        self._update_check_thread.no_update.connect(self._on_update_check_none)
        self._update_check_thread.check_failed.connect(self._on_update_check_failed)
        self._update_check_thread.start()

    def _on_update_available(self, info):
        try:
            if hasattr(self, 'update_status_label'):
                self.update_status_label.setText(
                    f"Version actuelle : {PROGRAM_VERSION_TAG} — nouvelle version {info.get('tag','')} disponible !"
                )
            box = QMessageBox(self)
            box.setWindowTitle("Mise à jour MultiDigi disponible")
            box.setIcon(QMessageBox.Information)
            notes = str(info.get('notes', '') or '').strip()
            if len(notes) > 600:
                notes = notes[:600] + "…"
            box.setText(
                f"<b>{info.get('name', info.get('tag',''))}</b> est disponible "
                f"(version actuelle : {PROGRAM_VERSION_TAG}).<br><br>"
                f"{notes.replace(chr(10), '<br>') if notes else '<i>Pas de notes de version.</i>'}"
            )
            btn_dl = box.addButton("⬇ Télécharger", QMessageBox.AcceptRole) if info.get('asset_url') else None
            btn_page = box.addButton("🌐 Voir la page", QMessageBox.ActionRole)
            box.addButton("Plus tard", QMessageBox.RejectRole)
            box.exec_()
            clicked = box.clickedButton()
            if btn_dl is not None and clicked is btn_dl:
                webbrowser.open(info['asset_url'])
            elif clicked is btn_page and info.get('html_url'):
                webbrowser.open(info['html_url'])
        except Exception as e:
            print(f"⚠️ Affichage mise à jour impossible : {e}")

    def _on_update_check_none(self):
        if hasattr(self, 'update_status_label'):
            self.update_status_label.setText(f"Version actuelle : {PROGRAM_VERSION_TAG} — à jour ✅")
        if getattr(self, '_update_check_manual', False):
            self._set_status("✅ MultiDigi est déjà à jour")

    def _on_update_check_failed(self, msg):
        if hasattr(self, 'update_status_label'):
            self.update_status_label.setText(f"Version actuelle : {PROGRAM_VERSION_TAG}")
        # Au démarrage, on reste silencieux (pas de connexion, dépôt pas encore
        # créé...) ; seule une vérification manuelle informe de l'échec.
        if getattr(self, '_update_check_manual', False):
            self._set_status(f"⚠️ Vérification de mise à jour impossible : {msg}")

    def _check_download_count(self):
        if getattr(self, '_dl_count_thread', None) is not None and self._dl_count_thread.isRunning():
            return
        if hasattr(self, 'download_count_label'):
            self.download_count_label.setText("📥 Téléchargements : vérification...")
        self._dl_count_thread = DownloadCountThread()
        self._dl_count_thread.result.connect(self._on_download_count_result)
        self._dl_count_thread.failed.connect(self._on_download_count_failed)
        self._dl_count_thread.start()

    def _on_download_count_result(self, total, nb_releases):
        if hasattr(self, 'download_count_label'):
            self.download_count_label.setText(
                f"📥 Téléchargements : {total} (sur {nb_releases} release{'s' if nb_releases > 1 else ''})"
            )

    def _on_download_count_failed(self, msg):
        if hasattr(self, 'download_count_label'):
            self.download_count_label.setText(f"📥 Téléchargements : indisponible ({msg})")

    # ── Peuplement ────────────────────────────────────────────────────────────

    def _populate_audio_in(self):
        self.audio_combo.clear()
        if not PYAUDIO_AVAILABLE: self.audio_combo.addItem("PyAudio non disponible"); return
        try:
            p = pyaudio.PyAudio()
            for i in range(p.get_device_count()):
                d = p.get_device_info_by_index(i)
                if d.get('maxInputChannels',0) > 0:
                    self.audio_combo.addItem(f"[{i}] {int(d['defaultSampleRate']//1000)}k  {d['name'][:40]}",i)
            p.terminate()
        except Exception as e: self.audio_combo.addItem(f"Erreur: {e}")

    def _populate_audio_out(self):
        self.tx_combo.clear(); self.tx_combo.addItem("Défaut système",-1)
        if not PYAUDIO_AVAILABLE: return
        try:
            p = pyaudio.PyAudio()
            for i in range(p.get_device_count()):
                d = p.get_device_info_by_index(i)
                if d.get('maxOutputChannels',0) > 0:
                    self.tx_combo.addItem(f"[{i}] {int(d['defaultSampleRate']//1000)}k  {d['name'][:40]}",i)
            p.terminate()
        except: pass

    # ── RX ───────────────────────────────────────────────────────────────────

    def _toggle_rx(self):
        if self._rx_active: self._stop_rx()
        else: self._start_rx()

    def _on_autopitch_toggled(self, checked):
        self._autopitch_enabled = checked
        fam = getattr(self, '_family', 'PSK')
        # MULTIDIGI V0.1 F4LPS : le scanner générique ci-dessous (_autopitch_scan)
        # est réglé pour une porteuse PSK étroite -- il n'a pas de sens sur un
        # signal multi-tons comme Olivia et pouvait activement le perturber
        # puisqu'il tournait par défaut quelle que soit la famille active.
        # Sur Olivia, on active à la place son propre centrage fin interne
        # (déjà écrit dans le décodeur, mais jamais relié à un bouton avant).
        if fam == "OLIVIA" and hasattr(self.decoder_obj, 'set_auto_center'):
            self.decoder_obj.set_auto_center(checked)
            if checked:
                self._set_status("🎯 Centrage fin OLIVIA activé (autour du curseur manuel)")
            else:
                self._set_status("🎯 Centrage fin OLIVIA désactivé")
            return
        if fam != "PSK":
            # Pas encore d'équivalent pour DominoEX/RTTY -- on ne fait rien
            # plutôt que d'appliquer à tort la logique réglée pour le PSK.
            return
        if checked:
            self._autopitch_ema = -1.0
            self._autopitch_buf_pos = 0
            self._autopitch_buf_full = False
            self._autopitch_buf[:] = 0
            self._autopitch_last_t = 0.0
            try:
                self._manual_center_hz = float(self.center_freq_spin.value())
            except Exception:
                self._manual_center_hz = 1500.0
            self._set_status(f"🎯 RX-CENTER MICRO activé autour de {self._manual_center_hz:.0f} Hz — pas de grand saut")
        else:
            self._set_status("🎯 RX-CENTER MICRO désactivé")

    def _show_mode_popup(self, mode, reason=""):
        """Petite fenêtre non bloquante pour signaler le mode PSK détecté/actif."""
        try:
            if not hasattr(self, '_last_mode_popup_t'):
                self._last_mode_popup_t = 0.0
            now = time.time()
            # Évite une avalanche de popups si l'AFC réanalyse plusieurs fois.
            if now - self._last_mode_popup_t < 4.0:
                return
            self._last_mode_popup_t = now

            box = QMessageBox(self)
            box.setWindowTitle("Mode PSK")
            box.setIcon(QMessageBox.Information)
            txt = f"Mode actif : {mode}"
            if reason:
                txt += f"\n{reason}"
            box.setText(txt)
            box.setStandardButtons(QMessageBox.Ok)
            box.setStyleSheet("QMessageBox{background:#071225;color:#e8f4ff;} QLabel{color:#e8f4ff;font-size:12pt;} QPushButton{padding:4px 12px;}")
            box.setModal(False)
            box.show()
            QTimer.singleShot(2600, box.close)
            self._mode_popup_box = box
        except Exception:
            pass

    def _on_automode_psk_toggled(self, checked):
        # V1.6.129 : AUTO MODE léger. Aucun décodeur PSK parallèle et aucune FFT
        # supplémentaire dans le thread audio. L'analyse réutilise uniquement le
        # spectre déjà calculé pour le waterfall afin de préserver le Costas RX.
        self._automode_psk_enabled = bool(checked)
        self._automode_votes = []
        self._automode_last_check = 0.0
        self._automode_last_change = 0.0
        if checked:
            self._set_status("🔎 AUTO MODE PSK activé — analyse légère du spectre")
        else:
            self._set_status("🔎 AUTO MODE PSK désactivé")

    def _automode_psk_from_spectrum(self, mag, sr):
        if not getattr(self, '_automode_psk_enabled', False):
            return
        now = time.time()
        if now - float(getattr(self, '_automode_last_check', 0.0) or 0.0) < 1.0:
            return
        self._automode_last_check = now
        try:
            a = np.asarray(mag, dtype=np.float64).flatten()
            if a.size < 128:
                return
            center = float(self.center_freq_spin.value()) if hasattr(self, 'center_freq_spin') else 1500.0
            freqs = np.linspace(0.0, float(sr) / 2.0, a.size, endpoint=True)
            mask = (freqs >= center - 180.0) & (freqs <= center + 180.0)
            if np.count_nonzero(mask) < 8:
                return
            f = freqs[mask]; v = a[mask]
            noise = float(np.percentile(v, 35))
            peak = float(np.max(v))
            if peak - noise < 6.0:
                return
            thr = noise + 0.38 * (peak - noise)
            hot = f[v >= thr]
            if hot.size < 2:
                return
            width = float(np.percentile(hot, 90) - np.percentile(hot, 10))
            # V1.6.137 : correction BPSK31.
            # La largeur affichée du PSK31 est ~62 Hz. L'ancien seuil 48 Hz
            # classait trop souvent un vrai BPSK31 en BPSK63, donc le RX restait
            # sur 63 et ne décodait plus le 31.
            if width <= 78.0:
                mode = 'BPSK31'
            elif width <= 155.0:
                mode = 'BPSK63'
            else:
                mode = 'BPSK125'
            votes = list(getattr(self, '_automode_votes', []))
            votes.append(mode); votes = votes[-6:]
            self._automode_votes = votes
            if len(votes) >= 5 and votes.count(mode) >= 5 and now - float(getattr(self, '_automode_last_change', 0.0) or 0.0) >= 8.0:
                if self.mode_combo.currentText() != mode:
                    self._automode_last_change = now
                    self.mode_combo.setCurrentText(mode)
                    self._set_status(f"✓ AUTO MODE PSK : {mode} détecté — largeur ≈ {width:.0f} Hz")
                self._automode_votes = []
        except Exception:
            pass

    def _autopitch_feed_audio(self, samples):
        if not self._autopitch_enabled:
            return
        n = len(samples); buf_size = len(self._autopitch_buf)
        pos = self._autopitch_buf_pos; end = pos + n
        if end <= buf_size:
            self._autopitch_buf[pos:end] = samples
        else:
            first = buf_size - pos
            self._autopitch_buf[pos:] = samples[:first]
            self._autopitch_buf[:end - buf_size] = samples[first:]
            self._autopitch_buf_full = True
        self._autopitch_buf_pos = end % buf_size
        if end >= buf_size:
            self._autopitch_buf_full = True
        now = time.time()
        if now - self._autopitch_last_t < 0.30:
            return
        self._autopitch_last_t = now
        if self._autopitch_buf_full:
            self._autopitch_scan()

    def _autopitch_scan(self):
        """RX-CENTER V1.6.19 — micro-ajustement final après calage manuel.

        Objectif : ne plus partir tout seul à gauche ou sur un faux pic.
        L'opérateur clique/règle d'abord le signal à la main, puis RX-CENTER FIN
        fait uniquement le petit ajustement de précision autour de ce point.
        On garde 0..3000 Hz utilisable : les QSO bas restent possibles si tu les
        sélectionnes manuellement, mais l'algorithme ne saute plus depuis 1500 Hz
        vers la bande blanche de gauche.
        """
        if not self._autopitch_enabled or not self.audio_thread:
            return
        if getattr(self, '_family', 'PSK') != 'PSK':
            # Réglé spécifiquement pour une porteuse PSK étroite -- ne rien
            # faire sur les autres familles plutôt que d'agir à tort dessus.
            return

        sr = float(self.audio_thread.sample_rate or 48000)
        pos = self._autopitch_buf_pos
        data = (np.concatenate([self._autopitch_buf[pos:], self._autopitch_buf[:pos]])
                if pos > 0 else self._autopitch_buf.copy())
        data = np.asarray(data, dtype=np.float32)
        if data.size < 4096:
            return

        # Retire seulement DC/ronflette lente du signal d'analyse, pas l'affichage.
        data = data - float(np.mean(data))
        # Petite dérivation douce : la barre DC/ronflette large baisse fortement,
        # une vraie modulation PSK étroite reste présente.
        hp = np.empty_like(data)
        hp[0] = 0.0
        hp[1:] = data[1:] - 0.985 * data[:-1]
        data = hp

        n = len(data)
        win = np.hanning(n).astype(np.float32)
        spec = np.abs(np.fft.rfft(data * win)) ** 2
        freqs = np.fft.rfftfreq(n, 1.0 / sr)

        # On analyse toute la zone utile. 0..80 Hz reste visible mais n'est pas un centre PSK fiable.
        mask = (freqs >= 80.0) & (freqs <= 3000.0)
        if not np.any(mask):
            return
        f = freqs[mask].astype(np.float64)
        p = spec[mask].astype(np.float64) + 1e-30

        # Fond de bruit local robuste : médiane glissante large approximée par convolution
        # sur le spectre compressé log. Suffisant et rapide pour l'auto-center.
        p_log = 10.0 * np.log10(p)
        # Lissage étroit pour PSK31, mais pas assez large pour transformer une bosse en pic.
        k_narrow = np.ones(5, dtype=np.float64) / 5.0
        s = np.convolve(p, k_narrow, mode='same') + 1e-30
        k_wide = np.ones(65, dtype=np.float64) / 65.0
        wide = np.convolve(s, k_wide, mode='same') + 1e-30
        noise = float(np.median(s)) + 1e-30

        def width_at(idx, ratio):
            level = s[idx] * ratio
            l = idx
            while l > 1 and s[l] > level:
                l -= 1
            r = idx
            while r < len(s)-2 and s[r] > level:
                r += 1
            return float(abs(f[r] - f[l])) if r > l else 999.0

        candidates = []
        for i in range(3, len(s)-3):
            # Maximum local strict sur quelques bins.
            if not (s[i] >= s[i-1] and s[i] >= s[i+1] and s[i] >= s[i-2] and s[i] >= s[i+2]):
                continue
            pk = float(s[i])
            snr_db = 10.0 * math.log10(max(pk / noise, 1e-30))
            if snr_db < 8.0:
                continue

            bw50 = width_at(i, 0.50)
            bw25 = width_at(i, 0.25)
            prom_db = 10.0 * math.log10(max(pk / float(wide[i]), 1e-30))

            # Profil attendu : PSK31/63/125 = relativement étroit.
            # On accepte large jusqu'à ~260 Hz pour PSK125, mais on rejette les pâtés.
            if bw50 < 6.0 or bw50 > 260.0:
                continue
            if bw25 > 420.0:
                continue
            if prom_db < 1.8:
                continue

            # Barre blanche gauche typique : large, stable, peu proéminente.
            # On ne bloque PAS toute la zone basse : une vraie raie fine à 250/350 Hz passe.
            low_freq_penalty = 0.0
            if f[i] < 520.0:
                if bw50 > 70.0 or bw25 > 180.0 or prom_db < 3.2:
                    continue
                low_freq_penalty = 3.0

            # Bonus si la largeur ressemble au mode actif.
            mode = self.mode_combo.currentText() if hasattr(self, 'mode_combo') else 'BPSK31'
            target_bw = 45.0
            if '63' in mode:
                target_bw = 85.0
            elif '125' in mode:
                target_bw = 160.0
            bw_bonus = max(0.0, 4.0 - abs(bw50 - target_bw) / max(18.0, target_bw * 0.45))

            # Score final : vraie raie étroite, dominante localement, pas trop large.
            score = snr_db + 3.5 * prom_db + bw_bonus - 0.035 * max(0.0, bw25 - 180.0) - low_freq_penalty
            candidates.append((score, float(f[i]), bw50, bw25, prom_db, snr_db))

        if not candidates:
            # Ne pas suivre le bruit : on relâche doucement la mémoire, sans bouger le curseur.
            try:
                self._autopitch_candidates.clear()
            except Exception:
                pass
            return

        # V1.6.15 : réglage final uniquement.
        # On ne choisit PAS le meilleur candidat de toute la bande 0..3000 Hz.
        # On garde seulement les candidats proches du centre déjà choisi manuellement.
        try:
            current_center = float(self.center_freq_spin.value())
        except Exception:
            current_center = float(getattr(self, '_manual_center_hz', 1500.0))
        capture_hz = min(45.0, float(getattr(self, '_autopitch_capture_hz', 65.0)))  # V1.6.113: fenêtre plus serrée, évite les faux pics
        near = [c for c in candidates if abs(c[1] - current_center) <= capture_hz]
        if not near:
            self._set_status(
                f"🎯 RX-CENTER MICRO: aucun PSK stable près de {current_center:.0f} Hz "
                f"(fenêtre ±{capture_hz:.0f} Hz)"
            )
            try:
                self._autopitch_candidates.clear()
            except Exception:
                pass
            return

        near.sort(reverse=True, key=lambda x: x[0])
        score, hz, bw50, bw25, prom_db, snr_db = near[0]

        # Mémoire de stabilité : il faut revoir le même candidat plusieurs fois.
        if not hasattr(self, '_autopitch_candidates'):
            self._autopitch_candidates = deque(maxlen=8)
        self._autopitch_candidates.append(hz)
        close = [x for x in self._autopitch_candidates if abs(x - hz) <= 8.0]
        # V2.1.8 : quatre validations cohérentes suffisent. À 300 ms par scan,
        # la correction commence en environ 1,2 s au lieu de plus de 2,4 s.
        if len(close) < 4:
            self._set_status(
                f"🎯 RX-CENTER analyse {len(close)}/4 : candidat {hz:.1f} Hz"
            )
            return
        stable_hz = float(np.median(close))

        # Lissage final, mais verrouillage assez rapide quand le candidat est stable.
        if self._autopitch_ema < 0:
            self._autopitch_ema = stable_hz
        else:
            self._autopitch_ema = 0.35 * self._autopitch_ema + 0.65 * stable_hz
        smooth = float(self._autopitch_ema)

        # Auto-mode : uniquement à partir de la largeur mesurée, pas du niveau brut.
        try:
            auto_mode_on = getattr(self, '_automode_psk_enabled', False)
            new_mode = None
            # V1.6.137 : mêmes seuils que l'Auto Mode léger.
            # BPSK31 occupe environ 62 Hz, donc le classer à 63 demandait un
            # seuil trop bas. On évite ainsi que le 31 reste bloqué en 63.
            if bw50 <= 78.0:
                new_mode = 'BPSK31'
            elif 78.0 < bw50 <= 155.0:
                new_mode = 'BPSK63'
            elif 155.0 < bw50 <= 280.0:
                new_mode = 'BPSK125'
            # Changement très prudent : seulement si le mode courant est incohérent.
            if auto_mode_on and new_mode and self.mode_combo.currentText() != new_mode:
                self.mode_combo.blockSignals(True)
                self.mode_combo.setCurrentText(new_mode)
                self.mode_combo.blockSignals(False)
                self._on_mode_changed(new_mode)
                if self.audio_thread:
                    self.audio_thread.set_mode(new_mode)
                self._show_mode_popup(new_mode, f"Largeur PSK détectée ≈ {bw50:.0f} Hz")
        except Exception:
            pass

        current = float(self.center_freq_spin.value())
        delta = smooth - current

        # V1.6.113 : diagnostic trouvé — le mauvais décodage venait surtout
        # d'un RX-CENTER qui continuait à chasser pendant que le décodeur essayait
        # de s'accrocher. On refuse donc tout candidat douteux.
        try:
            if snr_db < 12.0 or prom_db < 2.8:
                self._set_status(f"🎯 RX-CENTER ignoré: candidat trop faible SNR={snr_db:.1f}dB prom={prom_db:.1f}dB")
                return
        except Exception:
            pass
        if abs(delta) > 28.0:
            self._set_status(f"🎯 RX-CENTER ignoré: écart trop grand {delta:+.0f} Hz — recalage manuel conseillé")
            try:
                self._autopitch_candidates.clear()
            except Exception:
                pass
            return
        if abs(delta) < 0.6:
            self._set_status(f'🎯 RX-CENTER calé : erreur {delta:+.1f} Hz')
            return
        # V1.6.112 : si du texte vient d’être décodé, on ne touche plus au centre.
        # Cela évite la dérive RX-CENTER pendant un QSO réel.
        try:
            if (time.time() * 1000.0 - float(getattr(self, '_last_decode_ms', 0.0) or 0.0)) < 1200.0:
                self._set_status('🎯 RX-CENTER verrouillé : décodage actif, pas de dérive')
                return
        except Exception:
            pass
        # V1.6.19 : micro-ajustement seulement, aucun grand saut possible.
        max_step = 1.5  # V2.1.8 : correction locale rapide, toujours sans grand saut
        new_center = current + max(-max_step, min(max_step, delta))
        self.center_freq_spin.blockSignals(True)
        self.center_freq_spin.setValue(round(new_center, 1))
        self.center_freq_spin.blockSignals(False)
        self._on_center_freq_changed(new_center)
        self._set_status(
            f"🎯 RX-CENTER MICRO: {current:.0f} → {new_center:.0f} Hz  "
            f"(candidat={hz:.0f}Hz, largeur={bw50:.0f}Hz, SNR={snr_db:.1f}dB)"
        )

    def _get_rx_sample_rate(self):
        """Retourne le sample-rate RX choisi dans les réglages, sans le forcer par molette."""
        try:
            if hasattr(self, 'sample_rate_combo'):
                v = self.sample_rate_combo.currentData()
                if v:
                    return int(v)
        except Exception:
            pass
        try:
            return int(getattr(self, '_rx_sample_rate', 44100) or 44100)
        except Exception:
            return 44100

    def _update_rx_sr_label(self, sr=None, active=False):
        try:
            sr = int(sr or self._get_rx_sample_rate())
            if hasattr(self, 'rx_sr_lbl'):
                suffix = " ✓" if active else ""
                self.rx_sr_lbl.setText(f"RX SR : {sr} Hz{suffix}")
                if abs(sr - 44100) < 100 or abs(sr - 48000) < 100:
                    self.rx_sr_lbl.setStyleSheet("color:#00ff88;font-family:'Courier New';font-size:9pt;font-weight:bold;")
                else:
                    self.rx_sr_lbl.setStyleSheet("color:#ff4444;font-family:'Courier New';font-size:9pt;font-weight:bold;")
        except Exception:
            pass

    def _update_rx_quality_indicator(self):
        """V1.6.130 : voyant RX LOCK/SYNC supprimé. Garde seulement l'état MODE DX."""
        try:
            dx_on = bool(getattr(self, '_rx_dx_mode', True))
            if hasattr(self, 'rx_dx_lbl'):
                self.rx_dx_lbl.setText("MODE DX : ON" if dx_on else "MODE DX : OFF")
                self.rx_dx_lbl.setStyleSheet(("color:#00ff88;" if dx_on else "color:#ffaa00;") + "font-family:'Courier New';font-size:9pt;font-weight:bold;")
        except Exception:
            pass

    def _f4lps_warmup_rsid_codebooks_async(self):
        """V2.1.9 F4LPS : construit la table RS(15,3) en tâche de fond, avant
        toute RX, pour qu'elle soit déjà prête au premier burst RSID reçu et
        ne bloque plus jamais le thread audio ni l'interface."""
        if getattr(self, '_rsid_codebook_warmup_started', False):
            return
        self._rsid_codebook_warmup_started = True
        try:
            threading.Thread(
                target=_f4lps_build_rsid_codebooks, daemon=True
            ).start()
        except Exception:
            pass

    def _start_rx(self):
        if getattr(self, '_rx_needs_device_settle', False):
            # V2.1.9c F4LPS : le thread RX précédent vient d'être tué de force
            # (voir _stop_rx). Rouvrir le périphérique audio immédiatement dans
            # ce cas précis échoue ou redevient poussif sur certaines cartes
            # virtuelles (VAC) qui n'ont pas fini de le relâcher. On laisse un
            # court délai unique avant de vraiment (re)lancer le RX.
            self._rx_needs_device_settle = False
            QTimer.singleShot(400, self._start_rx)
            return
        self._f4lps_warmup_rsid_codebooks_async()
        dev = self.audio_combo.currentData()
        if dev is None: dev = 0
        # V1.6.68 F4LPS : NE PLUS FORCER BPSK31 AU DÉMARRAGE RX.
        # Si l'opérateur choisit BPSK63 ou BPSK125 manuellement, le programme
        # doit respecter ce choix. Le changement automatique est autorisé
        # uniquement avec le bouton 🔎 AUTO MODE PSK activé.
        # V1.6.15 : on n'active plus RX-CENTER automatiquement au démarrage RX.
        # Il doit servir uniquement après un clic/réglage manuel, pour finir le calage.
        try:
            self._autopitch_enabled = bool(getattr(self, "btn_autopitch", None) and self.btn_autopitch.isChecked())
            self._manual_center_hz = float(self.center_freq_spin.value())
        except Exception:
            self._autopitch_enabled = False

        rx_sr = self._get_rx_sample_rate()
        _fam = getattr(self, '_family', 'PSK')
        _mode = self.mode_combo.currentText()
        self.audio_thread = PSKAudioThread(
            dev, rx_sr,
            decoder_factory=lambda sr, _f=_fam, _m=_mode: multidigi_get_decoder(_f, _m, sr)
        )
        # V3 diagnostic : référence sans ambiguïté vers le décodeur qui reçoit
        # réellement stream.read() -> samples -> process_audio(samples).
        self._live_rx_decoder = self.audio_thread.decoder
        try:
            self.waterfall.sample_rate = float(rx_sr)
            self.waterfall._latest_sr = float(rx_sr)
        except Exception:
            pass
        self._update_rx_sr_label(rx_sr, active=False)
        self._autopitch_ema = -1.0
        self.audio_thread.set_mode(self.mode_combo.currentText())
        if _fam == "JS8":
            try:
                print(
                    "✅ JS8 LIVE AUDIO INSTANCE : "
                    f"{type(self.audio_thread.decoder).__name__} "
                    f"id={id(self.audio_thread.decoder)} "
                    f"SR={rx_sr}"
                )
            except Exception:
                pass
        self.audio_thread.set_center_freq(self.center_freq_spin.value())
        try:
            self.audio_thread.set_dx_mode(bool(getattr(self, '_rx_dx_mode', True)))
        except Exception:
            pass
        self._update_rx_quality_indicator()
        self.audio_thread.text_decoded.connect(self._on_text)
        if isinstance(self.audio_thread.decoder, JS8RXAdapter):
            self.audio_thread.band_activity_ready.connect(
                self._refresh_js8_band_table, Qt.QueuedConnection)
            self.audio_thread.decoder._band_activity_notify = self.audio_thread.band_activity_ready.emit
        self.audio_thread.diagnostic_data.connect(self._on_rx_diag)
        self.audio_thread.spectrum_data.connect(self._on_spectrum)
        self.audio_thread.snr_updated.connect(self._on_snr)
        self.audio_thread.envelope_data.connect(self._on_envelope)
        self.audio_thread.raw_audio.connect(self._autopitch_feed_audio)
        # V1.6.155 : le RSID reste passif et doit revenir presque immédiatement
        # après le TX. L'ancien délai de 2,8 s faisait rater entièrement le burst
        # RSID de l'OM quand il répondait rapidement.
        _after_tx = bool(getattr(self, '_rx_restart_after_tx', False))
        # F4LPS RSID RX FIX : ne pas lancer le worker avant l'ouverture réelle de la carte son.
        # Le périphérique peut refuser rx_sr et retomber sur son sample-rate par défaut ; dans
        # ce cas l'ancien worker calculait les durées/fréquences RSID avec un mauvais SR.
        # On l'attache juste après start(), quand PSKAudioThread a eu le temps d'ouvrir le flux.
        # V1.6.147 : préparer le décodeur AVANT de lancer le thread audio.
        # En 1.6.146, force_fast_acquire() était appelé APRES start() : le thread
        # pouvait déjà recevoir le début de la réponse OM puis être remis à zéro
        # en pleine acquisition. Symptôme : quelques secondes de charabia / début perdu.
        if _after_tx:
            self._rx_restart_after_tx = False
        try:
            # V1.6.145 : acquisition rapide également au premier lancement RX.
            # Elle est préparée AVANT le thread afin de ne jamais remettre le
            # décodeur à zéro après l'arrivée du début du message.
            self.audio_thread.decoder.force_fast_acquire(5.0 if not _after_tx else 8.0)
        except Exception:
            pass
        self.audio_thread.start()
        self._rx_active = True

        # F4LPS RSID RX FIX : attachement différé dans TOUS les cas, avec le SR réellement
        # ouvert par PyAudio. 120 ms sont négligeables devant une trame RSID (~1,39 s) et
        # évitent une erreur 44,1/48 kHz qui suffit à rendre les 15 symboles indécodables.
        def _late_rsid_attach():
            try:
                if self._rx_active and self.audio_thread is not None:
                    actual_sr = float(getattr(self.audio_thread, 'sample_rate', rx_sr) or rx_sr)
                    self._start_rsid_rx_worker(actual_sr)
                    try:
                        self.audio_thread.raw_audio.disconnect(self._rsid_rx_feed_audio)
                    except Exception:
                        pass
                    self.audio_thread.raw_audio.connect(self._rsid_rx_feed_audio)
                    try:
                        print(f"🔎 RSID RX attaché — SR réel {actual_sr:.0f} Hz — file 64 blocs")
                    except Exception:
                        pass
            except Exception as e:
                try: print(f"⚠ RSID attach RX: {e}")
                except Exception: pass
        QTimer.singleShot(120, _late_rsid_attach)
        # V1.6.109 F4LPS : au démarrage RX, autoriser une nouvelle ligne
        # d'information RSID/mode façon DM780 dans le texte reçu.
        self._rsid_rx_last_key = ''
        self._rsid_rx_mode_line_done = False
        self.btn_rx.setText("⏹ ARRÊTER RX")
        self.btn_rx.setStyleSheet(
            "QPushButton{background:#3a0050;color:#ff00cc;font-weight:bold;"
            "border:2px solid #ff00cc;border-radius:5px;padding:2px 10px;font-size:9pt;}"
            "QPushButton:hover{background:#4d0070;}"
        )
        self.rx_led.setStyleSheet("background:#002a00;color:#00ff00;font-weight:bold;padding:2px 6px;border:1px solid #00aa44;border-radius:10px;")
        self._set_status(f"✅ RX PSK démarré — {self.mode_combo.currentText()} — SR {self.audio_thread.sample_rate} Hz")
        self._update_rx_sr_label(self.audio_thread.sample_rate, active=True)
        self._show_mode_popup(self.mode_combo.currentText(), "Réception démarrée")

    def _clear_tx_text(self):
        """Efface uniquement la zone TX (texte à émettre).

        V1.6.24 : correction définitive du bouton CLEAR demandé par F4LPS.
        La vraie zone TX est self.tx_text, un QTextEdit créé dans _build_tx_tab().
        On ne touche pas à self.rx_text, au décodeur, au waterfall, ni à l'état RX.
        """
        try:
            if hasattr(self, 'tx_text') and self.tx_text is not None:
                self.tx_text.setUpdatesEnabled(False)
                self.tx_text.blockSignals(True)
                self.tx_text.clear()
                try:
                    self.tx_text.document().clear()
                except Exception:
                    pass
                self.tx_text.setPlainText("")
                self.tx_text.moveCursor(QTextCursor.Start)
                self.tx_text.blockSignals(False)
                self.tx_text.setUpdatesEnabled(True)
                self.tx_text.viewport().update()

            # Remettre aussi l'aperçu TX à zéro si présent, sans modifier le RX.
            try:
                if hasattr(self, 'preview_len'):
                    self.preview_len.setText("0 car.")
                if hasattr(self, 'preview_bits'):
                    self.preview_bits.setText("0 bits")
            except Exception:
                pass

            try:
                if hasattr(self, 'tx_follow_label'):
                    self.tx_follow_label.setText("TX suivi : prêt — texte envoyé vidé")
                if hasattr(self, 'tx_progress'):
                    self.tx_progress.setValue(0)
                self._pending_tx_text = ''
                self._pending_wf_text = ''
                self._pending_wf_position = 'before'
                self._tx_saved_text_before_test = None
            except Exception:
                pass

            self._set_status("🧹 CLEAR OK — texte envoyé / zone TX vidés")
        except Exception as e:
            try:
                self._set_status(f"Erreur CLEAR TX: {e}")
            except Exception:
                pass

    def _stop_rx(self):
        try:
            self._stop_rsid_rx_worker()
        except Exception:
            pass
        if self.audio_thread:
            clean = self.audio_thread.stop()
            self.audio_thread = None
            if not clean:
                # Le thread précédent a dû être arrêté de force : on laisse un
                # court instant au pilote audio (VAC) pour vraiment relâcher le
                # périphérique avant qu'un nouveau flux ne tente de l'ouvrir.
                self._rx_needs_device_settle = True
                try:
                    self._set_status("⚠️ RX audio bloqué (dérive VAC) — redémarrage forcé du flux")
                except Exception:
                    pass
            else:
                self._rx_needs_device_settle = False
        self._rx_active = False
        self.btn_rx.setText("▶ DÉMARRER RX")
        self.btn_rx.setStyleSheet(
            "QPushButton{background:#003a15;color:#00ff66;font-weight:bold;"
            "border:2px solid #00aa44;border-radius:5px;padding:2px 10px;font-size:9pt;}"
            "QPushButton:hover{background:#004a20;}"
        )
        self.rx_led.setStyleSheet("background:#0a2a0a;color:#006600;font-weight:bold;padding:2px 6px;border:1px solid #2a4a2a;border-radius:10px;")
        self.level_bar.setValue(0)


    # ── RSID RX passif V1.6.133 ──────────────────────────────────────────────
    def _start_rsid_rx_worker(self, sample_rate):
        """Lance le détecteur RSID audio hors du chemin RX PSK."""
        try:
            self._stop_rsid_rx_worker()
        except Exception:
            pass
        # En mode JS8 fixe, le scanner dédié remplace l'identification RSID.
        # Évite la contention CPU/GIL avec l'acquisition des trames de 15 s.
        if self.family_combo.currentText().strip().upper() == 'JS8':
            return
        try:
            self._rsid_passive_worker = F4LPSRsidPassiveThread(sample_rate, self)
            self._rsid_passive_worker.rsid_detected.connect(self._on_rsid_audio_detected)
            self._rsid_passive_worker.start(QThread.LowPriority)
            self._rsid_audio_last_line = 0.0
        except Exception as e:
            try:
                print(f"⚠ RSID RX passif non lancé: {e}")
            except Exception:
                pass
            self._rsid_passive_worker = None

    def _stop_rsid_rx_worker(self):
        try:
            w = getattr(self, '_rsid_passive_worker', None)
            if w is not None:
                try:
                    w.stop()
                except Exception:
                    try: w.terminate()
                    except Exception: pass
            self._rsid_passive_worker = None
        except Exception:
            pass

    def _rsid_rx_feed_audio(self, samples):
        """Envoie une copie très légère vers le RSID, sans bloquer le PSK."""
        try:
            if not getattr(self, '_rx_active', False):
                return
            if getattr(self, '_tx_active', False):
                return
            if time.time() < float(getattr(self, '_rx_ignore_until', 0.0) or 0.0):
                return
            if not self._rsid_rx_enabled():
                return
            w = getattr(self, '_rsid_passive_worker', None)
            if w is not None:
                w.feed(samples)
        except Exception:
            pass

    def _on_rsid_audio_detected(self, label, freq_hz, score):
        """Affiche un RSID sans jamais interrompre le QSO en cours.

        V2.1.6 F4LPS :
        - aucun recentrage automatique ;
        - aucun changement automatique de mode ;
        - double-clic volontaire sur la ligne RSID pour rejoindre sa fréquence ;
        - le nom affiché provient du décodage direct RS(15,3), pas d'une
          classification approximative du spectre qui suit.
        """
        try:
            if not self._rsid_rx_enabled() or not getattr(self, '_rx_active', False):
                return
            if getattr(self, '_tx_active', False):
                return
            now = time.time()
            if now - float(getattr(self, '_rsid_audio_last_line', 0.0) or 0.0) < 8.0:
                return
            self._rsid_audio_last_line = now

            rsid_hz = max(
                float(self.center_freq_spin.minimum()) if hasattr(self, 'center_freq_spin') else 20.0,
                min(
                    float(self.center_freq_spin.maximum()) if hasattr(self, 'center_freq_spin') else 3500.0,
                    float(freq_hz)
                )
            )
            lab = str(label or 'MODE NON DÉCODÉ').strip()
            self._insert_rsid_line_dm780(lab, freq_hz=rsid_hz, force=True)

            if lab.upper() == 'MODE NON DÉCODÉ':
                self._set_status(
                    f'RSID réel détecté à {rsid_hz:.0f} Hz — mode non décodé — '
                    'double-clique sur la ligne pour te déplacer'
                )
            else:
                self._set_status(
                    f'✓ RSID {lab} détecté à {rsid_hz:.0f} Hz — '
                    'double-clique sur la ligne pour te déplacer'
                )
        except Exception:
            pass

    # ── Palette couleurs RX ────────────────────────────────────────────────
    _RX_C_CALL   = QColor(  0, 220, 255)
    _RX_C_NAME   = QColor(255, 170,  60)   # prénom OM détecté / cliquable
    _RX_C_MYCALL = QColor(255, 220,  50)
    _RX_C_CQ     = QColor(120, 255, 120)
    _RX_C_DE     = QColor(180, 180, 255)
    _RX_C_RST    = QColor(255, 180,  60)
    _RX_C_73     = QColor(255, 130, 200)
    _RX_C_QXX    = QColor(255, 255, 100)
    _RX_C_TEXT   = QColor(210, 180, 210)
    _RX_C_DELIM  = QColor(110,  90, 110)
    # V8.4 F4LPS : surlignage façon JS8Call — fond rouge sombre sur toute la
    # ligne reçue quand elle contient notre indicatif (réponse / HEARTBEAT ACK
    # / mention directe), pour la repérer d'un coup d'œil dans le flux RX.
    _RX_BG_REPLY = QColor(110, 20, 20)
    _RE_CALL_CLR = re.compile(r'^(?:[A-Z]{1,2}[0-9][A-Z]{1,4}|[A-Z]{1,3}[0-9][A-Z0-9]{1,5})(?:/(?:P|M|MM|AM|QRP|[A-Z0-9]{1,4}))?$')
    # Locator Maidenhead : doit rester en blanc, pas en bleu indicatif.
    # Exemples acceptés : JN18, JN18EU, JN18EU47, KN68RA, IN94WL.
    _RE_LOCATOR_CLR = re.compile(r'^[A-R]{2}[0-9]{2}(?:[A-X]{2})?(?:[0-9]{2})?$')
    _RX_LOC_WORDS = {'LOC', 'LOCATOR', 'GRID', 'GRIDLOC'}
    _CALL_REJECT = {'CQ','DE','PSE','K','KN','BK','BTU','TU','TNX','TKS','QSL','QSO','QTH','QRA','QRM','QRN','QSB','QRZ','QSY','QRG','RST','NAME','OP','UR','HW','TEST','MY','NR','NW','HR','HI','ES','WX','ANT','PWR','RIG','LOG','LOC','LOCATOR','GRID','GRIDLOC','PSK','BPSK','QPSK','PSK31','BPSK31','QPSK31','PSK63','BPSK63','QPSK63','PSK125','BPSK125','QPSK125','OLIVIA','RTTY','FT8','FT4','USB','LSB','SSB','CW','AM','FM','RX','TX','SNR','UTC','WSPR','JT65','JT9','JS8','MFSK','599','5NN','599TU'}
    _RST_CLR = re.compile(r'^[1-5][1-9][1-9]$|^5NN$')

    def _rx_is_locator_token(self, word):
        """True si le mot est un locator Maidenhead ou un label locator.

        Important : certains locators comme KN68RA ressemblent à des indicatifs
        pour une regex trop large. On les détecte avant les indicatifs pour les
        garder en couleur normale RX.
        """
        try:
            w = str(word or '').strip().upper().replace('\u2029', ' ').replace('\u2028', ' ')
            w = re.sub(r'^[^A-Z0-9]+|[^A-Z0-9]+$', '', w)
            if not w:
                return False
            if w in getattr(self, '_RX_LOC_WORDS', set()):
                return True
            return bool(getattr(self, '_RE_LOCATOR_CLR').match(w))
        except Exception:
            return False

    def _f4lps_fix_rx_call_token(self, token):
        """Corrige seulement les erreurs Z dans un mot qui ressemble à un indicatif.

        Le décodeur PSK peut parfois transformer la dernière lettre Z en { } [ ] ( )
        ou mettre un symbole à la place de Z juste avant le chiffre du préfixe.
        On corrige uniquement si le résultat ressemble vraiment à un indicatif.
        """
        try:
            w0 = str(token or '').strip().upper().replace('\u2029', ' ').replace('\u2028', ' ')
            # Enlever uniquement la ponctuation extérieure qui n'a rien à voir avec un call.
            w0 = re.sub(r'^[^A-Z0-9\{\}\[\]\(\)/]+|[^A-Z0-9\{\}\[\]\(\)/]+$', '', w0)
            if not w0:
                return ''

            candidates = []
            candidates.append(w0)
            # V1.6.143 : cas observé en PSK31 réel — le Z de LZ1AEY arrive parfois
            # comme rien/1/I, donnant L1AEY, LIAEY ou L|AEY. Ces préfixes L1/LI ne
            # correspondent pas à l'indicatif réel vu par DM780 ; on essaye LZ1...
            candidates.append(re.sub(r'^L[1I|]([A-Z]{2,5})(?:/([A-Z0-9]{1,4}))?$', lambda m: 'LZ1' + m.group(1) + (('/' + m.group(2)) if m.group(2) else ''), w0))
            # Z en fin d'indicatif : RN4A{ -> RN4AZ, IZ0XYZ) -> IZ0XYZZ si valide seulement.
            candidates.append(re.sub(r'([A-Z]{1,3}[0-9][A-Z0-9]{1,6})[\{\}\[\]\(\)]$', r'\1Z', w0))
            # Z avant le chiffre : L(1AEY -> LZ1AEY, L[1AEY -> LZ1AEY.
            candidates.append(re.sub(r'^([A-Z]{1,2})[\{\}\[\]\(\)]([0-9][A-Z0-9]{1,6}(?:/[A-Z0-9]{1,4})?)$', r'\1Z\2', w0))
            # Nettoyage simple si le Z a déjà été remplacé dans un mot complet.
            candidates.append(w0.replace('{','Z').replace('}','Z').replace('[','Z').replace(']','Z').replace('(','Z').replace(')','Z'))

            for c in candidates:
                clean = re.sub(r'[^A-Z0-9/]', '', c.upper())
                if self._rx_is_locator_token(clean):
                    continue
                if (clean and clean not in self._CALL_REJECT and 3 <= len(clean) <= 14
                        and clean[0].isalpha() and self._RE_CALL_CLR.match(clean)):
                    return clean
            return re.sub(r'^[^A-Z0-9]+|[^A-Z0-9/]+$', '', w0)
        except Exception:
            return str(token or '')

    def _rx_text_mentions_mycall(self, text):
        """V8.4 F4LPS : True si le morceau de texte RX contient notre indicatif
        en mot entier (réponse, HEARTBEAT ACK, mention directe...).
        Sert à surligner toute la ligne en fond rouge, façon JS8Call."""
        try:
            t = str(text or '').upper()
            if not t.strip():
                return False
            try:
                mycall = self._station_value('mycall_edit', 'F4LPS').upper()
            except Exception:
                mycall = 'F4LPS'
            if not mycall:
                return False
            return bool(re.search(r'(?<![A-Z0-9/])' + re.escape(mycall) + r'(?![A-Z0-9/])', t))
        except Exception:
            return False

    def _word_color(self, word):
        raw_w = str(word or '').strip().upper()
        # Les locators Maidenhead et les labels LOC/GRID restent en couleur texte.
        # Ils ne doivent jamais passer en bleu comme un indicatif.
        if self._rx_is_locator_token(raw_w):
            return self._RX_C_TEXT
        w = self._f4lps_fix_rx_call_token(word)
        w = re.sub(r'[^A-Z0-9/]', '', w.upper())
        if not w: return self._RX_C_DELIM
        if self._rx_is_locator_token(w):
            return self._RX_C_TEXT
        try: mycall = self._station_value('mycall_edit', 'F4LPS').upper()
        except: mycall = 'F4LPS'
        # Indicatif DX actif → surligné en cyan vif
        dxcall = getattr(self, '_last_dxcall', '').upper()
        if dxcall and w == dxcall: return self._RX_C_CALL
        if w == mycall: return self._RX_C_MYCALL
        # Prénom OM connu ou déduit après NAME / OP / OPR / DR : couleur orange.
        try:
            dxn = getattr(self, '_dx_name', '') or (self.dx_name_edit.text().strip() if hasattr(self, 'dx_name_edit') else '')
            names = set(getattr(self, '_rx_name_candidates', set()) or set())
            if dxn:
                names.add(str(dxn).upper())
            if w in names:
                return self._RX_C_NAME
        except Exception:
            pass
        if w == 'CQ':  return self._RX_C_CQ
        if w == 'DE':  return self._RX_C_DE
        if w in ('QSL','QRZ','QSO','QTH','QRA','QRM','QRN','QSB','QSY','QRG'): return self._RX_C_QXX
        if w in {'73','88','55','44'} or w in ('TU','TNX','TKS','BTU'): return self._RX_C_73
        if w == 'RST' or self._RST_CLR.match(w): return self._RX_C_RST
        # Indicatif générique (pas actif) → cyan pâle si format valide
        if w not in self._CALL_REJECT and 3<=len(w)<=14 and w[0].isalpha() and self._RE_CALL_CLR.match(w):
            return QColor(0, 150, 180)
        return self._RX_C_TEXT

    def _rx_repair_callsign_glitches(self, text):
        """Corrige uniquement les petites erreurs typiques dans les indicatifs RX.

        Cette correction ne touche pas au décodeur PSK. Elle agit seulement sur
        l'affichage et la détection CALL, pour éviter les cas vus en trafic :
        RN4A{ -> RN4AZ, L(1AEY -> LZ1AEY.
        """
        try:
            t = str(text or '')

            # V1.6.143 : correction prioritaire du Z manquant dans les indicatifs LZ1...
            # Exemples vus : L1AEY, LIAEY, L|AEY -> LZ1AEY.
            t = re.sub(r'(?<![A-Z0-9/])L[1I|]([A-Z]{2,5})(/[A-Z0-9]{1,4})?(?![A-Z0-9/])',
                       lambda m: 'LZ1' + m.group(1).upper() + (m.group(2) or ''),
                       t, flags=re.IGNORECASE)

            # Z décodé comme parenthèse/crochet juste avant le chiffre d'un call : L(1AEY -> LZ1AEY
            t = re.sub(r'(?<![A-Z0-9/])([A-Z]{1,2})[\{\}\[\]\(\)]([0-9][A-Z0-9]{1,6}(?:/[A-Z0-9]{1,4})?)(?![A-Z0-9/])', r'\1Z\2', t, flags=re.IGNORECASE)

            # Z décodé en symbole en fin d'indicatif : RN4A{ -> RN4AZ.
            def _fix_end_symbol(m):
                base = m.group(1).upper()
                fixed = base + 'Z'
                try:
                    if fixed not in self._CALL_REJECT and self._RE_CALL_CLR.match(fixed):
                        return fixed
                except Exception:
                    pass
                return m.group(0)
            t = re.sub(r'(?<![A-Z0-9/])([A-Z]{1,3}[0-9][A-Z0-9]{1,6})[\{\}\[\]\(\)](?![A-Z0-9/])', _fix_end_symbol, t, flags=re.IGNORECASE)

            # Correction jeton par jeton, utile si un séparateur exotique arrive.
            def _fix_token(m):
                tok = m.group(0)
                fixed = self._f4lps_fix_rx_call_token(tok)
                return fixed if fixed and fixed != tok else tok
            t = re.sub(r'(?<![A-Z0-9/])[A-Z0-9\{\}\[\]\(\)/]{3,15}(?![A-Z0-9/])', _fix_token, t, flags=re.IGNORECASE)
            return t
        except Exception:
            return str(text or '')

    def _rx_recolor_all_text(self):
        """Recolore tout le texte RX après détection/saisie d'un prénom.

        V1.6.120 : si le prénom est détecté après que la ligne soit déjà
        affichée (ex: IK0UR ROGER ROGER), on repasse la colorisation sans
        toucher au décodeur ni au contenu texte.
        """
        if getattr(self, '_rx_recoloring', False):
            return
        try:
            plain = self.rx_text.toPlainText()
            if not plain:
                return
            self._rx_recoloring = True
            self.rx_text.blockSignals(True)
            self.rx_text.clear()
            cur = self.rx_text.textCursor()
            cur.movePosition(QTextCursor.End)

            def _flush(word):
                if not word:
                    return
                try:
                    word2 = self._f4lps_fix_rx_call_token(word)
                except Exception:
                    word2 = word
                fmt = QTextCharFormat()
                fmt.setForeground(self._word_color(word2))
                # Prénom OM : orange + gras pour bien ressortir du texte normal.
                try:
                    wclean = re.sub(r'[^A-ZÀ-ÖØ-Ý0-9/\-]', '', str(word2).upper())
                    dxn = getattr(self, '_dx_name', '') or (self.dx_name_edit.text().strip() if hasattr(self, 'dx_name_edit') else '')
                    names = set(getattr(self, '_rx_name_candidates', set()) or set())
                    if dxn:
                        names.add(str(dxn).upper())
                    if wclean in names:
                        fmt.setForeground(self._RX_C_NAME)
                        fmt.setFontWeight(QFont.Bold)
                except Exception:
                    pass
                cur.setCharFormat(fmt)
                cur.insertText(word2)

            def _delim(ch):
                fmt = QTextCharFormat()
                fmt.setForeground(self._RX_C_DELIM)
                cur.setCharFormat(fmt)
                cur.insertText(ch)

            buf = ''
            for ch in plain:
                if ch in (' ', '\t', '\n', '\r'):
                    _flush(buf)
                    buf = ''
                    _delim(ch)
                else:
                    buf += ch
                    if len(buf) > 16:
                        _flush(buf)
                        buf = ''
            _flush(buf)
            self._rx_word_buf = ''
            self.rx_text.setTextCursor(cur)
            self.rx_text.ensureCursorVisible()
        except Exception as e:
            try:
                print(f"⚠️ Recolor RX prénom ignoré: {e}")
            except Exception:
                pass
        finally:
            try:
                self.rx_text.blockSignals(False)
            except Exception:
                pass
            self._rx_recoloring = False

    def _rx_insert_colored(self, text, highlight=False):
        """Insère text dans rx_text mot par mot avec colorisation.
        V8.4 F4LPS : highlight=True surligne tout le morceau en fond rouge
        sombre (façon JS8Call) quand il s'agit d'une réponse/mention nous
        concernant — sans changer les couleurs de mots déjà en place."""
        cur = self.rx_text.textCursor(); cur.movePosition(QTextCursor.End)
        def _flush(word, cur):
            if not word: return
            # Correction Z uniquement au moment d'afficher le mot complet.
            # Cela marche même si l'indicatif arrive en plusieurs petits bouts audio.
            try:
                word = self._f4lps_fix_rx_call_token(word)
            except Exception:
                pass
            fmt = QTextCharFormat(); fmt.setForeground(self._word_color(word))
            # Prénom OM : orange + gras pour bien le distinguer du texte normal.
            try:
                wclean = re.sub(r'[^A-ZÀ-ÖØ-Ý0-9/\-]', '', str(word).upper())
                dxn = getattr(self, '_dx_name', '') or (self.dx_name_edit.text().strip() if hasattr(self, 'dx_name_edit') else '')
                names = set(getattr(self, '_rx_name_candidates', set()) or set())
                if dxn:
                    names.add(str(dxn).upper())
                if wclean in names:
                    fmt.setForeground(self._RX_C_NAME)
                    fmt.setFontWeight(QFont.Bold)
            except Exception:
                pass
            if highlight:
                fmt.setBackground(self._RX_BG_REPLY)
            cur.setCharFormat(fmt); cur.insertText(word)
        def _delim(ch, cur):
            fmt = QTextCharFormat(); fmt.setForeground(self._RX_C_DELIM)
            if highlight:
                fmt.setBackground(self._RX_BG_REPLY)
            cur.setCharFormat(fmt); cur.insertText(ch)
        buf = getattr(self, '_rx_word_buf', '')
        for ch in text:
            if ch in (' ','\t','\n','\r'): _flush(buf,cur); buf=''; _delim(ch,cur)
            else: buf+=ch
            if len(buf)>16: _flush(buf,cur); buf=''
        self._rx_word_buf = buf
        self.rx_text.setTextCursor(cur); self.rx_text.ensureCursorVisible()

    def _rx_clean_word(self, txt):
        """Nettoie un mot RX copié depuis QTextEdit sans embarquer les espaces/ponctuations."""
        t = str(txt or '').replace('\u2029', ' ').replace('\u2028', ' ')
        t = t.strip().upper()
        # D'abord corriger un éventuel Z transformé en accolade/crochet/parenthèse,
        # puis nettoyer le mot. Sinon RN4A{ deviendrait RN4A et le Z serait perdu.
        try:
            fixed = self._f4lps_fix_rx_call_token(t)
            if fixed:
                t = fixed
        except Exception:
            pass
        # Garder les suffixes radio /P, /M... mais enlever ponctuation autour.
        t = re.sub(r'^[^A-Z0-9]+|[^A-Z0-9/]+$', '', t)
        return t.strip()

    def _rx_find_calls_in_text(self, txt):
        """Retourne les indicatifs valides trouvés dans une sélection RX."""
        t = str(txt or '').replace('\u2029', ' ').replace('\u2028', ' ').upper()
        try:
            t = self._rx_repair_callsign_glitches(t)
        except Exception:
            pass
        # Recherche large par jetons, y compris les symboles qui peuvent remplacer un Z.
        toks = re.findall(r'[A-Z0-9\{\}\[\]\(\)]{2,10}(?:/(?:P|M|MM|AM|QRP|[A-Z0-9]{1,4}))?', t)
        out = []
        for tok in toks:
            if self._rx_is_locator_token(tok):
                continue
            w = self._rx_clean_word(tok)
            if self._rx_is_locator_token(w):
                continue
            if (w and w not in self._CALL_REJECT and 3 <= len(w) <= 14
                    and w[0].isalpha() and self._RE_CALL_CLR.match(w)):
                if w not in out:
                    out.append(w)
        return out

    def _rx_is_name_candidate(self, word):
        """Retourne True si un mot RX peut raisonnablement être un prénom OM.

        On reste volontairement prudent : pas de chiffre, pas d'indicatif,
        pas de mot radio courant. Le remplissage automatique reste déclenché
        surtout après NAME / OP / OPR / PRENOM / DR, mais le double-clic peut
        utiliser ce test pour mettre un mot isolé dans Prénom OM.
        """
        try:
            w = str(word or '').strip().upper()
            w = re.sub(r'^[^A-ZÀ-ÖØ-Ý]+|[^A-ZÀ-ÖØ-Ý\-]+$', '', w)
            if not (2 <= len(w) <= 18):
                return False
            if re.search(r'\d', w):
                return False
            if w in set(getattr(self, '_CALL_REJECT', set())) | {'IS','THE','MY','UR','RIG','ANT','QTH','LOC','RST','NAME','OP','OPR','PRENOM','FIRST','LAST'}:
                return False
            if self._rx_find_calls_in_text(w):
                return False
            return bool(re.match(r'^[A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý\-]{1,17}$', w))
        except Exception:
            return False

    def _rx_learn_name_candidates_from_text(self, txt, fill_field=False):
        """Déduit les prénoms probables après NAME / OP / OPR / PRENOM / DR.

        Les mots trouvés sont gardés dans _rx_name_candidates pour colorisation
        orange dans le texte reçu. Si fill_field=True, le premier prénom peut
        remplir le champ Prénom OM si celui-ci est vide.
        """
        found = []
        try:
            up = str(txt or '').upper().replace('\r', ' ').replace('\n', ' ')
            pats = (
                r'\bMY\s+NAME\s+IS\s+([A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý\-]{1,18})\b',
                r'\bNAME\s+(?:IS\s+)?([A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý\-]{1,18})\b',
                r'\bOP(?:R|ERATOR)?\s+(?:IS\s+)?([A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý\-]{1,18})\b',
                r'\bPR[ÉE]NOM\s+(?:IS\s+)?([A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý\-]{1,18})\b',
                r'\bFIRST\s+NAME\s+(?:IS\s+)?([A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý\-]{1,18})\b',
                r'\bDR\s+([A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý\-]{1,18})\b',
            )
            for pat in pats:
                for m in re.finditer(pat, up, flags=re.IGNORECASE):
                    cand = m.group(1).strip().upper()
                    if self._rx_is_name_candidate(cand) and cand not in found:
                        found.append(cand)

            # Cas très courant en PSK/DM780 : "DE IK0UR ROGER ROGER".
            # Quand un mot prénom est répété 2 fois juste après un indicatif,
            # on le considère comme prénom probable et on le colorise.
            try:
                call_re = r'[A-Z]{1,3}[0-9][A-Z0-9]{1,5}(?:/(?:P|M|MM|AM|QRP))?'
                rep_pat = r'\b(?:DE\s+)?' + call_re + r'\s+([A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý\-]{1,18})\s+\1\b'
                for m in re.finditer(rep_pat, up, flags=re.IGNORECASE):
                    cand = m.group(1).strip().upper()
                    if self._rx_is_name_candidate(cand) and cand not in found:
                        found.append(cand)
            except Exception:
                pass

            if found:
                names = set(getattr(self, '_rx_name_candidates', set()) or set())
                names.update(found)
                self._rx_name_candidates = names
                try:
                    QTimer.singleShot(0, self._rx_recolor_all_text)
                except Exception:
                    pass
                if fill_field and hasattr(self, 'dx_name_edit') and not self.dx_name_edit.text().strip():
                    name = found[0][:1] + found[0][1:].lower()
                    self.dx_name_edit.blockSignals(True)
                    self.dx_name_edit.setText(name)
                    self.dx_name_edit.blockSignals(False)
                    self._dx_name = name
                    try:
                        if hasattr(self, 'log_name'):
                            self.log_name.setText(name)
                    except Exception:
                        pass
                    try:
                        self._set_status(f"👤 Prénom détecté RX : {name}")
                    except Exception:
                        pass
        except Exception:
            pass
        return found

    def _rx_word_under_pos(self, pos):
        """Mot propre exactement sous la souris dans la zone RX."""
        cur = self.rx_text.cursorForPosition(pos)
        cur.select(QTextCursor.WordUnderCursor)
        return self._rx_clean_word(cur.selectedText())

    def _rx_use_call_from_mouse(self, pos, copy_clipboard=True):
        """Utilise l'indicatif sous la souris comme CALL actif sans sélectionner plusieurs mots."""
        word = self._rx_word_under_pos(pos)
        calls = self._rx_find_calls_in_text(word)
        if not calls:
            return False
        call = calls[0]
        try:
            self._set_active_dxcall(call)
        except Exception:
            pass
        # V8.3.11 F4LPS : SEUL le clic volontaire sur l'indicatif RX bleu
        # envoie le correspondant au MultiDigi Tracker.
        try:
            if self._tracker_manual_spot_allowed(call):
                self._wsjt_udp_auto_spot_call(call, force=True)
        except Exception:
            pass
        if copy_clipboard:
            try:
                QApplication.clipboard().setText(call)
            except Exception:
                pass
        try:
            self._set_status(f"📡 CALL actif depuis RX : {call}")
        except Exception:
            pass

        # Pré-cadrage immédiat si le Tracker est déjà ouvert.
        try:
            win = getattr(self, '_grid_tracker_win', None)
            if win is not None and getattr(win, 'live_map', None) is not None:
                win.live_map.clear_contacts()
            QTimer.singleShot(250, self._tracker_autozoom_active_qso)
            QTimer.singleShot(900, self._tracker_update_active_dx_marker)
        except Exception:
            pass
        return True

    def _rx_set_dx_name_from_word(self, word):
        """Met un seul mot RX dans le champ Prénom OM, sans prendre toute la phrase."""
        name = self._rx_clean_word(word)
        if not name:
            return
        # Un prénom ne doit pas ressembler à un indicatif ni à un mot radio courant.
        if not self._rx_is_name_candidate(name):
            return
        try:
            name = name[:1].upper() + name[1:].lower()
            if hasattr(self, 'dx_name_edit'):
                self.dx_name_edit.setText(name)
            self._dx_name = name
            self._set_status(f"👤 Prénom OM depuis RX : {name}")
        except Exception:
            pass

    def _rx_context_menu(self, pos):
        """Menu contextuel RX robuste : jamais de crash sur clic droit."""
        try:
            word = self._rx_word_under_pos(pos)
        except Exception:
            word = ''
        try:
            sel = self.rx_text.textCursor().selectedText().strip()
        except Exception:
            sel = ''
        try:
            calls_word = self._rx_find_calls_in_text(word)
            calls_sel = self._rx_find_calls_in_text(sel)
            cand = calls_word[0] if calls_word else (calls_sel[0] if calls_sel else '')
        except Exception:
            cand = ''

        try:
            menu = QMenu(self.rx_text)
            menu.setStyleSheet("QMenu{background:#0d000d;color:#ddaacc;border:1px solid #440044;}QMenu::item{padding:5px 20px;}QMenu::item:selected{background:#2a0035;}QMenu::separator{background:#330033;height:1px;margin:3px 0;}")

            a0 = menu.addAction(f"📡  Mettre « {cand} » dans CALL actif" if cand else "📡  Mettre l'indicatif dans CALL actif")
            a0.setEnabled(bool(cand))
            if cand:
                a0.triggered.connect(lambda _=False, c=cand: self._set_active_dxcall(c))

            a0b = menu.addAction(f"📋  Copier « {cand} »" if cand else "📋  Copier l'indicatif")
            a0b.setEnabled(bool(cand))
            if cand:
                a0b.triggered.connect(lambda _=False, c=cand: QApplication.clipboard().setText(c))

            menu.addSeparator()
            a1 = menu.addAction("📋  Copier la sélection")
            a1.setEnabled(bool(sel))
            a1.triggered.connect(lambda _=False, t=sel: QApplication.clipboard().setText(t))

            a2 = menu.addAction(f"📋  Copier le mot sous souris « {word} »" if word else "📋  Copier le mot sous souris")
            a2.setEnabled(bool(word))
            a2.triggered.connect(lambda _=False, t=word: QApplication.clipboard().setText(t))

            a3 = menu.addAction(f"👤  Mettre « {word} » dans Prénom OM" if word else "👤  Mettre le mot dans Prénom OM")
            a3.setEnabled(bool(word) and not bool(self._rx_find_calls_in_text(word)))
            if word:
                a3.triggered.connect(lambda _=False, t=word: self._rx_set_dx_name_from_word(t))

            menu.addSeparator()
            a4 = menu.addAction("📄  Copier tout le texte RX")
            a4.triggered.connect(lambda _=False: QApplication.clipboard().setText(self.rx_text.toPlainText()))

            # On garde l'effacement RX dans le menu, mais protégé.
            a5 = menu.addAction("🗑  Effacer la zone RX")
            a5.triggered.connect(lambda _=False: self.rx_text.clear())

            menu.exec_(self.rx_text.viewport().mapToGlobal(pos))
        except Exception as e:
            # Secours : le menu natif Qt est plus simple et évite tout crash.
            try:
                m = self.rx_text.createStandardContextMenu()
                m.exec_(self.rx_text.viewport().mapToGlobal(pos))
            except Exception:
                try:
                    print(f"⚠️ menu RX ignoré: {e}")
                except Exception:
                    pass

    def _rx_diag_path(self):
        folder = os.path.join(os.path.expanduser("~"), "Documents", "F4LPS_Diagnostics")
        try:
            os.makedirs(folder, exist_ok=True)
        except Exception:
            folder = os.path.expanduser("~")
        return os.path.join(folder, "psk_rx_diagnostic.log")

    def _open_rx_diag_log(self):
        path = self._rx_diag_path()
        try:
            if not os.path.exists(path):
                with open(path, "w", encoding="utf-8") as f:
                    f.write("Journal diagnostic RX PSK F4LPS\n")
            os.startfile(path)
        except Exception as e:
            self._set_status(f"⚠ Journal diagnostic : {e}")

    def _on_rx_diag(self, d):
        try:
            state = str(d.get("state", ""))
            self.diag_state.setText(state)
            colors = {
                "DÉCODAGE": "#66ff88",
                "VERROUILLAGE": "#ffdd66",
                "ACQUISITION": "#ff9966",
                "ATTENTE SIGNAL": "#aaaaaa",
            }
            self.diag_state.setStyleSheet(
                f"font-weight:bold;color:{colors.get(state, '#ffffff')};"
            )
            self.diag_signal.setText(f"{float(d.get('signal_db', 0)):.1f} dB")
            self.diag_costas.setText(f"{float(d.get('costas_pct', 0)):.0f} %")
            self.diag_timing.setText(f"{float(d.get('timing_pct', 0)):.0f} %")
            self.diag_dcd.setText("ON" if d.get("dcd") else "OFF")
            self.diag_dcd.setStyleSheet(
                "font-weight:bold;color:#66ff88;" if d.get("dcd")
                else "font-weight:bold;color:#ff6666;"
            )
            self.diag_snr.setText(f"{float(d.get('snr', 0)):.1f} dB")
            self.diag_varicode.setText(f"{float(d.get('varicode_pct', 0)):.0f} %")
            self.diag_acq.setText(
                "-- ms" if d.get("acq_ms") is None else f"{float(d['acq_ms']):.0f} ms"
            )
            self.diag_reacq.setText(
                "-- ms" if d.get("reacq_ms") is None else f"{float(d['reacq_ms']):.0f} ms"
            )
            self.diag_chars.setText(f"{int(d.get('good', 0))} / {int(d.get('bad', 0))}")

            now = time.time()
            if now - float(getattr(self, "_diag_log_t", 0.0) or 0.0) >= 0.5:
                self._diag_log_t = now
                stamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]
                with open(self._rx_diag_path(), "a", encoding="utf-8") as f:
                    f.write(
                        f"{stamp} | {state} | sig={float(d.get('signal_db',0)):.1f} "
                        f"| snr={float(d.get('snr',0)):.1f} | dcd={int(bool(d.get('dcd')))} "
                        f"| acquired={int(bool(d.get('acquired')))} "
                        f"| costas={float(d.get('costas_pct',0)):.0f}% "
                        f"| timing={float(d.get('timing_pct',0)):.0f}% "
                        f"| varicode={float(d.get('varicode_pct',0)):.0f}% "
                        f"| good={int(d.get('good',0))} bad={int(d.get('bad',0))} "
                        f"| acq_ms={d.get('acq_ms')} reacq_ms={d.get('reacq_ms')}\n"
                    )
        except Exception:
            pass

    def _on_text(self, text):
        """Réception texte PSK — colorisation + ligne RSID/mode façon DM780."""
        raw_text = str(text or '')

        # V1.6.124 : garde anti-retour TX. Après émission, le VAC / la carte son peut
        # encore contenir la fin de notre propre PSK. Ne pas l'afficher ni l'utiliser
        # comme RSID RX du correspondant.
        try:
            if time.time() < float(getattr(self, '_rx_ignore_until', 0.0) or 0.0):
                return
        except Exception:
            pass

        # Si le texte contient une balise RSID texte, elle est affichée AVANT le texte nettoyé.
        raw_text = self._handle_rx_rsid_text(raw_text)
        raw_text = self._rx_repair_callsign_glitches(raw_text)
        if not raw_text:
            return
        # Diagnostic léger : si le texte devient du charabia, on n'accuse pas les macros/RSID.
        # On garde le flux tel quel, mais on prévient que c'est le verrouillage PSK.
        try:
            sample = re.sub(r'\s+', '', raw_text)
            if len(sample) >= 12:
                good = sum(1 for c in sample if c.isalnum() or c in '/?.,:-')
                if good / max(1, len(sample)) < 0.70:
                    self._set_status('⚠ Décodage PSK instable : vérifier centre RX / mode / SR')
        except Exception:
            pass

        # V1.6.124 F4LPS : ne plus fabriquer un faux RSID au premier texte décodé.
        # Ce faux repère pouvait être déclenché par notre propre fin de TX et affichait
        # alors notre mode / notre fréquence de calage. Désormais, la ligne RSID RX
        # n'est affichée que si un vrai marqueur RSID est reçu de la station distante.

        try:
            self._last_decode_ms = time.time() * 1000.0
        except Exception:
            pass
        # Apprendre les prénoms AVANT l'insertion, pour que NAME PIERRE colore PIERRE immédiatement.
        self._rx_learn_name_candidates_from_text(raw_text, fill_field=False)
        self._update_rx_quality_indicator()

        # Tracker : le sens OM -> HOME ne démarre QUE si nous venons de finir
        # un TX et qu'un vrai morceau de texte RX est maintenant décodé.
        if bool(getattr(self, '_tracker_waiting_reply_after_tx', False)):
            self._tracker_qso_direction('rx', 2200)
            # Une fois la réponse constatée, les morceaux suivants peuvent prolonger
            # l'animation pendant cette salve RX.
            self._tracker_reply_active = True
            self._tracker_waiting_reply_after_tx = False
        elif bool(getattr(self, '_tracker_reply_active', False)):
            self._tracker_qso_direction('rx', 2200)

        self._rx_insert_colored(raw_text, highlight=self._rx_text_mentions_mycall(raw_text))
        self._auto_detect_call_name_from_rx(raw_text)
        self._feed_rx_translator(raw_text)



    # ── Auto CALL / prénom depuis RX + voyant de calage ───────────────────────
    def _auto_detect_call_name_from_rx(self, txt):
        """Détecte automatiquement l'indicatif et le prénom du correspondant.
        Exemples gérés : CQ CQ DE F4XXX, HB9BFM DE F4XXX, NAME JEAN, DR PIERRE.
        Ne remplace jamais un champ déjà rempli manuellement, sauf si le CALL est vide.
        """
        try:
            raw = str(txt or '')
            if not raw.strip():
                return
            up = raw.upper().replace('\r', ' ').replace('\n', ' ')
            my = ''
            try:
                my = (self._station_value('mycall_edit','') or '').upper().strip()
            except Exception:
                my = ''
            call_re = r'\b([A-Z]{1,3}[0-9][A-Z0-9]{1,4}(?:/(?:P|M|MM|AM|QRP))?)\b'
            candidates = []
            # Priorité aux constructions radio classiques.
            for pat in (r'\bCQ(?:\s+CQ)*\s+DE\s+'+call_re,
                        r'\bQRZ\s+DE\s+'+call_re,
                        r'\bDE\s+'+call_re,
                        call_re+r'\s+DE\s+'+call_re):
                for m in re.finditer(pat, up, flags=re.IGNORECASE):
                    groups = [g for g in m.groups() if g]
                    # Pour "DX DE MYCALL", on garde le premier si le dernier = mon call, sinon dernier après DE.
                    if len(groups) >= 2 and my and groups[-1].upper() == my:
                        candidates.append(groups[0])
                    else:
                        candidates.append(groups[-1])
            if not candidates:
                candidates = re.findall(call_re, up)
            for call in candidates:
                call = str(call).upper().strip()
                if not call or call == my:
                    continue
                if call in getattr(self, '_CALL_REJECT', set()):
                    continue
                # V8.3.11 F4LPS : détection RX = COLORATION UNIQUEMENT.
                # Aucun décodeur (PSK / Olivia / Contestia / RTTY / Domino / etc.)
                # ne doit copier automatiquement un indicatif dans CALL actif.
                # Le CALL devient actif uniquement après un clic volontaire de l'opérateur
                # sur l'indicatif bleu dans la fenêtre RX.
                break
            # Détection prénom : volontairement déclenchée seulement après des mots-clés.
            # Exemples : NAME JEAN, MY NAME IS JEAN, OP JEAN, OPR JEAN, PRENOM JEAN.
            name = ''
            name_patterns = (
                r'\bMY\s+NAME\s+IS\s+([A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý\-]{1,18})\b',
                r'\bNAME\s+(?:IS\s+)?([A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý\-]{1,18})\b',
                r'\bOP(?:R|ERATOR)?\s+(?:IS\s+)?([A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý\-]{1,18})\b',
                r'\bPR[ÉE]NOM\s+(?:IS\s+)?([A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý\-]{1,18})\b',
                r'\bFIRST\s+NAME\s+(?:IS\s+)?([A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý\-]{1,18})\b',
                r'\bDR\s+([A-ZÀ-ÖØ-Ý][A-ZÀ-ÖØ-Ý\-]{1,18})\b',
            )
            reject_names = set(getattr(self, '_CALL_REJECT', set())) | {'IS','THE','MY','UR','RIG','ANT','QTH','LOC','RST'}
            for pat in name_patterns:
                m = re.search(pat, up)
                if m:
                    cand = m.group(1).strip().upper()
                    if cand not in reject_names and not re.search(r'\d', cand):
                        name = cand[:1] + cand[1:].lower()
                    break
            if name:
                try:
                    names = set(getattr(self, '_rx_name_candidates', set()) or set())
                    names.add(name.upper())
                    self._rx_name_candidates = names
                    try:
                        QTimer.singleShot(0, self._rx_recolor_all_text)
                    except Exception:
                        pass
                except Exception:
                    pass
            if name and hasattr(self, 'dx_name_edit'):
                cur_name = self.dx_name_edit.text().strip()
                # Ne jamais écraser un prénom déjà saisi/collé manuellement.
                if not cur_name:
                    self.dx_name_edit.blockSignals(True)
                    self.dx_name_edit.setText(name)
                    self.dx_name_edit.blockSignals(False)
                    self._dx_name = name
                    try:
                        if hasattr(self, 'log_name'): self.log_name.setText(name)
                    except Exception:
                        pass
                    try:
                        self._set_status(f"👤 Prénom détecté RX : {name}")
                    except Exception:
                        pass
        except Exception as e:
            try: print(f"⚠️ Auto CALL/Prénom ignoré: {e}")
            except Exception: pass

    def _update_tuning_indicator(self, mag=None, sr=None):
        """Voyant RX supprimé à la demande F4LPS.

        On ne fait plus aucun calcul ni affichage RECALER / RX OK / RX —.
        Le décodage, le waterfall et l'auto-mode ne sont pas modifiés.
        """
        return

    def _on_spectrum(self, mag):
        sr = self.audio_thread.sample_rate if self.audio_thread else self._get_rx_sample_rate()
        # V1.6.137 : garder une copie du dernier spectre déjà calculé.
        # Utilisé par Auto Mode/RSID sans refaire de FFT ni ralentir le waterfall.
        try:
            self._last_spectrum_mag_for_mode = np.asarray(mag, dtype=np.float32).copy()
            self._last_spectrum_sr_for_mode = float(sr)
        except Exception:
            pass
        self._update_rx_sr_label(sr, active=bool(self.audio_thread))
        self.waterfall.update_data(mag, sr)
        # Copie d'affichage uniquement pour la fenêtre CW dédiée.
        try:
            if getattr(self, '_family', '') == "CW" and getattr(self, 'cw_waterfall_window', None) is not None:
                self.cw_waterfall_window.waterfall.update_data(mag, sr)
                dec = self.audio_thread.decoder if self.audio_thread is not None else self.decoder_obj
                self.cw_waterfall_window.update_diagnostics(dec)
        except Exception:
            pass
        self._update_rx_quality_indicator()
        # AUTO MODE réutilise ce spectre déjà disponible : zéro charge DSP dans RX.
        self._automode_psk_from_spectrum(mag, sr)

    def _on_snr(self, snr):
        try:
            self._last_snr = float(snr)
        except Exception:
            pass
        if getattr(self, '_family', '') == 'JS8':
            valid = np.isfinite(snr) and float(snr) > -99.0
            self.snr_lbl.setText(
                f"SNR estimé (2500 Hz): {snr:+.1f} dB | dernière trame"
                if valid else "SNR: — | attente d'une trame CRC valide"
            )
            self.snr_lbl.setStyleSheet("color:#88ccff;font-family:'Courier New';font-size:9pt;")
            self._update_rx_quality_indicator()
            return
        col = "#00ff88" if snr>15 else "#ffcc00" if snr>8 else "#ff6644"
        conf = int(max(0, min(99, (float(snr) - 3.0) / 15.0 * 100.0)))
        self.snr_lbl.setText(f"SNR: {snr:.1f} dB  |  Confiance: {conf}%")
        self.snr_lbl.setStyleSheet(f"color:{col};font-family:'Courier New';font-size:9pt;")
        self._update_rx_quality_indicator()

    def _on_envelope(self, rms):
        """VU RX V1.6.24 — échelle dBFS réaliste.

        Correction du problème V1.6.14/V1.6.24 : le gain visuel x4 faisait
        monter le VU RX à 100% même avec seulement -40/-45 dBFS de bruit.
        Ici les barres suivent le vrai niveau dBFS :
          - environ -55 dBFS = 0%
          - environ -45 dBFS = 20/25%
          - environ -10 dBFS = 100%
        Aucun changement sur le décodage, le waterfall ou l'audio réel.
        """
        if rms > 0:
            db = 20.0 * math.log10(rms + 1e-10)

            # V1.6.50 : échelle VU plus lisible pour la radio numérique.
            # Un vrai signal faible autour de -40 dBFS ne doit plus paraître à zéro.
            # Le dBFS affiché reste réel ; seule la barre VU est plus sensible.
            db_floor = -68.0
            db_full  = -22.0
            val_f = (db - db_floor) / (db_full - db_floor) * 100.0
            val = int(max(0, min(100, val_f)))
        else:
            db = -99.9
            val = 0

        self.level_bar.setValue(val)
        if hasattr(self, 'big_rx_meter'):
            self.big_rx_meter.setValue(val)
        if hasattr(self, 'rx_db_lbl'):
            self.rx_db_lbl.setText(f"{db:.1f} dBFS" if rms > 0 else "-\u221e dBFS")

    # ── DÉCODEUR DE LANGUES ───────────────────────────────────────────────────

    def _populate_language_microphones(self):
        """Remplit la liste des micros pour le module Parler -> TX."""
        if not hasattr(self, 'lang_mic_combo'):
            return
        current = self.lang_mic_combo.currentData()
        self.lang_mic_combo.blockSignals(True)
        self.lang_mic_combo.clear()
        self.lang_mic_combo.addItem("Windows par défaut", None)

        names = []
        # Méthode 1 : SpeechRecognition, même index que sr.Microphone(device_index=...).
        try:
            import speech_recognition as sr
            names = list(sr.Microphone.list_microphone_names())
            for idx, name in enumerate(names):
                label = f"{idx} - {name}"
                self.lang_mic_combo.addItem(label[:90], idx)
        except Exception:
            # Méthode 2 : PyAudio en secours si SpeechRecognition n'est pas encore installé.
            try:
                import pyaudio
                pa = pyaudio.PyAudio()
                for idx in range(pa.get_device_count()):
                    info = pa.get_device_info_by_index(idx)
                    if int(info.get('maxInputChannels', 0)) > 0:
                        name = str(info.get('name', f'Micro {idx}'))
                        self.lang_mic_combo.addItem(f"{idx} - {name}"[:90], idx)
                pa.terminate()
            except Exception:
                pass

        # Restaurer le choix précédent si possible.
        if current is not None:
            for i in range(self.lang_mic_combo.count()):
                if self.lang_mic_combo.itemData(i) == current:
                    self.lang_mic_combo.setCurrentIndex(i)
                    break
        self.lang_mic_combo.blockSignals(False)

    def _language_collect_mics(self):
        """Liste les micros comme le module vocal CW Terminal : PyAudio d'abord, SpeechRecognition en secours."""
        items = [("Windows par défaut", None)]
        seen = set()
        try:
            import pyaudio
            pa = pyaudio.PyAudio()
            for idx in range(pa.get_device_count()):
                info = pa.get_device_info_by_index(idx)
                if int(info.get('maxInputChannels', 0)) > 0:
                    name = str(info.get('name', f'Micro {idx}'))
                    key = (idx, name)
                    if key not in seen:
                        items.append((f"{idx} - {name}", idx))
                        seen.add(key)
            pa.terminate()
        except Exception:
            pass
        if len(items) <= 1:
            try:
                import speech_recognition as sr
                for idx, name in enumerate(sr.Microphone.list_microphone_names()):
                    items.append((f"{idx} - {name}", idx))
            except Exception:
                pass
        return items

    # ── Gestion CALL DX et prénom — saisie manuelle uniquement ───────────────

    def _on_dxcall_combo_activated(self, index):
        """Sélection dans l'historique des calls."""
        call = self.dx_call_combo.itemText(index).strip().upper()
        if call:
            self._set_active_dxcall(call, from_combo=True)
            # Restaurer le prénom associé si mémorisé
            name = self._call_history.get(call, {}).get('name', '')
            if name and hasattr(self, 'dx_name_edit'):
                self.dx_name_edit.blockSignals(True)
                self.dx_name_edit.setText(name)
                self.dx_name_edit.blockSignals(False)
                self._dx_name = name

    def _on_dxcall_text_edited(self, text):
        """Mise à jour de _last_dxcall à chaque frappe — pas besoin d'Entrée."""
        call = text.strip().upper()
        # Accepter dès qu'on a le minimum : lettre+chiffre+lettre
        if call and re.search(r'[A-Z][0-9][A-Z]', call):
            self._last_dxcall = call
            try: self.detected_call_lbl.setText(f'CALL actif : {call}')
            except: pass
            try:
                if hasattr(self,'log_call'): self.log_call.setText(call)
            except: pass
            # Recherche différée : évite une requête à chaque touche.
            try:
                self._dx_lookup_timer.start(700)
            except Exception:
                pass
        elif not call:
            self._last_dxcall = ''
            try:
                self._dx_lookup_timer.stop()
            except Exception:
                pass

    def _on_dxcall_manual_edit(self):
        """Entrée pressée — valide et ajoute à l'historique."""
        call = self.dx_call_combo.lineEdit().text().strip().upper()
        if not call:
            return
        # Validation souple : lettre + chiffre + lettre minimum
        if re.search(r'[A-Z][0-9][A-Z]', call):
            self._set_active_dxcall(call, from_combo=True)
        else:
            self._set_status(f'⚠️ Indicatif non reconnu : {call}')

    def _on_dxname_changed(self, name):
        """Prénom DX saisi manuellement."""
        name = name.strip()
        self._dx_name = name
        # Associer le prénom au call actif dans l'historique
        call = getattr(self, '_last_dxcall', '')
        if call and name:
            if not hasattr(self, '_call_history'): self._call_history = {}
            if call not in self._call_history: self._call_history[call] = {}
            self._call_history[call]['name'] = name
        # Mettre à jour le champ log_name
        try:
            if hasattr(self, 'log_name'): self.log_name.setText(name)
        except: pass
        # Recolorise le RX quand le prénom est saisi/collé ou détecté après coup.
        try:
            if name:
                names = set(getattr(self, '_rx_name_candidates', set()) or set())
                names.add(name.upper())
                self._rx_name_candidates = names
                QTimer.singleShot(0, self._rx_recolor_all_text)
        except Exception:
            pass

    def _set_active_dxcall(self, call, from_combo=False):
        """Définit l'indicatif DX actif — alimente macros et log."""
        call = str(call or '').strip().upper()
        if not call: return
        previous_call = str(getattr(self, '_last_dxcall', '') or '').strip().upper()
        call_changed = bool(previous_call and previous_call.split('/')[0] != call.split('/')[0])
        self._last_dxcall = call
        # Un nouvel indicatif doit toujours provoquer une nouvelle recherche.
        # On efface uniquement le prénom qui avait été rempli automatiquement ;
        # un prénom saisi manuellement reste protégé.
        if call_changed:
            try:
                old_auto = str(getattr(self, '_dx_lookup_auto_name', '') or '').strip()
                current_name = self.dx_name_edit.text().strip() if hasattr(self, 'dx_name_edit') else ''
                if old_auto and current_name == old_auto:
                    self.dx_name_edit.clear()
                self._dx_lookup_auto_name = ''
                self._dx_name = ''
                self._dx_lookup_last_requested = ''
            except Exception:
                pass
        # Mettre à jour le label
        try: self.detected_call_lbl.setText(f"CALL actif : {call}")
        except: pass
        # Mettre à jour le combo (sans boucle)
        if not from_combo:
            try:
                self.dx_call_combo.blockSignals(True)
                self.dx_call_combo.setCurrentText(call)
                self.dx_call_combo.blockSignals(False)
            except: pass
        # Ajouter à l'historique du combo
        try:
            items = [self.dx_call_combo.itemText(i) for i in range(self.dx_call_combo.count())]
            if call not in items:
                self.dx_call_combo.blockSignals(True)
                self.dx_call_combo.insertItem(0, call)
                while self.dx_call_combo.count() > 30:
                    self.dx_call_combo.removeItem(self.dx_call_combo.count()-1)
                self.dx_call_combo.blockSignals(False)
            self.dx_call_combo.blockSignals(True)
            self.dx_call_combo.setCurrentText(call)
            self.dx_call_combo.blockSignals(False)
        except: pass
        # Alimenter le log
        try:
            if hasattr(self, 'log_call') and self.log_call.text().strip().upper() != call:
                self.log_call.setText(call)
        except: pass
        # Mémoriser dans l'historique
        if not hasattr(self, '_call_history'): self._call_history = {}
        if call not in self._call_history: self._call_history[call] = {}
        # V8.3.11 F4LPS : définir le CALL actif ne doit plus envoyer de spot.
        # Cela évite les envois depuis l'auto-détection, les macros et les loggers.
        # Seul _rx_use_call_from_mouse() déclenche explicitement le Tracker.
        self._set_status(f"📡 CALL : {call} — prêt pour macros et log")
        # Lance aussi la recherche quand le CALL vient du RX, du menu ou de l'historique.
        try:
            self._dx_lookup_timer.start(120)
        except Exception:
            pass

    def _set_dx_lookup_state(self, text, state='idle'):
        """Affiche durablement l'état de recherche à côté du champ Prénom."""
        colors = {
            'idle':  ('#8899aa', '#071018', '#263746'),
            'busy':  ('#ffff66', '#272400', '#777000'),
            'ok':    ('#55ff99', '#002414', '#16804a'),
            'none':  ('#ffbb55', '#291700', '#8a5700'),
            'error': ('#ff7777', '#2a0808', '#8c3030'),
        }
        fg, bg, border = colors.get(state, colors['idle'])
        try:
            self.dx_lookup_state_lbl.setText(str(text))
            self.dx_lookup_state_lbl.setStyleSheet(
                f"color:{fg};background:{bg};border:1px solid {border};"
                "border-radius:3px;padding:3px 6px;font-size:8pt;font-weight:bold;"
            )
        except Exception:
            pass

    def _on_dx_lookup_progress(self, call, source):
        """Affiche en direct la source actuellement interrogée."""
        try:
            current = self.dx_call_combo.lineEdit().text().strip().upper()
        except Exception:
            current = str(getattr(self, '_last_dxcall', '') or '').upper()
        if current.split('/')[0] != str(call).upper().split('/')[0]:
            return
        self._set_dx_lookup_state(f"⏳ {source}…", 'busy')
        self._set_status(f"🌐 Recherche {call} : interrogation de {source}…")

    def _save_dx_lookup_cache(self):
        """Sauvegarde le callbook local pour les prochains lancements."""
        try:
            cache = getattr(self, '_dx_lookup_cache', {}) or {}
            # Garde une taille raisonnable et uniquement des dictionnaires.
            clean = {str(k): v for k, v in list(cache.items())[-5000:] if isinstance(v, dict)}
            with open(self._dx_lookup_cache_path, 'w', encoding='utf-8') as f:
                json.dump(clean, f, ensure_ascii=False, indent=2)
        except Exception as e:
            print('Cache callbook non sauvegardé:', e)

    def _force_dx_callsign_lookup(self):
        """Relance la recherche même si le CALL est déjà dans le cache."""
        try:
            call = self.dx_call_combo.lineEdit().text().strip().upper()
        except Exception:
            call = ''
        base_call = re.sub(r'[^A-Z0-9/]', '', call).split('/')[0]
        if not base_call or not re.search(r'[A-Z][0-9][A-Z]', base_call):
            self._set_dx_lookup_state("Indicatif invalide", 'error')
            self._set_status("⚠️ Entrez d'abord un indicatif valide dans CALL")
            return
        try:
            self._dx_lookup_cache.pop(base_call, None)
            self._dx_lookup_last_requested = ''
        except Exception:
            pass
        try:
            cfg = getattr(self, '_logbook_settings', {}) or {}
            qrz_user = str(cfg.get('qrz_xml_user') or '').strip()
            qrz_pass = str(cfg.get('qrz_xml_password') or cfg.get('qrz_xml_pass') or '').strip()
            if not qrz_user or not qrz_pass:
                self._set_status("ℹ️ QRZ XML non renseigné : recherche avec HamQTH et les bases publiques")
        except Exception:
            pass
        self._start_dx_callsign_lookup()

    def _normalize_dx_lookup_name(self, value):
        """Extrait un prénom propre d'un champ nom provenant d'un annuaire radio."""
        txt = re.sub(r'\s+', ' ', str(value or '')).strip()
        if not txt:
            return ''
        # Les annuaires renvoient parfois NOM, PRENOM ou un nom complet.
        if ',' in txt:
            parts = [x.strip() for x in txt.split(',') if x.strip()]
            txt = parts[-1] if parts else txt
        first = txt.split()[0].strip(' .,-_/')
        if not first or any(ch.isdigit() for ch in first):
            return ''
        return first[:1].upper() + first[1:].lower()

    def _start_dx_callsign_lookup(self):
        """Recherche multi-annuaire dans un thread, sans bloquer l'audio ni l'interface."""
        try:
            call = self.dx_call_combo.lineEdit().text().strip().upper()
        except Exception:
            call = str(getattr(self, '_last_dxcall', '') or '').strip().upper()
        call = re.sub(r'[^A-Z0-9/]', '', call)
        if not call or not re.search(r'[A-Z][0-9][A-Z]', call):
            self._set_dx_lookup_state("Indicatif invalide", 'error')
            return
        base_call = call.split('/')[0]
        if base_call in getattr(self, '_dx_lookup_cache', {}):
            self._set_dx_lookup_state("Résultat mémorisé", 'ok')
            self._on_dx_lookup_ready(call, dict(self._dx_lookup_cache[base_call]))
            return
        if base_call == getattr(self, '_dx_lookup_last_requested', ''):
            return
        self._dx_lookup_last_requested = base_call
        try:
            self._set_status(f"🌐 Recherche de {call} sur plusieurs annuaires…")
            self._set_dx_lookup_state(f"⏳ Recherche {call}…", 'busy')
            if hasattr(self, 'dx_lookup_btn'):
                self.dx_lookup_btn.setEnabled(False)
            if hasattr(self, 'dx_name_edit') and not self.dx_name_edit.text().strip():
                self.dx_name_edit.setPlaceholderText("Recherche en cours…")
        except Exception:
            pass

        def _http_json(url, timeout=7):
            req = urllib.request.Request(url, headers={
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) PSK-Terminal-F4LPS/1.6',
                'Accept': 'application/json, application/xml, text/xml;q=0.9, */*;q=0.8',
            })
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return r.read(262144).decode('utf-8', errors='replace')

        def _clean_data(data, source):
            out = {
                'name': str(data.get('name') or '').strip(),
                'qth': str(data.get('qth') or '').strip(),
                'locator': str(data.get('locator') or '').strip().upper(),
                'country': str(data.get('country') or '').strip(),
                'lat': data.get('lat'),
                'lon': data.get('lon'),
                'source': source,
            }
            return out if any(out.get(k) not in (None, '') for k in ('name','qth','locator','country','lat','lon')) else None

        def _lookup_grid_tracker(lookup_call):
            """Demande le Callbook au Grid Tracker F4LPS par UDP.
            Le terminal utilise un port temporaire et attend la réponse sans bloquer l'interface
            puisque cette fonction s'exécute déjà dans le thread de recherche.
            """
            cfg = getattr(self, '_wsjtx_udp_settings', {}) or {}
            if not cfg.get('enabled', False):
                return None
            host = str(cfg.get('udp_host', '127.0.0.1') or '127.0.0.1').strip()
            port = int(cfg.get('udp_port', 2237) or 2237)
            request_id = f"{lookup_call}-{int(time.time()*1000)}"
            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            try:
                sock.bind(('127.0.0.1', 0))
                reply_port = int(sock.getsockname()[1])
                sock.settimeout(14.0)
                payload = {
                    'type': 'callbook_lookup',
                    'program': 'MultiDigi',
                    'call': lookup_call,
                    'request_id': request_id,
                    'reply_host': '127.0.0.1',
                    'reply_port': reply_port,
                }
                raw = (json.dumps(payload, ensure_ascii=False) + '\n').encode('utf-8')
                sock.sendto(raw, (host, port))
                data, _addr = sock.recvfrom(65535)
                obj = json.loads(data.decode('utf-8', errors='replace').strip())
                if not isinstance(obj, dict) or obj.get('type') != 'callbook_result':
                    return None
                if str(obj.get('request_id', '')) != request_id:
                    return None
                return _clean_data({
                    'name': obj.get('name'),
                    'qth': obj.get('qth'),
                    'locator': obj.get('grid') or obj.get('locator'),
                    'country': obj.get('country'),
                    'lat': obj.get('lat'),
                    'lon': obj.get('lon'),
                }, 'Grid · ' + str(obj.get('source') or 'Callbook F4LPS'))
            finally:
                try:
                    sock.close()
                except Exception:
                    pass

        def _lookup_hamdb(lookup_call):
            url = 'https://api.hamdb.org/v1/' + urllib.parse.quote(lookup_call) + '/json/PSKTerminal-F4LPS'
            obj = json.loads(_http_json(url))
            station = obj.get('hamdb', {}).get('callsign', {}) if isinstance(obj, dict) else {}
            if isinstance(station, list):
                station = station[0] if station else {}
            if not isinstance(station, dict):
                return None
            messages = obj.get('hamdb', {}).get('messages', {}) if isinstance(obj, dict) else {}
            status = str(station.get('status') or (messages.get('status') if isinstance(messages, dict) else '') or '').upper()
            if status and status not in ('OK', 'VALID'):
                return None
            return _clean_data({
                'name': (station.get('fname') or station.get('first') or station.get('first_name') or
                         station.get('nickname') or station.get('nick') or station.get('name') or
                         station.get('fullname') or station.get('full_name')),
                'qth': station.get('qth') or station.get('addr2') or station.get('city'),
                'locator': station.get('grid') or station.get('locator'),
                'country': station.get('country'),
            }, 'HamDB')

        def _lookup_callook(lookup_call):
            # Callook couvre principalement les indicatifs FCC des États-Unis.
            url = 'https://callook.info/' + urllib.parse.quote(lookup_call) + '/json'
            obj = json.loads(_http_json(url))
            if not isinstance(obj, dict) or str(obj.get('status','')).upper() != 'VALID':
                return None
            current = obj.get('current') or {}
            address = obj.get('address') or {}
            location = obj.get('location') or {}
            return _clean_data({
                'name': current.get('name') or obj.get('name'),
                'qth': address.get('line2') or location.get('name') or address.get('attn'),
                'locator': location.get('gridsquare') or location.get('grid'),
                'country': 'United States',
            }, 'Callook')

        def _lookup_qrz_xml(lookup_call):
            """Interroge l'interface XML officielle QRZ.com et retourne les erreurs exactes."""
            cfg = getattr(self, '_logbook_settings', {}) or {}
            user = str(cfg.get('qrz_xml_user') or os.environ.get('QRZ_XML_USER','')).strip()
            password = str(cfg.get('qrz_xml_password') or cfg.get('qrz_xml_pass') or os.environ.get('QRZ_XML_PASSWORD','')).strip()
            if not user or not password:
                return None
            import xml.etree.ElementTree as ET

            login_url = ('https://xmldata.qrz.com/xml/current/?username=' + urllib.parse.quote(user, safe='') +
                         '&password=' + urllib.parse.quote(password, safe='') +
                         '&agent=PSKTerminalF4LPS-1.6.136')
            root = ET.fromstring(_http_json(login_url, timeout=10))

            def _qrz_local_text(node, wanted):
                wanted = str(wanted).lower()
                for elem in node.iter():
                    tag = str(getattr(elem, 'tag', '')).split('}')[-1].lower()
                    if tag == wanted and elem.text:
                        return elem.text.strip()
                return ''

            def _qrz_local_element(node, wanted):
                wanted = str(wanted).lower()
                for elem in node.iter():
                    tag = str(getattr(elem, 'tag', '')).split('}')[-1].lower()
                    if tag == wanted:
                        return elem
                return None

            key = _qrz_local_text(root, 'Key')
            login_error = _qrz_local_text(root, 'Error')
            login_message = _qrz_local_text(root, 'Message')
            if not key:
                raise RuntimeError('QRZ XML connexion refusée : ' + (login_error or login_message or 'aucune clé de session'))

            query_url = ('https://xmldata.qrz.com/xml/current/?s=' + urllib.parse.quote(key) +
                         '&callsign=' + urllib.parse.quote(lookup_call))
            root = ET.fromstring(_http_json(query_url, timeout=10))
            qrz_error = _qrz_local_text(root, 'Error')
            qrz_message = _qrz_local_text(root, 'Message')
            callsign = _qrz_local_element(root, 'Callsign')
            if callsign is None:
                if qrz_error or qrz_message:
                    raise RuntimeError('QRZ XML : ' + (qrz_error or qrz_message))
                return None

            def qtxt(tag):
                return _qrz_local_text(callsign, tag)

            # QRZ distingue fname (prénom), name (nom), nickname et name_fmt.
            first = qtxt('fname') or qtxt('nickname')
            if not first:
                first = qtxt('name_fmt')
            return _clean_data({
                'name': first,
                'qth': qtxt('addr2'),
                'locator': qtxt('grid'),
                'country': qtxt('country') or qtxt('land'),
            }, 'QRZ XML officiel')

        def _lookup_hamqth(lookup_call):
            # L'API HamQTH exige un compte. Les identifiants peuvent être ajoutés
            # au JSON des réglages : hamqth_user et hamqth_password, ou via les
            # variables d'environnement HAMQTH_USER / HAMQTH_PASSWORD.
            cfg = getattr(self, '_logbook_settings', {}) or {}
            user = str(cfg.get('hamqth_user') or os.environ.get('HAMQTH_USER','')).strip()
            password = str(cfg.get('hamqth_password') or os.environ.get('HAMQTH_PASSWORD','')).strip()
            if not user or not password:
                return None
            import xml.etree.ElementTree as ET
            login_url = ('https://www.hamqth.com/xml.php?u=' + urllib.parse.quote(user, safe='') +
                         '&p=' + urllib.parse.quote(password, safe=''))
            root = ET.fromstring(_http_json(login_url))
            session_id = root.findtext('.//session_id') or ''
            if not session_id:
                return None
            qurl = ('https://www.hamqth.com/xml.php?id=' + urllib.parse.quote(session_id) +
                    '&callsign=' + urllib.parse.quote(lookup_call) + '&prg=PSKTerminal')
            root = ET.fromstring(_http_json(qurl))
            search = root.find('.//search')
            if search is None:
                return None
            def txt(tag):
                e = search.find(tag)
                return e.text.strip() if e is not None and e.text else ''
            return _clean_data({
                'name': txt('nick') or txt('adr_name'),
                'qth': txt('qth') or txt('adr_city'),
                'locator': txt('grid'),
                'country': txt('country'),
            }, 'HamQTH')

        def _extract_public_name(html_text, lookup_call):
            """Extraction prudente d'un prénom depuis une fiche publique HTML."""
            import html as _html
            text = _html.unescape(str(html_text or ''))
            # Retire scripts/styles puis balises pour faciliter les motifs.
            text = re.sub(r'(?is)<(script|style)[^>]*>.*?</\1>', ' ', text)
            plain = re.sub(r'(?s)<[^>]+>', ' ', text)
            plain = re.sub(r'\s+', ' ', plain).strip()
            patterns = [
                r'(?i)\b(?:First\s*Name|Firstname|Prénom|Prenom|Nick(?:name)?)\s*[:=-]\s*([A-ZÀ-ÖØ-öø-ÿ][A-ZÀ-ÖØ-öø-ÿ\-]{1,24})',
                r'(?i)\b(?:Operator|Name)\s*[:=-]\s*([A-ZÀ-ÖØ-öø-ÿ][A-ZÀ-ÖØ-öø-ÿ\-]{1,24})(?:\s+[A-ZÀ-ÖØ-öø-ÿ][A-ZÀ-ÖØ-öø-ÿ\-]{1,30})?',
            ]
            for pat in patterns:
                m = re.search(pat, plain)
                if m:
                    n = self._normalize_dx_lookup_name(m.group(1))
                    if n and n.upper() not in {'QRZ','CALLSIGN','AMATEUR','RADIO','UNKNOWN'}:
                        return n
            return ''

        def _lookup_qrz_public(lookup_call):
            url = 'https://www.qrz.com/db/' + urllib.parse.quote(lookup_call)
            raw = _http_json(url, timeout=8)
            name = _extract_public_name(raw, lookup_call)
            # Certaines pages exposent les données dans des meta/JSON internes.
            if not name:
                for pat in [r'(?i)\"fname\"\s*:\s*\"([^\"]+)\"',
                            r'(?i)\"first_name\"\s*:\s*\"([^\"]+)\"',
                            r'(?i)property=[\"\']profile:first_name[\"\'][^>]*content=[\"\']([^\"\']+)']:
                    try:
                        m = re.search(pat, raw)
                    except Exception:
                        m = None
                    if m:
                        name = self._normalize_dx_lookup_name(m.group(1)); break
            return _clean_data({'name': name}, 'QRZ public') if name else None

        def _lookup_qrzcq_public(lookup_call):
            urls = [
                'https://www.qrzcq.com/call/' + urllib.parse.quote(lookup_call),
                'https://www.qrzcq.com/page/lookup.php?call=' + urllib.parse.quote(lookup_call),
            ]
            for url in urls:
                raw = _http_json(url, timeout=8)
                name = _extract_public_name(raw, lookup_call)
                if not name:
                    m = re.search(r'(?i)\b(?:fname|firstname|first_name)\b[^A-Za-zÀ-ÿ]{0,20}([A-ZÀ-ÖØ-öø-ÿ][A-ZÀ-ÖØ-öø-ÿ\-]{1,24})', raw)
                    if m:
                        name = self._normalize_dx_lookup_name(m.group(1))
                if name:
                    return _clean_data({'name': name}, 'QRZCQ public')
            return None

        def worker(requested_call, lookup_call):
            errors = []
            partial = None
            # IMPORTANT : un annuaire peut connaître le pays/QTH sans publier le prénom.
            # Dans ce cas on conserve les informations partielles, mais on continue
            # obligatoirement vers l'annuaire suivant jusqu'à trouver un vrai prénom.
            providers = (
                ('MultiDigi Tracker', _lookup_grid_tracker),
                ('QRZ XML officiel', _lookup_qrz_xml),
                ('HamQTH', _lookup_hamqth),
                ('HamDB', _lookup_hamdb),
                ('Callook', _lookup_callook),
                ('QRZ public', _lookup_qrz_public),
                ('QRZCQ public', _lookup_qrzcq_public),
            )
            for provider_name, provider in providers:
                self._dx_lookup_progress.emit(requested_call, provider_name)
                try:
                    data = provider(lookup_call)
                    if not data:
                        continue
                    if partial is None:
                        partial = dict(data)
                    else:
                        for key in ('qth', 'locator', 'country'):
                            if not partial.get(key) and data.get(key):
                                partial[key] = data.get(key)
                    raw_name = str(data.get('name') or '').strip()
                    if self._normalize_dx_lookup_name(raw_name):
                        self._dx_lookup_ready.emit(requested_call, data)
                        return
                except Exception as e:
                    errors.append(f'{provider.__name__}: {e}')
            # On transmet les infos partielles uniquement pour le QTH/locator,
            # mais le statut indiquera clairement que le prénom n'a pas été trouvé.
            if partial:
                partial['name'] = ''
                partial['name_missing'] = True
                self._dx_lookup_ready.emit(requested_call, partial)
                return
            self._dx_lookup_error.emit(requested_call, ' | '.join(errors) or 'aucun annuaire ne contient cet indicatif')

        threading.Thread(target=worker, args=(call, base_call), daemon=True, name='DXCallMultiLookup').start()

    def _on_dx_lookup_ready(self, call, data):
        """Applique le résultat seulement si l'utilisateur est toujours sur ce CALL."""
        try:
            current = self.dx_call_combo.lineEdit().text().strip().upper()
        except Exception:
            current = str(getattr(self, '_last_dxcall', '') or '').upper()
        if current.split('/')[0] != str(call).upper().split('/')[0]:
            return
        base_call = str(call).upper().split('/')[0]
        self._dx_lookup_cache[base_call] = dict(data or {})
        self._save_dx_lookup_cache()
        self._dx_lookup_last_requested = ''
        name = self._normalize_dx_lookup_name((data or {}).get('name'))
        qth = str((data or {}).get('qth') or '').strip()
        locator = str((data or {}).get('locator') or '').strip().upper()
        try:
            current_name = self.dx_name_edit.text().strip()
            # Ne jamais écraser un prénom réellement saisi par l'utilisateur.
            if name and (not current_name or current_name == getattr(self, '_dx_lookup_auto_name', '')):
                self.dx_name_edit.setText(name)
                self._dx_lookup_auto_name = name
                self._dx_name = name
                if hasattr(self, 'log_name'):
                    self.log_name.setText(name)
        except Exception:
            pass
        try:
            if not hasattr(self, '_call_history'):
                self._call_history = {}
            rec = self._call_history.setdefault(base_call, {})
            if name: rec['name'] = name
            if qth: rec['qth'] = qth
            if locator: rec['locator'] = locator
        except Exception:
            pass
        source = str((data or {}).get('source') or 'Internet').strip()

        # V8.3.11 F4LPS : synchroniser la position Callbook avec le Tracker.
        # Avant, le locator servait bien au calcul distance/azimut ci-dessous,
        # mais n'était jamais recopié dans _dx_locator/_dx_lat/_dx_lon. Le Tracker
        # recevait donc une position vide et retombait sur le centre approximatif
        # du pays/préfixe.
        try:
            self._dx_locator = locator
            self._dx_country = str((data or {}).get('country') or '').strip()

            # V8.3.22 : afficher immédiatement Pays + Langue TX après le clic CALL,
            # puis régler le vrai menu "Traduire vers" si le pays est non ambigu.
            try:
                self._update_tx_language_from_country(
                    self._dx_country, base_call
                )
            except Exception:
                pass

            lat = (data or {}).get('lat')
            lon = (data or {}).get('lon')
            valid_ll = False
            try:
                if lat not in (None, '') and lon not in (None, ''):
                    lat = float(lat); lon = float(lon)
                    valid_ll = (-90.0 <= lat <= 90.0 and -180.0 <= lon <= 180.0)
            except Exception:
                valid_ll = False

            # Si l'annuaire ne fournit pas de coordonnées exactes, utiliser le
            # centre du locator Maidenhead (4/6/8 caractères). C'est la même
            # information qui sert déjà au calcul distance/azimut.
            if not valid_ll and locator:
                try:
                    ll = grid_to_latlon(locator)
                except Exception:
                    ll = None
                if ll:
                    lat, lon = float(ll[0]), float(ll[1])
                    valid_ll = True

            self._dx_lat = float(lat) if valid_ll else None
            self._dx_lon = float(lon) if valid_ll else None

            if hasattr(self, '_call_history'):
                rec = self._call_history.setdefault(base_call, {})
                if locator: rec['locator'] = locator
                if self._dx_country: rec['country'] = self._dx_country
                if self._dx_lat is not None and self._dx_lon is not None:
                    rec['lat'] = self._dx_lat
                    rec['lon'] = self._dx_lon
        except Exception:
            pass

        # MULTIDIGI V0.1 F4LPS : distance + azimut vers le correspondant, calculés
        # dès qu'un locator est remonté par l'annuaire. Utilise le locator perso
        # des réglages station (locator_edit) en priorité, sinon celui de
        # MultiDigi Tracker si déjà configuré là-bas.
        dist_az_txt = ''
        try:
            my_grid = (self._station_value('locator_edit', '') or '').strip().upper()
            if not my_grid:
                my_grid = multidigi_get_my_grid('')
            if my_grid and locator:
                da = distance_azimuth_from_locators(my_grid, locator)
                if da:
                    dist_km, az_deg = da
                    self._dx_distance_km = dist_km
                    self._dx_azimuth_deg = az_deg
                    dist_az_txt = f"{dist_km:.0f} km / {az_deg:.0f}°"
                    try:
                        if hasattr(self, 'dx_direction_lbl'):
                            self.dx_direction_lbl.setText(f"🧭 {dist_km:.0f} km / {az_deg:.0f}°")
                            self.dx_direction_lbl.setToolTip(
                                f"{my_grid} → {locator} : {dist_km:.0f} km, azimut {az_deg:.0f}° depuis le Nord vrai"
                            )
                    except Exception:
                        pass
                    if hasattr(self, '_call_history'):
                        rec = self._call_history.setdefault(base_call, {})
                        rec['distance_km'] = dist_km
                        rec['azimuth_deg'] = az_deg
        except Exception:
            pass
        if not dist_az_txt:
            try:
                self._dx_distance_km = None
                self._dx_azimuth_deg = None
                if hasattr(self, 'dx_direction_lbl'):
                    self.dx_direction_lbl.setText("🧭 -- km / ---°")
                    self.dx_direction_lbl.setToolTip("Distance/azimut indisponibles : locator OM ou locator station manquant.")
            except Exception:
                pass
        details = ' — '.join(x for x in (name, qth, locator, dist_az_txt) if x)
        try:
            if hasattr(self, 'dx_lookup_btn'):
                self.dx_lookup_btn.setEnabled(True)
        except Exception:
            pass
        if name:
            self._set_dx_lookup_state(f"✅ {name} · {source}", 'ok')
            self._set_status(f"✅ {call} trouvé via {source} : {details}" if details else f"✅ {call} trouvé via {source}")
        elif (data or {}).get('name_missing'):
            cfg = getattr(self, '_logbook_settings', {}) or {}
            has_hamqth = bool(str(cfg.get('hamqth_user') or '').strip() and str(cfg.get('hamqth_password') or '').strip())
            self._set_dx_lookup_state("Terminé : aucun prénom public", 'none')
            extra = ' — '.join(x for x in (qth, locator, dist_az_txt) if x)
            if has_hamqth:
                self._set_status(f"🌐 {call} trouvé via {source}, mais prénom non publié" + (f" — {extra}" if extra else ''))
            else:
                self._set_status(f"🌐 {call} : aucun prénom public trouvé après HamDB, Callook, QRZ et QRZCQ. HamQTH reste conseillé.")
        else:
            # Résultat partiel sans prénom et sans drapeau explicite.
            # L'ancienne version utilisait ici une variable `error` inexistante,
            # ce qui interrompait silencieusement la mise à jour du prénom.
            self._set_dx_lookup_state("Terminé : aucun prénom", 'none')
            self._set_status(f"🌐 {call} : annuaire interrogé, mais aucun prénom n'a été retourné")
        try:
            self.dx_name_edit.setPlaceholderText("Prénom auto…")
        except Exception:
            pass

    def _on_dx_lookup_error(self, call, error):
        self._dx_lookup_last_requested = ''
        try:
            self.dx_name_edit.setPlaceholderText("Prénom OM…")
            if hasattr(self, 'dx_lookup_btn'):
                self.dx_lookup_btn.setEnabled(True)
        except Exception:
            pass
        raw_error = str(error or '').replace('RuntimeError:', '').strip()
        errtxt = raw_error.lower()
        if any(x in errtxt for x in ('timed out', 'timeout', 'urlopen', 'network', 'name resolution', 'ssl', 'certificate')):
            self._set_dx_lookup_state("❌ Erreur Internet", 'error')
            self._set_status(f"❌ Recherche {call} : connexion Internet indisponible")
        elif any(x in errtxt for x in ('qrz xml', 'password', 'username', 'subscription', 'not authorized', 'invalid login', 'connexion refusée')):
            self._set_dx_lookup_state("❌ QRZ XML refusé", 'error')
            self._set_status(f"❌ Recherche {call} : {raw_error[:260]}")
        elif raw_error:
            self._set_dx_lookup_state("Terminé : aucun prénom", 'none')
            self._set_status(f"🌐 Recherche {call} : {raw_error[:240]}")
        else:
            self._set_dx_lookup_state("Terminé : aucun prénom", 'none')
            self._set_status(f"🌐 Recherche {call} terminée : prénom non trouvé")
        try:
            print(f"Recherche indicatif {call} ignorée: {error}")
        except Exception:
            pass

    def _clear_detected_dxcall(self):
        """Efface toute l'identité OM : indicatif + prénom + infos associées."""
        self._set_dx_lookup_state("Internet : en attente", 'idle')
        try:
            if hasattr(self, 'dx_lookup_btn'):
                self.dx_lookup_btn.setEnabled(True)
        except Exception:
            pass
        try:
            self._last_dxcall = ""
            self._dx_name = ""
            self._dx_qth = ""
            self._dx_locator = ""
            self._dx_distance_km = None
            self._dx_azimuth_deg = None
            self._dx_lookup_auto_name = ""
            self._dx_lookup_last_requested = ""
            self._rx_word_buf = ""
        except Exception:
            pass
        try:
            self.detected_call_lbl.setText("CALL actif : --")
        except Exception:
            pass
        try:
            if hasattr(self, 'dx_direction_lbl'):
                self.dx_direction_lbl.setText("🧭 -- km / ---°")
                self.dx_direction_lbl.setToolTip("Distance/azimut en attente d'un locator OM.")
        except Exception:
            pass
        try:
            self.dx_call_combo.blockSignals(True)
            self.dx_call_combo.lineEdit().clear()
            self.dx_call_combo.setCurrentText("")
            self.dx_call_combo.blockSignals(False)
        except Exception:
            pass
        try:
            if hasattr(self, 'dx_name_edit'):
                self.dx_name_edit.blockSignals(True)
                self.dx_name_edit.clear()
                self.dx_name_edit.blockSignals(False)
        except Exception:
            pass
        # Nettoyer aussi les champs log liés à l'OM si présents.
        try:
            for attr in ('log_call', 'log_name', 'log_qth', 'log_locator', 'log_loc'):
                w = getattr(self, attr, None)
                if w is not None and hasattr(w, 'clear'):
                    w.clear()
        except Exception:
            pass
        self._set_status("🧹 OM effacé : indicatif + prénom + infos")


    def _translate_tx_text_now(self):
        """Traduit le texte déjà écrit dans TX puis remplace vraiment la zone TX.

        Contrairement au mode micro, on ne fait pas d'insertion à la fin :
        l'utilisateur écrit en français, clique TRADUIRE TEXTE -> TX, puis la
        zone d'émission devient directement la version traduite.
        """
        # Le suivi couleur/barré doit fonctionner aussi en TEST TX.
        # Le texte de test est affiché temporairement dans tx_text puis restauré à la fin.
        if not hasattr(self, 'tx_text') or self.tx_text is None:
            return
        text = self.tx_text.toPlainText().strip()
        if not text:
            self._on_language_status("⚠️ Aucun texte TX à traduire")
            return
        if self.tx_lang_thread is not None and self.tx_lang_thread.isRunning():
            self._on_language_status("⏳ Traduction TX déjà en cours...")
            return
        src = self.lang_src_combo.currentData() if hasattr(self, 'lang_src_combo') else 'fr-FR'
        dst = self.lang_dst_combo.currentData() if hasattr(self, 'lang_dst_combo') else 'en'
        self._on_language_status("🌍 Traduction du texte TX en cours...")
        if hasattr(self, 'btn_translate_text_tx'):
            self.btn_translate_text_tx.setEnabled(False)
        self.tx_lang_thread = RxTranslateThread(text, src, dst)
        self.tx_lang_thread.translated.connect(self._on_tx_text_translated_replace)
        self.tx_lang_thread.status.connect(self._on_language_status)
        self.tx_lang_thread.error.connect(self._on_tx_text_translate_error)
        self.tx_lang_thread.finished.connect(self._on_tx_text_translate_finished)
        self.tx_lang_thread.start()

    def _on_tx_text_translated_replace(self, translated):
        translated = (translated or '').strip()
        if not translated:
            self._on_language_status("❌ Traduction TX vide")
            return
        # Protection : si la lib renvoie exactement le même texte, on l'indique.
        old = self.tx_text.toPlainText().strip() if hasattr(self, 'tx_text') else ''
        self.tx_text.blockSignals(True)
        self.tx_text.setPlainText(translated)
        self.tx_text.moveCursor(QTextCursor.End)
        self.tx_text.blockSignals(False)
        self._update_preview()
        if old and translated.strip().lower() == old.strip().lower():
            self._on_language_status("⚠️ Texte TX inchangé : vérifie langue source/destination ou Internet/deep-translator")
        else:
            self._on_language_status("✅ Texte TX traduit et remplacé dans la zone d'émission")
        try:
            self.tx_text.setFocus()
        except Exception:
            pass

    def _on_tx_text_translate_error(self, err):
        msg = "❌ Traduction texte TX impossible : " + str(err)
        self._on_language_status(msg)
        try:
            QMessageBox.warning(self, "Traduction TX", msg + "\n\nÀ installer si besoin :\npip install deep-translator")
        except Exception:
            pass

    def _on_tx_text_translate_finished(self):
        if hasattr(self, 'btn_translate_text_tx'):
            self.btn_translate_text_tx.setEnabled(True)

    def _start_language_decoder(self):
        """Démarre la reconnaissance depuis les réglages intégrés au programme.
        V1.6.29 : plus de fenêtre intermédiaire. Le choix du micro/langues se fait
        directement dans le panneau principal Décodeur de langues.
        """
        if self.lang_thread is not None and self.lang_thread.isRunning():
            return

        # Vérification claire AVANT de lancer l'écoute, pour éviter une popup vide.
        try:
            import speech_recognition  # noqa: F401
        except Exception:
            msg = "❌ Module SpeechRecognition absent — installe : pip install SpeechRecognition deep-translator"
            self._on_language_status(msg)
            try:
                QMessageBox.warning(self, "Décodeur de langues", msg)
            except Exception:
                pass
            return

        src = self.lang_src_combo.currentData() if hasattr(self, 'lang_src_combo') else 'fr-FR'
        dst = self.lang_dst_combo.currentData() if hasattr(self, 'lang_dst_combo') else 'en'
        mic = self.lang_mic_combo.currentData() if hasattr(self, 'lang_mic_combo') else None
        if mic is not None:
            try:
                mic = int(mic)
            except Exception:
                mic = None

        mic_name = self.lang_mic_combo.currentText() if hasattr(self, 'lang_mic_combo') else 'Windows par défaut'
        self._on_language_status(f"🎙️ Écoute intégrée sur : {mic_name} — parlez maintenant...")

        self.lang_thread = SpeechTranslateThread(src, dst, mic)
        self.lang_thread.status.connect(self._on_language_status)
        self.lang_thread.recognized.connect(self._on_language_recognized)
        self.lang_thread.translated.connect(self._on_language_translated)
        self.lang_thread.error.connect(self._on_language_error)
        self.lang_thread.finished.connect(self._on_language_finished)
        if hasattr(self, 'btn_lang_listen'):
            self.btn_lang_listen.setEnabled(False)
        if hasattr(self, 'btn_lang_stop'):
            self.btn_lang_stop.setEnabled(True)
        self.lang_thread.start()

    def _test_language_microphone(self):
        """Petit test du micro sélectionné : affiche le dBFS moyen sans traduire."""
        mic = self.lang_mic_combo.currentData() if hasattr(self, 'lang_mic_combo') else None
        if mic is not None:
            try:
                mic = int(mic)
            except Exception:
                mic = None
        try:
            import pyaudio, audioop, math, time as _time
            pa = pyaudio.PyAudio()
            rate = 16000
            kwargs = dict(format=pyaudio.paInt16, channels=1, rate=rate, input=True, frames_per_buffer=1024)
            if mic is not None:
                kwargs['input_device_index'] = mic
            stream = pa.open(**kwargs)
            vals = []
            t0 = _time.time()
            while _time.time() - t0 < 1.0:
                data = stream.read(1024, exception_on_overflow=False)
                rms = max(1, audioop.rms(data, 2))
                dbfs = 20.0 * math.log10(rms / 32768.0)
                vals.append(dbfs)
            stream.stop_stream(); stream.close(); pa.terminate()
            avg = sum(vals) / max(1, len(vals))
            self._on_language_status(f"🎚️ Test micro : {avg:.1f} dBFS — parle plus près si < -45 dBFS")
        except Exception as e:
            self._on_language_status("❌ Test micro impossible : " + str(e))

    def _stop_language_decoder(self):
        if self.lang_thread is not None:
            try:
                self.lang_thread.abort()
            except Exception:
                pass
        self._on_language_status("⏹️ Arrêt demandé")

    def _on_language_status(self, msg):
        if hasattr(self, 'lang_status_lbl'):
            self.lang_status_lbl.setText(str(msg))
            self.lang_status_lbl.setStyleSheet("color:#88ccff;font-family:'Courier New';font-size:9pt;")
        try:
            self._set_status(str(msg))
        except Exception:
            pass

    def _on_language_recognized(self, text):
        if hasattr(self, 'lang_status_lbl'):
            self.lang_status_lbl.setText("Reconnu : " + str(text))

    def _on_language_translated(self, text):
        text = (text or '').strip()
        if not text or not hasattr(self, 'tx_text'):
            return
        cur = self.tx_text.textCursor()
        cur.movePosition(QTextCursor.End)
        existing = self.tx_text.toPlainText()
        prefix = "" if (not existing or existing.endswith((' ', '\n'))) else " "
        cur.insertText(prefix + text.upper())
        self.tx_text.setTextCursor(cur)
        self.tx_text.setFocus()
        self._update_preview()

    def _on_language_error(self, err):
        err_txt = str(err)
        if 'timed out' in err_txt.lower():
            err_txt += " — vérifie le micro choisi, parle plus près, ou clique sur 🔄 puis sélectionne la bonne entrée."
        msg = "❌ Décodeur langues : " + err_txt
        if hasattr(self, 'lang_status_lbl'):
            self.lang_status_lbl.setText(msg)
            self.lang_status_lbl.setStyleSheet("color:#ff7777;font-family:'Courier New';font-size:9pt;")
        try:
            QMessageBox.warning(self, "Décodeur de langues", msg + "\n\nÀ installer si besoin :\npip install SpeechRecognition deep-translator")
        except Exception:
            pass

    def _on_language_finished(self):
        if hasattr(self, 'btn_lang_listen'):
            self.btn_lang_listen.setEnabled(True)
        if hasattr(self, 'btn_lang_stop'):
            self.btn_lang_stop.setEnabled(False)


    # ── Traducteur RX ───────────────────────────────────────────────────────

    # ── Langage radio / PSK pour traduction RX ───────────────────────────────
    def _radio_join_callsigns(self, txt):
        """Reconstruit quelques indicatifs quand le décodeur a mis des espaces.
        Exemple : F 4 L P S -> F4LPS, D L 1 A B C -> DL1ABC.
        """
        import re as _re
        def repl(m):
            return m.group(0).replace(' ', '')
        # Groupes courts contenant au moins un chiffre, typiques d'un indicatif.
        pat = r'\b(?:[A-Z]{1,2}\s+){1,3}[0-9]\s+(?:[A-Z]\s*){1,4}\b'
        return _re.sub(pat, repl, txt)

    def _radio_nato_to_letters(self, txt):
        """Transforme l'alphabet international en lettres pour les appels.
        alpha bravo charlie -> A B C. On le fait avant traduction pour éviter que
        le traducteur transforme les mots radio en mots ordinaires.
        """
        import re as _re
        nato = {
            'ALFA':'A','ALPHA':'A','BRAVO':'B','CHARLIE':'C','DELTA':'D','ECHO':'E','FOXTROT':'F',
            'GOLF':'G','HOTEL':'H','INDIA':'I','JULIET':'J','JULIETT':'J','KILO':'K','LIMA':'L',
            'MIKE':'M','NOVEMBER':'N','OSCAR':'O','PAPA':'P','QUEBEC':'Q','ROMEO':'R','SIERRA':'S',
            'TANGO':'T','UNIFORM':'U','VICTOR':'V','WHISKEY':'W','XRAY':'X','X-RAY':'X','YANKEE':'Y','ZULU':'Z'
        }
        def repl(m):
            return nato.get(m.group(0).upper(), m.group(0))
        return _re.sub(r'\b(' + '|'.join(map(_re.escape, sorted(nato, key=len, reverse=True))) + r')\b', repl, txt, flags=_re.I)

    def _radio_spacing_cleanup(self, txt):
        """Nettoyage doux des espaces PSK avant traduction.
        Ne modifie pas le décodeur : seulement le bloc envoyé au traducteur RX.
        """
        import re as _re
        txt = str(txt or '').replace('\r', ' ')
        txt = _re.sub(r'[\t\n]+', ' ', txt)
        txt = _re.sub(r'\s+', ' ', txt).strip()
        # Sépare les mots radio collés courants sans casser les indicatifs.
        for tok in ('CQ','DE','K','KN','PSE','PLEASE','RST','QTH','QRA','NAME','OP','UR','HW','BTU','TU','TNX','TKS','73','88','599','CQDX'):
            txt = _re.sub(r'(?<![A-Z0-9])' + _re.escape(tok) + r'(?![A-Z0-9])', ' ' + tok + ' ', txt, flags=_re.I)
        txt = _re.sub(r'\s+', ' ', txt).strip()
        txt = self._radio_nato_to_letters(txt)
        txt = self._radio_join_callsigns(txt.upper())
        return txt

    def _radio_expand_for_translation(self, txt):
        """Ajoute le sens des abréviations radio pour améliorer la traduction.
        Le texte RX original à gauche reste inchangé ; seul le texte envoyé au
        traducteur est enrichi.
        """
        import re as _re
        txt = self._radio_spacing_cleanup(txt)
        glossary = {
            'CQ': 'appel général CQ',
            'CQDX': 'appel général longue distance CQ DX',
            'DE': 'de',
            'K': 'à vous',
            'KN': 'à vous seulement',
            'PSE': 's’il vous plaît',
            'PLS': 's’il vous plaît',
            'RST': 'report RST',
            'QTH': 'position géographique QTH',
            'QRA': 'nom de la station QRA',
            'QRM': 'brouillage QRM',
            'QRN': 'parasites atmosphériques QRN',
            'QSB': 'fading QSB',
            'QSL': 'confirmation QSL',
            'QRZ': 'qui m’appelle QRZ',
            'NAME': 'prénom',
            'OP': 'opérateur',
            'UR': 'votre',
            'HW': 'comment recevez-vous',
            'BTU': 'retour à vous',
            'TU': 'merci',
            'TNX': 'merci',
            'TKS': 'merci',
            'FB': 'très bien',
            'FER': 'pour',
            'AGN': 'encore',
            'WX': 'météo',
            'RIG': 'poste radio',
            'ANT': 'antenne',
            'PWR': 'puissance',
            'W': 'watts',
            '599': 'report cinq neuf neuf',
            '73': 'salutations amicales',
            '88': 'amitiés affectueuses'
        }
        # Remplace seulement les tokens isolés, pas l'intérieur des indicatifs.
        def repl(m):
            key = m.group(0).upper()
            return glossary.get(key, m.group(0))
        pat = r'\b(' + '|'.join(map(_re.escape, sorted(glossary, key=len, reverse=True))) + r')\b'
        txt = _re.sub(pat, repl, txt, flags=_re.I)
        # RST compact : 599, 579...
        txt = _re.sub(r'\b([1-5][1-9][1-9])\b', r'report RST \1', txt)
        return txt

    def _feed_rx_translator(self, text):
        """Ajoute le texte RX dans un petit tampon et traduit après une pause.
        Important : le RX original reste intact à gauche. La traduction travaille
        seulement sur des blocs suffisamment longs pour éviter de traduire lettre
        par lettre pendant le décodage PSK.
        """
        try:
            if not hasattr(self, 'rx_translate_enable') or not self.rx_translate_enable.isChecked():
                return
            t = str(text or '')
            if not t.strip():
                return
            self._rx_translate_buf += t
            # On attend que le texte se calme un peu avant de traduire.
            # Cela évite de bloquer sur chaque caractère reçu.
            self._rx_translate_timer.start(1800)
        except Exception:
            pass

    def _rx_translation_is_probably_text(self, txt):
        """Filtre doux : ne pas envoyer du charabia pur au traducteur.
        Le RX brut reste affiché à gauche ; on filtre seulement la copie envoyée
        à la traduction pour éviter les blocs incompréhensibles.
        """
        try:
            s = str(txt or '').strip()
            if len(s) < 6:
                return False
            letters = sum(1 for c in s if c.isalpha())
            spaces = s.count(' ')
            bad = sum(1 for c in s if not (c.isalnum() or c in " /?.,;:-_+=()[]{}'!\n\t"))
            # Accepte les petits bouts radio même courts : CQ, DE, 73, RST, QTH...
            if re.search(r'\b(CQ|DE|RST|QTH|QSL|QSO|PSE|TU|TNX|73|88|[A-Z]{1,3}[0-9][A-Z0-9]{1,4})\b', s.upper()):
                return True
            if letters < max(4, len(s) * 0.25):
                return False
            if bad > max(2, len(s) * 0.18):
                return False
            if len(s) > 18 and spaces == 0 and not re.search(r'\d', s):
                return False
            return True
        except Exception:
            return True

    def _rx_prepare_text_for_translation(self, txt):
        """Nettoyage léger avant traduction RX.
        Correction V1.6.48 : on ne force plus tout en MAJUSCULES et on
        n'expanse plus agressivement les abréviations ; cela déformait trop
        le texte et la traduction française devenait mauvaise.
        """
        try:
            s = str(txt or '').replace('\r', ' ').replace('\n', ' ')
            s = re.sub(r'\s+', ' ', s).strip()
            if not s:
                return ''
            # Reconstruit seulement les indicatifs espacés, sans changer le reste.
            try:
                s = self._radio_join_callsigns(s.upper()) if s.isupper() else self._radio_join_callsigns(s)
            except Exception:
                pass
            # Garde les termes radio lisibles pour le traducteur, mais sans tout remplacer.
            soft = {
                'QTH': 'QTH localisation', 'QRM': 'QRM brouillage',
                'QRN': 'QRN parasites', 'QSB': 'QSB fading',
                'QSL': 'QSL confirmation', 'RST': 'RST rapport',
                'PSE': 's’il vous plaît', 'TU': 'merci', 'TNX': 'merci',
                '73': '73 salutations'
            }
            if hasattr(self, 'rx_radio_language_enable') and self.rx_radio_language_enable.isChecked():
                def repl(m):
                    w = m.group(0).upper()
                    return soft.get(w, m.group(0))
                pat = r'\b(' + '|'.join(map(re.escape, sorted(soft, key=len, reverse=True))) + r')\b'
                s = re.sub(pat, repl, s, flags=re.I)
            return re.sub(r'\s+', ' ', s).strip()
        except Exception:
            return str(txt or '').strip()

    def _translate_rx_pending(self):
        try:
            if not hasattr(self, 'rx_translate_enable') or not self.rx_translate_enable.isChecked():
                return
            txt = (self._rx_translate_buf or '').strip()
            self._rx_translate_buf = ''
            txt = self._rx_prepare_text_for_translation(txt)
            if not self._rx_translation_is_probably_text(txt):
                return
            # Évite d'envoyer un énorme bloc charabia : traduction par bloc court.
            txt = txt[-650:]
            if len(txt) < 6:
                return
            if self.rx_lang_thread is not None and self.rx_lang_thread.isRunning():
                self._rx_translate_buf = txt + ' ' + self._rx_translate_buf
                self._rx_translate_timer.start(2400)
                return
            dst = self.rx_translate_dst.currentData() if hasattr(self, 'rx_translate_dst') else 'fr'
            self.rx_lang_thread = RxTranslateThread(txt, 'auto', dst)
            self.rx_lang_thread.translated.connect(self._on_rx_translated)
            self.rx_lang_thread.status.connect(self._on_rx_translate_status)
            self.rx_lang_thread.error.connect(self._on_rx_translate_error)
            self.rx_lang_thread.start()
        except Exception as e:
            self._on_rx_translate_error(str(e))

    def _on_rx_translated(self, text):
        try:
            if not hasattr(self, 'rx_translated_view'):
                return
            cur = self.rx_translated_view.textCursor()
            cur.movePosition(QTextCursor.End)
            if self.rx_translated_view.toPlainText().strip():
                cur.insertText('\n')
            cur.insertText(str(text).strip())
            self.rx_translated_view.setTextCursor(cur)
            self.rx_translated_view.ensureCursorVisible()
        except Exception:
            pass

    def _on_rx_translate_toggled(self, checked):
        """V8.4 F4LPS : affiche/masque le panneau de traduction RX à la demande."""
        try:
            if hasattr(self, '_rx_translate_panel'):
                self._rx_translate_panel.setVisible(bool(checked))
            if hasattr(self, '_rx_split'):
                if checked:
                    self._rx_split.setSizes([420, 420, 420])
                else:
                    self._rx_split.setSizes([620, 0, 620])
            if not checked:
                self._rx_translate_buf = ''
        except Exception:
            pass

    def _on_rx_translate_status(self, msg):
        try:
            self._set_status(str(msg))
        except Exception:
            pass

    def _on_rx_translate_error(self, err):
        try:
            self._set_status('❌ Traduction RX : ' + str(err))
        except Exception:
            pass

    # ── TX ───────────────────────────────────────────────────────────────────


    def _f4lps_guess_psk_mode_from_last_spectrum(self):
        """Retourne BPSK31/63/125 d'après le dernier spectre waterfall déjà calculé.

        Aucun calcul lourd : on réutilise le dernier spectre reçu par _on_spectrum.
        Sert surtout après un burst RSID, pour éviter d'afficher/appliquer le mode
        précédent. Corrige le cas BPSK31 vu comme BPSK63.
        """
        try:
            mag = getattr(self, '_last_spectrum_mag_for_mode', None)
            sr = float(getattr(self, '_last_spectrum_sr_for_mode', 0.0) or 0.0)
            if mag is None or sr <= 0:
                return None, 0.0
            a = np.asarray(mag, dtype=np.float64).flatten()
            if a.size < 128:
                return None, 0.0
            center = float(self.center_freq_spin.value())
            freqs = np.linspace(0.0, sr / 2.0, a.size, endpoint=True)
            mask = (freqs >= center - 220.0) & (freqs <= center + 220.0)
            if np.count_nonzero(mask) < 8:
                return None, 0.0
            f = freqs[mask]
            v = a[mask]
            noise = float(np.percentile(v, 35))
            peak = float(np.max(v))
            if peak - noise < 5.0:
                return None, 0.0
            thr = noise + 0.38 * (peak - noise)
            hot = f[v >= thr]
            if hot.size < 2:
                return None, 0.0
            width = float(np.percentile(hot, 90) - np.percentile(hot, 10))
            if width <= 78.0:
                return 'BPSK31', width
            if width <= 155.0:
                return 'BPSK63', width
            return 'BPSK125', width
        except Exception:
            return None, 0.0


    def _f4lps_guess_digital_mode_from_last_spectrum(self, target_freq_hz=None):
        """Classe passivement le signal utile après le burst RSID.

        V1.6.153 : évite de confondre Olivia 8/250 avec du RTTY. Un signal
        Olivia peut ne montrer que 2 à 4 pics forts sur une image instantanée,
        alors que ses autres tons restent visibles plus bas. On mesure donc aussi
        les groupes occupés à un seuil plus bas. Le RTTY n'est annoncé que si deux
        porteuses étroites et réellement dominantes sont présentes.
        """
        try:
            mag = getattr(self, '_last_spectrum_mag_for_mode', None)
            sr = float(getattr(self, '_last_spectrum_sr_for_mode', 0.0) or 0.0)
            if mag is None or sr <= 0:
                return '', 0.0, 0
            a = np.asarray(mag, dtype=np.float64).flatten()
            if a.size < 128:
                return '', 0.0, 0
            freqs = np.linspace(0.0, sr / 2.0, a.size, endpoint=True)
            center = float(target_freq_hz or 0.0)
            if center <= 0.0:
                center = float(self.center_freq_spin.value()) if hasattr(self, 'center_freq_spin') else 1500.0
            # Analyser autour de la fréquence du burst RSID reçu, pas autour du centre PSK.
            # Sinon un Olivia vers 1850/2000 Hz est mélangé au bruit de toute la bande
            # et sa largeur est faussement estimée à 1000 ou 2000 Hz.
            half_window = 430.0
            mask = (freqs >= max(80.0, center - half_window)) & (freqs <= min(3000.0, center + half_window))
            f = freqs[mask]; v = a[mask]
            if v.size < 16:
                return '', 0.0, 0
            noise = float(np.percentile(v, 40))
            peak = float(np.max(v))
            dyn = peak - noise
            if dyn < 5.0:
                return '', 0.0, 0

            # V1.6.139 : cœur très fort autour de la porteuse. Le seuil bas peut être
            # élargi par le bruit et faire croire à une bande de plusieurs centaines de Hz.
            # Le cœur haut reste fiable pour distinguer PSK31/63/125.
            core_thr = noise + 0.72 * dyn
            core_f = f[v >= core_thr]
            core_width = float(np.percentile(core_f, 92) - np.percentile(core_f, 8)) if core_f.size > 1 else 0.0

            # Seuil haut : pics dominants. Seuil bas : tons secondaires Olivia/MFSK.
            thr_hi = noise + 0.55 * dyn
            thr_lo = noise + 0.24 * dyn
            hf = f[v >= thr_lo]
            if hf.size < 1:
                return '', 0.0, 0
            width = float(np.percentile(hf, 96) - np.percentile(hf, 4)) if hf.size > 1 else 0.0

            def _merged_local_peaks(thr, min_gap_hz=7.0, limit=80):
                idx = np.where((v[1:-1] > v[:-2]) & (v[1:-1] >= v[2:]) & (v[1:-1] >= thr))[0] + 1
                raw = sorted([(float(v[i]), float(f[i])) for i in idx], reverse=True)[:limit]
                pf = sorted(x[1] for x in raw)
                merged = []
                for x in pf:
                    if not merged or x - merged[-1] > min_gap_hz:
                        merged.append(x)
                    else:
                        merged[-1] = (merged[-1] + x) / 2.0
                return merged

            peaks_hi = _merged_local_peaks(thr_hi, 8.0, 40)
            peaks_lo = _merged_local_peaks(thr_lo, 6.0, 100)
            n_hi = len(peaks_hi)
            n_lo = len(peaks_lo)
            spac_hi = np.diff(peaks_hi) if n_hi >= 2 else np.asarray([])
            medsp = float(np.median(np.diff(peaks_lo))) if n_lo >= 2 else 0.0

            # Occupation spectrale : Olivia remplit plusieurs petites zones dans sa bande,
            # contrairement au RTTY qui reste essentiellement sur deux raies.
            occ = (v >= thr_lo)
            groups = []
            st = None
            for i, on in enumerate(occ):
                if on and st is None:
                    st = i
                elif (not on) and st is not None:
                    if i - st >= 1:
                        groups.append((st, i - 1))
                    st = None
            if st is not None:
                groups.append((st, len(occ) - 1))
            group_centers = [float((f[a0] + f[b0]) * 0.5) for a0, b0 in groups]
            # fusion de groupes séparés de moins de 5 Hz
            merged_groups = []
            for x in group_centers:
                if not merged_groups or x - merged_groups[-1] > 5.0:
                    merged_groups.append(x)
                else:
                    merged_groups[-1] = (merged_groups[-1] + x) / 2.0
            ngroup = len(merged_groups)
            occupancy = float(np.count_nonzero(occ)) / float(max(1, occ.size))

            # Olivia / Contestia d'abord : plusieurs tons, même si seulement quelques-uns
            # dépassent le seuil haut sur l'instant. Cas visé : Olivia 8/250.
            # Olivia 8/250 présente typiquement 8 tons espacés d'environ 31,25 Hz.
            olivia_8_250_shape = (
                5 <= max(n_lo, ngroup) <= 14
                and 18.0 <= medsp <= 46.0
                and 150.0 <= width <= 430.0
            )
            if olivia_8_250_shape:
                return 'OLIVIA 8/250', width, max(n_lo, ngroup)

            multitone = (n_lo >= 5 or ngroup >= 5 or (occupancy >= 0.055 and width >= 170.0))
            if multitone and 170.0 <= width <= 2300.0:
                bw_choices = [250, 500, 1000, 2000]
                bw = min(bw_choices, key=lambda b: abs(width - b))
                tone_measure = max(n_lo, ngroup)
                tones = min([4, 8, 16, 32, 64], key=lambda n: abs(n - tone_measure))
                # Sur 180..360 Hz avec plusieurs groupes, Olivia 8/250 est de loin
                # le cas le plus fréquent et correspond au signal de test F4LPS.
                if 180.0 <= width <= 360.0 and 5 <= tone_measure <= 13:
                    tones, bw = 8, 250
                return f'OLIVIA {tones}/{bw}', width, tone_measure

            # RTTY : exiger exactement deux raies dominantes, étroites, et peu
            # d'occupation ailleurs. Cela empêche Olivia d'être pris pour du RTTY.
            if n_hi == 2 and spac_hi.size == 1 and occupancy < 0.055 and ngroup <= 4:
                sep = float(spac_hi[0])
                if 135.0 <= sep <= 205.0 and 120.0 <= width <= 260.0:
                    return 'RTTY 45/170', width, n_hi
                if 760.0 <= sep <= 920.0 and width >= 650.0:
                    return 'RTTY 75/850', width, n_hi
                return 'RTTY', width, n_hi

            # DominoEX / MFSK : plusieurs tons mais bande plus étroite.
            if n_lo >= 4 and 35.0 <= width < 220.0:
                if 10.0 <= medsp <= 28.0:
                    return 'DOMINOEX', width, n_lo
                return 'MFSK', width, n_lo

            # PSK : une porteuse compacte. Priorité au cœur haut, moins sensible
            # au bruit de fond que la largeur calculée au seuil bas.
            if core_f.size >= 1 and core_width <= 145.0 and n_hi <= 9:
                measure = core_width if core_width > 2.0 else width
                if measure <= 38.0:
                    return 'BPSK31', measure, n_hi
                if measure <= 82.0:
                    return 'BPSK63', measure, n_hi
                return 'BPSK125', measure, n_hi
            if width <= 115.0 and n_hi <= 6:
                if width <= 42.0:
                    return 'BPSK31', width, n_hi
                if width <= 82.0:
                    return 'BPSK63', width, n_hi
                return 'BPSK125', width, n_hi

            return 'MODE NUMÉRIQUE', width, max(n_lo, ngroup)
        except Exception:
            return '', 0.0, 0

    def _finalize_rsid_audio_mode(self):
        """Finalise le RSID par vote sur plusieurs spectres après le burst.

        V1.6.139 : le RSID précède les données. On observe jusqu'à cinq fois le
        signal utile, puis on retient le mode reconnu le plus souvent. Aucun mode
        n'est changé automatiquement : l'analyse reste passive et ne reset pas RX.
        """
        try:
            p = getattr(self, '_rsid_pending_audio', None)
            if not p:
                return
            label, freq_hz, score, detected_at = p
            if not self._rsid_rx_enabled() or not getattr(self, '_rx_active', False):
                self._rsid_pending_audio = None
                return
            if getattr(self, '_tx_active', False):
                return

            attempt = int(getattr(self, '_rsid_mode_attempt', 0) or 0) + 1
            self._rsid_mode_attempt = attempt
            # V2.1.5 : le RSID peut annoncer n'importe quel mode numérique.
            # On utilise donc le classificateur multimode déjà intégré :
            # PSK, Olivia, RTTY, DominoEX, MFSK...
            guessed_mode, guessed_width, guessed_peaks = (
                self._f4lps_guess_digital_mode_from_last_spectrum(
                    target_freq_hz=float(freq_hz)
                )
            )

            # Si le classificateur général reste indécis sur une porteuse compacte,
            # compléter avec le mesureur PSK spécialisé.
            gm0 = str(guessed_mode or '').strip().upper()
            if not gm0 or gm0 in (
                'MODE NUMÉRIQUE', 'MODE NUMERIQUE',
                'MODE NUMÉRIQUE INCONNU'
            ):
                psk_mode, psk_width = self._f4lps_guess_psk_mode_from_last_spectrum()
                if psk_mode:
                    guessed_mode = psk_mode
                    guessed_width = psk_width
                    guessed_peaks = 1
            gm = str(guessed_mode or '').strip()
            if gm and gm not in ('MODE NUMÉRIQUE', 'MODE NUMERIQUE', 'MODE NUMÉRIQUE INCONNU'):
                votes = list(getattr(self, '_rsid_mode_votes', []) or [])
                votes.append((gm, float(guessed_width or 0.0), int(guessed_peaks or 0)))
                self._rsid_mode_votes = votes

            votes = list(getattr(self, '_rsid_mode_votes', []) or [])
            # Attendre au moins 3 observations, ou terminer plus tôt si deux votes concordent.
            counts = {}
            for m, w, n in votes:
                counts[m] = counts.get(m, 0) + 1
            best_mode = max(counts, key=counts.get) if counts else ''
            best_count = counts.get(best_mode, 0) if best_mode else 0
            finished = (attempt >= 6) or (attempt >= 3 and best_count >= 2)
            if not finished:
                try:
                    self._set_status(f'RSID détecté à {float(freq_hz):.0f} Hz — identification du mode {attempt}/6…')
                except Exception:
                    pass
                QTimer.singleShot(850, self._finalize_rsid_audio_mode)
                return

            self._rsid_pending_audio = None
            details = ', '.join(
                f'{k}×{v}' for k, v in sorted(counts.items(), key=lambda x: -x[1])
            )

            valid_psk_modes = {
                'BPSK31', 'QPSK31',
                'BPSK63', 'QPSK63',
                'BPSK125', 'QPSK125',
            }
            lab = _f4lps_rsid_label(best_mode) if best_mode else ''
            accepted = bool(lab and best_count >= 2)

            if accepted and lab in valid_psk_modes:
                # Mode pris en charge directement par MultiDigi :
                # on peut changer le décodeur automatiquement.
                previous_mode = ''
                try:
                    previous_mode = str(self.mode_combo.currentText() or '').strip()
                except Exception:
                    previous_mode = str(getattr(self, '_current_mode', '') or '').strip()

                changed = previous_mode != lab
                if changed:
                    self._apply_rsid_mode(lab)

                self._insert_rsid_line_dm780(
                    lab, freq_hz=float(freq_hz), force=True
                )
                try:
                    action = (
                        f'mode automatique {previous_mode} → {lab}'
                        if changed else f'mode confirmé {lab}'
                    )
                    self._set_status(
                        f'✓ RSID RX : {action} à {float(freq_hz):.0f} Hz'
                        + (f' — votes {details}' if details else '')
                    )
                except Exception:
                    pass

            elif accepted:
                # Olivia, RTTY, DominoEX, MFSK, etc. sont reconnus et affichés,
                # mais MultiDigi ne doit pas prétendre les décoder.
                self._insert_rsid_line_dm780(
                    lab, freq_hz=float(freq_hz), force=True
                )
                try:
                    self._set_status(
                        f'✓ RSID RX : {lab} détecté à {float(freq_hz):.0f} Hz'
                        + (f' — votes {details}' if details else '')
                        + ' — mode reconnu, décodeur PSK conservé'
                    )
                except Exception:
                    pass

            else:
                shown = f"{lab} probable" if lab else "mode non identifié"
                self._insert_rsid_line_dm780(
                    shown, freq_hz=float(freq_hz), force=True
                )
                try:
                    self._set_status(
                        f'RSID RX à {float(freq_hz):.0f} Hz : {shown}'
                        + (f' — votes {details}' if details else
                           ' — signal suivant insuffisant')
                        + ' — mode courant conservé'
                    )
                except Exception:
                    pass
        except Exception as e:
            try:
                self._rsid_pending_audio = None
                self._set_status(f'RSID : erreur identification mode : {e}')
            except Exception:
                pass

    # ── RSID texte F4LPS ─────────────────────────────────────────────────────
    def _rsid_current_mode_label(self):
        try:
            if hasattr(self, 'mode_combo'):
                return _f4lps_rsid_label(self.mode_combo.currentText())
        except Exception:
            pass
        try:
            return _f4lps_rsid_label(getattr(self, '_current_mode', ''))
        except Exception:
            return ''

    def _rsid_tx_enabled(self):
        try:
            cb = getattr(self, 'rsid_tx_cb', None)
            if cb is not None:
                return bool(cb.isChecked())
        except Exception:
            pass
        return True

    def _rsid_rx_enabled(self):
        try:
            cb = getattr(self, 'rsid_rx_cb', None)
            if cb is not None:
                return bool(cb.isChecked())
        except Exception:
            pass
        return True

    def _prepend_rsid_to_tx(self, text):
        text = str(text or '').strip()
        # JS8 est déjà identifié par sa synchronisation Costas et son sous-mode.
        # Un préfixe texte [RSID] devant une directive [JS8:HB]/[JS8:DIR...]
        # empêcherait le packer structuré de la reconnaître et ferait rejeter
        # le caractère '[' avant même toute commande PTT.
        # V8.4.1 F4LPS : le CW ne doit jamais recevoir de préfixe RSID (tonalité
        # numérique incongrue devant un message envoyé à l'oreille) — même
        # exclusion que JS8, qui s'identifie déjà par sa propre synchronisation.
        if getattr(self, '_family', '') in ('JS8', 'CW'):
            return text
        if not text or not self._rsid_tx_enabled():
            return text
        if re.search(r'\bRSID\b', text[:80], flags=re.IGNORECASE):
            return text
        label = self._rsid_current_mode_label()
        if not label:
            return text
        return f"[RSID] {label}\n" + text

    # ========================================================================
    # V0.7 F4LPS — RSID CLIQUABLE : bascule mode + fréquence
    # ========================================================================
    def _f4lps_rsid_family_and_mode(self, label):
        """Traduit un libellé RSID en (famille, variante) réellement gérées.

        _f4lps_rsid_to_mode() ne donnait que la variante, sans la famille. Or
        mode_combo n'est peuplé qu'avec les variantes de la famille COURANTE :
        recevoir « OLIVIA 8/250 » alors qu'on est en PSK ne changeait donc
        rien du tout. Il faut basculer family_combo d'abord.
        Retourne (None, None) si le mode n'est pas géré par MultiDigi.
        """
        mode = _f4lps_rsid_to_mode(label)
        if not mode:
            return None, None
        try:
            if mode in globals().get('OLIVIA_MODES', {}):
                return "OLIVIA", mode
            if mode in globals().get('CONTESTIA_MODES', {}):
                return "CONTESTIA", mode
            if mode in globals().get('DOMINOEX_MODES', {}):
                return "DOMINOEX", mode
            if mode in globals().get('PSK_MODES', {}):
                return "PSK", mode
            if str(mode).upper().startswith('RTTY'):
                names = globals().get('RTTY_MODE_NAMES', [])
                if not names:
                    return None, None
                # Le RSID donne parfois la vitesse : on prend la plus proche.
                mm = re.search(r'(\d+)', str(label))
                if mm:
                    want = float(mm.group(1))
                    best = min(names, key=lambda nm: abs(
                        float(re.search(r'(\d+)', nm).group(1)) - want))
                    return "RTTY", best
                return "RTTY", names[0]
        except Exception:
            pass
        return None, None

    def _f4lps_apply_rsid_click(self, label, freq_hz=None):
        """Applique un RSID : bascule la famille, la variante, puis le centre."""
        fam, mode = self._f4lps_rsid_family_and_mode(label)
        if not fam or not mode:
            try:
                self._set_status(f"RSID {label} : mode non géré par MultiDigi")
            except Exception:
                pass
            return False
        try:
            # 1) la famille EN PREMIER : elle repeuple mode_combo et
            #    reconstruit les décodeurs (et relance le RX au besoin).
            if hasattr(self, 'family_combo') and self.family_combo.currentText() != fam:
                self.family_combo.setCurrentText(fam)
            # 2) la variante. IMPORTANT RSID : ne pas dépendre uniquement du
            #    signal currentTextChanged de Qt. Selon le chemin de clic / restart RX,
            #    ce signal pouvait ne pas reconstruire immédiatement le décodeur :
            #    la fréquence changeait mais le modem restait dans l'ancien mode.
            mode_applied = False
            if hasattr(self, 'mode_combo'):
                dispo = [self.mode_combo.itemText(i)
                         for i in range(self.mode_combo.count())]
                if mode in dispo:
                    self.mode_combo.setCurrentText(mode)
                    mode_applied = (self.mode_combo.currentText() == mode)

            if not mode_applied:
                self._set_status(f"⚠️ RSID {label} : variante {mode} absente de {fam}")
                return False

            # Forcer explicitement le moteur sur la variante RSID, même si Qt n'a
            # pas émis currentTextChanged (ou si un changement de famille vient de
            # reconstruire les objets). C'est idempotent et garantit UI + RX + TX.
            self._family = fam
            self._current_mode = mode
            try:
                self._on_mode_changed(mode)
            except Exception:
                try:
                    if getattr(self, 'audio_thread', None) is not None:
                        self.audio_thread.set_mode(mode)
                    if getattr(self, 'decoder_obj', None) is not None:
                        self.decoder_obj.set_mode(mode)
                    if getattr(self, 'encoder_obj', None) is not None:
                        self.encoder_obj.set_mode(mode)
                except Exception:
                    pass

            # 3) la fréquence centrale
            if freq_hz:
                f = float(freq_hz)
                if 100.0 <= f <= 4000.0:
                    if hasattr(self, 'center_freq_spin'):
                        self.center_freq_spin.setValue(f)
                    for obj in (getattr(self, 'decoder_obj', None),
                                getattr(self, 'audio_thread', None),
                                getattr(self, 'waterfall', None)):
                        try:
                            if obj is not None:
                                obj.set_center_freq(f)
                        except Exception:
                            pass
            self._set_status(f"✓ RSID appliqué : {fam} / {mode}"
                             + (f" à {float(freq_hz):.0f} Hz" if freq_hz else ""))
            return True
        except Exception as e:
            try:
                self._set_status(f"⚠️ RSID non appliqué : {e}")
            except Exception:
                pass
            return False

    def _f4lps_rx_text_mouse_release(self, event):
        """Clic dans la zone RX : si on tombe sur une ligne RSID, on l'applique."""
        try:
            cur = self.rx_text.cursorForPosition(event.pos())
            cur.select(QTextCursor.BlockUnderCursor)
            ligne = cur.selectedText().replace('\u2029', ' ').strip()
            # L'invite « ← clic pour basculer » est retirée AVANT l'analyse :
            # ancrée en fin de ligne, elle empêchait la fréquence d'être
            # reconnue et le libellé absorbait le « f=1932Hz ».
            ligne = ligne.split('←')[0].strip()
            m = re.search(r'RSID\s*:\s*(.*?)(?:\s*f\s*=\s*'
                          r'([0-9]+(?:[.,][0-9]+)?)\s*Hz)?\s*$', ligne, re.I)
            if m:
                label = m.group(1).strip()
                fz = m.group(2)
                fz = float(str(fz).replace(',', '.')) if fz else None
                if label:
                    self._f4lps_apply_rsid_click(label, fz)
                    return

            # V8.3.11 F4LPS : clic SIMPLE sur un indicatif bleu = CALL actif
            # + envoi volontaire au MultiDigi Tracker. Aucune détection RX
            # automatique, macro ou journalisation ne passe par ce chemin.
            try:
                if event.button() == Qt.LeftButton:
                    if self._rx_use_call_from_mouse(event.pos(), copy_clipboard=True):
                        return
            except Exception:
                pass
        except Exception as e:
            try:
                print(f"⚠️ clic RSID ignoré : {e}")
            except Exception:
                pass
        try:
            QTextEdit.mouseReleaseEvent(self.rx_text, event)
        except Exception:
            pass

    def _apply_rsid_mode(self, label):
        mode = _f4lps_rsid_to_mode(label)
        if not mode:
            return False
        try:
            if hasattr(self, 'mode_combo') and mode in [self.mode_combo.itemText(i) for i in range(self.mode_combo.count())]:
                self.mode_combo.setCurrentText(mode)
        except Exception:
            pass
        try:
            if mode in globals().get('OLIVIA_MODES', {}) or mode in globals().get('DOMINOEX_MODES', {}) or mode in globals().get('PSK_MODES', {}):
                self._current_mode = mode
        except Exception:
            pass
        try:
            if hasattr(self, '_on_mode_changed'):
                self._on_mode_changed(mode)
            elif hasattr(self, 'on_mode_changed'):
                self.on_mode_changed(mode)
        except Exception:
            pass
        try:
            self._set_status(f"✓ RSID détecté : {mode}")
        except Exception:
            try: self.statusBar().showMessage(f"✓ RSID détecté : {mode}")
            except Exception: pass
        return True

    def _insert_rsid_line_dm780(self, label=None, freq_hz=None, force=False):
        """Insère dans le texte reçu une ligne façon DM780 : RSID:BPSK31 f=1500Hz.

        Cette fonction sert à deux cas :
        1) vrai marqueur texte [RSID] reçu ;
        2) uniquement un vrai marqueur RSID reçu de la station distante.
        """
        try:
            label = str(label or self._rsid_current_mode_label() or '').strip()
            if not label:
                return False
            label = _f4lps_rsid_label(label)
            if freq_hz is None:
                try:
                    freq_hz = float(self.center_freq_spin.value())
                except Exception:
                    try:
                        freq_hz = float(getattr(getattr(self, 'waterfall', None), 'center_freq', 0.0) or 0.0)
                    except Exception:
                        freq_hz = 0.0
            try:
                freq_hz = float(freq_hz or 0.0)
            except Exception:
                freq_hz = 0.0

            if freq_hz > 0:
                line = f"\nRSID:{label} f={freq_hz:.0f}Hz  ← clic pour basculer\n"
                key = f"{label}:{int(round(freq_hz))}"
            else:
                line = f"\nRSID:{label}\n"
                key = f"{label}:0"

            if not force and key == str(getattr(self, '_rsid_rx_last_key', '')):
                return False
            self._rsid_rx_last_key = key

            if not hasattr(self, 'rx_text'):
                return False
            cur = self.rx_text.textCursor()
            cur.movePosition(QTextCursor.End)
            fmt = QTextCharFormat()
            fmt.setForeground(QColor(0, 210, 255))
            fmt.setFontWeight(QFont.Bold)
            fmt.setFontUnderline(True)
            cur.setCharFormat(fmt)
            cur.insertText(line)
            # Revenir au format normal pour le texte suivant.
            fmt2 = QTextCharFormat()
            fmt2.setForeground(self._RX_C_TEXT if hasattr(self, '_RX_C_TEXT') else QColor(210, 180, 210))
            cur.setCharFormat(fmt2)
            self.rx_text.setTextCursor(cur)
            self.rx_text.ensureCursorVisible()
            return True
        except Exception as e:
            try:
                print(f"⚠️ affichage RSID RX ignoré: {e}")
            except Exception:
                pass
            return False

    def _handle_rx_rsid_text(self, text):
        """Détecte les marqueurs texte RSID et affiche la ligne DM780 dans RX.

        Exemple affiché : RSID:BPSK31 f=1500Hz
        Le texte RSID lui-même est retiré du flux pour éviter d'être affiché deux fois.
        """
        if not text:
            return text
        # Même si la case RSID RX est désactivée, si le texte contient explicitement RSID,
        # on l'affiche quand même : c'est une information reçue utile.
        label, cleaned = _f4lps_extract_rsid(text)
        if label:
            try:
                self._apply_rsid_mode(label)
            except Exception:
                pass
            self._insert_rsid_line_dm780(label, force=True)
            self._rsid_rx_mode_line_done = True
            return cleaned
        return text


    def _open_wf_msg_dialog(self):
        """Fenêtre simple pour insérer ou envoyer un message dessiné dans le waterfall."""
        try:
            dlg = QDialog(self)
            dlg.setWindowTitle("Message Waterfall")
            dlg.setMinimumWidth(420)
            lay = QVBoxLayout(dlg)

            title = QLabel("Texte à dessiner dans le waterfall")
            title.setStyleSheet("color:#99ccff;font-weight:bold;font-size:11pt;")
            lay.addWidget(title)

            row = QHBoxLayout()
            row.addWidget(QLabel("Message :"))
            combo = QComboBox()
            for item in ["CQ CQ", "73", "{MYCALL}", "F4LPS", "ARB", "POTA", "TEST"]:
                combo.addItem(item)
            combo.setEditable(True)
            row.addWidget(combo, 1)
            lay.addLayout(row)

            info = QLabel("Insérer ajoute [WF:...] dans la zone TX. Envoyer WF transmet seulement le dessin waterfall.")
            info.setStyleSheet("color:#88aacc;font-size:8pt;")
            info.setWordWrap(True)
            lay.addWidget(info)

            preview_title = QLabel("Prévisualisation locale — ce qui est écrit :")
            preview_title.setStyleSheet("color:#99ccff;font-weight:bold;font-size:9pt;")
            lay.addWidget(preview_title)

            preview = QLabel()
            preview.setTextInteractionFlags(Qt.TextSelectableByMouse)
            preview.setStyleSheet(
                "QLabel{background:#020814;color:#ffffff;"
                "border:1px solid #3355aa;border-radius:4px;"
                "font-family:'Courier New', Consolas, monospace;"
                "font-size:12pt;padding:8px;}"
            )
            preview.setMinimumHeight(145)
            lay.addWidget(preview)

            br = QHBoxLayout()
            btn_insert = QPushButton("➕ Insérer dans TX")
            btn_send = QPushButton("📡 Envoyer WF")
            btn_close = QPushButton("Fermer")
            for b in (btn_insert, btn_send, btn_close):
                b.setMinimumHeight(30)
            btn_insert.setStyleSheet("background:#102a18;color:#88ff99;font-weight:bold;")
            btn_send.setStyleSheet("background:#301020;color:#ff99cc;font-weight:bold;")
            br.addWidget(btn_insert)
            br.addWidget(btn_send)
            br.addWidget(btn_close)
            lay.addLayout(br)

            def _wf_text():
                t = combo.currentText().strip().upper()
                if t == "{MYCALL}":
                    try:
                        t = self.mycall_edit.text().strip().upper()
                    except Exception:
                        t = "F4LPS"
                return re.sub(r'[^A-Z0-9 /\-]', '', t)[:24] or "73"

            def _update_preview():
                try:
                    t = _wf_text()
                    preview.setText("WF : " + t + "\n" + _f4lps_make_wf_preview_text(t))
                except Exception:
                    preview.setText("WF : 73\n" + _f4lps_make_wf_preview_text("73"))

            try:
                combo.currentTextChanged.connect(lambda _=None: _update_preview())
                combo.editTextChanged.connect(lambda _=None: _update_preview())
                _update_preview()
            except Exception:
                pass

            def _insert():
                t = _wf_text()
                cur = self.tx_text.textCursor()
                cur.insertText(f"[WF:{t}]\n")
                self.tx_text.setTextCursor(cur)
                self.tx_text.setFocus()
                try: self._set_status(f"🌊 Message waterfall inséré : {t}")
                except Exception: pass
                dlg.accept()

            def _send():
                t = _wf_text()
                try: self._set_status(f"🌊 Envoi message waterfall : {t}")
                except Exception: pass
                dlg.accept()
                self._start_tx(f"[WF:{t}]")

            btn_insert.clicked.connect(_insert)
            btn_send.clicked.connect(_send)
            btn_close.clicked.connect(dlg.reject)
            dlg.exec_()
        except Exception as e:
            try:
                QMessageBox.warning(self, "WF MSG", f"Impossible d'ouvrir WF MSG : {e}")
            except Exception:
                print(f"WF MSG error: {e}")

    def _start_test_tx(self):
        """Envoie une courte trame PSK de test sans modifier la zone TX."""
        try:
            mycall = self.mycall_edit.text().strip().upper() if hasattr(self, 'mycall_edit') else ''
        except Exception:
            mycall = ''
        if not mycall:
            mycall = 'F4LPS'
        test_text = f"VVV VVV TEST DE {mycall} {mycall}"
        try:
            self._set_status(f"🧪 TEST TX PSK : {test_text}")
        except Exception:
            pass
        self._start_tx(test_text)

    def _start_tx(self, override_text=None):
        # FIX F4LPS : QPushButton.clicked envoie un booléen False à la fonction.
        # Sans cette protection, un clic sur ÉMETTRE était interprété comme
        # un TEST TX avec override_text=False, donc le programme envoyait :
        # [RSID] ... puis le mot "False".
        if isinstance(override_text, bool):
            override_text = None
        if self._tx_active: return
        is_test_tx = override_text is not None
        self._tx_test_mode = bool(is_test_tx)
        self._tx_saved_text_before_test = None
        orig_text = str(override_text).strip() if is_test_tx else self.tx_text.toPlainText().strip()
        # V1.6.79 : quand le bouton WF MSG envoie directement [WF:...], ce n'est PAS
        # un test PSK. On ne doit donc pas préfixer [RSID] BPSK31, sinon le dessin
        # waterfall part après la trame RSID et on croit qu'il n'y a rien d'écrit.
        _wf_direct_only = False
        try:
            _t0, _wf0, _pos0 = _f4lps_extract_wf_text_directive(orig_text)
            _wf_direct_only = bool(str(_wf0 or '').strip()) and not str(_t0 or '').strip()
        except Exception:
            _wf_direct_only = False

        # FIX F4LPS V1.0 TEST TX PRO :
        # - le TEST TX doit TOUJOURS envoyer le RSID, même si la case RSID TX est décochée ;
        # - le texte réellement émis est affiché temporairement dans la grande fenêtre TX
        #   pour que le suivi vert/barré fonctionne aussi pendant TEST TX ;
        # - à la fin du test, le texte utilisateur original est restauré automatiquement.
        if is_test_tx and not _wf_direct_only and getattr(self, '_family', '') not in ('JS8', 'CW'):
            label = self._rsid_current_mode_label()
            text = (f"[RSID] {label}\n" if label else "") + orig_text
        else:
            # Envoi normal ou WF direct : respecter exactement [WF:...] sans RSID parasite.
            text = self._prepend_rsid_to_tx(orig_text) if not _wf_direct_only else orig_text

        text, self._pending_wf_text, self._pending_wf_position = _f4lps_extract_wf_text_directive(text)
        # V1.6.75 : autorise un envoi uniquement waterfall, par exemple [WF:73],
        # SANS ajouter d'espace PSK après. L'espace PSK créait une barre parasite
        # qui faisait croire que les lettres WF étaient mal orientées.
        wf_only = (not str(text).strip()) and str(getattr(self, '_pending_wf_text', '') or '').strip()

        # Afficher dans la zone TX exactement ce qui part à l'antenne, pour le suivi couleur/barré.
        if is_test_tx:
            try:
                self._tx_saved_text_before_test = self.tx_text.toPlainText()
                self.tx_text.setPlainText(text)
            except Exception:
                self._tx_saved_text_before_test = None
        elif text != orig_text:
            try:
                self.tx_text.setPlainText(text)
            except Exception:
                pass
        if (not str(text).strip()) and not str(getattr(self, '_pending_wf_text', '') or '').strip():
            QMessageBox.warning(self,"TX","Texte vide."); return
        tx_sr = self.audio_thread.sample_rate if self.audio_thread else 48000
        self.encoder_obj.sample_rate = tx_sr
        self.encoder_obj.set_mode(self.mode_combo.currentText())
        # Sauvegarde RX avant TX : le dessin WF ne doit pas décaler le décodeur RX.
        # Sans cela, après un WF MSG, le RX-CENTER peut rester sur une fréquence du dessin
        # et le décodage devient de moins en moins bon.
        try:
            # V0.6 F4LPS — CORRECTION. getattr(..., 'center_freq') echouait en
            # OLIVIA : ce decodeur stocke son centre dans _center_freq (avec un
            # souligne). La valeur par defaut 1500.0 etait donc renvoyee, et au
            # retour en RX les traits et le spin box sautaient a 1500 Hz alors
            # que le decodage restait bon (le RX-CENTER FIN rattrapait seul le
            # signal reel). Le spin box contient toujours le vrai centre RX
            # affiche, quel que soit le mode : c'est la source fiable.
            self._rx_center_before_tx = float(self.center_freq_spin.value())
        except Exception:
            self._rx_center_before_tx = None
        try:
            self._wf_center_before_tx = float(getattr(self.waterfall, 'center_freq', 1500.0))
        except Exception:
            self._wf_center_before_tx = None

        # TX = RX : verrouillage final juste avant génération audio.
        # On force l'encodeur sur le trait visible du waterfall pour supprimer
        # le décalage constaté entre le curseur et la trame émise.
        tx_hz = self._get_tx_audio_hz()
        self.encoder_obj.set_center_freq(tx_hz)
        try:
            if getattr(self, 'tx_link_rx_cb', None) is not None and self.tx_link_rx_cb.isChecked():
                self.waterfall.set_center_freq(tx_hz)
                self.decoder_obj.set_center_freq(tx_hz)
                if self.audio_thread:
                    self.audio_thread.set_center_freq(tx_hz)
        except Exception:
            pass
        self._set_status(f"📡 TX PSK à {tx_hz:.0f} Hz audio" + ("  (TX=RX trait waterfall)" if getattr(self, 'tx_link_rx_cb', None) and self.tx_link_rx_cb.isChecked() else ""))
        self.encoder_obj._amplitude = self.amp_slider.value()/100
        self._verify_tx_psk_settings()
        self._on_tx_char_progress(0, 0)
        tx_dev = self.tx_combo.currentData()
        if tx_dev is None or tx_dev < 0: tx_dev = None
        self._pending_tx_text = text; self._pending_tx_dev = tx_dev; self._pending_tx_sr = tx_sr; self._pending_tx_hz = tx_hz
        # V1.6.48 HRD FIX : calculer la durée TX avant de passer en émission.
        # Chez certains OM, HRD/PTT retombait presque aussitôt car le thread TX
        # se terminait trop vite ou l'audio démarrait avant que le TX soit stable.
        try:
            if str(text or '').strip():
                _aud = self.encoder_obj.encode_text(text.upper())
            else:
                _aud = np.zeros(0, dtype=np.float32)
            try:
                _wf = _f4lps_make_waterfall_text_audio(
                    getattr(self, '_pending_wf_text', ''), tx_sr, tx_hz, amplitude=0.25)
                if _wf is not None and len(_wf):
                    _aud = np.concatenate([_wf.astype(np.float32), _aud.astype(np.float32)])
            except Exception:
                pass
            self._pending_tx_expected_sec = max(0.8, float(len(_aud)) / float(tx_sr or 48000))
            self._pending_tx_preflight_ok = bool(
                getattr(self, "_family", "") != "JS8"
                or getattr(self.encoder_obj, "tx_validated", False)
            )
            if not self._pending_tx_preflight_ok:
                raise RuntimeError("auto-validation TX JS8 non confirmee")
        except Exception as exc:
            self._pending_tx_preflight_ok = False
            if getattr(self, "_family", "") == "JS8":
                QMessageBox.critical(
                    self, "TX JS8 bloque",
                    "La trame JS8 n'a pas passe l'auto-validation.\n\n"
                    f"Aucun PTT n'a ete commande.\nDetail : {exc}"
                )
                self._set_status(f"⛔ TX JS8 bloque avant PTT : {exc}")
                return
            self._pending_tx_expected_sec = max(1.0, len(text) * 0.32)
        if self._rx_active:
            self._stop_rx(); self._rx_was_active = True
            QTimer.singleShot(650, self._launch_tx)
        else:
            self._rx_was_active = False; self._launch_tx()

    def _launch_tx(self):
        if getattr(self, "_family", "") == "JS8":
            if not bool(getattr(self, "_pending_tx_preflight_ok", False)):
                self._set_status("⛔ TX JS8 bloque : prevalidation absente")
                return
            # L'audio doit commencer sur la grille UTC du sous-mode, apres le
            # start_delay officiel. Le PTT est leve 750 ms avant cette cible.
            now = time.time()
            target = getattr(self, "_js8_pending_audio_epoch", None)
            if target is None:
                params = JS8_MODES.get(
                    str(self.mode_combo.currentText()), JS8_MODES["JS8 NORMAL"]
                )
                frame_s = float(params["frame_s"])
                start_delay = float(params["start_delay_s"])
                target = (
                    math.ceil((now + 1.0 - start_delay) / frame_s) * frame_s
                    + start_delay
                )
                self._js8_pending_audio_epoch = target
            ptt_epoch = float(target) - 0.750
            if now + 0.010 < ptt_epoch:
                wait_ms = max(1, int(round((ptt_epoch - now) * 1000.0)))
                self._set_status(
                    f"⏱ TX JS8 pret — prochain creneau dans {max(0.0, target-now):.1f}s"
                )
                QTimer.singleShot(wait_ms, self._launch_tx)
                return
            audio_delay_ms = max(0, int(round((float(target) - now) * 1000.0)))
        else:
            audio_delay_ms = 750
        # V1.6.48 : séquence HRD plus sûre : PTT ON puis petit délai avant audio.
        # Cela évite le symptôme "ça commence puis ça coupe" sur certains postes/HRD.
        self._tx_launch_time = time.time()
        self._tx_min_hold_until = self._tx_launch_time + float(getattr(self, '_pending_tx_expected_sec', 1.0)) + 0.8
        if self.radio_ctrl.connected:
            try:
                self.radio_ctrl.ptt_on()
                self._set_status("🔴 PTT HRD ON — attente stabilisation TX...")
            except Exception as e:
                self._set_status(f"⚠️ PTT HRD ON impossible: {e}")
        QTimer.singleShot(audio_delay_ms, self._start_tx_audio_thread)

    def _start_tx_audio_thread(self):
        # IMPORTANT : le waterfall TX doit utiliser la même fréquence d'échantillonnage
        # que l'audio TX. Sinon, avec une carte en 44.1 kHz, un trait à 1200 Hz
        # s'affiche décalé comme s'il était calculé en 48 kHz.
        try:
            self.waterfall.sample_rate = float(self._pending_tx_sr or 48000)
            self.waterfall._tx_sample_rate = float(self._pending_tx_sr or 48000)
        except Exception:
            pass
        try:
            self.waterfall._tx_expected_hz = float(getattr(self, '_pending_tx_hz', 0.0) or 0.0)
        except Exception:
            pass
        # V1.6.91 F4LPS : affichage local TX en FFT 4096, dessin WF petits ronds.
        # Le 1024 donnait un aperçu local en gros pavés blancs. Les OM auront chacun
        # leur waterfall, mais 4096 est un meilleur compromis pour voir si le dessin
        # reste fin et lisible.
        try:
            self.waterfall._tx_fft_size = 4096
            self.waterfall._tx_buf = np.zeros(int(self.waterfall._tx_fft_size), dtype=np.float32)
            self.waterfall._tx_pos = 0
        except Exception:
            pass
        self.tx_thread = PSKTxThread(self.encoder_obj, self._pending_tx_text,
                                     self._pending_tx_dev, self._pending_tx_sr,
                                     getattr(self, '_pending_tx_hz', None),
                                     self._get_tx_gain(),
                                     getattr(self, '_pending_wf_text', ''),
                                     getattr(self, '_pending_wf_position', 'before'))
        self.tx_thread.tx_started.connect(self._on_tx_started)
        self.tx_thread.tx_finished.connect(self._on_tx_finished)
        self.tx_thread.tx_progress.connect(self.tx_progress.setValue)
        self.tx_thread.tx_char_progress.connect(self._on_tx_char_progress)
        try: self.tx_thread.tx_audio.connect(self.waterfall.push_tx_audio)
        except Exception: pass
        try: self.tx_thread.tx_level.connect(self._on_tx_level_update)
        except Exception: pass
        # V1.6.53 : VU-mètres TX animés pendant l'émission
        self.tx_thread.tx_progress.connect(self._update_tx_vu_meters)
        self.tx_thread.start()

    @staticmethod
    def _calibration_fft_peak(samples, sample_rate, expected_hz=None, search_hz=120.0):
        """Mesure précise d'une fréquence par FFT avec interpolation parabolique.

        Cette fonction ne se contente pas du numéro du bin FFT. Elle estime le
        sommet entre trois bins afin de distinguer une vraie erreur de quelques
        hertz d'un simple manque de résolution graphique.
        """
        try:
            x = np.asarray(samples, dtype=np.float64).reshape(-1)
            sr = float(sample_rate)
            if len(x) < 64 or sr <= 0:
                return None

            x = x - float(np.mean(x))
            nfft = 1
            target = max(len(x), 262144)
            while nfft < target:
                nfft <<= 1

            window = np.hanning(len(x))
            spec = np.abs(np.fft.rfft(x * window, n=nfft))
            freqs = np.fft.rfftfreq(nfft, d=1.0 / sr)

            lo = 1
            hi = len(spec) - 2
            if expected_hz is not None:
                center = float(expected_hz)
                width = max(10.0, float(search_hz))
                lo = max(lo, int(np.searchsorted(freqs, center - width)))
                hi = min(hi, int(np.searchsorted(freqs, center + width)))
            if hi <= lo:
                return None

            k = lo + int(np.argmax(spec[lo:hi + 1]))
            alpha = float(spec[k - 1])
            beta = float(spec[k])
            gamma = float(spec[k + 1])
            den = alpha - 2.0 * beta + gamma
            delta = 0.0 if abs(den) < 1e-20 else 0.5 * (alpha - gamma) / den
            delta = max(-1.0, min(1.0, delta))
            return float((k + delta) * sr / nfft)
        except Exception:
            return None

    def _calibration_measure_rx_peak(self, expected_hz):
        """Mesure le pic du dernier spectre RX déjà calculé par le waterfall."""
        try:
            mag = np.asarray(
                getattr(self, '_last_spectrum_mag_for_mode', None),
                dtype=np.float64
            ).reshape(-1)
            sr = float(getattr(self, '_last_spectrum_sr_for_mode', 0.0) or 0.0)
            if len(mag) < 16 or sr <= 0:
                return None

            # _on_spectrum reçoit la magnitude RFFT : le dernier bin correspond
            # approximativement à Nyquist.
            freqs = np.linspace(0.0, sr / 2.0, len(mag), endpoint=True)
            expected = float(expected_hz)
            mask = (freqs >= expected - 120.0) & (freqs <= expected + 120.0)
            idxs = np.flatnonzero(mask)
            if len(idxs) < 3:
                return None

            k = int(idxs[int(np.argmax(mag[idxs]))])
            if k <= 0 or k >= len(mag) - 1:
                return float(freqs[k])

            alpha = float(mag[k - 1])
            beta = float(mag[k])
            gamma = float(mag[k + 1])
            den = alpha - 2.0 * beta + gamma
            delta = 0.0 if abs(den) < 1e-20 else 0.5 * (alpha - gamma) / den
            delta = max(-1.0, min(1.0, delta))
            bin_hz = float(freqs[1] - freqs[0])
            return float(freqs[k] + delta * bin_hz)
        except Exception:
            return None

    def _calibration_measure_encoder(self, requested_hz, sample_rate):
        """Mesure la porteuse réellement créée par PSKEncoder.

        On analyse le préambule stable produit par encode_text(). C'est donc bien
        la sortie du véritable encodeur PSK du programme, et non une sinusoïde
        artificielle indépendante.
        """
        try:
            sr = int(max(8000, float(sample_rate)))
            enc = PSKEncoder(
                sample_rate=sr,
                mode=str(self.mode_combo.currentText()),
                center_freq=float(requested_hz)
            )
            enc._amplitude = 0.50
            audio = enc.encode_text("CAL")
            stable_len = int(max(256, 16 * enc.symbol_len))
            stable = np.asarray(audio[:stable_len], dtype=np.float64)
            return self._calibration_fft_peak(
                stable, sr, expected_hz=float(requested_hz), search_hz=80.0
            )
        except Exception:
            return None

    def _open_frequency_calibration(self):
        """Fenêtre de diagnostic fréquentiel, sans PTT et sans émission."""
        try:
            dlg = QDialog(self)
            dlg.setWindowTitle("Calibration fréquence RX / TX — sans émission")
            dlg.resize(720, 500)
            root = QVBoxLayout(dlg)

            info = QLabel(
                "Cette mesure ne déclenche jamais le PTT.\\n"
                "TX interne = fréquence réellement fabriquée par l'encodeur PSK.\\n"
                "RX spectral = pic du dernier spectre reçu près du RX Center."
            )
            info.setWordWrap(True)
            info.setStyleSheet(
                "color:#99ddff;background:#001522;border:1px solid #226688;"
                "padding:8px;font-family:'Courier New';"
            )
            root.addWidget(info)

            rx_display = float(self.center_freq_spin.value())
            tx_display = float(self._get_tx_audio_hz())
            rx_engine = float(getattr(self.decoder_obj, 'center_freq', rx_display))
            sr_rx = float(getattr(self, '_last_spectrum_sr_for_mode', 0.0) or 0.0)
            if sr_rx <= 0:
                sr_rx = float(self.audio_thread.sample_rate if self.audio_thread else self._get_rx_sample_rate())
            sr_tx = float(self.audio_thread.sample_rate if self.audio_thread else 48000)

            rx_peak = self._calibration_measure_rx_peak(rx_display)
            tx_peak = self._calibration_measure_encoder(tx_display, sr_tx)

            grid = QGridLayout()
            headers = ["Mesure", "Demandé / affiché", "Mesuré", "Écart"]
            for c, title in enumerate(headers):
                h = QLabel(title)
                h.setStyleSheet("font-weight:bold;color:#ff77cc;")
                grid.addWidget(h, 0, c)

            rows = [
                ("RX Center affiché → moteur", rx_display, rx_engine),
                ("RX Center affiché → pic spectral", rx_display, rx_peak),
                ("TX Hz affiché → encodeur PSK", tx_display, tx_peak),
            ]
            for r, (name, requested, measured) in enumerate(rows, start=1):
                grid.addWidget(QLabel(name), r, 0)
                grid.addWidget(QLabel(f"{requested:.2f} Hz"), r, 1)
                if measured is None:
                    grid.addWidget(QLabel("indisponible"), r, 2)
                    grid.addWidget(QLabel("—"), r, 3)
                else:
                    err = float(measured) - float(requested)
                    grid.addWidget(QLabel(f"{measured:.2f} Hz"), r, 2)
                    e = QLabel(f"{err:+.2f} Hz")
                    if abs(err) <= 1.0:
                        e.setStyleSheet("color:#66ff99;font-weight:bold;")
                    elif abs(err) <= 4.0:
                        e.setStyleSheet("color:#ffcc55;font-weight:bold;")
                    else:
                        e.setStyleSheet("color:#ff5555;font-weight:bold;")
                    grid.addWidget(e, r, 3)

            root.addLayout(grid)

            details = QTextEdit()
            details.setReadOnly(True)
            details.setMinimumHeight(190)
            lines = [
                f"Mode actuel : {self.mode_combo.currentText()}",
                f"Taux RX utilisé pour l'affichage spectral : {sr_rx:.0f} Hz",
                f"Taux TX utilisé par l'encodeur : {sr_tx:.0f} Hz",
                "",
            ]

            if tx_peak is not None:
                tx_err = tx_peak - tx_display
                if abs(tx_err) <= 1.0:
                    lines.append(
                        "TX : l'encodeur produit la bonne fréquence. "
                        "Un écart avec DM780 est probablement graphique ou lié au calibrage de son waterfall."
                    )
                else:
                    lines.append(
                        "TX : un écart interne est mesuré. Il peut réellement déplacer la trace émise."
                    )
            else:
                lines.append("TX : mesure interne indisponible.")

            if rx_peak is None:
                lines.append(
                    "RX : aucun spectre exploitable. Laisse RX actif sur une trace nette, puis relance CAL."
                )
            else:
                rx_err = rx_peak - rx_display
                lines.append(
                    f"RX : le pic reçu est à {rx_peak:.2f} Hz, soit {rx_err:+.2f} Hz "
                    "par rapport au RX Center affiché."
                )
                lines.append(
                    "Attention : cette différence peut simplement signifier que le curseur "
                    "n'est pas exactement au centre du signal reçu."
                )

            lines.extend([
                "",
                "Test comparatif conseillé avec DM780 :",
                "1. Relier la sortie TX du programme à l'entrée RX de DM780 par VAC.",
                "2. Tester 500, 1000, 1500 et 2500 Hz.",
                "3. Si l'écart DM780 reste constant : offset d'affichage.",
                "4. Si l'écart augmente avec la fréquence : taux d'échantillonnage ou échelle incorrecte.",
            ])
            details.setPlainText("\\n".join(lines))
            root.addWidget(details)

            buttons = QHBoxLayout()
            refresh = QPushButton("🔄 Refaire la mesure")
            close_btn = QPushButton("Fermer")
            refresh.clicked.connect(lambda: (dlg.accept(), QTimer.singleShot(0, self._open_frequency_calibration)))
            close_btn.clicked.connect(dlg.accept)
            buttons.addStretch()
            buttons.addWidget(refresh)
            buttons.addWidget(close_btn)
            root.addLayout(buttons)
            dlg.exec_()
        except Exception as e:
            QMessageBox.warning(self, "Calibration RX/TX", f"Mesure impossible : {e}")

    def _get_tx_gain(self):
        try:
            return max(0.05, min(1.0, float(self.tx_gain_slider.value()) / 100.0))
        except Exception:
            return 0.45

    def _on_tx_gain_changed(self, v):
        try: self.tx_gain_lbl.setText(f"{int(v)} %")
        except Exception: pass
        try:
            if int(v) > 60:
                self.tx_clip_lbl.setText("⚠️ baisse si ALC monte")
                self.tx_clip_lbl.setStyleSheet("color:#ffcc66;font-family:'Courier New';font-size:8pt;")
            else:
                self.tx_clip_lbl.setText("ALC logiciel : OK")
                self.tx_clip_lbl.setStyleSheet("color:#66ff99;font-family:'Courier New';font-size:8pt;")
        except Exception: pass

    def _on_tx_level_update(self, peak, warn):
        try:
            db = -120.0 if peak <= 0 else 20.0 * math.log10(max(1e-9, float(peak)))
            if warn:
                self.tx_clip_lbl.setText(f"⚠️ niveau fort {db:.1f} dBFS")
                self.tx_clip_lbl.setStyleSheet("color:#ff4444;font-family:'Courier New';font-size:8pt;font-weight:bold;")
            else:
                self.tx_clip_lbl.setText(f"OK {db:.1f} dBFS")
                self.tx_clip_lbl.setStyleSheet("color:#66ff99;font-family:'Courier New';font-size:8pt;")
        except Exception:
            pass

    def _verify_tx_psk_settings(self):
        # V0.8c F4LPS : Hell n'a ni baud PSK, ni type de modulation PSK, ni
        # longueur de symbole. Les getattr retombaient donc sur 0 et '?', ce
        # qui affichait « ? / 0.00 bauds / centre 0 Hz / symbole 0 éch. ».
        if getattr(self, '_family', 'PSK') == "CW":
            try:
                c = float(getattr(self.encoder_obj, 'center', 700.0))
                w = float(getattr(self.encoder_obj, 'wpm', 20.0))
                self.tx_check_info.setText(
                    f"Vérif TX: CW / Morse OOK / {w:.0f} WPM / pitch {c:.0f} Hz")
                self.tx_check_info.setStyleSheet(
                    "color:#66ff99;font-family:'Courier New';font-size:9pt;")
            except Exception:
                pass
            return
        if getattr(self, '_family', 'PSK') == "HELL":
            try:
                m = self.mode_combo.currentText()
                p = HELL_MODES.get(m, HELL_MODES["FELD HELL"])
                c = float(getattr(self.encoder_obj, 'center', 0.0))
                msg = (f"Vérif TX: {m} / OOK image / "
                       f"{float(p['pixel_rate']):.1f} px/s / centre {c:.0f} Hz / "
                       f"{float(p['pixel_rate'])/49.0:.1f} car./s")
                self.tx_check_info.setText(msg)
                self.tx_check_info.setStyleSheet(
                    "color:#66ff99;font-family:'Courier New';font-size:9pt;")
            except Exception:
                pass
            return
        mode = self.mode_combo.currentText() if hasattr(self, 'mode_combo') else getattr(self.encoder_obj, 'mode_name', '?')
        baud = float(getattr(self.encoder_obj, 'baud_rate', 0.0))
        sym_len = int(getattr(self.encoder_obj, 'symbol_len', 0))
        center = float(getattr(self.encoder_obj, 'center_freq', 0.0))
        psk_type = getattr(self.encoder_obj, 'psk_type', '?')
        ok31 = (mode == 'BPSK31' and abs(baud - 31.25) < 0.01 and psk_type == 'BPSK')
        msg = f"Vérif TX: {mode} / {psk_type} / {baud:.2f} bauds / centre {center:.0f} Hz / symbole {sym_len} éch."
        if hasattr(self, 'tx_check_info'):
            if ok31:
                self.tx_check_info.setText("✅ " + msg + " — compatible PSK31")
                self.tx_check_info.setStyleSheet("color:#66ff99;font-family:'Courier New';font-size:9pt;")
            else:
                self.tx_check_info.setText("ℹ️ " + msg + " — vérifie que le correspondant est sur le même mode")
                self.tx_check_info.setStyleSheet("color:#ffcc66;font-family:'Courier New';font-size:9pt;")
        print("TX PSK VERIFY:", msg)

    def _tx_waterfall_tick(self):
        """Pendant TX, le waterfall reçoit maintenant le vrai audio TX via tx_audio.
        On ne dessine plus de colonne artificielle : même comportement qu'Olivia.
        """
        try:
            if hasattr(self, 'waterfall'):
                self.waterfall.update()
        except Exception:
            pass

    def _on_tx_char_progress(self, sent_chars, current_char):
        """Coloration du vrai QTextEdit TX pendant l'envoi.
        Vert = déjà envoyé, jaune = caractère en cours. Option barré disponible.
        """
        # Le suivi couleur/barré doit fonctionner aussi en TEST TX.
        # Le texte de test est affiché temporairement dans tx_text puis restauré à la fin.
        if not hasattr(self, 'tx_text') or self.tx_text is None:
            return
        text = self.tx_text.toPlainText()
        n = len(text)
        sent = max(0, min(int(sent_chars), n))
        cur = max(0, min(int(current_char), n))
        sels = []

        def make_sel(start, end, fg, bg=None, strike=False):
            if end <= start:
                return None
            sel = QTextEdit.ExtraSelection()
            cursor = QTextCursor(self.tx_text.document())
            cursor.setPosition(start)
            cursor.setPosition(end, QTextCursor.KeepAnchor)
            fmt = QTextCharFormat()
            fmt.setForeground(QColor(fg))
            if bg:
                fmt.setBackground(QColor(bg))
            if strike:
                fmt.setFontStrikeOut(True)
            sel.cursor = cursor
            sel.format = fmt
            return sel

        strike = bool(getattr(self, 'tx_strike_cb', None) and self.tx_strike_cb.isChecked())
        s1 = make_sel(0, sent, '#66ff99', None, strike)
        if s1: sels.append(s1)
        if sent < n:
            s2 = make_sel(sent, min(sent+1, n), '#ffff66', '#403000', False)
            if s2: sels.append(s2)
        self.tx_text.setExtraSelections(sels)
        if hasattr(self, 'tx_follow_label'):
            self.tx_follow_label.setText(f"TX suivi : {sent}/{n} caractères envoyés")

    def _abort_tx(self):
        if self.tx_thread: self.tx_thread.abort()

    def _update_tx_vu_meters(self, pct):
        """Anime les VU-mètres TX en fonction du pourcentage d'avancement TX."""
        try:
            amp = int(self.amp_slider.value()) if hasattr(self,'amp_slider') else 35
            # Pendant TX : VU oscille légèrement autour de l'amplitude réglée
            import math, time
            t = time.time()
            wobble = int(amp * 0.12 * abs(math.sin(t * 8.0 + pct * 0.1)))
            val = min(100, amp + wobble)
            if hasattr(self,'big_tx_meter'):  self.big_tx_meter.setValue(val)
            if hasattr(self,'tx_peak_bar'):   self.tx_peak_bar.setValue(val)
            # Waterfall TX : le vrai audio TX est injecté via tx_audio, pas par faux trait.
        except Exception:
            pass

    def _tracker_manual_spot_allowed(self, call, window_ms=1800):
        """Un clic volontaire sur un CALL ne crée qu'un seul spot Tracker."""
        call = str(call or "").strip().upper()
        if not call:
            return False
        now = time.monotonic()
        last_call = str(getattr(self, "_tracker_last_manual_spot_call", "") or "").upper()
        last_time = float(getattr(self, "_tracker_last_manual_spot_time", 0.0) or 0.0)
        if call == last_call and (now - last_time) * 1000.0 < float(window_ms):
            return False
        self._tracker_last_manual_spot_call = call
        self._tracker_last_manual_spot_time = now
        return True

    def _country_to_tx_language(self, country):
        """Retourne (langue, auto_ok).

        auto_ok=False pour les pays clairement multilingues : on affiche le
        pays et une suggestion mais on ne change pas automatiquement le TX.
        """
        c = str(country or "").strip().lower()

        # Pays multilingues : ne jamais imposer automatiquement une langue.
        ambiguous = {
            "belgium": "À choisir",
            "belgique": "À choisir",
            "switzerland": "À choisir",
            "suisse": "À choisir",
            "canada": "À choisir",
        }
        for key, label in ambiguous.items():
            if key in c:
                return label, False

        mapping = {
            "france": "Français",
            "germany": "Allemand", "allemagne": "Allemand",
            "austria": "Allemand", "autriche": "Allemand",
            "italy": "Italien", "italie": "Italien",
            "spain": "Espagnol", "espagne": "Espagnol",
            "portugal": "Portugais",
            "netherlands": "Néerlandais", "pays-bas": "Néerlandais",
            "poland": "Polonais", "pologne": "Polonais",
            "united kingdom": "Anglais", "england": "Anglais",
            "scotland": "Anglais", "wales": "Anglais",
            "ireland": "Anglais",
            "united states": "Anglais", "usa": "Anglais",
            "australia": "Anglais", "new zealand": "Anglais",
            "brazil": "Portugais", "brésil": "Portugais",
            "argentina": "Espagnol", "argentine": "Espagnol",
            "mexico": "Espagnol", "mexique": "Espagnol",
        }

        for key, lang in mapping.items():
            if key in c:
                return lang, True

        return "À choisir", False

    def _update_tx_language_from_country(self, country, call=""):
        """Affiche Pays/Langue TX et règle réellement 'Traduire vers' si sûr."""
        country = str(country or "").strip()
        self._dx_country = country

        if not country:
            try:
                if hasattr(self, "dx_country_lbl"):
                    self.dx_country_lbl.setText("🌍 Pays : —")
                if hasattr(self, "dx_tx_lang_lbl"):
                    self.dx_tx_lang_lbl.setText("🗣 TX : —")
            except Exception:
                pass
            return ""

        lang, auto_ok = self._country_to_tx_language(country)

        try:
            if hasattr(self, "dx_country_lbl"):
                self.dx_country_lbl.setText(f"🌍 Pays : {country}")
                self.dx_country_lbl.setToolTip(
                    f"Pays Callbook : {country}"
                )

            if hasattr(self, "dx_tx_lang_lbl"):
                self.dx_tx_lang_lbl.setText(f"🗣 TX : {lang}")
        except Exception:
            pass

        # Le vrai menu de l'interface s'appelle lang_dst_combo.
        # On ne change automatiquement que pour une langue sûre ET présente.
        changed = False
        if auto_ok and lang and hasattr(self, "lang_dst_combo"):
            try:
                idx = self.lang_dst_combo.findText(
                    lang, Qt.MatchFixedString
                )
                if idx >= 0:
                    self.lang_dst_combo.setCurrentIndex(idx)
                    changed = True
            except Exception:
                changed = False

        self._suggested_tx_language = lang

        try:
            msg = f"🌍 {call or 'CALL'} : {country} — langue TX : {lang}"
            if changed:
                msg += " ✓ Traduire vers réglé automatiquement"
            elif not auto_ok:
                msg += " — choix manuel conseillé"
            self._set_status(msg)
        except Exception:
            pass

        return lang


    def _tracker_active_qso_coords(self):
        """Retourne (call, home_lat, home_lon, dx_lat, dx_lon) avec priorité lat/lon Callbook."""
        try:
            call = self._active_dxcall_for_log()
        except Exception:
            call = str(getattr(self, '_last_dxcall', '') or '').strip().upper()
        call = str(call or '').strip().upper()
        if not call:
            return None

        win = getattr(self, '_grid_tracker_win', None)
        if win is None:
            return None

        # HOME
        home_lat = home_lon = None
        try:
            my_grid = str((getattr(win, 'settings', {}) or {}).get('my_grid', '') or '').strip().upper()
            ll = grid_to_latlon(my_grid) if my_grid else None
            if ll:
                home_lat, home_lon = float(ll[0]), float(ll[1])
        except Exception:
            pass
        if home_lat is None:
            try:
                my_grid = str(getattr(self, '_my_locator', '') or '').strip().upper()
                if not my_grid and hasattr(self, 'locator_edit'):
                    my_grid = self.locator_edit.text().strip().upper()
                ll = grid_to_latlon(my_grid) if my_grid else None
                if ll:
                    home_lat, home_lon = float(ll[0]), float(ll[1])
            except Exception:
                pass

        # DX : priorité absolue aux coordonnées géographiques des infos Callbook.
        dx_lat = getattr(self, '_dx_lat', None)
        dx_lon = getattr(self, '_dx_lon', None)

        # Sinon locator DX.
        if dx_lat in (None, '') or dx_lon in (None, ''):
            try:
                grid = str(getattr(self, '_dx_locator', '') or '').strip().upper()
                ll = grid_to_latlon(grid) if grid else None
                if ll:
                    dx_lat, dx_lon = float(ll[0]), float(ll[1])
            except Exception:
                pass

        # Sinon dernier contact Tracker connu pour ce call.
        if dx_lat in (None, '') or dx_lon in (None, ''):
            try:
                contacts = list(getattr(getattr(win, 'store', None), 'contacts', []) or [])
                matches = [c for c in contacts
                           if str(c.get('call', '')).strip().upper() == call
                           and c.get('lat') not in (None, '')
                           and c.get('lon') not in (None, '')]
                if matches:
                    c = matches[-1]
                    dx_lat, dx_lon = float(c['lat']), float(c['lon'])
            except Exception:
                pass

        if home_lat is None or dx_lat in (None, '') or dx_lon in (None, ''):
            return None

        return call, float(home_lat), float(home_lon), float(dx_lat), float(dx_lon)

    def _tracker_update_active_dx_marker(self):
        """Place un point sur l'OM actif avec les infos connues dans une bulle."""
        try:
            coords = self._tracker_active_qso_coords()
            if not coords:
                return False
            call, home_lat, home_lon, dx_lat, dx_lon = coords

            name = str(getattr(self, '_dx_name', '') or '').strip()
            qth = str(getattr(self, '_dx_qth', '') or '').strip()
            grid = str(getattr(self, '_dx_locator', '') or '').strip().upper()
            country = str(getattr(self, '_dx_country', '') or '').strip()

            try:

                self._update_tx_language_from_country(country, call)

            except Exception:

                pass

            # Valeurs déjà calculées par l'interface si présentes.
            distance = ''
            azimuth = ''
            try:
                distance = str(getattr(self, '_dx_distance_km', '') or '').strip()
            except Exception:
                pass
            try:
                azimuth = str(getattr(self, '_dx_azimuth_deg', '') or '').strip()
            except Exception:
                pass

            # Si les variables internes n'existent pas, lire le label visible.
            if not distance or not azimuth:
                try:
                    lbl = str(self.dx_bearing_label.text() or '')
                    m = re.search(r'(\d+(?:[.,]\d+)?)\s*km.*?(\d{1,3})\s*°', lbl, re.I)
                    if m:
                        distance = distance or m.group(1).replace(',', '.')
                        azimuth = azimuth or m.group(2)
                except Exception:
                    pass

            rows = [f"<b style='font-size:14px'>{call}</b>"]
            if name:
                rows.append(f"👤 {name}")
            if qth:
                rows.append(f"📍 {qth}")
            if grid:
                rows.append(f"▦ Locator : {grid}")
            if country:
                rows.append(f"🌍 {country}")
            if distance:
                rows.append(f"📏 {distance} km")
            if azimuth:
                rows.append(f"🧭 {azimuth}°")
            rows.append(f"<span style='color:#8fb7d8'>Lat/Lon : {dx_lat:.5f}, {dx_lon:.5f}</span>")

            popup = "<br>".join(rows)

            win = getattr(self, '_grid_tracker_win', None)
            live_map = getattr(win, 'live_map', None) if win is not None else None
            if live_map is None:
                return False
            live_map.set_active_dx_marker(call, dx_lat, dx_lon, popup)
            try:
                win.set_live_qso_info({
                    "call": call,
                    "name": name,
                    "qth": qth,
                    "grid": grid,
                    "country": country,
                    "distance": distance,
                    "azimuth": azimuth,
                    "status": "🟡 OM sélectionné — prêt pour TX",
                })
            except Exception:
                pass
            return True
        except Exception as e:
            try:
                print(f"⚠️ Tracker active DX marker: {e}")
            except Exception:
                pass
            return False

    def _tracker_autozoom_active_qso(self):
        """Zoom robuste : coordonnées HOME + DX envoyées directement à Leaflet."""
        try:
            call = self._active_dxcall_for_log()
        except Exception:
            call = str(getattr(self, '_last_dxcall', '') or '').strip().upper()
        call = str(call or '').strip().upper()
        if not call:
            try: self._set_status("⚠️ Tracker zoom : aucun CALL actif")
            except Exception: pass
            return False

        try:
            win = getattr(self, '_grid_tracker_win', None)
            if win is None:
                # Crée et affiche le Tracker si nécessaire.
                win = GridTrackerWindow()
                self._grid_tracker_win = win
            if win.isHidden():
                win.show()

            real_map = getattr(win, 'live_map', None)
            if real_map is None:
                try: self._set_status("⚠️ Tracker zoom : carte Trafic réel indisponible")
                except Exception: pass
                return False

            # Pendant un QSO, afficher automatiquement la carte Trafic réel.
            try:
                win._show_map("live")
            except Exception:
                try:
                    win.btn_live_map.setChecked(True)
                    win.btn_real_map.setChecked(False)
                    win.btn_grid_map.setChecked(False)
                    win.map_stack.setCurrentWidget(real_map)
                except Exception:
                    pass

            # HOME : locator configuré dans le Tracker, sinon locator MultiDigi.
            home_lat = home_lon = None
            try:
                my_grid = str((getattr(win, 'settings', {}) or {}).get('my_grid', '') or '').strip().upper()
                ll = grid_to_latlon(my_grid) if my_grid else None
                if ll:
                    home_lat, home_lon = float(ll[0]), float(ll[1])
            except Exception:
                pass
            if home_lat is None:
                try:
                    my_grid = str(getattr(self, '_my_locator', '') or '').strip().upper()
                    if not my_grid and hasattr(self, 'locator_edit'):
                        my_grid = self.locator_edit.text().strip().upper()
                    ll = grid_to_latlon(my_grid) if my_grid else None
                    if ll:
                        home_lat, home_lon = float(ll[0]), float(ll[1])
                except Exception:
                    pass

            # DX : priorité aux coordonnées Callbook déjà récupérées.
            dx_lat = getattr(self, '_dx_lat', None)
            dx_lon = getattr(self, '_dx_lon', None)

            # Si absentes : locator DX courant.
            if dx_lat in (None, '') or dx_lon in (None, ''):
                try:
                    grid = str(getattr(self, '_dx_locator', '') or '').strip().upper()
                    ll = grid_to_latlon(grid) if grid else None
                    if ll:
                        dx_lat, dx_lon = float(ll[0]), float(ll[1])
                except Exception:
                    pass

            # Dernier recours : retrouver le CALL dans le store du Tracker.
            if dx_lat in (None, '') or dx_lon in (None, ''):
                try:
                    contacts = list(getattr(getattr(win, 'store', None), 'contacts', []) or [])
                    matches = [c for c in contacts
                               if str(c.get('call', '')).strip().upper() == call
                               and c.get('lat') not in (None, '')
                               and c.get('lon') not in (None, '')]
                    if matches:
                        c = matches[-1]
                        dx_lat, dx_lon = float(c['lat']), float(c['lon'])
                except Exception:
                    pass

            if home_lat is None or dx_lat in (None, '') or dx_lon in (None, ''):
                try:
                    self._set_status(f"⚠️ Tracker zoom : position incomplète pour {call}")
                except Exception:
                    pass
                return False

            # Coordonnées directes -> aucun besoin de marker JS.
            real_map.zoom_between_coords(
                float(home_lat), float(home_lon),
                float(dx_lat), float(dx_lon)
            )
            self._tracker_update_active_dx_marker()

            try:
                win.raise_()
                win.activateWindow()
            except Exception:
                pass

            try:
                self._set_status(
                    f"🗺 Tracker zoom : HOME ↔ {call} "
                    f"({float(dx_lat):.4f},{float(dx_lon):.4f})"
                )
            except Exception:
                pass
            return True

        except Exception as e:
            try:
                self._set_status(f"❌ Tracker zoom : {e}")
            except Exception:
                pass
            try:
                print(f"❌ Tracker autozoom direct: {e}")
            except Exception:
                pass
            return False

    def _tracker_qso_direction(self, direction, hold_ms=0):
        """Anime TX HOME->DX ou RX DX->HOME avec les mêmes coordonnées que l'autozoom."""
        try:
            coords = self._tracker_active_qso_coords()
            if not coords:
                return False
            call, home_lat, home_lon, dx_lat, dx_lon = coords
            win = getattr(self, '_grid_tracker_win', None)
            real_map = getattr(win, 'live_map', None) if win is not None else None
            if real_map is None:
                return False

            real_map.animate_traffic_coords(
                home_lat, home_lon, dx_lat, dx_lon,
                direction, hold_ms
            )
            try:
                win.set_live_qso_info({
                    "call": call,
                    "name": str(getattr(self, "_dx_name", "") or ""),
                    "qth": str(getattr(self, "_dx_qth", "") or ""),
                    "grid": str(getattr(self, "_dx_locator", "") or ""),
                    "country": str(getattr(self, "_dx_country", "") or ""),
                    "distance": str(getattr(self, "_dx_distance_km", "") or ""),
                    "azimuth": str(getattr(self, "_dx_azimuth_deg", "") or ""),
                    "status": "🟠 TX : émission vers l’OM" if str(direction).lower() == "tx"
                              else "🟢 RX : réponse de l’OM reçue",
                })
            except Exception:
                pass
            try:
                arrow = "→" if str(direction).lower() == 'tx' else "←"
                self._set_status(f"••• Tracker {direction.upper()} : HOME {arrow} {call}")
            except Exception:
                pass
            return True
        except Exception as e:
            try:
                self._set_status(f"❌ Tracker pointillés : {e}")
            except Exception:
                pass
            return False

    def _tracker_stop_direction(self):
        try:
            win = getattr(self, '_grid_tracker_win', None)
            real_map = getattr(win, 'live_map', None) if win is not None else None
            if real_map is not None:
                real_map.stop_traffic()
        except Exception:
            pass

    def _on_tx_started(self):
        # Nouveau cycle : pendant le TX, pas encore de "réponse OM".
        self._tracker_waiting_reply_after_tx = False
        self._tracker_reply_active = False

        # Tracker : au démarrage de l'émission, cadrer automatiquement les deux OM.
        self._tracker_autozoom_active_qso()
        try:
            QTimer.singleShot(350, self._tracker_autozoom_active_qso)
        except Exception:
            pass
        # L'ancienne animation des pointillés reste secondaire.
        self._tracker_qso_direction('tx', 0)
        try: self.waterfall.set_tx_active(True)
        except Exception: pass
        self._tx_active = True; self.btn_tx.setEnabled(False)
        try: self.btn_test_tx.setEnabled(False)
        except Exception: pass
        try: self.btn_wf_msg.setEnabled(False)
        except Exception: pass
        self.btn_tx_abort.setEnabled(True); self.tx_progress.setVisible(True)
        # Init VU-mètres TX
        amp = int(self.amp_slider.value()) if hasattr(self,'amp_slider') else 35
        if hasattr(self,'big_tx_meter'):  self.big_tx_meter.setValue(amp)
        if hasattr(self,'tx_peak_bar'):   self.tx_peak_bar.setValue(amp)
        # TX waterfall : plus de timer artificiel, le vrai audio TX est injecté par tx_audio.
        if hasattr(self,'waterfall'): self.waterfall._tx_active = True
        self.tx_led.setStyleSheet("background:#2a0000;color:#ff0000;font-weight:bold;"
            "padding:2px 6px;border:1px solid #ff0000;border-radius:10px;")
        self._set_status("📡 ÉMISSION PSK EN COURS...")

    def _on_tx_finished(self):
        # Fin TX : arrêt immédiat des pointillés sortants.
        # On attend ensuite une vraie réception décodée avant d'afficher OM -> HOME.
        self._tracker_stop_direction()
        self._tracker_waiting_reply_after_tx = True
        try:
            win = getattr(self, "_grid_tracker_win", None)
            if win is not None:
                win.set_live_qso_info({
                    "call": self._active_dxcall_for_log(),
                    "name": str(getattr(self, "_dx_name", "") or ""),
                    "qth": str(getattr(self, "_dx_qth", "") or ""),
                    "grid": str(getattr(self, "_dx_locator", "") or ""),
                    "country": str(getattr(self, "_dx_country", "") or ""),
                    "distance": str(getattr(self, "_dx_distance_km", "") or ""),
                    "azimuth": str(getattr(self, "_dx_azimuth_deg", "") or ""),
                    "status": "⏳ TX terminé — en attente de réponse",
                })
        except Exception:
            pass
        try: self.waterfall.set_tx_active(False)
        except Exception: pass
        self._tx_active = False; self.btn_tx.setEnabled(True)
        try: self.btn_test_tx.setEnabled(True)
        except Exception: pass
        try: self.btn_wf_msg.setEnabled(True)
        except Exception: pass
        self.btn_tx_abort.setEnabled(False); self.tx_progress.setVisible(False)
        # Reset VU-mètres TX à l'amplitude de repos
        amp = int(self.amp_slider.value()) if hasattr(self,'amp_slider') else 35
        if hasattr(self,'big_tx_meter'):  self.big_tx_meter.setValue(amp)
        if hasattr(self,'tx_peak_bar'):   self.tx_peak_bar.setValue(amp)
        # Stopper le QTimer waterfall TX
        if hasattr(self,'_tx_wf_timer') and self._tx_wf_timer.isActive():
            self._tx_wf_timer.stop()
        if hasattr(self,'waterfall'): self.waterfall._tx_active = False
        try:
            self._on_tx_char_progress(len(self.tx_text.toPlainText()), len(self.tx_text.toPlainText()))
        except Exception:
            pass
        # V1.6.48 : ne jamais relâcher HRD/PTT trop tôt. Si le thread audio
        # finit anormalement vite, on garde un court maintien et on signale le problème.
        def _finish_ptt_and_rx():
            self._js8_pending_audio_epoch = None
            self._pending_tx_preflight_ok = False
            if self.radio_ctrl.connected:
                try:
                    self.radio_ctrl.ptt_off()
                except Exception as e:
                    self._set_status(f"⚠️ PTT OFF impossible: {e}")
            # Restaurer le calage RX d'avant TX : le WF MSG ne doit jamais laisser
            # le décodeur bloqué sur une fréquence de dessin.
            try:
                old_rx = getattr(self, '_rx_center_before_tx', None)
                if old_rx is not None:
                    self.decoder_obj.set_center_freq(float(old_rx))
                    if getattr(self, 'audio_thread', None):
                        self.audio_thread.set_center_freq(float(old_rx))
                    if getattr(self, 'waterfall', None):
                        self.waterfall.set_center_freq(float(old_rx))
                    if hasattr(self, 'center_freq_spin'):
                        self.center_freq_spin.blockSignals(True)
                        self.center_freq_spin.setValue(float(old_rx))
                        self.center_freq_spin.blockSignals(False)
            except Exception:
                pass
            if getattr(self,'_rx_was_active',False):
                # V1.6.146 F4LPS : reprise RX propre et rapide après TX.
                # L'ancien délai ajoutait 1,8 s d'ignorance + 1,1 s avant de
                # recréer le RX : on perdait typiquement 3 à 4 mots de la réponse OM.
                # On redémarre dès la retombée PTT et on ne masque qu'une très courte
                # queue audio. Le décodeur est forcé en acquisition rapide.
                self._rx_was_active = False
                # V2.1.8 : retour RX immédiat.
                # La coupure précédente ajoutait 320 ms ici, plus 300 ms autour
                # de la retombée PTT, plus le temps d'ouverture du périphérique.
                # Sur une réponse très rapide, cela supprimait la préambule PSK.
                # On ne garde que 80 ms pour laisser disparaître la queue locale.
                self._rx_ignore_until = time.time() + 0.08
                self._rx_restart_after_tx = True
                try:
                    self._autopitch_candidates.clear()
                    self._autopitch_ema = -1.0
                    self._autopitch_buf[:] = 0.0
                    self._autopitch_buf_pos = 0
                    self._autopitch_buf_full = False
                except Exception:
                    pass
                QTimer.singleShot(80, self._start_rx)
            self.tx_led.setStyleSheet("background:#2a0a1a;color:#660033;font-weight:bold;"
                "padding:2px 6px;border:1px solid #4a2a3a;border-radius:10px;")
            if getattr(self, '_tx_test_mode', False):
                self._set_status("✅ TEST TX PSK terminé")
                # Restaurer le texte utilisateur après un petit délai pour laisser voir
                # le texte de test terminé en vert/barré.
                try:
                    saved = getattr(self, '_tx_saved_text_before_test', None)
                    if saved is not None:
                        QTimer.singleShot(1800, lambda txt=saved: (self.tx_text.setPlainText(txt), self.tx_text.setExtraSelections([])))
                except Exception:
                    pass
                self._tx_test_mode = False
            else:
                self._set_status("✅ Émission PSK terminée")

        try:
            remain = float(getattr(self, '_tx_min_hold_until', 0.0)) - time.time()
        except Exception:
            remain = 0.0
        if remain > 0.10:
            self._set_status(f"⏳ Fin audio reçue trop tôt — maintien PTT {remain:.1f}s pour éviter coupure HRD")
            QTimer.singleShot(int(min(remain, 8.0) * 1000), _finish_ptt_and_rx)
        else:
            QTimer.singleShot(40, _finish_ptt_and_rx)

    # ── Mode / Fréq ───────────────────────────────────────────────────────────


    def _switch_macro_set(self, famille):
        """Bascule le jeu de macros actif vers celui de `famille`.

        On SAUVEGARDE d'abord le jeu courant (l'operateur a pu l'editer), puis
        on remplace le CONTENU de self._macros en place — sans creer une
        nouvelle liste — pour que l'editeur, la barre de boutons et la
        sauvegarde JSON continuent de pointer sur le meme objet.
        """
        try:
            jeux = getattr(self, '_macros_par_famille', None)
            if not jeux:
                return
            prec = getattr(self, '_macros_famille_active', 'PSK')
            if prec in jeux:
                jeux[prec] = list(self._macros)
            name_sets = getattr(self, '_macro_names_par_famille', {})
            if prec in name_sets:
                name_sets[prec] = list(self._macro_names)
            cible = famille if famille in jeux else 'PSK'
            nouveau = list(jeux.get(cible) or jeux['PSK'])
            n = len(self._macros)
            nouveau = (nouveau + [""] * n)[:n]
            self._macros[:] = nouveau
            if cible in name_sets:
                self._macro_names[:] = (
                    list(name_sets[cible]) + [f"F{i+1}" for i in range(n)]
                )[:n]
            self._macros_famille_active = cible
            # Rafraichir tout ce qui affiche les macros.
            for i, txt in enumerate(self._macros):
                if i < len(getattr(self, '_macro_edits', [])):
                    try:
                        self._macro_edits[i].setText(txt)
                    except Exception:
                        pass
                if i < len(getattr(self, '_macro_name_edits', [])):
                    try:
                        self._macro_name_edits[i].setText(self._macro_names[i])
                    except Exception:
                        pass
            win = getattr(self, '_macros_win', None)
            if win is not None:
                for i, txt in enumerate(self._macros):
                    try:
                        win._macro_edits[i].setPlainText(txt)
                    except Exception:
                        pass
                    try:
                        win._macro_name_edits[i].setText(self._macro_names[i])
                    except Exception:
                        pass
            self._refresh_macro_bar_labels()
            self._set_status(f"Macros : jeu {cible}")
        except Exception as e:
            print(f"⚠️ bascule macros : {e}")

    def _ensure_cw_waterfall_window(self, force_show=False):
        """Crée et affiche de façon sûre la fenêtre waterfall CW.

        Cette fonction est volontairement indépendante du signal currentTextChanged :
        elle couvre aussi le démarrage direct en CW, la restauration d'un réglage
        mémorisé et une fenêtre qui aurait été masquée.
        """
        try:
            fam = str(getattr(self, '_family', '') or '')
            try:
                if hasattr(self, 'family_combo'):
                    fam = str(self.family_combo.currentText() or fam)
            except Exception:
                pass
            if fam != 'CW':
                return False
            win = getattr(self, 'cw_waterfall_window', None)
            if win is None:
                win = CWWaterfallWindow(self)
                win.pitchSelected.connect(self._on_wf_click)
                win.autoPitchSelected.connect(self._on_cw_auto_align)
                win.filterChanged.connect(self._on_cw_filter_changed)
                self.cw_waterfall_window = win
            try:
                hz = float(self.center_freq_spin.value())
                win.waterfall.set_center_freq(hz)
            except Exception:
                pass
            if force_show or not win.isVisible():
                win.show()
                win.raise_()
                win.activateWindow()
            return True
        except Exception as e:
            print(f"⚠️ création/affichage fenêtre CW : {type(e).__name__}: {e}")
            return False

    def _on_family_changed(self, family):
        """MULTIDIGI V0.1 F4LPS : appelé quand l'opérateur change de famille
        de mode (PSK/OLIVIA/DOMINOEX/RTTY/JS8). Repeuple mode_combo avec les
        modes de cette famille et reconstruit decoder_obj/encoder_obj via le
        registre. Si le RX tournait, on l'arrête (on ne peut pas changer de
        décodeur au milieu d'un flux audio) puis on le RELANCE automatiquement
        derrière — l'opérateur n'a plus besoin de recliquer DÉMARRER RX à
        chaque changement de mode.
        """
        fam = str(family or "PSK")
        info = MULTIDIGI_MODEM_REGISTRY.get(fam)
        if not info:
            return
        # V0.11 F4LPS : chaque famille a son jeu de macros (voir le commentaire
        # a la creation de _macros_par_famille : une fiche station complete
        # demande 83 s en BPSK31 mais 281 s en OLIVIA 8/250).
        self._switch_macro_set(fam)
        # V0.8 F4LPS : Hell est un mode IMAGE. Sa sortie ne peut pas aller dans
        # la zone de texte RX ; on ouvre une fenetre dediee. Elle est creee a la
        # demande et simplement masquee quand on quitte la famille, pour ne pas
        # perdre l'historique deja recu.
        try:
            if fam == "HELL":
                if getattr(self, 'hell_window', None) is None:
                    self.hell_window = HellWindow(self)
                self.hell_window.show()
                self.hell_window.raise_()
            elif getattr(self, 'hell_window', None) is not None:
                self.hell_window.hide()
        except Exception as e:
            print(f"⚠️ fenêtre Hell : {e}")
        # V2.2.6 : mémoriser d'abord la famille, puis ouvrir la fenêtre CW.
        # L'ancienne version essayait de l'ouvrir avant self._family = fam ;
        # selon le chemin de démarrage/restauration, la fenêtre pouvait rester cachée.
        self._family = fam

        # Waterfall spécial JS8 : règle de temps visible uniquement en JS8.
        try:
            if hasattr(self, "js8_time_ruler"):
                self.js8_time_ruler.setVisible(fam == "JS8")
            if hasattr(self, "js8_decode_status"):
                self.js8_decode_status.setVisible(fam == "JS8")
            if hasattr(self, "js8_activity_panel"):
                self.js8_activity_panel.setVisible(fam == "JS8")
            if hasattr(self, "js8_command_panel"):
                self.js8_command_panel.setVisible(fam == "JS8")
            if hasattr(self, "js8_auto_grp"):
                self.js8_auto_grp.setVisible(fam == "JS8")
            if hasattr(self, "js8_band_table"):
                self.js8_band_table.setVisible(fam == "JS8")
            if hasattr(self, "js8_calls_table"):
                self.js8_calls_table.setVisible(fam == "JS8")
            if hasattr(self, "btn_auto_js8"):
                self.btn_auto_js8.setVisible(fam == "JS8")
                if hasattr(self, "btn_js8_selftest"):
                    self.btn_js8_selftest.setVisible(fam == "JS8")
            if hasattr(self, "btn_automode_psk"):
                self.btn_automode_psk.setVisible(fam == "PSK")
            if hasattr(self, "wf_grp"):
                self.wf_grp.setTitle(
                    "⏱ WATERFALL JS8 — fréquence audio + synchronisation temps"
                    if fam == "JS8" else ""
                )
        except Exception:
            pass

        try:
            if fam == "CW":
                QTimer.singleShot(0, lambda: self._ensure_cw_waterfall_window(True))
            elif getattr(self, 'cw_waterfall_window', None) is not None:
                self.cw_waterfall_window.hide()
        except Exception as e:
            print(f"⚠️ fenêtre CW : {type(e).__name__}: {e}")
        was_rx = bool(getattr(self, '_rx_active', False))
        if was_rx:
            try:
                self._stop_rx()
            except Exception:
                pass
        try:
            self.mode_combo.blockSignals(True)
            self.mode_combo.clear()
            for m in info["modes"]:
                self.mode_combo.addItem(m)
            self.mode_combo.setCurrentText(info["default_mode"])
        finally:
            self.mode_combo.blockSignals(False)
        default_mode = info["default_mode"]
        self.decoder_obj = multidigi_get_decoder(fam, default_mode, 48000)
        self.encoder_obj = multidigi_get_encoder(fam, default_mode, 48000)
        if fam == "CW":
            try:
                self.encoder_obj.set_wpm(int(getattr(self, '_cw_tx_wpm', 20)))
            except Exception:
                pass
        self._on_mode_changed(default_mode)
        self._sync_cw_tx_wpm_ui()
        # Réappliquer l'état du bouton RX-CENTER FIN au nouveau décodeur : un
        # decoder_obj tout neuf repart toujours à auto_center_enabled=False,
        # même si le bouton reste visuellement coché à l'écran.
        try:
            if hasattr(self, 'btn_autopitch') and self.btn_autopitch.isChecked():
                self._on_autopitch_toggled(True)
        except Exception:
            pass
        try:
            if fam == "JS8" and hasattr(self, "btn_auto_js8"):
                self._toggle_js8_auto_detect(self.btn_auto_js8.isChecked())
        except Exception:
            pass
        if was_rx:
            self._set_status(f"✅ Famille changée : {fam} — mode {default_mode} — redémarrage RX...")
            QTimer.singleShot(200, self._start_rx)
        else:
            self._set_status(f"✅ Famille changée : {fam} — mode {default_mode}")

    def _on_mode_changed(self, mode):
        # MULTIDIGI V0.1 F4LPS : largeur de bande affichée, dépend maintenant
        # de la famille active plutôt que de supposer PSK. PSK_MODES reste la
        # table utilisée pour la famille PSK (inchangé) ; les autres familles
        # ont leur propre table (OLIVIA_MODES, DOMINOEX_MODES) ou un calcul
        # dédié (RTTY : ~ (bauds*2 + décalage)).
        fam = getattr(self, '_family', 'PSK')
        if fam == "OLIVIA":
            bw = OLIVIA_MODES.get(mode, {}).get("bandwidth", 500)
        elif fam == "DOMINOEX":
            bw = DOMINOEX_MODES.get(mode, {}).get("bandwidth", 350)
        elif fam == "RTTY":
            baud, shift = _RTTY_MODE_PARAMS.get(mode, (45.45, 170.0))
            bw = shift + baud * 2
        elif fam == "HELL":
            bw = HELL_MODES.get(mode, {}).get("bandwidth", 245.0)
        elif fam == "CONTESTIA":
            bw = CONTESTIA_MODES.get(mode, {}).get("bandwidth", 250)
        elif fam == "CW":
            bw = CW_MODES.get(mode, {}).get("bandwidth", 200.0)
        elif fam == "JS8":
            bw = JS8_MODES.get(mode, {}).get("bandwidth", 50.0)
        else:
            p = PSK_MODES.get(mode, {})
            bw = p.get("baud", 62.5) * 2
        self.waterfall.set_bandwidth(bw)

        if fam == "JS8":
            try:
                self.js8_time_ruler.set_mode(mode)
                self.js8_time_ruler.setVisible(True)
                self.js8_time_ruler.clear_signal_sync()
                self._js8_last_ruler_serial = -1
                if hasattr(self, "js8_decode_status"):
                    self.js8_decode_status.setText(
                        "JS8 RX : attente synchro | LDPC — | CRC —"
                    )
            except Exception:
                pass

        if self.audio_thread:
            self.audio_thread.set_mode(mode)
        self.decoder_obj.set_mode(mode)
        try:
            self.decoder_obj.force_fast_acquire(3.5)
        except Exception:
            pass
        self.encoder_obj.set_mode(mode)
        if fam == "CW":
            try:
                self.encoder_obj.set_wpm(int(getattr(self, '_cw_tx_wpm', 20)))
            except Exception:
                pass
        self._sync_cw_tx_wpm_ui()
        self._update_mode_info()
        if fam == "JS8":
            base = "JS8"
        else:
            base = "BPSK63" if "63" in mode else "BPSK125" if "125" in mode else "BPSK31"
        self._update_freq_buttons(base)
        if hasattr(self, '_update_preview'):
            self._update_preview()

    def _get_visible_waterfall_center_hz(self):
        """Retourne exactement la fréquence audio du trait visible waterfall.

        Important F4LPS : le TX doit partir sur le trait que l'opérateur voit,
        pas sur une ancienne variable mémorisée. On prend donc waterfall.center_freq
        comme source principale, puis on remet les spinbox RX/TX en phase.
        """
        try:
            hz = float(getattr(self.waterfall, 'center_freq', self.center_freq_spin.value()))
        except Exception:
            hz = float(self.center_freq_spin.value())
        hz = max(20.0, min(3000.0, hz))
        try:
            self.center_freq_spin.blockSignals(True)
            self.center_freq_spin.setValue(hz)
            self.center_freq_spin.blockSignals(False)
        except Exception:
            pass
        try:
            if hasattr(self, 'tx_freq_spin') and getattr(self, 'tx_link_rx_cb', None) is not None and self.tx_link_rx_cb.isChecked():
                self.tx_freq_spin.blockSignals(True)
                self.tx_freq_spin.setValue(hz)
                self.tx_freq_spin.blockSignals(False)
        except Exception:
            pass
        return hz

    def _get_tx_audio_hz(self):
        """Fréquence TX audio réelle.

        V1.6.67 F4LPS : correction définitive sous 500 Hz.
        - Si TX=RX est coché : le TX part exactement sur le trait RX visible.
        - Si TX=RX est décoché : le TX part sur le champ TX Hz.
        - Aucune limite à 500 Hz : plage utile 20..3000 Hz.
        """
        try:
            linked = bool(getattr(self, 'tx_link_rx_cb', None) is not None and self.tx_link_rx_cb.isChecked())
        except Exception:
            linked = True

        if linked:
            try:
                hz = float(getattr(self.waterfall, 'center_freq', self.center_freq_spin.value()))
            except Exception:
                try:
                    hz = float(self.center_freq_spin.value())
                except Exception:
                    hz = 1500.0
        else:
            try:
                hz = float(self.tx_freq_spin.value())
            except Exception:
                hz = 1500.0

        hz = max(20.0, min(3000.0, float(hz)))

        try:
            if linked:
                self.center_freq_spin.blockSignals(True)
                self.center_freq_spin.setValue(hz)
                self.center_freq_spin.blockSignals(False)
                self.waterfall.set_center_freq(hz)
                self.decoder_obj.set_center_freq(hz)
                if self.audio_thread:
                    self.audio_thread.set_center_freq(hz)
            if hasattr(self, 'tx_freq_spin'):
                self.tx_freq_spin.blockSignals(True)
                self.tx_freq_spin.setValue(hz)
                self.tx_freq_spin.blockSignals(False)
        except Exception:
            pass
        return hz

    def _copy_rx_to_tx(self):
        if not hasattr(self, 'tx_freq_spin'):
            return
        self.tx_freq_spin.blockSignals(True)
        self.tx_freq_spin.setValue(float(self.center_freq_spin.value()))
        self.tx_freq_spin.blockSignals(False)
        self._set_status(f"↔ TX Hz copié sur RX Center : {self.tx_freq_spin.value():.0f} Hz")

    def _on_tx_link_toggled(self, checked):
        if checked:
            self._copy_rx_to_tx()

    def _sync_tx_to_rx_if_linked(self, hz):
        try:
            if hasattr(self, 'tx_link_rx_cb') and self.tx_link_rx_cb.isChecked() and hasattr(self, 'tx_freq_spin'):
                self.tx_freq_spin.blockSignals(True)
                self.tx_freq_spin.setValue(float(hz))
                self.tx_freq_spin.blockSignals(False)
        except Exception:
            pass

    def _on_cw_filter_changed(self, total_hz):
        """Ajuste UNIQUEMENT le filtre du décodeur CW actif.

        Le moteur historique attend une demi-largeur ; l'interface affiche une
        largeur totale plus intuitive. Aucun autre décodeur n'est appelé.
        """
        try:
            if getattr(self, '_family', '') != "CW":
                return
            half = max(25.0, min(150.0, float(total_hz) * 0.5))
            if hasattr(self.decoder_obj, 'set_filter_bw'):
                self.decoder_obj.set_filter_bw(half)
            if self.audio_thread is not None and hasattr(self.audio_thread.decoder, 'set_filter_bw'):
                self.audio_thread.decoder.set_filter_bw(half)
            self._set_status(f"CW : filtre dédié réglé à {float(total_hz):.0f} Hz")
        except Exception as e:
            print(f"CW filtre dédié : {e}")

    def _on_center_freq_changed(self, val):
        self._manual_center_hz = float(val)
        try:
            self._autopitch_candidates.clear()
            self._autopitch_ema = float(val)
        except Exception:
            pass
        self.waterfall.set_center_freq(val)
        try:
            if getattr(self, 'cw_waterfall_window', None) is not None:
                self.cw_waterfall_window.waterfall.set_center_freq(val)
        except Exception:
            pass
        if getattr(self, "_family", "") == "JS8":
            self._js8_manual_center(val)
        else:
            self.decoder_obj.set_center_freq(val)
            if self.audio_thread:
                self.audio_thread.set_center_freq(val)
        self._sync_tx_to_rx_if_linked(val)
        self._update_rx_center_display(val)
        try:
            self._save_settings()
        except Exception:
            pass

    def _on_cw_auto_align(self, hz):
        """AFC CW interne : suit la porteuse sans déplacer le repère graphique.

        Le trait vert, le centre manuel et le spinbox restent fixes. Seul le filtre
        du décodeur CW est déplacé doucement. Les autres familles sont inchangées.
        """
        try:
            if getattr(self, '_family', '') != "CW":
                return
            hz = max(50.0, min(2950.0, float(hz)))
            self._cw_afc_hz = hz

            # Mise à jour visuelle secondaire (trait jaune), jamais du trait vert.
            win = getattr(self, 'cw_waterfall_window', None)
            if win is not None:
                try:
                    win.waterfall.set_afc_freq(hz)
                except Exception:
                    pass

            # Déplace uniquement le filtre interne sans remettre à zéro le timing.
            if hasattr(self.decoder_obj, 'soft_set_center_freq'):
                self.decoder_obj.soft_set_center_freq(hz)
            else:
                self.decoder_obj.set_center_freq(hz)

            # Selon la construction du thread, son décodeur peut être une autre
            # référence : on le synchronise seulement s'il est réellement distinct.
            if self.audio_thread is not None:
                try:
                    td = getattr(self.audio_thread, 'decoder', None)
                    if td is not None and td is not self.decoder_obj:
                        if hasattr(td, 'soft_set_center_freq'):
                            td.soft_set_center_freq(hz)
                        elif hasattr(td, 'set_center_freq'):
                            td.set_center_freq(hz)
                    self.audio_thread.center_freq = float(hz)
                except Exception:
                    pass
        except Exception as e:
            print(f"AFC CW interne : {e}")

    def _js8_manual_center(self, hz):
        """Applique un réglage manuel JS8 et libère l'ancien verrou."""
        if getattr(self, "_family", "") != "JS8":
            return False

        hz = float(hz)
        done = False

        # Main decoder object.
        try:
            d = getattr(self, "decoder_obj", None)
            if d is not None and hasattr(d, "manual_set_center_freq"):
                d.manual_set_center_freq(hz, 30.0)
                done = True
            elif d is not None and hasattr(d, "set_center_freq"):
                d.set_center_freq(hz)
        except Exception:
            pass

        # Audio-thread decoder can be another reference.
        try:
            at = getattr(self, "audio_thread", None)
            td = getattr(at, "decoder", None) if at is not None else None
            if td is not None and td is not getattr(self, "decoder_obj", None):
                if hasattr(td, "manual_set_center_freq"):
                    td.manual_set_center_freq(hz, 30.0)
                    done = True
                elif hasattr(td, "set_center_freq"):
                    td.set_center_freq(hz)

            if at is not None:
                try:
                    at.center_freq = float(hz)
                except Exception:
                    pass
        except Exception:
            pass

        try:
            if hasattr(self, "js8_time_ruler"):
                # L'ancien lock temps n'est plus valable après un déplacement manuel.
                self.js8_time_ruler.clear_signal_sync()
                self._js8_last_ruler_serial = -1
        except Exception:
            pass

        return done

    def _on_wf_click(self, hz):
        self._manual_center_hz = float(hz)
        try:
            self._autopitch_candidates.clear()
            self._autopitch_ema = float(hz)
        except Exception:
            pass
        self.center_freq_spin.blockSignals(True)
        self.center_freq_spin.setValue(hz)
        self.center_freq_spin.blockSignals(False)
        self.waterfall.set_center_freq(hz)
        try:
            if getattr(self, 'cw_waterfall_window', None) is not None:
                self.cw_waterfall_window.waterfall.set_center_freq(hz)
        except Exception:
            pass
        if getattr(self, "_family", "") == "JS8":
            self._js8_manual_center(hz)
        else:
            self.decoder_obj.set_center_freq(hz)
            if self.audio_thread:
                self.audio_thread.set_center_freq(hz)
        self._sync_tx_to_rx_if_linked(hz)
        self._update_rx_center_display(hz)
        if getattr(self, "_family", "") == "JS8":
            self._set_status(
                f"🎯 Sélection JS8 {float(hz):.0f} Hz — "
                f"le scanner pleine bande continue sur 200-2900 Hz"
            )
        else:
            self._set_status(
                f"🎯 RX placé à {float(hz):.0f} Hz — acquisition rapide en cours"
            )

    # ------------------------------------------------------------------
    # V8.3.55 F4LPS : liste "Signaux décodés" JS8 (pleine bande, comme
    # la table Band Activity de JS8Call/WSJT-X) + actions au clic.
    # ------------------------------------------------------------------
    def _refresh_js8_band_table(self):
        """Poll periodique de JS8RXAdapter.get_band_hits() -> peuple/actualise
        la table. N'ecrase pas la selection en cours de l'operateur."""
        if getattr(self, "_family", "") != "JS8":
            return
        dec = None
        try:
            if self.audio_thread is not None:
                dec = self.audio_thread.decoder
            else:
                dec = self.decoder_obj
        except Exception:
            dec = None
        if dec is None or not hasattr(dec, "get_band_hits"):
            return

        # V8.3.55 : statut visible du scan pleine bande (marche/erreur/0
        # trouve), affiche dans le meme label que la synchro JS8 normale.
        try:
            status = dec.get_band_status() if hasattr(dec, "get_band_status") else None
            if status is not None:
                err = status["last_error"]
                if err and err != getattr(self, "_js8_band_last_error_shown", None):
                    self._js8_band_last_error_shown = err
                    self._set_status(
                        f"⚠️ Scan pleine bande JS8 en erreur : {err}"
                    )
                elif not err:
                    self._js8_band_last_error_shown = None
                if not status["busy"] and status["last_scan_ms"] > 0:
                    _due = status.get("due_variants", ()) or ()
                    _due_txt = ",".join(
                        str(v).replace("JS8 ","") for v in _due
                    ) or "attente slot"
                    _bank = status.get("signal_bank", []) or []
                    _bank_txt = ",".join(
                        f"{q.get('freq_hz',0):.0f}"
                        for q in _bank[:12]
                    ) or "—"
                    _hb_err = status.get("hb_exception", "")
                    _hb = (
                        f"HB A{status.get('hb_audio',0)} "
                        f"S{status.get('hb_schedule',0)} "
                        f"W{status.get('hb_worker',0)} "
                        f"D{status.get('hb_done',0)} "
                        f"B{status.get('buffer_samples',0)}"
                    )
                    if _hb_err:
                        _hb += f" ERR={_hb_err[:80]}"
                    self._js8_band_last_status = (
                        f"MULTI CANDIDATS | {_hb} | SIG[{_bank_txt}] | "
                        f"scan={_due_txt} {status['last_scan_ms']:.0f}ms"
                    )
                    _multi = status.get("multi_diag", {}) or {}
                    if _multi:
                        _parts = []
                        _labels = (
                            ("JS8 NORMAL", "N"),
                            ("JS8 FAST", "F"),
                            ("JS8 SLOW", "S"),
                            ("JS8 40", "T"),
                        )
                        for _name, _short in _labels:
                            _lst = _multi.get(_name, []) or []
                            if _lst:
                                _r = _lst[0]
                                _llr = "174" if _r.get("llr174", False) else "—"
                                _parts.append(
                                    f"{_short} {_r.get('freq_hz',0):.0f}Hz "
                                    f"C={_r.get('costas',0):.2f} "
                                    f"LLR={_llr} "
                                    f"L={_r.get('checks',87)} "
                                    f"CRC={_r.get('crc','—')}"
                                )
                            else:
                                _parts.append(f"{_short} —")
                        self._js8_band_last_status += " | " + " | ".join(_parts)

                    _hb_key = (
                        status.get("hb_audio",0), status.get("hb_schedule",0),
                        status.get("hb_worker",0), status.get("hb_done",0),
                        status.get("hb_exception","")
                    )
                    if getattr(self, "_js8_last_hb_print", None) != _hb_key:
                        self._js8_last_hb_print = _hb_key
                        print(
                            "JS8 MULTI HB | "
                            f"AUDIO={_hb_key[0]} SCHED={_hb_key[1]} "
                            f"WORKER={_hb_key[2]} DONE={_hb_key[3]} "
                            f"BUF={status.get('buffer_samples',0)} "
                            f"DUE={status.get('hb_due',())} "
                            f"ERR={_hb_key[4] or '-'}"
                        )

                    _mx = status.get("signal_matrix", []) or []
                    if _mx:
                        # Trie d'abord par niveau spectral réel : les émissions
                        # visibles dans le waterfall apparaissent en tête.
                        _mx = sorted(
                            _mx,
                            key=lambda r: float(r.get("rel_db", 0.0)),
                            reverse=True
                        )
                        _mout = []
                        _shorts = (
                            ("JS8 NORMAL","N"), ("JS8 FAST","F"),
                            ("JS8 SLOW","S"), ("JS8 40","T")
                        )
                        for _row in _mx[:8]:
                            _vtxt = []
                            for _vn, _sh in _shorts:
                                _r = _row.get(_vn)
                                if _r:
                                    _vtxt.append(
                                        f"{_sh}{_r.get('costas',0):.1f}/"
                                        f"{_r.get('checks',87)}"
                                    )
                            _mout.append(
                                f"{_row.get('freq_hz',0):.0f}Hz["
                                + (",".join(_vtxt) if _vtxt else "—") + "]"
                            )
                        self._js8_band_last_status += " | CAND " + " ; ".join(_mout)
                    try:
                        self.js8_band_table.setToolTip(
                            self._js8_band_last_status + "\n\n" +
                            "Clic = régler RX Center + tenter de remplir l'indicatif.\n"
                            "Double-clic = insérer une macro de réponse dans TEXTE À ÉMETTRE.\n"
                            "⚠ Décodage humain (indicatif/grid) pas encore implémenté."
                        )
                    except Exception:
                        pass
        except Exception:
            pass

        try:
            hits = dec.get_band_hits()
        except Exception:
            return
        if not hits:
            return

        tbl = self.js8_band_table
        known = self._js8_band_known_keys

        new_rows = []
        for h in hits:
            key = (round(float(h["epoch"]), 1), round(float(h["freq_hz"])),
                   h["text12"])
            if key in known:
                continue
            known.add(key)
            new_rows.append(h)

        # Met à jour les âges même s'il n'y a aucune nouvelle trame.
        self._js8_update_activity_ages()
        if not new_rows:
            return

        # La décision est prise dans le thread UI et uniquement si l'opérateur
        # a explicitement activé ACK HB. AUTO+CONF demande alors son accord.
        self._js8_maybe_ack_hits(new_rows)
        # V8.4 F4LPS : log auto du QSO quand une trame dirigée nous répond.
        self._js8_maybe_log_reply(new_rows)

        # Les plus récents en tête, présentation JS8Call-like.
        tbl.setUpdatesEnabled(False)
        try:
            for h in new_rows:
                print(
                    f"🔗 V96 UI_BAND_ACTIVITY_INSERT "
                    f"F={float(h.get('freq_hz',0)):.1f} "
                    f"MSG={str(h.get('text12',''))!r}"
                )
                tbl.insertRow(0)
                items = [
                    QTableWidgetItem(f"{h['freq_hz']:.0f} Hz"),
                    QTableWidgetItem("now"),
                    QTableWidgetItem(f"{h['snr_db']:+.0f} dB"),
                    QTableWidgetItem(str(h.get("text12", ""))),
                ]
                for col, it in enumerate(items):
                    it.setData(Qt.UserRole, h)
                    tbl.setItem(0, col, it)
                self._js8_update_callsign_activity(h)
            while tbl.rowCount() > 200:
                tbl.removeRow(tbl.rowCount() - 1)
        finally:
            tbl.setUpdatesEnabled(True)
        self._js8_rebuild_calls_table()

    @staticmethod
    def _js8_age_text(seconds):
        try:
            s = max(0, int(seconds))
        except Exception:
            return ""
        if s < 8:
            return "now"
        if s < 60:
            return f"{s}s"
        m = s // 60
        if m < 60:
            return f"{m}m"
        h = m // 60
        if h < 24:
            return f"{h}h"
        return f"{h//24}d"

    def _js8_update_activity_ages(self):
        now = time.time()
        try:
            for row in range(self.js8_band_table.rowCount()):
                it = self.js8_band_table.item(row, 0)
                if it is None:
                    continue
                h = it.data(Qt.UserRole) or {}
                age = self._js8_age_text(now - float(h.get("epoch", now)))
                age_it = self.js8_band_table.item(row, 1)
                if age_it is not None:
                    age_it.setText(age)
        except Exception:
            pass
        try:
            for row in range(self.js8_calls_table.rowCount()):
                it = self.js8_calls_table.item(row, 0)
                if it is None:
                    continue
                d = it.data(Qt.UserRole) or {}
                age = self._js8_age_text(now - float(d.get("epoch", now)))
                age_it = self.js8_calls_table.item(row, 1)
                if age_it is not None:
                    age_it.setText(age)
        except Exception:
            pass

    def _on_js8_automation_toggle(self, *_args):
        if getattr(self, "_loading_settings", False):
            return
        if getattr(self, "js8_hb_network_cb", None) is not None and self.js8_hb_network_cb.isChecked():
            minutes = int(self.js8_hb_interval_spin.value())
            self._js8_hb_next_epoch = time.time() + minutes * 60.0
            self.js8_auto_status.setText(f"Prochain HB dans {minutes} min")
        else:
            self._js8_hb_next_epoch = 0.0
            if hasattr(self, "js8_auto_status"):
                self.js8_auto_status.setText("Réseau HB arrêté")
        self._save_settings()

    def _on_js8_auto_option_changed(self, *_args):
        if getattr(self, "_loading_settings", False):
            return
        hb = bool(getattr(self, "js8_hb_network_cb", None) and self.js8_hb_network_cb.isChecked())
        ack = bool(getattr(self, "js8_hb_ack_cb", None) and self.js8_hb_ack_cb.isChecked())
        confirm = bool(getattr(self, "js8_auto_confirm_cb", None) and self.js8_auto_confirm_cb.isChecked())
        mode = "avec confirmation" if confirm else "envoi direct"
        if ack and not hb:
            self.js8_auto_status.setText(f"ACK automatique actif — {mode}")
        elif hb or ack:
            self.js8_auto_status.setToolTip(f"Automatismes actifs — {mode}")
        else:
            self.js8_auto_status.setText("Automatismes arrêtés")
        self._save_settings()

    def _stop_js8_automation(self):
        for name in ("js8_hb_network_cb", "js8_hb_ack_cb"):
            cb = getattr(self, name, None)
            if cb is not None:
                cb.setChecked(False)
        self._js8_hb_next_epoch = 0.0
        if hasattr(self, "js8_auto_status"):
            self.js8_auto_status.setText("Tous les automatismes sont arrêtés")
        self._save_settings()

    def _js8_auto_confirm(self, title, message):
        cb = getattr(self, "js8_auto_confirm_cb", None)
        if cb is None or not cb.isChecked():
            return True
        return QMessageBox.question(
            self, title, message,
            QMessageBox.Yes | QMessageBox.No, QMessageBox.No
        ) == QMessageBox.Yes

    def _js8_auto_tick(self):
        cb = getattr(self, "js8_hb_network_cb", None)
        if cb is None or not cb.isChecked():
            return
        minutes = max(1, int(self.js8_hb_interval_spin.value()))
        now = time.time()
        due = float(getattr(self, "_js8_hb_next_epoch", 0.0) or 0.0)
        if due <= 0.0:
            self._js8_hb_next_epoch = now + minutes * 60.0
            return
        remaining = max(0, int(math.ceil((due - now) / 60.0)))
        self.js8_auto_status.setText(f"Prochain HB dans {remaining} min")
        if now < due or getattr(self, "_tx_active", False):
            return
        # Reprogramme avant toute boîte de dialogue pour empêcher les doublons.
        self._js8_hb_next_epoch = now + minutes * 60.0
        if getattr(self, "_family", "") != "JS8":
            self.js8_auto_status.setText("HB en attente du mode JS8")
            return
        if not self._js8_auto_confirm("HB automatique", "Envoyer maintenant le Heartbeat JS8 ?"):
            self.js8_auto_status.setText(f"HB refusé — prochain dans {minutes} min")
            return
        self._prepare_js8_command("HB")
        self._start_tx()

    def _js8_maybe_ack_hits(self, hits):
        cb = getattr(self, "js8_hb_ack_cb", None)
        if cb is None or not cb.isChecked() or getattr(self, "_tx_active", False):
            return False
        now = time.time()
        mycall = (self._station_value("mycall_edit", "") or "").upper().strip()
        for hit in hits:
            text = f" {str(hit.get('text12', '') or '').upper()} "
            if str(hit.get("frame_name", "")).upper() != "HEARTBEAT" or " HB " not in text:
                continue
            call = str(hit.get("from_call", "") or self._js8_sender_from_hit(hit)).upper().strip()
            if not call or call == mycall:
                continue
            if now - float(self._js8_hb_ack_last.get(call, 0.0)) < 1800.0:
                continue
            self._js8_hb_ack_last[call] = now
            if not self._js8_auto_confirm("ACK Heartbeat", f"Répondre ACK au HB de {call} ?"):
                self.js8_auto_status.setText(f"ACK de {call} refusé")
                return False
            self._set_active_dxcall(call)
            self._prepare_js8_command("ACK")
            self.js8_auto_status.setText(f"ACK automatique vers {call}")
            self._start_tx()
            return True
        return False

    def _js8_maybe_log_reply(self, hits):
        """V8.4 F4LPS : logue automatiquement le QSO dès qu'une trame JS8
        dirigée (DIRECTED/COMPOUND_DIRECTED) nous répond — destinataire =
        notre indicatif. Ne commande jamais le PTT, seulement le log."""
        cb = getattr(self, "js8_reply_log_cb", None)
        if cb is None or not cb.isChecked():
            return False
        if getattr(self, "_family", "") != "JS8":
            return False
        now = time.time()
        mycall = (self._station_value("mycall_edit", "") or "").upper().strip()
        if not mycall:
            return False
        logged_any = False
        for hit in hits:
            fname = str(hit.get("frame_name", "")).upper()
            if fname not in ("DIRECTED", "COMPOUND_DIRECTED"):
                continue
            to_call = str(hit.get("to_call", "") or "").upper().strip()
            if to_call != mycall:
                continue
            call = str(hit.get("from_call", "") or self._js8_sender_from_hit(hit)).upper().strip()
            if not call or call == mycall:
                continue
            if now - float(self._js8_reply_log_last.get(call, 0.0)) < 600.0:
                continue
            self._js8_reply_log_last[call] = now
            self._set_active_dxcall(call)
            if self._auto_log_qso():
                self.js8_auto_status.setText(f"📋 QSO logué automatiquement : {call} a répondu")
                logged_any = True
        return logged_any

    def _prepare_js8_command(self, kind):
        """Prépare une commande JS8Call-like sans lancer l'émetteur."""
        kind = str(kind or "").strip().upper()
        mycall = (self._station_value("mycall_edit", "F4LPS") or "F4LPS").upper().strip()
        grid = (self._station_value("locator_edit", "") or
                self._station_value("locator", "")).upper().strip()
        dxcall = str(getattr(self, "_last_dxcall", "") or "").upper().strip()
        if not dxcall:
            try:
                dxcall = self.dx_call_combo.currentText().upper().strip()
            except Exception:
                dxcall = ""

        if kind in ("HB", "CQ"):
            text = f"[JS8:{kind}] {mycall}" + (f" {grid}" if grid else "")
        elif kind == "REPLY":
            if not dxcall:
                self._set_status("JS8 REPLY : sélectionnez d'abord un indicatif")
                return False
            text = f"{dxcall} "
        else:
            if not dxcall:
                self._set_status(f"JS8 {kind} : sélectionnez d'abord un indicatif")
                return False
            text = f"[JS8:DIR {kind}] {mycall} {dxcall}"
        try:
            self.tx_text.setPlainText(text)
            cursor = self.tx_text.textCursor()
            cursor.movePosition(cursor.End)
            self.tx_text.setTextCursor(cursor)
            self.tx_text.setFocus()
            self._update_preview()
            self._set_status(f"JS8 {kind} préparé — utilisez ÉMETTRE pour l'envoyer")
            return True
        except Exception:
            return False

    @staticmethod
    def _js8_sender_from_hit(h):
        call = str(h.get("from_call", "") or "").strip().upper()
        if call:
            return call
        txt = str(h.get("text12", "") or "").strip().upper()
        m = re.match(r"^([A-Z0-9/]{3,14})\s*:", txt)
        if m:
            return m.group(1)
        m = re.search(r"\b([A-Z]{1,3}[0-9][A-Z0-9]{1,4})\b", txt)
        return m.group(1) if m else ""

    def _js8_update_callsign_activity(self, h):
        call = self._js8_sender_from_hit(h)
        if not call:
            return
        txt = str(h.get("text12", "") or "").strip()
        comment = str(h.get("frame_name", "") or "").strip()
        if "HEARTBEAT" in txt.upper():
            comment = "HEARTBEAT"
        elif "CQ" in txt.upper():
            comment = "CQ"
        elif not comment or comment == "UNKNOWN":
            comment = txt[:48]
        self._js8_calls_activity[call] = {
            "call": call,
            "epoch": float(h.get("epoch", time.time())),
            "snr_db": float(h.get("snr_db", 0.0)),
            "freq_hz": float(h.get("freq_hz", 0.0)),
            "name": "",
            "comment": comment,
            "text12": txt,
        }

    def _js8_rebuild_calls_table(self):
        tbl = getattr(self, "js8_calls_table", None)
        if tbl is None:
            return
        vals = sorted(
            self._js8_calls_activity.values(),
            key=lambda d: float(d.get("epoch", 0.0)), reverse=True
        )[:200]
        tbl.setUpdatesEnabled(False)
        try:
            tbl.setRowCount(len(vals))
            now = time.time()
            for row, d in enumerate(vals):
                items = [
                    QTableWidgetItem(d.get("call", "")),
                    QTableWidgetItem(self._js8_age_text(now-float(d.get("epoch", now)))),
                    QTableWidgetItem(f"{float(d.get('snr_db',0.0)):+.0f} dB"),
                    QTableWidgetItem(f"{float(d.get('freq_hz',0.0)):.0f} Hz"),
                    QTableWidgetItem(d.get("name", "")),
                    QTableWidgetItem(d.get("comment", "")),
                ]
                for col, it in enumerate(items):
                    it.setData(Qt.UserRole, d)
                    tbl.setItem(row, col, it)
        finally:
            tbl.setUpdatesEnabled(True)

    def _js8_calls_row_data(self, row):
        try:
            it = self.js8_calls_table.item(row, 0)
            return it.data(Qt.UserRole) if it is not None else None
        except Exception:
            return None

    def _on_js8_calls_row_clicked(self, row, _col):
        d = self._js8_calls_row_data(row)
        if not d:
            return
        call = str(d.get("call", "") or "").strip().upper()
        if call:
            try:
                self._set_active_dxcall(call)
            except Exception:
                pass
        try:
            self.center_freq_spin.setValue(float(d.get("freq_hz", self.center_freq_spin.value())))
        except Exception:
            pass
        self._set_status(f"📡 JS8 OM sélectionné : {call} — {float(d.get('freq_hz',0.0)):.0f} Hz")

    def _on_js8_calls_row_double_clicked(self, row, _col):
        d = self._js8_calls_row_data(row)
        if not d:
            return
        self._on_js8_calls_row_clicked(row, _col)
        call = str(d.get("call", "") or "").strip().upper()
        if call:
            try:
                cur = self.tx_text.toPlainText().strip()
                if not cur:
                    self.tx_text.setPlainText(f"{call} ")
                    c = self.tx_text.textCursor()
                    c.movePosition(c.End)
                    self.tx_text.setTextCursor(c)
            except Exception:
                pass

    def _js8_row_hit(self, row):
        it = self.js8_band_table.item(row, 0)
        if it is None:
            return None
        return it.data(Qt.UserRole)

    @staticmethod
    def _js8_guess_callsign(text12):
        """Extraction indicatif au mieux depuis la chaine brute 12 car.
        ⚠ Provisoire : tant que le decodage humain JS8 (unpack73-style,
        callsigns/grid/texte libre selon i3) n'est pas implemente, le
        'message' est la chaine base-64 brute des 72 bits — pas du texte
        JS8 reel. On tente juste un motif indicatif plausible dedans."""
        m = re.search(r'[A-Z0-9]{0,3}[A-Z][0-9][A-Z]{1,4}', text12.upper())
        return m.group(0) if m else ""

    def _on_js8_band_row_clicked(self, row, _col):
        """Clic simple : bascule sur la variante detectee, cale le RX
        Center sur le signal, et tente de remplir l'indicatif (best-effort,
        voir _js8_guess_callsign)."""
        h = self._js8_row_hit(row)
        if not h:
            return

        # V8.3.56 : la variante detectee (NORMAL/FAST/SLOW/40) doit devenir
        # le mode actif, sinon le decodeur mono-signal continuera a
        # chercher avec les mauvais parametres (tone_spacing, frame_s...)
        # meme une fois la frequence reglee.
        variant = h.get("variant")
        if variant and hasattr(self, "mode_combo"):
            try:
                if self.mode_combo.currentText() != variant:
                    self.mode_combo.setCurrentText(variant)
            except Exception:
                pass

        try:
            self._on_wf_click(float(h["freq_hz"]))
        except Exception:
            pass

        guess = self._js8_guess_callsign(h["text12"])
        if guess:
            try:
                self.dx_call_combo.blockSignals(False)
                self.dx_call_combo.lineEdit().setText(guess)
                self._set_active_dxcall(guess, from_combo=True)
            except Exception:
                pass
            self._set_status(
                f"📥 JS8 {variant} {h['freq_hz']:.0f} Hz — indicatif probable {guess} "
                f"(extraction brute, à confirmer)"
            )
        else:
            self._set_status(
                f"📥 JS8 {variant} {h['freq_hz']:.0f} Hz — message brut {h['text12']!r} "
                f"(décodage humain JS8 pas encore implémenté)"
            )

    def _on_js8_band_row_double_clicked(self, row, _col):
        """Double-clic : en plus des actions du simple clic, insere une
        macro de reponse dans TEXTE A EMETTRE. Comme le message n'est pas
        encore un vrai texte JS8 humain (cf. _js8_guess_callsign), la
        macro reste generique tant que la phase 2 (unpack) n'est pas la."""
        self._on_js8_band_row_clicked(row, _col)
        h = self._js8_row_hit(row)
        if not h:
            return
        mycall = self._station_value('mycall_edit', 'F4LPS').upper() if hasattr(self, '_station_value') else 'F4LPS'
        guess = self._js8_guess_callsign(h["text12"])
        target = guess if guess else "??"
        reply = f"{target} DE {mycall} RSNR {h['snr_db']:+.0f}DB K"
        try:
            self.tx_text.setPlainText(reply)
        except Exception:
            pass
        self._set_status(f"✉️ Réponse préparée pour {target} — à vérifier avant émission")

    # ------------------------------------------------------------------
    # V8.3.59 F4LPS : auto-test JS8 contre les .wav de reference officiels
    # (depot js8call/js8call, media/tests/). Chaque fichier est nomme
    # MODE_DEPTH_EXPECTED.wav (ex: A_2_9.wav = mode Normal, 9 signaux
    # attendus) ; on compare le nombre de signaux realement decodes par
    # notre JS8BandDecoder au nombre attendu, pour verifier que le moteur
    # fonctionne toujours correctement sans dependre d'un enregistrement
    # radio reel a chaque fois.
    # ------------------------------------------------------------------
    def _find_js8_test_suite_dir(self):
        candidates = []
        try:
            candidates.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), "js8_test_suite"))
        except Exception:
            pass
        try:
            candidates.append(os.path.join(os.path.dirname(sys.argv[0]), "js8_test_suite"))
        except Exception:
            pass
        candidates.append(os.path.join(os.getcwd(), "js8_test_suite"))
        for c in candidates:
            if c and os.path.isdir(c):
                return c
        return None

    def _run_js8_selftest(self):
        test_dir = self._find_js8_test_suite_dir()
        if test_dir is None:
            test_dir = QFileDialog.getExistingDirectory(
                self, "Dossier contenant les .wav de test JS8 (js8_test_suite)"
            )
            if not test_dir:
                return

        files = sorted(f for f in os.listdir(test_dir) if f.lower().endswith(".wav"))
        if not files:
            QMessageBox.warning(
                self, "Auto-test JS8",
                f"Aucun fichier .wav trouvé dans :\n{test_dir}"
            )
            return

        mode_map = {"A": "JS8 NORMAL", "B": "JS8 FAST", "C": "JS8 40", "E": "JS8 SLOW"}
        lines = []
        total_expected = 0
        total_found = 0
        n_files_ok = 0

        self._set_status("🧪 Auto-test JS8 en cours…")
        QApplication.processEvents()

        for fname in files:
            base = fname[:-4]
            parts = base.split("_")
            if len(parts) != 3 or parts[0] not in mode_map:
                lines.append(f"{fname} : nom non reconnu, ignoré")
                continue
            mode_letter, _depth, expected_s = parts
            try:
                expected = int(expected_s)
            except ValueError:
                lines.append(f"{fname} : nombre attendu illisible, ignoré")
                continue
            mode_name = mode_map[mode_letter]

            path = os.path.join(test_dir, fname)
            try:
                wf = wave.open(path, "rb")
                sr = wf.getframerate()
                raw = wf.readframes(wf.getnframes())
                audio = np.frombuffer(raw, dtype="<i2").astype(np.float32) / 32768.0
            except Exception as exc:
                lines.append(f"{fname} : erreur lecture ({exc})")
                continue

            try:
                core = JS8RXDecoder(sample_rate=sr, mode=mode_name)
                band = JS8BandDecoder(core, band_lo_hz=100.0, band_hi_hz=3000.0)
                hits = band.decode_cycle(audio, snapshot_epoch=time.time())
            except Exception as exc:
                lines.append(f"{fname} : erreur décodage ({exc})")
                continue

            found = len(hits)
            total_expected += expected
            total_found += found
            ok = found >= max(1, expected * 0.5)  # tolerant : au moins la moitie
            if ok:
                n_files_ok += 1
            marker = "✅" if found == expected else ("🟡" if ok else "❌")
            lines.append(f"{marker} {fname} ({mode_name}) : {found}/{expected} décodé(s)")

        summary = (
            f"Auto-test JS8 — {test_dir}\n\n"
            + "\n".join(lines)
            + f"\n\n{'—'*40}\n"
            f"Total : {total_found}/{total_expected} signaux décodés sur {len(files)} fichiers\n"
            f"Fichiers avec au moins la moitié des signaux attendus : {n_files_ok}/{len(files)}"
        )

        self._set_status(
            f"🧪 Auto-test JS8 terminé : {total_found}/{total_expected} signaux décodés"
        )

        dlg = QMessageBox(self)
        dlg.setWindowTitle("Auto-test JS8 — résultats")
        dlg.setText(summary)
        dlg.setTextInteractionFlags(Qt.TextSelectableByMouse)
        dlg.exec_()

    def _qsy(self, freq_hz):
        if self.radio_ctrl.connected: self.radio_ctrl.set_frequency(freq_hz)
        self._current_freq_hz = freq_hz
        self.freq_display.setText(f"{freq_hz/1e6:.4f}  MHz")
        self._set_status(f"📻 QSY → {freq_hz/1e6:.4f} MHz")

    def _update_preview(self):
        text = self.tx_text.toPlainText()
        n    = len(text)
        self.preview_len.setText(f"{n} car.")
        mode = self.mode_combo.currentText()
        if getattr(self, '_family', 'PSK') == 'JS8':
            try:
                expanded, _do_log, _stop = self._process_macro_tags(
                    self._expand_macro(text)
                )
                frames = len(JS8TXEncoder._pack_message_frames(expanded)) if expanded else 0
                params = JS8_MODES.get(mode, JS8_MODES['JS8 NORMAL'])
                duration = (frames * float(params['tx_s'])
                            + max(0, frames - 1) * (float(params['frame_s']) - float(params['tx_s'])))
                self.preview_dur.setText(f"≈ {duration:.1f} s / {frames} trame" + ("s" if frames != 1 else ""))
            except Exception:
                self.preview_dur.setText("⛔ texte JS8 incompatible")
            return
        if getattr(self, '_family', 'PSK') == 'CW':
            try:
                # PARIS = 50 unités par mot standard ; estimation lisible pour l'OM.
                wpm = max(5.0, float(getattr(self, '_cw_tx_wpm', 20)))
                words_equiv = max(0.0, n / 5.0)
                dur = words_equiv * 60.0 / wpm
                self.preview_dur.setText(f"≈ {dur:.1f} s à {wpm:.0f} WPM")
            except Exception:
                self.preview_dur.setText("— s")
            return
        p    = PSK_MODES.get(mode,{})
        baud = p.get('baud',31.25)
        if baud > 0:
            # Estimation : chaque char ≈ 10 bits varicode en moyenne
            dur = n * 10 / baud
            self.preview_dur.setText(f"≈ {dur:.1f} s")

    # ── Macros ────────────────────────────────────────────────────────────────

    def _macro_edit(self, idx, text): self._macros[idx] = text

    def _current_rst_sent(self):
        """RST envoyé : priorité au champ visible Send, sinon log."""
        try:
            w = getattr(self, 'rst_send_combo', None)
            if w is not None:
                v = w.currentText().strip()
                if v:
                    return v.upper().replace('N', '9') if v.upper() == '5NN' else v.upper()
        except Exception:
            pass
        try:
            return (self.log_rst_s.text().strip() or '599')
        except Exception:
            return '599'

    def _current_rst_recv(self):
        """RST reçu : priorité au champ visible Recv, sinon log ou détection RX."""
        try:
            w = getattr(self, 'rst_recv_combo', None)
            if w is not None:
                v = w.currentText().strip()
                if v:
                    return v.upper().replace('N', '9') if v.upper() == '5NN' else v.upper()
        except Exception:
            pass
        try:
            v = self.log_rst_r.text().strip()
            if v:
                return v
        except Exception:
            pass
        return getattr(self, '_dx_rst', '') or '599'

    def _on_main_rst_changed(self):
        """Synchronise les champs RST visibles avec l'onglet LOG si déjà créé."""
        try:
            s = self._current_rst_sent()
            r = self._current_rst_recv()
            if hasattr(self, 'log_rst_s') and self.log_rst_s.text().strip() != s:
                self.log_rst_s.setText(s)
            if hasattr(self, 'log_rst_r') and self.log_rst_r.text().strip() != r:
                self.log_rst_r.setText(r)
        except Exception:
            pass

    def _expand_macro(self, text):
        import datetime
        now=datetime.datetime.utcnow(); h=now.hour
        greet="GN" if h<6 else "GM" if h<12 else "GA" if h<18 else "GE"
        _combo_txt = self.dx_call_combo.lineEdit().text().strip() if hasattr(self,'dx_call_combo') else ''
        dxcall = (getattr(self,'_last_dxcall','') or _combo_txt or self._station_value('log_call','')).upper().strip() or 'DXCALL'
        dx_name=(getattr(self,'dx_name_edit',None) and self.dx_name_edit.text().strip()) or getattr(self,'_dx_name','') or self._station_value('log_name','') or 'OM'
        freq_hz=float(getattr(self,'_current_freq_hz',0)or 0)
        freq_mhz=f"{freq_hz/1e6:.3f}" if freq_hz>1e6 else "?"
        band="?"
        for lo,hi,b in [(1800000,2000000,"160m"),(3500000,4000000,"80m"),(7000000,7300000,"40m"),(10100000,10150000,"30m"),(14000000,14350000,"20m"),(18068000,18168000,"17m"),(21000000,21450000,"15m"),(24890000,24990000,"12m"),(28000000,29700000,"10m"),(50000000,54000000,"6m")]:
            if lo<=freq_hz<=hi: band=b; break
        try: mode=self.mode_combo.currentText().strip()
        except: mode="BPSK31"
        rst_s=self._current_rst_sent()
        rst_r=self._current_rst_recv()
        repl={
            "{MYCALL}":(self._station_value('mycall_edit','F4LPS')or'F4LPS').upper(),
            "{DXCALL}":dxcall,"{CALL}":dxcall,
            "{DXNAME}":dx_name, "{FIRSTNAME}":dx_name, "{PRENOM}":dx_name,
            "{DXQTH}":getattr(self,'_dx_qth','')or'?',
            "{DXLOC}":getattr(self,'_dx_locator','')or'?',
            "{DISTANCE}": (f"{getattr(self,'_dx_distance_km',None):.0f}km" if getattr(self,'_dx_distance_km',None) is not None else '?'),
            "{AZIMUT}": (f"{getattr(self,'_dx_azimuth_deg',None):.0f}°" if getattr(self,'_dx_azimuth_deg',None) is not None else '?'),
            "{AZIMUTH}": (f"{getattr(self,'_dx_azimuth_deg',None):.0f}°" if getattr(self,'_dx_azimuth_deg',None) is not None else '?'),
            "{DXRST}":rst_r,
            "{RST}":rst_s,"{RST_TX}":rst_s,"{RST_SENT}":rst_s,"{RSTS}":rst_s,
            "{RST_RX}":rst_r,"{RST_RCVD}":rst_r,"{RSTR}":rst_r,
            "{NAME}":self._station_value('op_name_edit','').strip(),
            "{QTH}":self._station_value('qth_edit','').strip(),
            "{LOCATOR}":self._station_value('locator_edit','').upper().strip(),
            "{POWER}":self._station_value('power_edit','').strip() or '?',
            "{ANTENNA}":self._station_value('antenna_edit','').strip() or '?',
            "{RIG}":self._station_value('rig_edit','').strip() or '?',
            "{LICENCE}":self._station_value('licence_edit','').strip() or '?',
            "{AGE}":self._station_value('created_edit','').strip() or '?',
            "{QSL}":self._station_value('qsl_edit','').strip() or '?',
            "{EMAIL}":self._station_value('email_edit','').strip(),
            "{OP}":self._station_value('op_name_edit','').strip(),
            "{OPERATOR}":self._station_value('op_name_edit','').strip(),
            "{STATION}":self._station_value('qth_edit','').strip(),
            "{SOFTWARE}": "MultiDigi by F4LPS",
            "{PROGRAM}": "MultiDigi by F4LPS",
            "{INFO}": self._station_value('info_edit','').strip(),
            "{FREQ}":freq_mhz,"{BAND}":band,"{MODE}":mode,
            "{DATE}":now.strftime("%Y-%m-%d"),"{TIME}":now.strftime("%H%MZ"),"{UTC}":now.strftime("%H%MZ"),
            "{LOGGED}": self._f4lps_qso_logged_tx_line(now) if hasattr(self, '_f4lps_qso_logged_tx_line') else now.strftime("QSO LOGGED  %d %b %Y  TIME %H:%M:%SZ").upper(),
            "{QSO_LOGGED}": self._f4lps_qso_logged_tx_line(now) if hasattr(self, '_f4lps_qso_logged_tx_line') else now.strftime("QSO LOGGED  %d %b %Y  TIME %H:%M:%SZ").upper(),
            "{GREET}":greet,"{SERNR}":f"{getattr(self,'_sernr',1):03d}",
        }
        for k,v in repl.items(): text=text.replace(k,str(v))
        return text
    def _f4lps_qso_logged_tx_line(self, when_utc=None):
        """Ligne QSO LOGGED envoyée à l'OM par la macro 73+Log."""
        try:
            import datetime as _dt
            dt = when_utc or _dt.datetime.utcnow()
            return dt.strftime("QSO LOGGED  %d %b %Y  TIME %H:%M:%SZ").upper()
        except Exception:
            return "QSO LOGGED"

    def _process_macro_tags(self, text):
        do_log = "<add-log>" in text
        # V1.6.122 F4LPS : <add-log> ne sert plus seulement à logger localement.
        # Il insère aussi une ligne DM780 dans le texte TX, donc visible chez l'OM.
        # Exemple reçu par l'OM : QSO LOGGED  28 JUN 2026  TIME 11:26:55Z
        if do_log:
            try:
                logged_line = self._f4lps_qso_logged_tx_line()
            except Exception:
                logged_line = "QSO LOGGED"
            # On évite un doublon si l'utilisateur a déjà écrit la ligne dans la macro.
            if "QSO LOGGED" not in str(text).upper():
                text = text.replace("<add-log>", logged_line + "\n")
            else:
                text = text.replace("<add-log>", "")
        else:
            text = text.replace("<add-log>", "")
        stop = "<stop>" in text
        text = text.replace("<stop>", "")
        return text.strip(), do_log, stop

    def _show_emission_tab_ready(self):
        """Affiche l’onglet ÉMISSION et place le curseur dans la zone TX."""
        try:
            if hasattr(self, 'main_tabs') and self.main_tabs is not None:
                self.main_tabs.setCurrentIndex(0)
            if hasattr(self, 'tx_text') and self.tx_text is not None:
                self.tx_text.setFocus()
                self.tx_text.moveCursor(QTextCursor.End)
            self._update_preview()
        except Exception as e:
            print(f"⚠️ Macro retour émission ignoré: {e}")

    def _copy_macro_to_tx(self, idx):
        raw=self._macros[idx] if idx<len(self._macros) else ""
        if not raw: return
        text,do_log,_=self._process_macro_tags(self._expand_macro(raw))
        self.tx_text.setPlainText(text); self._show_emission_tab_ready()
        if do_log: self._auto_log_qso()
        name=self._macro_names[idx] if hasattr(self,'_macro_names') and idx<len(self._macro_names) else f"F{idx+1}"
        self._set_status(f"📋 Macro [{name}] copiée dans TX")
    def _send_macro(self, idx):
        raw=self._macros[idx] if idx<len(self._macros) else ""
        if not raw: return
        text,do_log,stop=self._process_macro_tags(self._expand_macro(raw))
        self.tx_text.setPlainText(text); self._show_emission_tab_ready()
        if do_log: self._auto_log_qso()
        self._start_tx()
        if stop:
            if getattr(self, '_family', '') == 'JS8':
                # Une trame JS8 se termine d'elle-meme. L'ancien minuteur
                # PSK31 couperait l'audio avant la fin des 79 symboles.
                return
            try: baud=31.25 if "31" in self.mode_combo.currentText() else 63.0
            except: baud=31.25
            QTimer.singleShot(max(500,int(len(text)/baud*1000)+500), self._stop_tx_after_macro)
        if hasattr(self,'_sernr') and "{SERNR}" in raw: self._sernr+=1

    def _stop_tx_after_macro(self):
        try: self._stop_tx()
        except: pass

    def _rx_insert_qso_logged_dm780(self, when_utc=None, call=''):
        """Affiche dans la fenêtre RX une confirmation de log façon DM780."""
        try:
            import datetime as _dt
            dt = when_utc or _dt.datetime.utcnow()
            if hasattr(dt, 'strftime'):
                line = dt.strftime("QSO LOGGED  %d %b %Y  TIME %H:%M:%SZ").upper()
            else:
                line = "QSO LOGGED"
            # Évite les doublons si la macro est cliquée deux fois très vite.
            last = getattr(self, '_last_qso_logged_rx_line', '')
            last_t = float(getattr(self, '_last_qso_logged_rx_time', 0.0) or 0.0)
            if line == last and time.time() - last_t < 3.0:
                return
            self._last_qso_logged_rx_line = line
            self._last_qso_logged_rx_time = time.time()

            cur = self.rx_text.textCursor()
            cur.movePosition(QTextCursor.End)

            fmt = QTextCharFormat()
            fmt.setForeground(QColor(255, 235, 90))
            try:
                fmt.setFontWeight(QFont.Bold)
            except Exception:
                pass

            # Ligne DM780 courte et visible.
            cur.setCharFormat(fmt)
            cur.insertText(("\n" if self.rx_text.toPlainText().strip() else "") + line + "\n")

            # Revenir au format normal RX pour le texte suivant.
            normal = QTextCharFormat()
            try:
                normal.setForeground(self._RX_C_TEXT)
            except Exception:
                normal.setForeground(QColor(230, 230, 230))
            cur.setCharFormat(normal)
            self.rx_text.setTextCursor(cur)
            self.rx_text.ensureCursorVisible()
        except Exception as e:
            try:
                print(f"⚠️ QSO LOGGED RX ignoré: {e}")
            except Exception:
                pass

    def _auto_log_qso(self):
        """Enregistre réellement le QSO quand la macro contient <add-log>.

        V1.6.123 F4LPS : le bouton 73+Log utilisait seulement _last_dxcall/log_call.
        Si le CALL était saisi dans le champ principal en haut, le log pouvait être ignoré.
        Ici on reprend la même source fiable que le bouton LOG QSO : _active_dxcall_for_log().
        """
        try:
            # Source CALL unique : champ CALL haut RX -> _last_dxcall -> champ Log QSO.
            try:
                call = self._active_dxcall_for_log()
            except Exception:
                call = ''
            if not call:
                call = (getattr(self, '_last_dxcall', '') or self._station_value('log_call', '')).strip().upper()
            if not call:
                try:
                    self._set_status("⚠️ 73+Log : aucun indicatif DX, QSO non logué")
                except Exception:
                    pass
                return False

            import datetime
            now = datetime.datetime.utcnow()
            freq_hz = float(getattr(self, '_current_freq_hz', 0) or 0)
            try:
                rst_s = self._current_rst_sent()
                rst_r = self._current_rst_recv()
            except Exception:
                rst_s = self._station_value('log_rst_s', '599') or '599'
                rst_r = self._station_value('log_rst_r', '599') or '599'
            mode = self.mode_combo.currentText() if hasattr(self, 'mode_combo') else "BPSK31"
            name = ''
            try:
                name = (getattr(self, 'dx_name_edit', None) and self.dx_name_edit.text().strip()) or self._station_value('log_name', '')
            except Exception:
                name = ''

            entry = {
                "datetime": now.strftime("%Y-%m-%d %H:%M"),
                "call": call.upper(),
                "name": name,
                "rst_s": rst_s,
                "rst_r": rst_r,
                "mode": mode,
                "freq_hz": freq_hz,
            }

            if not hasattr(self, '_qso_list_local'):
                self._qso_list_local = []

            # Anti-doublon : évite deux lignes si on appuie deux fois très vite.
            last_t = float(getattr(self, '_last_auto_log_time', 0.0) or 0.0)
            last_call = str(getattr(self, '_last_auto_log_call', '') or '').upper()
            if last_call == entry["call"] and time.time() - last_t < 2.0:
                return True
            self._last_auto_log_call = entry["call"]
            self._last_auto_log_time = time.time()

            self._qso_list_local.append(entry)

            # Alimente aussi les champs du Log QSO si l'onglet existe.
            try:
                if hasattr(self, 'log_call'):
                    self.log_call.setText(entry["call"])
                if hasattr(self, 'log_name') and name:
                    self.log_name.setText(name)
                if hasattr(self, 'log_rst_s'):
                    self.log_rst_s.setText(rst_s)
                if hasattr(self, 'log_rst_r'):
                    self.log_rst_r.setText(rst_r)
            except Exception:
                pass

            if hasattr(self, 'qso_table'):
                row = self.qso_table.rowCount()
                self.qso_table.insertRow(row)
                from PyQt5.QtWidgets import QTableWidgetItem
                self.qso_table.setItem(row, 0, QTableWidgetItem(entry["datetime"]))
                self.qso_table.setItem(row, 1, QTableWidgetItem(entry["call"]))
                self.qso_table.setItem(row, 2, QTableWidgetItem(entry["rst_s"]))
                self.qso_table.setItem(row, 3, QTableWidgetItem(entry["rst_r"]))
                self.qso_table.setItem(row, 4, QTableWidgetItem(entry["mode"]))
                self.qso_table.setItem(row, 5, QTableWidgetItem(f"{freq_hz/1e6:.4f}" if freq_hz > 1e6 else "?"))

            self._set_status(f"📋 QSO logué : {entry['call']}")

            # V8.3.11 F4LPS : logique Tracker voulue par l'opérateur :
            #   - clic sur CALL bleu  -> spot / correspondant en cours ;
            #   - macro 73+Log       -> transforme/ajoute ce contact en vrai QSO ;
            #   - validation HRD/eQSL/QRZ/LoTW -> aucun nouvel envoi Tracker.
            # Le QSO est injecté directement dans le Tracker intégré afin de ne pas
            # dépendre du port UDP. L'UDP reste seulement un secours externe.
            try:
                qso_payload = {
                    'type': 'qso',
                    'program': 'MultiDigi',
                    'time_utc': now.strftime('%Y-%m-%dT%H:%M:%SZ'),
                    'my_call': (self.mycall_edit.text().strip().upper() if hasattr(self, 'mycall_edit') else ''),
                    'dx_call': entry['call'],
                    'mode': str(entry['mode'] or '').strip().upper(),
                    'freq_hz': int(float(entry['freq_hz'] or 0)),
                    'band': '',
                    'dx_grid': str(getattr(self, '_dx_locator', '') or '').strip().upper(),
                    'dx_lat': getattr(self, '_dx_lat', None),
                    'dx_lon': getattr(self, '_dx_lon', None),
                    'dx_country': str(getattr(self, '_dx_country', '') or ''),
                    'rst_sent': str(entry['rst_s'] or ''),
                    'rst_recv': str(entry['rst_r'] or ''),
                }
                try:
                    fmhz = float(qso_payload['freq_hz']) / 1e6
                    if 1.8 <= fmhz < 2.1: qso_payload['band'] = '160m'
                    elif 3.4 <= fmhz < 4.1: qso_payload['band'] = '80m'
                    elif 5.0 <= fmhz < 5.6: qso_payload['band'] = '60m'
                    elif 6.8 <= fmhz < 7.4: qso_payload['band'] = '40m'
                    elif 10.0 <= fmhz < 10.2: qso_payload['band'] = '30m'
                    elif 13.9 <= fmhz < 14.5: qso_payload['band'] = '20m'
                    elif 18.0 <= fmhz < 18.3: qso_payload['band'] = '17m'
                    elif 20.9 <= fmhz < 21.6: qso_payload['band'] = '15m'
                    elif 24.8 <= fmhz < 25.1: qso_payload['band'] = '12m'
                    elif 27.9 <= fmhz < 30.0: qso_payload['band'] = '10m'
                except Exception:
                    pass

                tracker_ok = False
                try:
                    win = getattr(self, '_grid_tracker_win', None)
                    if win is None:
                        win = GridTrackerWindow()
                        self._grid_tracker_win = win
                    win._on_packet(dict(qso_payload))
                    tracker_ok = True
                except Exception as _te:
                    try:
                        print(f"⚠️ 73+Log Tracker direct: {_te}")
                    except Exception:
                        pass

                # Secours : si le Tracker intégré ne peut pas être alimenté,
                # tenter l'ancien paquet QSO UDP, sans jamais faire les deux.
                if not tracker_ok:
                    try:
                        tracker_ok = bool(self._wsjt_udp_send_qso(
                            entry['call'], entry['rst_s'], entry['rst_r'],
                            entry['mode'], entry['freq_hz'], now))
                    except Exception:
                        tracker_ok = False

                if tracker_ok:
                    self._set_status(f"✅ 73+Log : {entry['call']} inscrit dans le Tracker")
                else:
                    self._set_status(f"⚠️ 73+Log : QSO logué mais Tracker non alimenté ({entry['call']})")
            except Exception as e:
                try:
                    print(f"⚠️ 73+Log Tracker: {e}")
                except Exception:
                    pass

            try:
                self._rx_insert_qso_logged_dm780(now, entry["call"])
            except Exception:
                pass
            return True
        except Exception as e:
            print(f"⚠️ _auto_log_qso: {e}")
            return False
    def _toggle_cat(self):
        if self.radio_ctrl.connected:
            self.radio_ctrl.disconnect()
            self.cat_status.setText("Déconnecté")
            self.cat_status.setStyleSheet("color:#ff6644;font-weight:bold;")
            self.btn_cat.setText("🔗 CONNECTER")
        else:
            port  = self.cat_port_combo.currentData() or self.cat_port_combo.currentText().split(" ")[0]
            baud  = int(self.cat_baud_combo.currentText())
            proto = 'icom' if 'Icom' in self.cat_proto_combo.currentText() else 'yaesu'
            at    = self.civ_combo.currentText()
            addr  = int(at.split("x")[1].split(" ")[0],16) if "0x" in at else 0x94
            ok,msg = self.radio_ctrl.connect_serial(port,baud,proto,addr)
            if ok:
                self.cat_status.setText(f"✅ {msg}")
                self.cat_status.setStyleSheet("color:#00ff66;font-weight:bold;")
                self.btn_cat.setText("🔌 DÉCONNECTER")
                self._restart_freq_poll()
            else:
                QMessageBox.critical(self,"Erreur CAT",msg)

    def _toggle_omnirig(self):
        if self.radio_ctrl.connection_type == 'omnirig':
            self.radio_ctrl.disconnect()
            self.omnirig_status.setText("Déconnecté")
            self.omnirig_status.setStyleSheet("color:#ff6644;font-size:8pt;")
