            (7040000, "40m", "40m EU 7.040"),
            (10142000, "30m", "30m 10.142"),
            (14070000, "20m", "20m 14.070"),
            (14071500, "20m", "20m 14.0715"),
            (18100000, "17m", "17m 18.100"),
            (21080000, "15m", "15m 21.080"),
