    def _active_dxcall_for_log(self):
        """CALL actif unique : champ CALL haut RX → _last_dxcall → champ LOG.
        C'est cette valeur qui alimente HRD, QRZ.com et les autres loggers.
        """
        vals = []
        try:
            if hasattr(self, 'dx_call_combo'):
                vals.append(self.dx_call_combo.lineEdit().text().strip().upper())
        except Exception:
            pass
        vals.append(str(getattr(self, '_last_dxcall', '') or '').strip().upper())
        try:
            vals.append(self.log_call.text().strip().upper())
        except Exception:
            pass
        for c in vals:
            if c and c not in ('F4XXX','DXCALL'):
                return c
        return ''

    def _open_qso_log_dialog(self):
        call   = self._active_dxcall_for_log() or "F4XXX"
        try:
            if hasattr(self, 'log_call') and call != "F4XXX":
                self.log_call.setText(call)
        except Exception:
            pass
        rst_s  = self._current_rst_sent()
        rst_r  = self._current_rst_recv()
        name   = (getattr(self, 'dx_name_edit', None) and self.dx_name_edit.text().strip()) or self.log_name.text().strip()
        freq_hz = self._current_freq_hz
        # V8.3.11 F4LPS : journaliser le mode réellement actif.
        # Avant, cette valeur était forcée à PSK31 même en Olivia/Contestia/etc.
        try:
            mode = self.mode_combo.currentText().strip() or "BPSK31"
        except Exception:
            mode = "BPSK31"
        mycall = self.mycall_edit.text().strip().upper() if hasattr(self, 'mycall_edit') else "F4LPS"

        dlg = QSOLogDialog(self, call, rst_s, rst_r, name, freq_hz, mode, mycall)
        dlg.show()

        if call != "F4XXX":
            from datetime import datetime as _dt
            now = _dt.utcnow()
            entry = {"datetime": now.strftime("%Y-%m-%d %H:%M"), "call": call,
                     "rst_s": rst_s, "rst_r": rst_r, "mode": mode, "freq_hz": freq_hz}
            self._qso_list_local.append(entry)
            row = self.qso_table.rowCount()
            self.qso_table.insertRow(row)
            self.qso_table.setItem(row, 0, QTableWidgetItem(entry["datetime"]))
            self.qso_table.setItem(row, 1, QTableWidgetItem(call))
            self.qso_table.setItem(row, 2, QTableWidgetItem(rst_s))
            self.qso_table.setItem(row, 3, QTableWidgetItem(rst_r))
            self.qso_table.setItem(row, 4, QTableWidgetItem(mode))
            self.qso_table.setItem(row, 5, QTableWidgetItem(f"{freq_hz/1e6:.4f}" if freq_hz else "—"))
            # V8.3.11 F4LPS : le journal/loggers n'envoient plus le QSO au Tracker.
            # Le Tracker est alimenté uniquement par un clic volontaire sur le CALL RX bleu.
            self.log_call.clear(); self.log_name.clear()

    def _export_log_adif(self):
        if not getattr(self, '_qso_list_local', []):
            QMessageBox.information(self, "ADIF", "Aucun QSO à exporter.")
            return
        from datetime import datetime as _dt
        path, _ = QFileDialog.getSaveFileName(
            self, "Export ADIF", f"MultiDigi_{_dt.utcnow().strftime('%Y%m%d')}.adi",
            "ADIF (*.adi *.adif)"
        )
        if not path:
            return
        def af(t, v): v = str(v) if v else ""; return f"<{t}:{len(v)}>{v}"
        with open(path, "w", encoding="utf-8") as f:
            f.write("MultiDigi V1.6 F4LPS\n<ADIF_VER:5>3.1.4 <EOH>\n")
            for q in self._qso_list_local:
                dt = q["datetime"].replace("-","").replace(" ","").replace(":","")
                qmode = str(q.get("mode", "BPSK31") or "BPSK31").strip()
                f.write(af("CALL", q["call"]) + af("QSO_DATE", dt[:8])
                        + af("TIME_ON", dt[8:12]) + af("MODE", qmode)
                        + af("RST_SENT", q["rst_s"]) + af("RST_RCVD", q["rst_r"])
                        + (af("FREQ", f"{q['freq_hz']/1e6:.4f}") if q["freq_hz"] else "")
                        + "<EOR>\n")
        QMessageBox.information(self, "ADIF", f"Fichier exporté :\n{path}")

    def closeEvent(self, event):
        self._save_settings(); self._stop_rx()
        if self.tx_thread: self.tx_thread.abort(); self.tx_thread.wait(2000)
        if self.prop_thread: self.prop_thread.stop(); self.prop_thread.wait(2000)
        t = getattr(self,'_freq_poll_thread',None)
        if t: t.stop(); t.wait(1000)
        if self.radio_ctrl.connected: self.radio_ctrl.disconnect()
        event.accept()



