from PyQt5.QtGui import QPainter, QColor, QFont, QPen, QBrush, QIcon, QKeySequence

try:
    from PyQt5.QtWebChannel import QWebChannel
    HAVE_WEBCHANNEL = True
except Exception:
    HAVE_WEBCHANNEL = False

def _ensure_webengine_installed():
    """Tente d'installer PyQtWebEngine automatiquement au premier lancement
    s'il est absent, pour éviter à l'utilisateur de taper une commande pip.
    Retourne True si le module est disponible après tentative (déjà présent
    ou installé avec succès), False sinon (ex: pas d'internet)."""
    try:
        import PyQt5.QtWebEngineWidgets  # noqa
        return True
    except Exception:
        pass
    try:
        import subprocess
        print(f"[{PROGRAM_NAME}] PyQtWebEngine absent — installation automatique en cours (une seule fois)…")
        base_cmd = [sys.executable, "-m", "pip", "install", "--quiet", "--disable-pip-version-check", "PyQtWebEngine"]
        try:
            subprocess.run(base_cmd, check=True, timeout=300)
        except subprocess.CalledProcessError:
            # Python "externally-managed" (courant sur Linux récent) : on retente
            # avec l'option d'override, sans risque particulier ici (venv/utilisateur).
            subprocess.run(base_cmd + ["--break-system-packages"], check=True, timeout=300)
        import importlib
        importlib.invalidate_caches()
        import PyQt5.QtWebEngineWidgets  # noqa
        print(f"[{PROGRAM_NAME}] PyQtWebEngine installé avec succès.")
        return True
    except Exception as e:
        print(f"[{PROGRAM_NAME}] Installation automatique de PyQtWebEngine impossible ({e}). "
              f"Carte réelle indisponible — bascule sur la grille Maidenhead. "
              f"Vous pouvez installer manuellement avec : {sys.executable} -m pip install PyQtWebEngine")
        return False


