def multidigi_get_my_grid(default="JN28TJ"):
    """Lit le locator personnel depuis les réglages de MultiDigi Tracker
    (même fichier, que la fenêtre Tracker ait déjà été ouverte ou non) —
    évite de dupliquer ce réglage dans deux endroits différents."""
    try:
        with open(_MULTIDIGI_TRACKER_SETTINGS_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        grid = str(data.get("my_grid", "") or "").strip().upper()
        if grid:
            return grid
    except Exception:
        pass
    return default


def latlon_to_field(lat, lon):
    """Retourne le champ Maidenhead 2 lettres (ex: JN) pour lat/lon donnés."""
    try:
        lon = max(-180.0, min(179.999999, float(lon)))
        lat = max(-90.0, min(89.999999, float(lat)))
        A = chr(ord('A') + int((lon + 180) / 20))
        B = chr(ord('A') + int((lat + 90) / 10))
        return A + B
    except Exception:
        return None


