_DXCC_PREFIXES_SORTED = sorted(DXCC_PREFIXES.keys(), key=len, reverse=True)


def approximate_location_from_call(call):
    """Retourne (country, lat, lon) approx à partir du préfixe de l'indicatif."""
    call = str(call or "").strip().upper()
    if not call:
        return None
    base = call.split('/')[0]
    if '/' in call:
        # F4LPS/W3 style -> le suffixe après / est parfois le pays réel
        parts = call.split('/')
        for p in parts:
            for pre in _DXCC_PREFIXES_SORTED:
                if p.startswith(pre) and len(pre) >= 2:
                    c = DXCC_PREFIXES[pre]
                    return c
    for pre in _DXCC_PREFIXES_SORTED:
        if base.startswith(pre):
            return DXCC_PREFIXES[pre]
    return None


# ─────────────────────────────────────────────────────────────────────────
#  Thread d'écoute UDP (reçoit les paquets JSON des terminaux F4LPS)
# ─────────────────────────────────────────────────────────────────────────
def format_contact_datetime(c):
    """Formate proprement la date+heure d'un contact quel que soit le format
    d'origine (ISO UTC type WSJT-X, ou 'AAAA-MM-JJ HH:MM' type ADIF)."""
    raw = str(c.get("time", "") or "").strip()
    if not raw:
        return ""
    try:
        if "T" in raw:
            # ex: 2026-07-11T14:05:00Z
            d = raw.split("T")[0]
            t = raw.split("T")[1].rstrip("Z")[:5]
            return f"{d} {t}Z"
        # ex: 2026-07-11 14:05 (import ADIF)
        return raw
    except Exception:
        return raw


# ─────────────────────────────────────────────────────────────────────────
#  Lookup HamQTH (gratuit — compte HamQTH.com requis, contrairement à l'API
#  QRZ.com qui est payante). Session mise en cache en mémoire.
# ─────────────────────────────────────────────────────────────────────────
class HamQTHClient:
    def __init__(self, username, password):
        self.username = username
        self.password = password
        self._session_id = None
        self._session_time = 0

    def _fetch_url(self, url, timeout=8):
        with urllib.request.urlopen(url, timeout=timeout) as resp:
            return resp.read()

    def _ensure_session(self):
        if self._session_id and (time.time() - self._session_time) < 1800:
            return self._session_id
        if not self.username or not self.password:
            return None
        url = ("https://www.hamqth.com/xml.php?u=" + urllib.parse.quote(self.username)
               + "&p=" + urllib.parse.quote(self.password))
        data = self._fetch_url(url)
        root = ET.fromstring(data)
        ns = {"h": "https://www.hamqth.com"}
        sid = root.find(".//h:session_id", ns)
        if sid is None:
            sid = root.find(".//session_id")  # au cas où le namespace n'est pas repris
        if sid is not None and sid.text:
            self._session_id = sid.text.strip()
            self._session_time = time.time()
            return self._session_id
        err = root.find(".//h:error", ns) or root.find(".//error")
        raise RuntimeError(err.text if err is not None and err.text else "Session HamQTH refusée")

    def lookup(self, call):
        """Retourne un dict (nick, name, qth, country, grid, email, adif_id) ou lève une exception."""
        sid = self._ensure_session()
        if not sid:
            raise RuntimeError("Identifiants HamQTH manquants (Réglages)")
        url = (f"https://www.hamqth.com/xml.php?id={urllib.parse.quote(sid)}"
               f"&callsign={urllib.parse.quote(call)}&prg=GridTrackerF4LPS")
        data = self._fetch_url(url)
        root = ET.fromstring(data)
        ns = {"h": "https://www.hamqth.com"}

        def _get(tag):
            el = root.find(f".//h:search/h:{tag}", ns) or root.find(f".//search/{tag}")
            return el.text.strip() if el is not None and el.text else ""

        err = root.find(".//h:session/h:error", ns) or root.find(".//session/error")
        if err is not None and err.text:
            raise RuntimeError(err.text)

        return {
            "call": call, "nick": _get("nick"), "name": (_get("adr_name") or _get("nick")),
            "qth": _get("adr_city"), "country": _get("country"), "grid": _get("grid"),
            "email": _get("email"), "adif_id": _get("adif"),
            "lat": _get("latitude") or _get("lat"),
            "lon": _get("longitude") or _get("lon"),
        }


class HamQTHLookupThread(QThread):
    """Requête HamQTH en arrière-plan pour ne jamais geler l'interface."""
    result_ready = pyqtSignal(dict)
    error = pyqtSignal(str)

    def __init__(self, client, call, parent=None):
        super().__init__(parent)
        self.client = client
        self.call = call

    def run(self):
        try:
            info = self.client.lookup(self.call)
            self.result_ready.emit(info)
        except Exception as e:
            self.error.emit(str(e))


# ─────────────────────────────────────────────────────────────────────────
#  Callbook central F4LPS — service UDP partagé par tous les terminaux
# ─────────────────────────────────────────────────────────────────────────
CALLBOOK_CACHE_FILE = os.path.join(os.path.expanduser("~"), "grid_tracker_f4lps_callbook.json")


def _cb_http_text(url, timeout=9):
    req = urllib.request.Request(url, headers={
        "User-Agent": "GridTracker-F4LPS/1.2",
        "Accept": "application/json, application/xml, text/xml, */*",
    })
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        return resp.read(262144).decode("utf-8", errors="replace")


def _cb_clean_name(value):
    value = re.sub(r"\s+", " ", str(value or "")).strip(" ,;:-")
    if not value:
        return ""
    # Les annuaires renvoient parfois NOM Prénom. Pour les macros, on garde
    # le premier mot utile et on applique une casse lisible.
    first = value.split()[0].strip()
    if not re.match(r"^[A-Za-zÀ-ÖØ-öø-ÿ][A-Za-zÀ-ÖØ-öø-ÿ'\-]{1,30}$", first):
        return ""
    return first[:1].upper() + first[1:].lower()


def _cb_local_text(root, tag):
    for el in root.iter():
        if str(el.tag).split("}")[-1].lower() == tag.lower() and el.text:
            return el.text.strip()
    return ""


def _cb_float(value):
    """Convertit une latitude/longitude issue d'un annuaire, sinon None."""
    try:
        txt = str(value or "").strip().replace(",", ".")
        if not txt:
            return None
        return float(txt)
    except Exception:
        return None


class CentralCallbookThread(QThread):
    """Recherche multi-sources puis répond au terminal demandeur par UDP."""
    result_ready = pyqtSignal(dict)
    error = pyqtSignal(str)

    def __init__(self, settings, call, request_id="", parent=None, force_refresh=False):
        super().__init__(parent)
        self.settings = dict(settings or {})
        self.call = str(call or "").strip().upper().split("/")[0]
        self.request_id = str(request_id or "")
        self.force_refresh = bool(force_refresh)

    def _cache_load(self):
        try:
            with open(CALLBOOK_CACHE_FILE, encoding="utf-8") as f:
                obj = json.load(f)
            return obj if isinstance(obj, dict) else {}
        except Exception:
            return {}

    def _cache_save(self, cache):
        try:
            with open(CALLBOOK_CACHE_FILE, "w", encoding="utf-8") as f:
                json.dump(cache, f, ensure_ascii=False, indent=2)
        except Exception:
            pass

    def _lookup_qrz_xml(self):
        user = str(self.settings.get("qrz_xml_user", "") or "").strip()
        password = str(self.settings.get("qrz_xml_pass", "") or "").strip()
        if not user or not password:
            return None
        login = ("https://xmldata.qrz.com/xml/current/?username=" +
                 urllib.parse.quote(user, safe='') + "&password=" +
                 urllib.parse.quote(password, safe='') + "&agent=GridTrackerF4LPS-1.2")
        root = ET.fromstring(_cb_http_text(login, 10))
        key = _cb_local_text(root, "Key")
        if not key:
            err = _cb_local_text(root, "Error") or _cb_local_text(root, "Message")
            raise RuntimeError("QRZ XML : " + (err or "connexion refusée"))
        query = ("https://xmldata.qrz.com/xml/current/?s=" +
                 urllib.parse.quote(key) + "&callsign=" +
                 urllib.parse.quote(self.call))
        root = ET.fromstring(_cb_http_text(query, 10))
        first = _cb_local_text(root, "fname") or _cb_local_text(root, "nickname")
        return {
            "call": self.call, "name": _cb_clean_name(first),
            "qth": _cb_local_text(root, "addr2"),
            "grid": _cb_local_text(root, "grid").upper(),
            "country": _cb_local_text(root, "country") or _cb_local_text(root, "land"),
            "lat": _cb_float(_cb_local_text(root, "lat")),
            "lon": _cb_float(_cb_local_text(root, "lon")),
            "source": "QRZ XML"
        }

    def _lookup_hamqth(self):
        user = str(self.settings.get("hamqth_user", "") or "").strip()
        password = str(self.settings.get("hamqth_pass", "") or "").strip()
        if not user or not password:
            return None
        info = HamQTHClient(user, password).lookup(self.call)
        return {
            "call": self.call,
            "name": _cb_clean_name(info.get("nick") or info.get("name")),
            "qth": info.get("qth", ""), "grid": str(info.get("grid", "")).upper(),
            "country": info.get("country", ""), "email": info.get("email", ""),
            "lat": _cb_float(info.get("lat")), "lon": _cb_float(info.get("lon")),
            "source": "HamQTH"
        }

    def _lookup_hamdb(self):
        url = ("https://api.hamdb.org/v1/" + urllib.parse.quote(self.call) +
               "/json/GridTrackerF4LPS")
        obj = json.loads(_cb_http_text(url))
        station = obj.get("hamdb", {}).get("callsign", {}) if isinstance(obj, dict) else {}
        if isinstance(station, list):
            station = station[0] if station else {}
        if not isinstance(station, dict):
            return None
        name = (station.get("fname") or station.get("first") or
                station.get("nickname") or station.get("name"))
        return {
            "call": self.call, "name": _cb_clean_name(name),
            "qth": station.get("qth") or station.get("addr2") or station.get("city") or "",
            "grid": str(station.get("grid") or station.get("locator") or "").upper(),
            "country": station.get("country") or "",
            "lat": _cb_float(station.get("latitude") or station.get("lat")),
            "lon": _cb_float(station.get("longitude") or station.get("lon") or station.get("lng")),
            "source": "HamDB"
        }

    def _lookup_callook(self):
        obj = json.loads(_cb_http_text(
            "https://callook.info/" + urllib.parse.quote(self.call) + "/json"))
        if not isinstance(obj, dict) or str(obj.get("status", "")).upper() != "VALID":
            return None
        current, address, location = obj.get("current") or {}, obj.get("address") or {}, obj.get("location") or {}
        return {
            "call": self.call, "name": _cb_clean_name(current.get("name") or obj.get("name")),
            "qth": address.get("line2") or location.get("name") or "",
            "grid": str(location.get("gridsquare") or location.get("grid") or "").upper(),
            "country": "United States",
            "lat": _cb_float(location.get("latitude") or location.get("lat")),
            "lon": _cb_float(location.get("longitude") or location.get("lon") or location.get("lng")),
            "source": "Callook"
        }

    def run(self):
        if not self.call:
            self.error.emit("Indicatif vide")
            return
        cache = self._cache_load()
        cached = cache.get(self.call)
        if (not self.force_refresh) and isinstance(cached, dict) and cached.get("name"):
            out = dict(cached)
            out.update({"request_id": self.request_id, "cached": True})
            self.result_ready.emit(out)
            return

        partial = {}
        errors = []
        for func in (self._lookup_qrz_xml, self._lookup_hamqth,
                     self._lookup_hamdb, self._lookup_callook):
            try:
                data = func()
                if not data:
                    continue
                for key in ("qth", "grid", "country", "email", "lat", "lon"):
                    if data.get(key) and not partial.get(key):
                        partial[key] = data[key]
                if data.get("name"):
                    data["request_id"] = self.request_id
                    data["time"] = datetime.now(timezone.utc).isoformat()
                    cache[self.call] = data
                    self._cache_save(cache)
                    self.result_ready.emit(data)
                    return
            except Exception as exc:
                errors.append(str(exc))

        partial.update({
            "call": self.call, "name": "", "request_id": self.request_id,
            "source": partial.get("source", "Aucune source"),
            "name_missing": True,
            "diagnostic": " | ".join(errors)[:500],
        })
        self.result_ready.emit(partial)


# ─────────────────────────────────────────────────────────────────────────
#  eQSL — téléchargement des confirmations reçues (InBox), pour distinguer
#  "travaillé" de "confirmé" (award réel), cohérent avec un usage eQSL exclusif.
# ─────────────────────────────────────────────────────────────────────────
class EqslClient:
    def __init__(self, username, password):
        self.username = username
        self.password = password

    def fetch_confirmed(self, timeout=20):
        """Télécharge l'ADIF des QSL reçues sur eQSL.cc et retourne un set de
        clés (CALL, BAND, MODE) confirmées."""
        if not self.username or not self.password:
            raise RuntimeError("Identifiants eQSL manquants (Réglages)")
        url = ("https://www.eqsl.cc/qslcard/DownloadInBox.cfm?UserName="
               + urllib.parse.quote(self.username) + "&Password="
               + urllib.parse.quote(self.password) + "&QSLType=ADIF")
        with urllib.request.urlopen(url, timeout=timeout) as resp:
            text = resp.read().decode("utf-8", errors="replace")
        if "Invalid" in text[:400] or "error" in text[:200].lower():
            raise RuntimeError("eQSL a refusé la connexion (identifiants ?)")
        records = parse_adif(text)
        confirmed = set()
        for rec in records:
            call = str(rec.get("CALL", "")).strip().upper()
            band = str(rec.get("BAND", "")).strip().lower()
            mode = str(rec.get("MODE", "")).strip().upper()
            if call:
                confirmed.add((call, band, mode))
        return confirmed


class EqslFetchThread(QThread):
    result_ready = pyqtSignal(set)
    error = pyqtSignal(str)

    def __init__(self, client, parent=None):
        super().__init__(parent)
        self.client = client

    def run(self):
        try:
            confirmed = self.client.fetch_confirmed()
            self.result_ready.emit(confirmed)
        except Exception as e:
            self.error.emit(str(e))


# ─────────────────────────────────────────────────────────────────────────
#  Conditions solaires (hamqsl.com — flux XML public, largement utilisé par
#  les logiciels ham ; portage du panneau déjà présent dans CW Terminal).
# ─────────────────────────────────────────────────────────────────────────
class SolarFetchThread(QThread):
    result_ready = pyqtSignal(dict)
    error = pyqtSignal(str)

    def run(self):
        try:
            with urllib.request.urlopen("https://www.hamqsl.com/solarxml.php", timeout=10) as resp:
                data = resp.read()
            root = ET.fromstring(data)
            src = root.find(".//solardata")
            if src is None:
                src = root

            def _g(tag):
                el = src.find(tag)
                return el.text.strip() if el is not None and el.text else "?"

            info = {
                "sfi": _g("solarflux"), "aindex": _g("aindex"), "kindex": _g("kindex"),
                "sunspots": _g("sunspots"), "xray": _g("xray"), "aurora": _g("aurora"),
                "geomag": _g("geomagfield"), "muf": _g("muf"),
                "updated": _g("updated"),
            }
            self.result_ready.emit(info)
        except Exception as e:
            self.error.emit(str(e))


class UdpListenerThread(QThread):
    packet_received = pyqtSignal(dict)
    status_changed = pyqtSignal(str, bool)  # message, ok

    def __init__(self, host="0.0.0.0", port=2237, parent=None):
        super().__init__(parent)
        self.host = host
        self.port = port
        self._running = False
        self._sock = None

    def run(self):
        self._running = True
        try:
            self._sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            self._sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self._sock.bind((self.host, self.port))
            self._sock.settimeout(1.0)
            self.status_changed.emit(f"🟢 Écoute UDP active sur {self.host}:{self.port}", True)
        except Exception as e:
            self.status_changed.emit(f"🔴 Impossible d'écouter sur {self.host}:{self.port} — {e}", False)
            self._running = False
            return

        while self._running:
            try:
                data, addr = self._sock.recvfrom(65535)
            except socket.timeout:
                continue
            except OSError:
                break
            except Exception:
                continue
            for line in data.decode('utf-8', errors='replace').splitlines():
                line = line.strip()
                if not line:
                    continue
                try:
                    payload = json.loads(line)
                    if isinstance(payload, dict):
                        self.packet_received.emit(payload)
                except Exception:
                    continue

    def stop(self):
        self._running = False
        try:
            if self._sock:
                self._sock.close()
        except Exception:
            pass
        self.wait(1500)


