# ─────────────────────────────────────────────────────────────────────────
#  Magasin de contacts (spots + qso + import ADIF), avec dédoublonnage léger
# ─────────────────────────────────────────────────────────────────────────
class ContactStore:
    def __init__(self):
        self.contacts = []          # liste de dicts normalisés
        self.grids_worked = {}      # grid(4) -> count
        self.fields_worked = {}     # champ 2 lettres -> count
        self.dxcc_worked = {}       # pays approx -> count
        self.bands_worked = {}      # bande -> count
        self.modes_worked = {}      # mode -> count
        self.confirmed = set()      # {(CALL, band, mode)} confirmés via eQSL

    def add(self, contact):
        """contact: dict avec au moins call, source('spot'/'qso'/'adif'), et
        idéalement grid, band, mode, lat, lon, country, time."""
        self.contacts.append(contact)
        grid = contact.get("grid")
        if grid and len(grid) >= 4:
            g4 = grid[:4]
            self.grids_worked[g4] = self.grids_worked.get(g4, 0) + 1
            field = g4[:2]
            self.fields_worked[field] = self.fields_worked.get(field, 0) + 1
        country = contact.get("country")
        if country:
            self.dxcc_worked[country] = self.dxcc_worked.get(country, 0) + 1
        band = contact.get("band")
        if band:
            self.bands_worked[band] = self.bands_worked.get(band, 0) + 1
        mode = contact.get("mode")
        if mode:
            self.modes_worked[mode] = self.modes_worked.get(mode, 0) + 1

    def clear(self):
        self.__init__()

    def remove_by_id(self, cid):
        """Supprime un contact précis (par son id unique) et recalcule tous
        les agrégats (grids/champs/DXCC/bandes/modes) proprement."""
        remaining = [c for c in self.contacts if c.get("_id") != cid]
        self.contacts = []
        self.grids_worked = {}
        self.fields_worked = {}
        self.dxcc_worked = {}
        self.bands_worked = {}
        self.modes_worked = {}
        for c in remaining:
            self.add(c)

    def history_for_call(self, call, only_qso=False):
        """Retourne l'historique (liste triée) des contacts déjà connus pour
        cet indicatif — utilisé pour le contrôle de doublon au clic sur la carte."""
        call = str(call or "").strip().upper()
        if not call:
            return []
        res = [c for c in self.contacts if str(c.get("call", "")).strip().upper() == call]
        if only_qso:
            res = [c for c in res if c.get("source") == "qso"]
        return res

    def qso_count_for_call(self, call):
        return len(self.history_for_call(call, only_qso=True))

    def is_confirmed(self, call, band, mode):
        key = (str(call or "").strip().upper(), str(band or "").strip().lower(), str(mode or "").strip().upper())
        return key in self.confirmed

    def set_confirmed(self, confirmed_set):
        self.confirmed = set(confirmed_set)

    def to_json(self):
        return json.dumps(self.contacts, ensure_ascii=False)

    def load_json(self, txt):
        try:
            data = json.loads(txt)
            if isinstance(data, list):
                for c in data:
                    self.add(c)
        except Exception:
            pass


# ─────────────────────────────────────────────────────────────────────────
#  Vraie carte du monde (OpenStreetMap via Leaflet) — zoom/pan à la souris,
#  incruste éventuellement la grille Maidenhead en superposition.
#  Nécessite PyQtWebEngine + accès internet (tuiles OSM) sur le poste où
#  tourne le Grid Tracker.
# ─────────────────────────────────────────────────────────────────────────
_LEAFLET_HTML = """<!DOCTYPE html>
<html><head><meta charset="utf-8">
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"/>
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script src="qrc:///qtwebchannel/qwebchannel.js"></script>
<style>
  html, body, #map { height:100%; margin:0; background:#0a0f16; }
  .f4lps-home { font-size:22px; text-shadow:0 0 4px #000; }
  .leaflet-popup-content-wrapper { background:#0d141d; color:#cfe8ff; }
  .leaflet-popup-tip { background:#0d141d; }
  .f4lps-field-label { color:#5a90b8; font-size:10px; font-family:monospace; text-shadow:0 0 3px #000; }
</style>
</head>
<body>
<div id="map"></div>
<script>
  var map = L.map('map', {worldCopyJump:true}).setView([46.6, 2.5], 4);
  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 18,
      attribution: '&copy; OpenStreetMap contributors'
  }).addTo(map);

  var markersLayer = L.layerGroup().addTo(map);
  var activityLayer = L.layerGroup().addTo(map);
  var gridLayer = L.layerGroup();
  var homeMarker = null;
  var homeLat = null, homeLon = null;
  var markersByCall = {};
  var gridBuilt = false;

  // V8.3.11 F4LPS — animation du sens du QSO.
  // TX : les pointillés vont de HOME vers l'OM.
  // RX : ils reviennent de l'OM vers HOME.
  var trafficLine = null;
  var trafficTimer = null;
  var trafficStopTimer = null;
  var trafficCall = '';
  var trafficDirection = '';
  var trafficOffset = 0;

  // Pont Python <-> JS (double-clic sur un marqueur = renvoyer le call à Python)
  var bridge = null;
  if (typeof qt !== 'undefined' && qt.webChannelTransport) {
      new QWebChannel(qt.webChannelTransport, function(channel) { bridge = channel.objects.bridge; });
  }

  function setHome(lat, lon, label) {
      if (homeMarker) { map.removeLayer(homeMarker); }
      homeLat = lat; homeLon = lon;
      var icon = L.divIcon({className:'f4lps-home', html:'⭐', iconSize:[22,22], iconAnchor:[11,11]});
      homeMarker = L.marker([lat, lon], {icon: icon}).addTo(map).bindPopup(label);
      map.setView([lat, lon], 4);
  }

  var _occupiedPositions = {};  // "lat_rounded,lon_rounded" -> count déjà placés ici

  function _spreadPosition(lat, lon) {
      // MULTIDIGI V0.1 F4LPS : avec un indicatif grille à 4 caractères, la
      // précision est une case de 2°x1° (~150x110 km) -- plusieurs stations
      // de la même région tombent exactement sur le même point et leurs
      // marqueurs se superposent parfaitement, donnant l'impression qu'un
      // seul contact est affiché par pays. On écarte légèrement chaque
      // nouveau marqueur en spirale autour du point réel s'il coïncide avec
      // un marqueur déjà présent, pour que tous restent visibles.
      var key = lat.toFixed(2) + ',' + lon.toFixed(2);
      var n = _occupiedPositions[key] || 0;
      _occupiedPositions[key] = n + 1;
      if (n === 0) return [lat, lon];
      var angle = n * 2.399963;  // angle doré : répartition régulière en spirale
      var radius = 0.12 * Math.sqrt(n);  // degrés -- petit écart croissant
      return [lat + radius * Math.cos(angle), lon + radius * Math.sin(angle)];
  }

  function addContact(lat, lon, color, popupHtml, radius, call, isQso) {
      var pos = _spreadPosition(lat, lon);
      var c = L.circleMarker(pos, {
          radius: radius || 6, color: color, weight: 1,
          fillColor: color, fillOpacity: 0.85
      }).addTo(markersLayer);
      c.bindPopup(popupHtml);
      markersByCall[String(call || '').toUpperCase()] = c;
      c.on('dblclick', function() {
          if (bridge) { bridge.call_double_clicked(call); }
      });
      if (homeLat !== null && homeLon !== null) {
          L.polyline([[homeLat, homeLon], pos], {
              color: color, weight: isQso ? 1.6 : 1.0,
              opacity: isQso ? 0.75 : 0.35,
              dashArray: isQso ? '7,7' : '3,9',
              interactive: false
          }).addTo(activityLayer);
      }
  }


  function stopTraffic() {
      if (trafficTimer) {
          clearInterval(trafficTimer);
          trafficTimer = null;
      }
      if (trafficStopTimer) {
          clearTimeout(trafficStopTimer);
          trafficStopTimer = null;
      }
      if (trafficLine) {
          try { activityLayer.removeLayer(trafficLine); } catch(e) {}
          trafficLine = null;
      }
      trafficCall = '';
      trafficDirection = '';
      trafficOffset = 0;
  }

  function animateTraffic(call, direction, holdMs) {
      if (homeLat === null || homeLon === null) return;
      var key = String(call || '').toUpperCase();
      var marker = markersByCall[key];
      if (!marker) return;

      var dir = String(direction || '').toLowerCase();
      if (dir !== 'tx' && dir !== 'rx') return;
      var pos = marker.getLatLng();

      // Si on change de correspondant, on reconstruit la ligne.
      if (!trafficLine || trafficCall !== key) {
          if (trafficLine) {
              try { activityLayer.removeLayer(trafficLine); } catch(e) {}
          }
          trafficLine = L.polyline([[homeLat, homeLon], [pos.lat, pos.lng]], {
              color: dir === 'tx' ? '#ffcc33' : '#55ddff',
              weight: 3.0,
              opacity: 0.95,
              dashArray: '10,14',
              dashOffset: '0',
              interactive: false
          }).addTo(activityLayer);
          trafficCall = key;
          trafficOffset = 0;
      } else {
          trafficLine.setLatLngs([[homeLat, homeLon], [pos.lat, pos.lng]]);
          trafficLine.setStyle({
              color: dir === 'tx' ? '#ffcc33' : '#55ddff',
              weight: 3.0,
              opacity: 0.95,
              dashArray: '10,14'
          });
      }

      trafficDirection = dir;

      if (!trafficTimer) {
          trafficTimer = setInterval(function() {
              // Leaflet/CSS : le signe opposé donne visuellement le sens inverse.
              // HOME -> OM pendant TX ; OM -> HOME pendant RX.
              trafficOffset += (trafficDirection === 'tx') ? -2.6 : 2.6;
              if (trafficLine) {
                  trafficLine.setStyle({dashOffset: String(trafficOffset)});
              }
          }, 70);
      }

      if (trafficStopTimer) clearTimeout(trafficStopTimer);
      var ms = Number(holdMs || 0);
      if (ms > 0) {
          trafficStopTimer = setTimeout(function() {
              stopTraffic();
          }, ms);
      }
  }




  function animateTrafficCoords(homeLatArg, homeLonArg, dxLatArg, dxLonArg, direction, holdMs) {
      var hlat = Number(homeLatArg), hlon = Number(homeLonArg);
      var dlat = Number(dxLatArg), dlon = Number(dxLonArg);
      if (![hlat, hlon, dlat, dlon].every(Number.isFinite)) return false;

      var dir = String(direction || '').toLowerCase();
      if (dir !== 'tx' && dir !== 'rx') return false;

      if (trafficTimer) {
          clearInterval(trafficTimer);
          trafficTimer = null;
      }
      if (trafficStopTimer) {
          clearTimeout(trafficStopTimer);
          trafficStopTimer = null;
      }
      if (trafficLine) {
          try { activityLayer.removeLayer(trafficLine); } catch(e) {}
          trafficLine = null;
      }

      // Ligne toujours dessinée HOME -> DX. On inverse uniquement le dashOffset.
      trafficLine = L.polyline([[hlat, hlon], [dlat, dlon]], {
          color: dir === 'tx' ? '#ffd84a' : '#55e6ff',
          weight: 4.0,
          opacity: 1.0,
          dashArray: '9,13',
          dashOffset: '0',
          lineCap: 'round',
          interactive: false
      }).addTo(activityLayer);

      trafficDirection = dir;
      trafficOffset = 0;

      trafficTimer = setInterval(function() {
          if (!trafficLine) return;
          // Sens visuel :
          // TX = HOME -> DX
          // RX = DX -> HOME
          trafficOffset += (trafficDirection === 'tx') ? -3.8 : 3.8;
          try {
              trafficLine.setStyle({dashOffset: String(trafficOffset)});
          } catch(e) {}
      }, 60);

      var ms = Number(holdMs || 0);
      if (ms > 0) {
          trafficStopTimer = setTimeout(function() {
              stopTraffic();
          }, ms);
      }
      return true;
  }


  var activeDxMarker = null;

  function setActiveDxMarker(call, latArg, lonArg, popupHtml) {
      var lat = Number(latArg), lon = Number(lonArg);
      if (!Number.isFinite(lat) || !Number.isFinite(lon)) return false;

      if (activeDxMarker) {
          try { activityLayer.removeLayer(activeDxMarker); } catch(e) {}
          activeDxMarker = null;
      }

      var icon = L.divIcon({
          className: '',
          html:
              '<div style="' +
              'width:18px;height:18px;border-radius:50%;' +
              'background:#ffcc33;border:3px solid #ffffff;' +
              'box-shadow:0 0 0 3px rgba(255,204,51,.35);' +
              '"></div>',
          iconSize: [18,18],
          iconAnchor: [9,9],
          popupAnchor: [0,-11]
      });

      activeDxMarker = L.marker([lat, lon], {
          icon: icon,
          zIndexOffset: 3000
      }).addTo(activityLayer);

      if (popupHtml) {
          activeDxMarker.bindPopup(String(popupHtml), {
              maxWidth: 300,
              autoPan: true
          });
      }

      activeDxMarker.bindTooltip(String(call || ''), {
          permanent: true,
          direction: 'top',
          offset: [0,-12],
          opacity: 0.95
      });

      return true;
  }

  function zoomBetweenCoords(homeLatArg, homeLonArg, dxLatArg, dxLonArg) {
      var hlat = Number(homeLatArg), hlon = Number(homeLonArg);
      var dlat = Number(dxLatArg), dlon = Number(dxLonArg);
      if (![hlat, hlon, dlat, dlon].every(Number.isFinite)) return false;

      var bounds = L.latLngBounds(
          [hlat, hlon],
          [dlat, dlon]
      );

      map.invalidateSize(true);
      map.fitBounds(bounds.pad(0.30), {
          paddingTopLeft: [55, 55],
          paddingBottomRight: [55, 55],
          maxZoom: 10,
          animate: true,
          duration: 0.8
      });

      // Refaire un second fit après le rafraîchissement de taille de QWebEngine.
      setTimeout(function() {
          try {
              map.invalidateSize(true);
              map.fitBounds(bounds.pad(0.30), {
                  paddingTopLeft: [55, 55],
                  paddingBottomRight: [55, 55],
                  maxZoom: 10,
                  animate: true,
                  duration: 0.55
              });
          } catch(e) {}
      }, 220);

      return true;
  }

  function zoomBetweenHomeAndCall(call) {
      if (homeLat === null || homeLon === null) return false;
      var key = String(call || '').toUpperCase();
      var marker = markersByCall[key];
      if (!marker) return false;

      var pos = marker.getLatLng();
      var bounds = L.latLngBounds(
          [homeLat, homeLon],
          [pos.lat, pos.lng]
      );

      // Toujours cadrer les DEUX OM avec une marge confortable.
      // maxZoom évite de zoomer excessivement pour un OM proche.
      map.fitBounds(bounds.pad(0.28), {
          padding: [45, 45],
          maxZoom: 10,
          animate: true,
          duration: 0.65
      });
      return true;
  }

  function focusContact(call, lat, lon, zoomLevel) {
      var key = String(call || '').toUpperCase();
      var marker = markersByCall[key];
      var z = zoomLevel || 8;
      map.flyTo([lat, lon], z, {animate:true, duration:0.8});
      if (marker) { setTimeout(function(){ marker.openPopup(); }, 850); }
  }

  function showPropagationContacts(items) {
      stopTraffic();
      activeDxMarker = null;
      markersLayer.clearLayers(); activityLayer.clearLayers(); markersByCall = {}; _occupiedPositions = {};
      var pts = [];
      if (homeLat !== null && homeLon !== null) pts.push([homeLat, homeLon]);
      (items || []).forEach(function(c) {
          var lat=Number(c.lat), lon=Number(c.lon);
          if (!Number.isFinite(lat) || !Number.isFinite(lon)) return;
          var call=String(c.call||'').toUpperCase();
          var marker=L.circleMarker([lat,lon], {radius:6,weight:2,opacity:1,fillOpacity:0.86}).addTo(markersLayer);
          marker.bindPopup('<b>'+call+'</b>'+(c.band?'<br>📻 '+c.band:'')+(c.mode?'<br>🔤 '+c.mode:'')+(c.age?'<br>🕒 '+c.age:''));
          markersByCall[call]=marker; pts.push([lat,lon]);
          if (homeLat !== null && homeLon !== null) L.polyline([[homeLat,homeLon],[lat,lon]], {weight:1.4,opacity:0.50,dashArray:'5,8',interactive:false}).addTo(activityLayer);
      });
      if (pts.length >= 2) map.fitBounds(L.latLngBounds(pts).pad(0.18), {padding:[35,35],maxZoom:8});
      else map.invalidateSize(true);
      return true;
  }

  function clearContacts() {
      stopTraffic();
      activeDxMarker = null;
      markersLayer.clearLayers();
      activityLayer.clearLayers();
      markersByCall = {};
      _occupiedPositions = {};
  }

  function buildGrid() {
      if (gridBuilt) return;
      gridBuilt = true;
      for (var lon = -180; lon <= 180; lon += 20) {
          L.polyline([[-90, lon],[90, lon]], {color:'#3a5468', weight:1, opacity:0.6}).addTo(gridLayer);
      }
      for (var lat = -90; lat <= 90; lat += 10) {
          L.polyline([[lat, -180],[lat, 180]], {color:'#3a5468', weight:1, opacity:0.6}).addTo(gridLayer);
      }
      for (var fi = 0; fi < 18; fi++) {
          for (var fj = 0; fj < 18; fj++) {
              var lonA = String.fromCharCode(65 + fi);
              var latB = String.fromCharCode(65 + fj);
              var lon0 = fi * 20 - 180, lat0 = fj * 10 - 90;
              var lbl = L.divIcon({className:'f4lps-field-label', html: lonA + latB, iconSize:[24,12]});
              L.marker([lat0 + 1, lon0 + 1], {icon: lbl, interactive:false}).addTo(gridLayer);
          }
      }
  }

  function toggleGrid(show) {
      buildGrid();
      if (show) { gridLayer.addTo(map); } else { map.removeLayer(gridLayer); }
  }
</script>
</body></html>
"""


class TrackerBridge(QObject):
    """Pont JS -> Python exposé au Leaflet via QWebChannel (double-clic marqueur)."""
    callDoubleClicked = pyqtSignal(str)

    @pyqtSlot(str)
    def call_double_clicked(self, call):
        self.callDoubleClicked.emit(call)


class RealMapWidget(QWebEngineView if HAVE_WEBENGINE else object):
    """Vraie carte OpenStreetMap zoomable, pilotée depuis Python via JS.
    Si PyQtWebEngine n'est pas installé, cette classe hérite de `object` et
    n'est jamais instanciée (voir HAVE_WEBENGINE dans GridTrackerWindow)."""
    call_double_clicked = pyqtSignal(str)  # ré-émis depuis TrackerBridge (double-clic marqueur)

    def __init__(self, parent=None):
        if not HAVE_WEBENGINE:
            raise RuntimeError("PyQtWebEngine n'est pas installé (pip install PyQtWebEngine)")
        super().__init__(parent)
        self.setMinimumSize(640, 340)
        self._bridge = None
        if HAVE_WEBCHANNEL:
            self._bridge = TrackerBridge()
            self._bridge.callDoubleClicked.connect(self.call_double_clicked.emit)
            self._channel = QWebChannel()
            self._channel.registerObject('bridge', self._bridge)
            self.page().setWebChannel(self._channel)
        self.setHtml(_LEAFLET_HTML, QUrl("https://unpkg.com/"))
        self._ready = False
        self.loadFinished.connect(self._on_loaded)
        self._pending = []

    def _on_loaded(self, ok):
        self._ready = bool(ok)
        for js in self._pending:
            self.page().runJavaScript(js)
        self._pending = []

    def _run(self, js):
        if self._ready:
            self.page().runJavaScript(js)
        else:
            self._pending.append(js)

    @staticmethod
    def _esc(s):
        return str(s or "").replace("\\", "\\\\").replace("'", "\\'").replace("\n", " ")

    def set_home(self, lat, lon, label):
        self._run(f"setHome({lat}, {lon}, '{self._esc(label)}');")

    def add_contact(self, lat, lon, color, popup_html, radius=6, call="", is_qso=False):
        qso_js = "true" if is_qso else "false"
        self._run(f"addContact({lat}, {lon}, '{color}', '{self._esc(popup_html)}', {radius}, '{self._esc(call)}', {qso_js});")

    def focus_contact(self, call, lat, lon, zoom=8):
        self._run(f"focusContact('{self._esc(call)}', {float(lat)}, {float(lon)}, {int(zoom)});")

    def zoom_between_home_and_call(self, call):
        """Ancienne méthode par marqueur JS, conservée en secours."""
        self._run(f"zoomBetweenHomeAndCall('{self._esc(call)}');")

    def zoom_between_coords(self, home_lat, home_lon, dx_lat, dx_lon):
        """Cadre HOME + DX directement par coordonnées, sans dépendre des marqueurs."""
        self._run(
            "zoomBetweenCoords("
            f"{float(home_lat)}, {float(home_lon)}, "
            f"{float(dx_lat)}, {float(dx_lon)}"
            ");"
        )

    def animate_traffic_coords(self, home_lat, home_lon, dx_lat, dx_lon, direction, hold_ms=0):
        """Anime les pointillés directement entre deux coordonnées."""
        d = 'tx' if str(direction).lower() == 'tx' else 'rx'
        self._run(
            "animateTrafficCoords("
            f"{float(home_lat)}, {float(home_lon)}, "
            f"{float(dx_lat)}, {float(dx_lon)}, "
            f"'{d}', {int(max(0, hold_ms))}"
            ");"
        )

    def set_active_dx_marker(self, call, lat, lon, popup_html=''):
        """Point jaune/blanc sur l'OM appelé + bulle d'informations."""
        safe_popup = self._esc(str(popup_html or ''))
        self._run(
            f"setActiveDxMarker('{self._esc(call)}', "
            f"{float(lat)}, {float(lon)}, '{safe_popup}');"
        )

    def animate_traffic(self, call, direction, hold_ms=0):
        """Anime les pointillés : TX HOME->DX, RX DX->HOME."""
        d = 'tx' if str(direction).lower() == 'tx' else 'rx'
        self._run(
            f"animateTraffic('{self._esc(call)}', '{d}', {int(max(0, hold_ms))});"
        )

    def stop_traffic(self):
        self._run("stopTraffic();")

    def show_propagation_contacts(self, contacts):
        payload = json.dumps(list(contacts or []), ensure_ascii=False)
        self._run(f"showPropagationContacts({payload});")

    def clear_contacts(self):
        self._run("clearContacts();")

    def set_grid_overlay(self, show):
        self._run("toggleGrid(%s);" % ("true" if show else "false"))


