class HellWindow(QDialog):
    """Affichage Feld Hell : PAGE a lignes fixes, facon DM780.

    V0.10 F4LPS — le defilement continu a ete abandonne. L'image glissait d'un
    pixel a CHAQUE colonne, soit 122 fois par seconde en FELD HELL : le texte
    bougeait sans arret sous les yeux et devenait tres difficile a lire, meme
    quand le decodage etait parfait. DM780 n'a pas ce probleme parce qu'il
    n'utilise pas de ruban defilant : il ecrit sur une ligne FIXE qui se
    remplit de gauche a droite, puis passe a la ligne suivante quand elle est
    pleine. Rien ne bouge pendant l'ecriture.

    Chaque ligne est affichee en DEUX copies empilees. Hell n'a aucune
    synchronisation verticale : selon l'instant d'accrochage, un caractere
    peut etre coupe en deux dans la hauteur. Avec deux copies, une des deux
    est toujours entiere. Ce n'est pas une redondance inutile.
    """
    LINE_COLS = 460     # colonnes par ligne avant passage a la ligne suivante
    LINES     = 4       # nombre de lignes visibles sur la page
    GAP       = 2       # separation entre lignes, en pixels Hell
    ZOOM_Y    = 5       # hauteur d'un pixel Hell, a l'ecran

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle("〰️ MultiDigi — Feld Hell")
        self._rows = 7
        h_page = self.LINES * (2 * self._rows + self.GAP) * self.ZOOM_Y
        self.setMinimumSize(self.LINE_COLS + 40, h_page + 70)
        self._lines = [np.zeros((self._rows, self.LINE_COLS), dtype=np.float32)
                       for _ in range(self.LINES)]
        self._cur = 0                     # colonne d'ecriture sur la ligne du bas
        lay = QVBoxLayout(self)
        self._label = QLabel()
        self._label.setMinimumHeight(h_page)
        lay.addWidget(self._label)
        barre = QHBoxLayout()
        self._info = QLabel("En attente de signal…")
        barre.addWidget(self._info)
        barre.addStretch(1)
        b = QPushButton("Effacer")
        b.clicked.connect(self.clear)
        barre.addWidget(b)
        lay.addLayout(barre)
        self._n = 0
        # Hell ne produit pas de texte : le signal text_decoded du thread audio
        # ne se declenche donc jamais. On vient chercher les colonnes nous-memes.
        self._timer = QTimer(self)
        self._timer.timeout.connect(self._collecte)
        self._timer.start(100)

    def _collecte(self):
        if not self.isVisible():
            return
        try:
            # V0.8d F4LPS — POINT IMPORTANT.
            # PSKAudioThread ne recoit pas l'objet decodeur : il recoit une
            # FABRIQUE et construit sa PROPRE instance. self.decoder_obj de la
            # fenetre principale est donc un objet DIFFERENT, qui ne voit
            # jamais passer l'audio. C'est bien le decodeur du thread qu'il
            # faut lire.
            par = self.parent()
            dec = None
            th = getattr(par, 'audio_thread', None)
            if th is not None:
                dec = getattr(th, 'decoder', None)
            if dec is None or not hasattr(dec, 'take_columns'):
                dec = getattr(par, 'decoder_obj', None)
            if dec is not None and hasattr(dec, 'take_columns'):
                self.add_columns(dec.take_columns())
        except Exception as e:
            print(f"⚠️ collecte Hell : {e}")

    def clear(self):
        for l in self._lines:
            l[:] = 0.0
        self._cur = 0
        self._n = 0
        self._redraw()

    def add_columns(self, cols):
        if not cols:
            return
        for c in cols:
            c = np.asarray(c, dtype=np.float32)
            if c.size != self._rows:
                continue
            if self._cur >= self.LINE_COLS:
                # ligne pleine : tout remonte d'un cran, on repart a gauche.
                self._lines.pop(0)
                self._lines.append(
                    np.zeros((self._rows, self.LINE_COLS), dtype=np.float32))
                self._cur = 0
            # V0.10b F4LPS — INVERSION VERTICALE.
            # Le Feld Hell emet les pixels d'une colonne DE BAS EN HAUT.
            # Sans ce [::-1] le texte s'affichait tete en bas, ce qui ne se
            # voyait pas en boucle locale : mon encodeur de test utilisait la
            # meme (mauvaise) convention que le decodeur, les deux erreurs se
            # compensaient. Seul un vrai signal recu sur l'air l'a revele.
            self._lines[-1][:, self._cur] = np.clip(c, 0.0, 1.0)[::-1]
            self._cur += 1
            self._n += 1
        self._info.setText(f"{self._n} colonnes reçues")
        self._redraw()

    def _redraw(self):
        try:
            sep = np.zeros((self.GAP, self.LINE_COLS), dtype=np.float32)
            bandes = []
            for k, l in enumerate(self._lines):
                bandes.append(np.vstack([l, l]))     # les deux copies
                if k < len(self._lines) - 1:
                    bandes.append(sep)
            img = np.vstack(bandes)
            g = (255.0 * (1.0 - np.clip(img, 0.0, 1.0))).astype(np.uint8)
            g = np.ascontiguousarray(g)
            h, w = g.shape
            qi = QImage(g.tobytes(), w, h, w, QImage.Format_Grayscale8)
            pm = QPixmap.fromImage(qi).scaled(
                max(w, self._label.width() or w), h * self.ZOOM_Y,
                Qt.IgnoreAspectRatio, Qt.SmoothTransformation)
            self._label.setPixmap(pm)
        except Exception as e:
            print(f"⚠️ affichage Hell : {e}")


class GridMapWidget(QWidget):
    field_clicked = pyqtSignal(str)
    point_clicked = pyqtSignal(dict)
    point_double_clicked = pyqtSignal(dict)

    def __init__(self, store: ContactStore, parent=None):
        super().__init__(parent)
        self.store = store
        self.home_grid = ""
        self.setMinimumSize(640, 340)
        self.setMouseTracking(True)
        self._hover_field = None
        self._contact_points = []  # [(x, y, contact), ...] recalculé à chaque paint

    def set_home_grid(self, grid):
        self.home_grid = grid
        self.update()

    # projection équirectangulaire simple : lon [-180,180] -> x, lat[-90,90] -> y
    def _proj(self, lat, lon, w, h):
        x = (lon + 180.0) / 360.0 * w
        y = (90.0 - lat) / 180.0 * h
        return x, y

    def paintEvent(self, event):
        p = QPainter(self)
        p.setRenderHint(QPainter.Antialiasing, True)
        w, h = self.width(), self.height()

        p.fillRect(0, 0, w, h, QColor("#050a12"))

        # Contours continentaux (repère visuel léger, sous la grille)
        p.setPen(QPen(QColor("#1c3a2e"), 1.2))
        p.setBrush(QBrush(QColor("#0e2018")))
        for name, coords in CONTINENT_OUTLINES.items():
            poly = []
            for lon, lat in coords:
                x, y = self._proj(lat, lon, w, h)
                poly.append(QPoint(int(x), int(y)))
            from PyQt5.QtGui import QPolygon
            p.drawPolygon(QPolygon(poly))

        field_w = w / 18.0
        field_h = h / 18.0

        max_count = max(self.store.fields_worked.values()) if self.store.fields_worked else 1

        # Fonds des champs travaillés (dégradé selon nb de contacts)
        for fi in range(18):
            for fj in range(18):
                lon_a = chr(ord('A') + fi)
                lat_b = chr(ord('A') + fj)
                field = lon_a + lat_b
                count = self.store.fields_worked.get(field, 0)
                x = fi * field_w
                y = (17 - fj) * field_h
                if count > 0:
                    intensity = 60 + int(140 * min(1.0, count / max(1, max_count)))
                    color = QColor(0, intensity, int(intensity * 0.55))
                    p.fillRect(QRectF(x, y, field_w, field_h), color)

        # Grille
        pen = QPen(QColor("#1a2c3a")); pen.setWidth(1)
        p.setPen(pen)
        for i in range(19):
            x = i * field_w
            p.drawLine(int(x), 0, int(x), h)
        for j in range(19):
            y = j * field_h
            p.drawLine(0, int(y), w, int(y))

        # Ligne équateur / méridien de Greenwich soulignés
        pen2 = QPen(QColor("#33506a")); pen2.setWidth(2)
        p.setPen(pen2)
        eq_y = h / 2.0
        gw_x = w / 2.0
        p.drawLine(0, int(eq_y), w, int(eq_y))
        p.drawLine(int(gw_x), 0, int(gw_x), h)

        # Labels des champs (si assez de place)
        if field_w > 22:
            p.setPen(QColor("#3a5468"))
            f = QFont("Courier New", 7)
            p.setFont(f)
            for fi in range(18):
                for fj in range(18):
                    lon_a = chr(ord('A') + fi)
                    lat_b = chr(ord('A') + fj)
                    x = fi * field_w
                    y = (17 - fj) * field_h
                    p.drawText(QRectF(x + 2, y + 1, field_w, 12), Qt.AlignLeft, lon_a + lat_b)

        # Position station perso (étoile)
        if self.home_grid:
            latlon = grid_to_latlon(self.home_grid)
            if latlon:
                lat, lon = latlon
                x, y = self._proj(lat, lon, w, h)
                p.setPen(QPen(QColor("#ffcc00"), 2))
                p.setBrush(QBrush(QColor("#ffcc00")))
                self._draw_star(p, x, y, 7)
                p.setPen(QColor("#ffee88"))
                p.drawText(int(x) + 9, int(y) + 4, self.home_grid)

        # Points de contact
        self._contact_points = []
        for c in self.store.contacts:
            lat, lon = c.get("lat"), c.get("lon")
            if lat is None or lon is None:
                continue
            x, y = self._proj(lat, lon, w, h)
            src = c.get("source", "spot")
            prior = int(c.get("_prior_qso_count", 0) or 0)
            if prior > 0:
                color = QColor("#ffcc00")
            else:
                color = QColor("#ff5533") if src == "qso" else QColor("#44aaff")
            p.setPen(Qt.NoPen)
            p.setBrush(QBrush(color))
            r = 3.5 if src != "qso" else 4.5
            p.drawEllipse(QPoint(int(x), int(y)), int(r), int(r))
            self._contact_points.append((x, y, c))

        p.end()

    def _draw_star(self, p, cx, cy, r):
        pts = []
        for i in range(10):
            ang = math.pi / 2 + i * math.pi / 5
            rad = r if i % 2 == 0 else r * 0.45
            pts.append(QPoint(int(cx + rad * math.cos(ang)), int(cy - rad * math.sin(ang))))
        from PyQt5.QtGui import QPolygon
        p.drawPolygon(QPolygon(pts))

    def _find_point_near(self, x, y, radius=7):
        best = None; best_d2 = radius * radius
        for px, py, c in self._contact_points:
            d2 = (px - x) ** 2 + (py - y) ** 2
            if d2 <= best_d2:
                best_d2 = d2; best = c
        return best

    def mouseMoveEvent(self, event):
        near = self._find_point_near(event.x(), event.y())
        if near is not None:
            prior = int(near.get("_prior_qso_count", 0) or 0)
            status = f" — déjà travaillé {prior}x" if prior > 0 else " — nouveau"
            loc = near.get("grid") or near.get("country") or ""
            when = format_contact_datetime(near)
            when_txt = f" — {when}" if when else ""
            QToolTip.showText(event.globalPos(),
                               f"{near.get('call','')} — {near.get('mode','')} {near.get('band','')}"
                               f" — {loc}{status}{when_txt}", self)
            super().mouseMoveEvent(event)
            return
        w, h = self.width(), self.height()
        field_w = w / 18.0
        field_h = h / 18.0
        fi = int(event.x() / field_w)
        fj = 17 - int(event.y() / field_h)
        if 0 <= fi < 18 and 0 <= fj < 18:
            field = chr(ord('A') + fi) + chr(ord('A') + fj)
            count = self.store.fields_worked.get(field, 0)
            if field != self._hover_field:
                self._hover_field = field
            QToolTip.showText(event.globalPos(), f"Champ {field} — {count} contact(s)", self)
        super().mouseMoveEvent(event)

    def mousePressEvent(self, event):
        near = self._find_point_near(event.x(), event.y())
        if near is not None:
            self.point_clicked.emit(near)
            return
        w, h = self.width(), self.height()
        field_w = w / 18.0
        field_h = h / 18.0
        fi = int(event.x() / field_w)
        fj = 17 - int(event.y() / field_h)
        if 0 <= fi < 18 and 0 <= fj < 18:
            field = chr(ord('A') + fi) + chr(ord('A') + fj)
            self.field_clicked.emit(field)
        super().mousePressEvent(event)

    def mouseDoubleClickEvent(self, event):
        near = self._find_point_near(event.x(), event.y())
        if near is not None:
            self.point_double_clicked.emit(near)
            return
        super().mouseDoubleClickEvent(event)


