# ─────────────────────────────────────────────────────────────────────────
#  Import ADIF (léger, tolérant)
# ─────────────────────────────────────────────────────────────────────────
_ADIF_FIELD_RE = re.compile(r'<([A-Za-z_]+):(\d+)(?::[A-Za-z])?>', re.IGNORECASE)


def parse_adif(text):
    """Parse un fichier ADIF et retourne une liste de dicts de QSO bruts."""
    records = []
    upos = 0
    text_upper = text
    # découpe sur <EOR> (insensible à la casse)
    chunks = re.split(r'<eor>', text, flags=re.IGNORECASE)
    for chunk in chunks:
        fields = {}
        for m in _ADIF_FIELD_RE.finditer(chunk):
            tag = m.group(1).upper()
            length = int(m.group(2))
            start = m.end()
            value = chunk[start:start + length]
            fields[tag] = value.strip()
        if fields.get("CALL"):
            records.append(fields)
    return records


def adif_record_to_contact(rec):
    call = str(rec.get("CALL", "")).strip().upper()
    if not call:
        return None
    grid = str(rec.get("GRIDSQUARE", "")).strip().upper()
    band = str(rec.get("BAND", "")).strip().lower()
    mode = str(rec.get("MODE", "")).strip().upper()
    date_s = str(rec.get("QSO_DATE", "")).strip()
    time_s = str(rec.get("TIME_ON", "")).strip()
    when = ""
    if date_s and time_s:
        try:
            when = f"{date_s[0:4]}-{date_s[4:6]}-{date_s[6:8]} {time_s[0:2]}:{time_s[2:4]}"
        except Exception:
            when = date_s

    lat = lon = None
    country = None
    if grid:
        ll = grid_to_latlon(grid)
        if ll:
            lat, lon = ll
    if lat is None:
        approx = approximate_location_from_call(call)
        if approx:
            country, lat, lon = approx
    return {
        "_id": uuid.uuid4().hex,
        "source": "adif", "call": call, "grid": grid, "band": band, "mode": mode,
        "time": when, "lat": lat, "lon": lon, "country": country,
    }


