class PSKReporterBandGraph(QWidget):
    BANDS=[("160m",1800000,2000000),("80m",3500000,4000000),("60m",5000000,5500000),
           ("40m",7000000,7300000),("30m",10100000,10150000),("20m",14000000,14350000),
           ("17m",18068000,18168000),("15m",21000000,21450000),("12m",24890000,24990000),
           ("10m",28000000,29700000),("6m",50000000,54000000),("2m",144000000,148000000)]
    def __init__(self,parent=None):
        super().__init__(parent); self.counts={x[0]:0 for x in self.BANDS}; self.setMinimumHeight(220)
    @classmethod
    def band_for(cls,hz):
        try: hz=float(hz)
        except Exception: return None
        for n,a,b in cls.BANDS:
            if a<=hz<=b: return n
        return None
    def set_reports(self,reports):
        self.counts={x[0]:0 for x in self.BANDS}
        for r in reports or []:
            b=self.band_for(r.get("frequency"))
            if b: self.counts[b]+=1
        self.update()
    def paintEvent(self, e):
        p = QPainter(self)
        try:
            p.setRenderHint(QPainter.Antialiasing)
            r = self.rect().adjusted(14, 30, -14, -42)
            p.drawText(14, 20, "Activité par bande")

            band_colors = [
                "#7E57C2", "#5C6BC0", "#42A5F5", "#26A69A",
                "#66BB6A", "#9CCC65", "#D4E157", "#FFCA28",
                "#FFA726", "#FF7043", "#EC407A", "#AB47BC"
            ]

            vmax = max([1] + list(self.counts.values()))
            n = len(self.BANDS)
            gap = 5
            bw = max(10, int((r.width() - gap * (n - 1)) / max(1, n)))
            x = r.left()

            for idx, (name, _, _) in enumerate(self.BANDS):
                v = int(self.counts.get(name, 0) or 0)
                h = int(r.height() * v / vmax)
                bar_h = max(1, h) if v > 0 else 1
                bar_rect = QRect(x, r.bottom() - bar_h, bw, bar_h)

                p.save()
                p.setBrush(QColor(band_colors[idx % len(band_colors)]))
                p.setPen(QPen(QColor("#d9e2ec")))
                p.drawRoundedRect(bar_rect, 3, 3)
                p.restore()

                p.drawText(x, max(r.top() + 12, r.bottom() - bar_h - 5), str(v))
                p.drawText(x, r.bottom() + 18, name)
                x += bw + gap
        except Exception as exc:
            # Ne jamais laisser une erreur graphique fermer MultiDigi.
            try:
                p.drawText(14, 45, f"Graphique PSK Reporter indisponible : {exc}")
            except Exception:
                pass
        finally:
            try:
                p.end()
            except Exception:
                pass

class PSKReporterFetchThread(QThread):
    result_ready=pyqtSignal(list); error=pyqtSignal(str)
    def __init__(self,call,minutes=30,mode="",parent=None):
        super().__init__(parent); self.call=str(call or "").strip().upper()
        self.minutes=max(5,min(int(minutes),1440)); self.mode=str(mode or "").strip()
    def run(self):
        try:
            q={"callsign":self.call,"flowStartSeconds":str(-self.minutes*60),
               "rptlimit":"1000","rronly":"1","noactive":"1"}
            if self.mode and self.mode.upper()!="TOUS MODES": q["mode"]=self.mode
            url="https://retrieve.pskreporter.info/query?"+urllib.parse.urlencode(q)
            req=urllib.request.Request(url,headers={"User-Agent":"MultiDigi/8.3.13","Accept":"application/xml"})
            with urllib.request.urlopen(req,timeout=15) as f: raw=f.read()
            root=ET.fromstring(raw); out=[]
            for el in root.iter():
                if not str(el.tag).lower().endswith("receptionreport"): continue
                a=el.attrib
                out.append({"senderCallsign":a.get("senderCallsign",""),
                    "receiverCallsign":a.get("receiverCallsign",""),
                    "receiverLocator":a.get("receiverLocator",""),
                    "frequency":a.get("frequency","0"),"mode":a.get("mode",""),
                    "sNR":a.get("sNR",a.get("snr","")),
                    "flowStartSeconds":a.get("flowStartSeconds","0")})
            self.result_ready.emit(out)
        except Exception as e: self.error.emit(str(e))


class LiveDxSpotThread(QThread):
    """Flux temps réel DX Cluster / Reverse Beacon Network."""
    spot_received = pyqtSignal(dict)
    status_changed = pyqtSignal(str)

    DX_RE = re.compile(
        r"DX\s+de\s+([A-Z0-9\/\-]+)[^:]*:\s*"
        r"([0-9]+(?:\.[0-9]+)?)\s+"
        r"([A-Z0-9\/\-]+)\s*(.*?)\s+"
        r"(\d{4})Z",
        re.I
    )

    def __init__(self, source_name, host, port, login_call="", parent=None, forced_mode=""):
        super().__init__(parent)
        self.source_name = str(source_name or "CLUSTER").upper()
        self.host = str(host or "").strip()
        self.port = int(port)
        self.login_call = str(login_call or "").strip().upper()
        self.forced_mode = str(forced_mode or "").strip().upper()
        self._running = True
        self._sock = None

    @staticmethod
    def _strip_telnet_iac(data):
        """Retire les négociations Telnet simples sans dépendre de telnetlib."""
        out = bytearray()
        i = 0
        data = bytearray(data)
        while i < len(data):
            if data[i] == 255:  # IAC
                if i + 1 < len(data) and data[i+1] == 255:
                    out.append(255); i += 2; continue
                # WILL/WONT/DO/DONT + option
                if i + 2 < len(data) and data[i+1] in (251,252,253,254):
                    i += 3; continue
                i += 2
                continue
            out.append(data[i]); i += 1
        return bytes(out)

    @staticmethod
    def _infer_mode(freq_hz, comment):
        c = str(comment or "").upper()
        for token in ("JS8","FT8","FT4","RTTY","CW","PSK31","PSK63","PSK","OLIVIA","CONTESTIA","DOMINO"):
            if token in c:
                return token
        if "RTTY" in c:
            return "RTTY"
        if "FT8" in c:
            return "FT8"
        if "FT4" in c:
            return "FT4"
        # Sur le flux RBN 7000, WPM/dB correspond le plus souvent à un spot CW.
        return "CW" if c.find("DB") >= 0 or c.find("WPM") >= 0 else ""

    @classmethod
    def parse_line(cls, line, source):
        m = cls.DX_RE.search(str(line or "").upper())
        if not m:
            return None
        spotter, freq_khz, dxcall, comment, hhmm = m.groups()
        try:
            freq_hz = float(freq_khz) * 1000.0
        except Exception:
            return None
        band = PSKReporterBandGraph.band_for(freq_hz) or "—"
        return {
            "source": source,
            "time": hhmm,
            "timestamp": time.time(),
            "spotter": spotter.strip(),
            "call": dxcall.strip(),
            "frequency": freq_hz,
            "frequency_khz": float(freq_khz),
            "band": band,
            "mode": cls._infer_mode(freq_hz, comment),
            "comment": str(comment or "").strip(),
        }

    def stop(self):
        self._running = False
        try:
            if self._sock:
                self._sock.shutdown(socket.SHUT_RDWR)
        except Exception:
            pass
        try:
            if self._sock:
                self._sock.close()
        except Exception:
            pass
        self._sock = None

    def run(self):
        while self._running:
            try:
                self.status_changed.emit(
                    f"🔌 {self.source_name} : connexion {self.host}:{self.port}…"
                )
                s = socket.create_connection((self.host, self.port), timeout=10)
                s.settimeout(1.0)
                self._sock = s

                # Beaucoup de clusters demandent simplement l'indicatif au login.
                if self.login_call:
                    try:
                        time.sleep(0.7)
                        s.sendall((self.login_call + "\r\n").encode("ascii", "ignore"))
                    except Exception:
                        pass

                self.status_changed.emit(
                    f"✅ {self.source_name} connecté — spots en direct"
                )
                buf = b""
                while self._running:
                    try:
                        chunk = s.recv(8192)
                        if not chunk:
                            raise ConnectionError("connexion fermée")
                    except socket.timeout:
                        continue

                    chunk = self._strip_telnet_iac(chunk)
                    buf += chunk
                    while b"\n" in buf:
                        raw, buf = buf.split(b"\n", 1)
                        line = raw.decode("latin-1", "ignore").strip("\r ")
                        spot = self.parse_line(line, self.source_name)
                        if spot:
                            if self.forced_mode:
                                spot["mode"] = self.forced_mode
                            self.spot_received.emit(spot)

            except Exception as exc:
                if self._running:
                    self.status_changed.emit(
                        f"⚠️ {self.source_name} : {exc} — reconnexion…"
                    )
                    for _ in range(10):
                        if not self._running:
                            break
                        time.sleep(0.5)
            finally:
                try:
                    if self._sock:
                        self._sock.close()
                except Exception:
                    pass
                self._sock = None


