    # ── Réception UDP ───────────────────────────────────────────────────
    def _start_listener(self):
        if self.udp_thread:
            self.udp_thread.stop()
        self.udp_thread = UdpListenerThread(host="0.0.0.0", port=int(self.settings.get("udp_port", 2237)))
        self.udp_thread.packet_received.connect(self._on_packet)
        self.udp_thread.status_changed.connect(self._on_udp_status)
        self.udp_thread.start()

    def _on_udp_status(self, msg, ok):
        self.status.showMessage(msg)

    def _show_world_traffic(self):
        try:
            self.btn_world.setChecked(True)
            self.btn_pskr.setChecked(False)
            self.btn_prop_map.setChecked(False)
            self.btn_real_map.setChecked(False)
            self.btn_live_map.setChecked(False)
            self.btn_grid_map.setChecked(False)
            self.live_info_panel.hide()
            self.map_stack.setCurrentWidget(self.world_page)
            self._refresh_world_traffic()
            if not (
                (self._world_rbn_thread and self._world_rbn_thread.isRunning())
                or (self._world_ft8_thread and self._world_ft8_thread.isRunning())
                or (self._world_cluster_thread and self._world_cluster_thread.isRunning())
            ):
                QTimer.singleShot(150, self._start_world_traffic)
        except Exception as exc:
            self.status.showMessage(f"⚠️ Trafic mondial : {exc}")

    def _start_world_traffic(self):
        call = str(
            self.settings.get("my_call", "")
            or self.settings.get("callsign", "")
            or self.settings.get("call", "")
            or "F4LPS"
        ).strip().upper()

        host = self.world_cluster_host.text().strip()
        port = int(self.world_cluster_port.value())
        use_cluster = bool(self.world_use_cluster.isChecked())

        self.settings["cluster_host"] = host
        self.settings["cluster_port"] = port
        self.settings["cluster_enabled"] = use_cluster
        try:
            self._save_settings()
        except Exception:
            pass

        # RBN 7000 : flux officiel CW + RTTY.
        if not (self._world_rbn_thread and self._world_rbn_thread.isRunning()):
            self._world_rbn_thread = LiveDxSpotThread(
                "RBN", "telnet.reversebeacon.net", 7000, call, self
            )
            self._world_rbn_thread.spot_received.connect(self._on_world_spot)
            self._world_rbn_thread.status_changed.connect(
                lambda msg: self._on_world_source_status("RBN CW/RTTY", msg)
            )
            self._world_rbn_thread.start()

        # RBN 7001 : flux officiel FT8 séparé.
        if not (self._world_ft8_thread and self._world_ft8_thread.isRunning()):
            self._world_ft8_thread = LiveDxSpotThread(
                "RBN-FT8", "telnet.reversebeacon.net", 7001, call, self,
                forced_mode="FT8"
            )
            self._world_ft8_thread.spot_received.connect(self._on_world_spot)
            self._world_ft8_thread.status_changed.connect(
                lambda msg: self._on_world_source_status("RBN FT8", msg)
            )
            self._world_ft8_thread.start()

        # DX Cluster : optionnel. Un serveur indisponible ne doit plus gêner RBN.
        if use_cluster and host:
            if not (
                self._world_cluster_thread
                and self._world_cluster_thread.isRunning()
            ):
                self._world_cluster_thread = LiveDxSpotThread(
                    "CLUSTER", host, port, call, self
                )
                self._world_cluster_thread.spot_received.connect(self._on_world_spot)
                self._world_cluster_thread.status_changed.connect(
                    lambda msg: self._on_world_source_status("DX Cluster", msg)
                )
                self._world_cluster_thread.start()
        else:
            if self._world_cluster_thread is not None:
                try:
                    self._world_cluster_thread.stop()
                    self._world_cluster_thread.wait(1000)
                except Exception:
                    pass
                self._world_cluster_thread = None

        # Rafraîchissement visuel lent, réception réseau toujours continue.
        try:
            if not self._world_visual_timer.isActive():
                self._world_visual_timer.start()
            self._world_visual_refresh_pending = True
        except Exception:
            pass

        # PSK Reporter en fond : requête immédiate puis toutes les 5 minutes.
        try:
            if not self._world_pskr_timer.isActive():
                self._world_pskr_timer.start()
            QTimer.singleShot(300, self._refresh_world_pskr_background)
        except Exception:
            pass

        self.world_start.setEnabled(False)
        self.world_stop.setEnabled(True)
        self.status.showMessage(
            "🌎 Trafic mondial : flux actifs — affichage actualisé toutes les 5 s"
            + (" + DX Cluster" if use_cluster else "")
        )


    def _stop_world_traffic(self):
        for attr in ("_world_rbn_thread", "_world_ft8_thread", "_world_cluster_thread"):
            th = getattr(self, attr, None)
            if th is not None:
                try:
                    th.stop()
                    th.wait(1500)
                except Exception:
                    pass
                setattr(self, attr, None)
        try:
            if getattr(self, "_world_visual_timer", None) is not None:
                self._world_visual_timer.stop()
        except Exception:
            pass
        try:
            if getattr(self, "_world_pskr_timer", None) is not None:
                self._world_pskr_timer.stop()
        except Exception:
            pass
        try:
            th = getattr(self, "_world_pskr_thread", None)
            if th is not None and th.isRunning():
                th.requestInterruption()
        except Exception:
            pass
        self._world_pskr_thread = None

        self.world_start.setEnabled(True)
        self.world_stop.setEnabled(False)
        self.world_source_status.setText(
            "RBN CW/RTTY : arrêté   |   RBN FT8 : arrêté   |   "
            "PSK Reporter : arrêté   |   DX Cluster : arrêté"
        )
        self.status.showMessage("🌎 Trafic mondial arrêté")

    def _refresh_world_pskr_background(self):
        """Récupère PSK Reporter en fond pour enrichir Trafic mondial."""
        # Evite toute requête trop fréquente.
        now = time.time()
        if now - float(getattr(self, "_world_pskr_last_fetch", 0.0) or 0.0) < 280:
            return

        th = getattr(self, "_world_pskr_thread", None)
        if th is not None and th.isRunning():
            return

        call = str(
            self.settings.get("my_call", "")
            or self.settings.get("callsign", "")
            or self.settings.get("call", "")
            or ""
        ).strip().upper()
        if not call:
            return

        # On demande tous les modes sur 60 min afin d'alimenter tous les filtres locaux.
        self._world_pskr_last_fetch = now
        self._world_pskr_thread = PSKReporterFetchThread(
            call, 60, "Tous modes", self
        )
        self._world_pskr_thread.result_ready.connect(self._on_world_pskr_results)
        self._world_pskr_thread.error.connect(
            lambda msg: self._on_world_source_status(
                "PSK Reporter", f"⚠️ PSK Reporter : {msg}"
            )
        )
        self._world_pskr_thread.start()
        self._on_world_source_status("PSK Reporter", "connexion")

    def _on_world_pskr_results(self, reports):
        reports = list(reports or [])
        now_ts = time.time()

        # Supprime seulement les anciens PSKR de la fenêtre en mémoire,
        # puis réinjecte le dernier lot pour éviter l'accumulation de doublons.
        preserved = [s for s in list(self._world_spots) if s.get("source") != "PSKR"]
        self._world_spots.clear()
        for s in preserved[-2500:]:
            self._world_spots.append(s)

        added = 0
        for r in reports:
            try:
                freq = float(r.get("frequency") or 0)
            except Exception:
                freq = 0.0
            try:
                ts = float(r.get("flowStartSeconds") or now_ts)
            except Exception:
                ts = now_ts

            mode = str(r.get("mode", "") or "").strip().upper()
            if not mode:
                continue

            call = str(r.get("senderCallsign", "") or "").strip().upper()
            if not call:
                continue

            self._world_spots.append({
                "source": "PSKR",
                "time": datetime.fromtimestamp(ts).strftime("%H%M"),
                "timestamp": ts,
                "spotter": str(r.get("receiverCallsign", "") or "").strip().upper(),
                "call": call,
                "frequency": freq,
                "frequency_khz": freq / 1000.0 if freq else 0.0,
                "band": PSKReporterBandGraph.band_for(freq) or "—",
                "mode": mode,
                "comment": (
                    f"SNR {r.get('sNR','')} "
                    f"RXloc {r.get('receiverLocator','')}"
                ).strip(),
            })
            added += 1

        self._on_world_source_status(
            "PSK Reporter", f"✅ PSK Reporter : {added} reports"
        )
        self._world_visual_refresh_pending = True

    def _on_world_status(self, msg):
        # Compatibilité anciennes connexions.
        self._on_world_source_status("Source", msg)

    def _on_world_source_status(self, source, msg):
        try:
            if not hasattr(self, "_world_status_by_source"):
                self._world_status_by_source = {}
            self._world_status_by_source[str(source)] = str(msg)

            order = ("RBN CW/RTTY", "RBN FT8", "PSK Reporter", "DX Cluster")
            parts = []
            for key in order:
                if key in self._world_status_by_source:
                    val = self._world_status_by_source[key]
                    # Texte compact : garde la partie utile.
                    if "connecté" in val.lower():
                        parts.append(f"{key} : ✅")
                    elif "connexion" in val.lower() and "reconnexion" not in val.lower():
                        parts.append(f"{key} : …")
                    elif "reconnexion" in val.lower() or "⚠️" in val:
                        parts.append(f"{key} : ⚠️")
                    else:
                        parts.append(f"{key} : {val}")
            self.world_source_status.setText("   |   ".join(parts))
        except Exception:
            pass

    def _on_world_spot(self, spot):
        spot = dict(spot or {})
        if not spot.get("call"):
            return

        # Anti-doublon ultra-court : certains clusters relaient deux fois le même spot.
        now = time.time()
        for old in list(self._world_spots)[-20:]:
            if (
                old.get("source") == spot.get("source")
                and old.get("call") == spot.get("call")
                and abs(float(old.get("frequency",0)) - float(spot.get("frequency",0))) < 50
                and now - float(old.get("timestamp",0)) < 2.0
            ):
                return

        self._world_spots.append(spot)

        # Le spot est mémorisé immédiatement, mais on ne reconstruit pas
        # le tableau à chaque ligne reçue : sinon la sélection saute sous la souris.
        self._world_visual_refresh_pending = True

    def _world_visual_tick(self):
        """Reconstruit l'affichage au maximum toutes les 5 s.

        Si l'utilisateur est en train de sélectionner une ligne, on conserve
        le tableau stable jusqu'au tick suivant.
        """
        if not bool(getattr(self, "_world_visual_refresh_pending", False)):
            return

        try:
            # Si l'utilisateur maintient le bouton souris sur le tableau,
            # ne surtout pas déplacer les lignes sous son curseur.
            if QApplication.mouseButtons() != Qt.NoButton:
                return
        except Exception:
            pass

        self._world_visual_refresh_pending = False
        self._refresh_world_traffic()

    def _refresh_world_traffic(self):
        if not hasattr(self, "world_graph"):
            return

        try:
            minutes = int(self.world_window.currentText().split()[0])
        except Exception:
            minutes = 15

        mode_filter = str(self.world_mode.currentText() or "Tous modes").upper()
        cutoff = time.time() - minutes * 60

        recent_all = [
            s for s in list(self._world_spots)
            if float(s.get("timestamp", 0) or 0) >= cutoff
        ]

        def mode_matches(s):
            if mode_filter == "TOUS MODES":
                return True

            mode = str(s.get("mode", "") or "").upper()
            comment = str(s.get("comment", "") or "").upper()

            if mode_filter == "PSK":
                return "PSK" in mode or "PSK" in comment

            return mode_filter in mode or mode_filter in comment

        recent = [s for s in recent_all if mode_matches(s)]

        self.world_graph.set_reports(recent)

        self.world_table.setUpdatesEnabled(False)
        try:
            self.world_table.setRowCount(0)
            for spot in reversed(recent[-500:]):
                row = self.world_table.rowCount()
                self.world_table.insertRow(row)
                vals = [
                    spot.get("source", ""),
                    spot.get("time", ""),
                    spot.get("band", ""),
                    f"{float(spot.get('frequency_khz',0)):.1f}",
                    spot.get("call", ""),
                    spot.get("spotter", ""),
                    spot.get("mode", ""),
                    spot.get("comment", ""),
                ]
                for col, val in enumerate(vals):
                    self.world_table.setItem(row, col, QTableWidgetItem(str(val)))
        finally:
            self.world_table.setUpdatesEnabled(True)

        rbn_n = sum(1 for s in recent if s.get("source") == "RBN")
        ft8_n = sum(1 for s in recent if s.get("source") == "RBN-FT8")
        clu_n = sum(1 for s in recent if s.get("source") == "CLUSTER")
        pskr_n = sum(1 for s in recent if s.get("source") == "PSKR")

        try:
            self.status.showMessage(
                f"🌎 Trafic réel {minutes} min — {self.world_mode.currentText()} : "
                f"{len(recent)} spots "
                f"(RBN CW/RTTY {rbn_n} / RBN FT8 {ft8_n} / "
                f"Cluster {clu_n} / PSKR {pskr_n})"
            )
        except Exception:
            pass


    def _world_spot_double_clicked(self, row, col):
        """Double-clic spot : CALL actif + mode radio + QSY CAT."""
        try:
            call_item = self.world_table.item(row, 4)
            freq_item = self.world_table.item(row, 3)
            mode_item = self.world_table.item(row, 6)

            call = call_item.text().strip().upper() if call_item else ""
            freq_khz_txt = (
                freq_item.text().strip().replace(",", ".")
                if freq_item else ""
            )
            spot_mode = (
                mode_item.text().strip().upper()
                if mode_item else ""
            )

            try:
                freq_hz = int(round(float(freq_khz_txt) * 1000.0))
            except Exception:
                freq_hz = 0

            if not call:
                self.status.showMessage("⚠️ Spot sélectionné sans indicatif")
                return

            terminal = None
            try:
                for w in QApplication.topLevelWidgets():
                    if hasattr(w, "_qsy") and hasattr(w, "_set_active_dxcall"):
                        terminal = w
                        break
            except Exception:
                terminal = None

            if terminal is None:
                self._send_call_to_terminal(call)
                self.status.showMessage(
                    f"⚠️ {call} sélectionné, mais fenêtre MultiDigi CAT introuvable"
                )
                return

            # CALL choisi volontairement.
            try:
                terminal._set_active_dxcall(call)
            except Exception:
                pass

            rc = getattr(terminal, "radio_ctrl", None)
            connected = bool(getattr(rc, "connected", False))

            if not connected:
                self.status.showMessage(
                    f"⚠️ {call} sélectionné — CAT non connecté"
                )
                return

            # CW uniquement -> CW.
            # Tout le reste (FT8/FT4/RTTY/PSK/Olivia/Contestia/DominoEX...) -> USB.
            is_cw = (
                spot_mode == "CW"
                or spot_mode.startswith("CW ")
                or spot_mode.startswith("CW-")
            )

            if is_cw:
                mode_ok = bool(rc.set_mode_cw())
                rig_mode = "CW"
            else:
                mode_ok = bool(rc.set_mode_usb())
                rig_mode = "USB"

            # Petit délai pour laisser la radio appliquer le mode avant le QSY.
            if freq_hz > 100000:
                QTimer.singleShot(
                    120,
                    lambda f=freq_hz: terminal._qsy(f)
                )

            msg = (
                f"📻 {call} — {rig_mode} → "
                f"{freq_hz/1e6:.6f} MHz"
                if freq_hz > 100000
                else f"📻 {call} — mode {rig_mode}"
            )
            if not mode_ok:
                msg += " (mode CAT non confirmé)"

            self.status.showMessage(msg)
            try:
                terminal._set_status(msg)
            except Exception:
                pass

        except Exception as exc:
            try:
                self.status.showMessage(f"❌ QSY Cluster : {exc}")
            except Exception:
                pass


