    def _refresh_psk_reporter(self):
        if not self.btn_pskr.isChecked(): return
        th=getattr(self,"_pskr_thread",None)
        if th is not None and th.isRunning(): return
        call = str(
            self.settings.get("my_call", "")
            or self.settings.get("callsign", "")
            or self.settings.get("call", "")
            or ""
        ).strip().upper()
        if not call:
            self.status.showMessage("⚠️ PSK Reporter : indicatif station non renseigné."); return
        minutes=int(self.pskr_period.currentText().split()[0]); mode=self.pskr_mode.currentText()
        self.status.showMessage(f"📡 PSK Reporter : recherche {call}…")
        self._pskr_thread=PSKReporterFetchThread(call,minutes,mode,self)
        self._pskr_thread.result_ready.connect(self._on_pskr_results)
        self._pskr_thread.error.connect(lambda e:self.status.showMessage(f"⚠️ PSK Reporter : {e}"))
        self._pskr_thread.start()

    def _on_pskr_results(self,reports):
        reports=list(reports or []); self.pskr_graph.set_reports(reports); self.pskr_table.setRowCount(0)
        # Si l'utilisateur ouvre l'onglet PSK Reporter manuellement,
        # on réutilise le même lot pour Trafic mondial sans doublons.
        if hasattr(self, "_world_spots"):
            self._on_world_pskr_results(reports)
        for r in sorted(reports,key=lambda x:int(x.get("flowStartSeconds") or 0),reverse=True):
            row=self.pskr_table.rowCount(); self.pskr_table.insertRow(row)
            try:
                ts=int(r.get("flowStartSeconds") or 0); hh=datetime.fromtimestamp(ts).strftime("%H:%M:%S") if ts else "—"
            except Exception: hh="—"
            vals=[hh,PSKReporterBandGraph.band_for(r.get("frequency")) or "—",r.get("mode") or "—",
                  r.get("senderCallsign") or "—",r.get("receiverCallsign") or "—",
                  r.get("receiverLocator") or "—",r.get("sNR") or "—"]
            for c,v in enumerate(vals): self.pskr_table.setItem(row,c,QTableWidgetItem(str(v)))
        self.status.showMessage(f"📡 PSK Reporter : {len(reports)} report(s) — graphe par bande mis à jour")

    def _show_propagation_now(self):
        try: self.btn_world.setChecked(False)
        except Exception: pass
        if self.real_map is None:
            return
        self.live_info_panel.hide()
        self.map_stack.setCurrentWidget(self.real_map)
        self.btn_prop_map.setChecked(True); self.btn_real_map.setChecked(False); self.btn_live_map.setChecked(False); self.btn_grid_map.setChecked(False)
        self._refresh_propagation_now()
        QTimer.singleShot(80, lambda: self.prop_map._run("map.invalidateSize(true);"))

    def _refresh_propagation_now(self):
        if self.prop_map is None or not self.btn_prop_map.isChecked():
            return

        try:
            minutes = int(self.prop_minutes.currentText().split()[0])
        except Exception:
            minutes = 30

        band_filter = self.prop_band.currentText().strip().lower()
        mode_filter = self.prop_mode.currentText().strip().upper()
        now = datetime.now()
        out = []

        def parse_contact_time(c):
            raw = str(c.get("time", "") or "").strip()
            if not raw:
                return None

            # Format principal envoyé par MultiDigi : ISO UTC
            # ex. 2026-08-11T05:17:22Z
            try:
                if "T" in raw:
                    s = raw.replace("Z", "+00:00")
                    dt = datetime.fromisoformat(s)
                    if dt.tzinfo is not None:
                        dt = dt.astimezone().replace(tzinfo=None)
                    return dt
            except Exception:
                pass

            # Imports ADIF / saisie manuelle.
            for fmt in (
                "%Y-%m-%d %H:%M:%S",
                "%Y-%m-%d %H:%M",
                "%Y%m%d %H%M%S",
                "%Y%m%d %H%M",
            ):
                try:
                    return datetime.strptime(raw, fmt)
                except Exception:
                    pass

            return None

        for c in list(self.store.contacts or []):
            try:
                lat = float(c.get("lat"))
                lon = float(c.get("lon"))
            except Exception:
                continue

            dt = parse_contact_time(c)
            if dt is None:
                continue

            age = (now - dt).total_seconds() / 60.0
            if age < -2 or age > minutes:
                continue

            band = str(c.get("band", "") or "").strip().lower()
            mode = str(c.get("mode", "") or "").strip().upper()

            if band_filter != "toutes bandes" and band != band_filter:
                continue
            if mode_filter != "TOUS MODES" and mode_filter not in mode:
                continue

            out.append({
                "call": str(c.get("call", "") or ""),
                "lat": lat,
                "lon": lon,
                "band": band,
                "mode": mode,
                "age": f"il y a {max(0, int(round(age)))} min",
            })

        self.prop_map.show_propagation_contacts(out)

        try:
            self.status.showMessage(
                f"🌐 Propagation maintenant : {len(out)} contact(s) "
                f"sur {minutes} min — {self.prop_band.currentText()} — "
                f"{self.prop_mode.currentText()}"
            )
        except Exception:
            pass


