# POINT D'ENTRÉE
# ============================================================================
def main():
    # MULTIDIGI V0.1 F4LPS : requis par QWebEngineView (carte réelle du Grid
    # Tracker intégré) -- doit être défini AVANT la création de QApplication.
    try:
        QApplication.setAttribute(Qt.AA_ShareOpenGLContexts, True)
    except Exception:
        pass
    app = QApplication(sys.argv)
    app.setApplicationName("MultiDigi")
    app.setOrganizationName("F4LPS")
    app.setApplicationVersion("1.1")

    win = PSKMainWindow()
    win.showMaximized()
    if _SPLASH_OK and _splash_root is not None:
        try:
            _splash_root.withdraw()
            _splash_root.destroy()
        except Exception:
            pass
    sys.exit(app.exec_())


if __name__ == "__main__":
    main()
